repas/enseignes.py:
"""Enseignes : lire les prix (et remplir le panier) sur le site de courses.

Chaque enseigne a sa classe : choix du magasin a partir du code postal, recherche
d'un article, lecture de la composition d'un produit, ajout au panier. Le
navigateur est le Firefox de Jarvis (repas.navigateur).

Les protections anti-robot ne sont PAS contournees : si un site affiche une
verification (captcha), Jarvis s'arrete et te demande de la passer toi-meme dans
la fenetre, ou abandonne cette enseigne.
"""
from __future__ import annotations

import re
import time
from dataclasses import asdict, dataclass
from urllib.parse import quote_plus

from repas.navigateur import ErreurNavigateur, Firefox


class Bloque(RuntimeError):
    """Le site demande une verification anti-robot."""


@dataclass
class Offre:
    enseigne: str
    nom: str
    prix: float                 # prix du paquet, en euros
    format: str = ""            # « 1kg », « 15cl », « 5x90g »…
    prix_ref: float = 0.0       # prix au kilo / au litre / a la piece
    unite_ref: str = ""         # kg | l | pièce
    promo: str = ""
    lien: str = ""

    def dict(self):
        return asdict(self)


def _nombre(texte: str) -> float:
    return float(texte.replace(" ", "").replace(" ", "").replace(",", "."))


_MARQUES_BLOCAGE = ("captcha-delivery.com", "Attention Required", "you have been blocked",
                    "pas un robot", "cf-challenge", "Access Denied")


def est_bloque(f: Firefox) -> bool:
    try:
        page = f.js("return document.title + ' ' + document.documentElement.outerHTML.slice(0, 4000)")
    except ErreurNavigateur:
        return False
    return any(m.lower() in (page or "").lower() for m in _MARQUES_BLOCAGE)


def passer_verification(f: Firefox, enseigne: str, attente: float = 300.0) -> None:
    """Verification anti-robot : on ne la contourne pas. Fenetre visible -> on
    laisse l'utilisateur la passer ; sinon on abandonne l'enseigne."""
    if not est_bloque(f):
        return
    if f.invisible:
        raise Bloque(f"{enseigne} affiche une verification anti-robot.")
    print(f"  {enseigne} affiche une verification anti-robot : passe-la dans la fenetre "
          f"Firefox, j'attends {int(attente // 60)} minutes…", flush=True)
    fin = time.monotonic() + attente
    while time.monotonic() < fin:
        time.sleep(3)
        if not est_bloque(f):
            time.sleep(2)
            return
    raise Bloque(f"{enseigne} : verification anti-robot non passee.")


def fermer_bandeau(f: Firefox) -> None:
    """Bandeau cookies : on choisit « continuer sans accepter » (il masque la page)."""
    try:
        f.js(r"""
const b = [...document.querySelectorAll('button, a, span[role=button]')].find(e =>
  /^(continuer sans accepter|tout refuser|refuser tout|refuser)\b/i.test((e.innerText || '').trim()));
if (b) b.click();""")
        time.sleep(0.8)
    except ErreurNavigateur:
        pass


class Enseigne:
    nom = "?"
    pause = 2.0                 # secondes entre deux recherches (rythme humain)

    def preparer(self, f: Firefox, code_postal: str) -> str:
        """Choisit un magasin si aucun ne l'est. Renvoie le contexte courant."""
        raise NotImplementedError

    def chercher(self, f: Firefox, requete: str) -> list:
        raise NotImplementedError

    def catalogue(self, f: Firefox, journal=print) -> list:
        """Toutes les offres du catalogue des promotions en cours (quelques pages
        a charger, au lieu d'une recherche par article)."""
        raise NotImplementedError

    def composition(self, f: Firefox, offre: Offre) -> str:
        """Liste d'ingredients du produit ('' si elle n'est pas affichee)."""
        raise NotImplementedError

    def ajouter_au_panier(self, f: Firefox, offre: Offre, quantite: int) -> int:
        """Ajoute `quantite` paquets. Renvoie le nombre reellement ajoute."""
        raise NotImplementedError


class Auchan(Enseigne):
    nom = "Auchan"
    _RECHERCHE = "https://www.auchan.fr/recherche?text={q}"
    _CARTES = r"""
return [...document.querySelectorAll('article.product-thumbnail')].slice(0, 24).map(a => {
  const lien = a.querySelector('a.productThumbnailLink');
  const image = a.querySelector('picture img[alt]:not([height="30"])') || a.querySelector('picture source[alt]');
  return {
    vendeur: a.dataset.currentSellerType || '',
    lignes: (a.innerText || '').split('\n').map(l => l.trim()).filter(Boolean),
    prix: (a.querySelector('meta[itemprop=price]') || {}).content || '',
    alt: image ? image.getAttribute('alt') : '',
    lien: lien ? lien.href : '',
    ajoutable: !!a.querySelector('.quantity-selector__button--add'),
  };
});"""

    def _contexte(self, f):
        return (f.js("const b=document.querySelector('.context-header__button');"
                     "return b ? b.innerText.replace(/\\s+/g,' ').trim() : ''") or "")

    def preparer(self, f, code_postal):
        f.aller(self._RECHERCHE.format(q="riz"))
        passer_verification(f, self.nom)
        f.attendre("document.querySelector('article.product-thumbnail')", 15)
        fermer_bandeau(f)
        if not f.js("return !!document.querySelector('button.product-thumbnail__see-prices-button')"):
            return self._contexte(f)                 # magasin deja choisi (par toi ou avant)
        f.clic("button.product-thumbnail__see-prices-button")
        f.attendre("document.querySelector('#journey-search')", 10)
        f.saisir("#journey-search", code_postal)
        f.attendre("document.querySelector('li.geocoding__search-suggest')", 10)
        time.sleep(1.0)
        # La liste de suggestions se referme au moindre mouvement : on lui envoie
        # directement la sequence d'evenements d'un clic (fiable sur Chrome et Firefox).
        f.js(r"""
const li = [...document.querySelectorAll('li.geocoding__search-suggest')]
  .find(e => e.getBoundingClientRect().width > 0);
if (li) for (const t of ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'])
  li.dispatchEvent(new MouseEvent(t, {bubbles: true, cancelable: true, view: window}));""")
        if not f.attendre("document.querySelector('button.btnJourneySubmit')", 15):
            f.clic("li.geocoding__search-suggest")
            f.attendre("document.querySelector('button.btnJourneySubmit')", 15)
        time.sleep(1.5)
        options = f.js(r"""
return [...document.querySelectorAll('button.btnJourneySubmit')].map((b, i) => {
  let c = b;
  for (let k = 0; k < 8 && c; k++) { c = c.parentElement;
    if (c && c.querySelectorAll('button.btnJourneySubmit').length === 1 && (c.innerText || '').length > 30) break; }
  b.setAttribute('data-jarvis-opt', i);
  return (c ? c.innerText : '').replace(/\s+/g, ' ').replace(/Infos et Tarifs.*/, '').trim();
});""") or []
        if not options:
            raise ErreurNavigateur("Auchan : aucun magasin propose pour ce code postal.")

        def distance(texte):
            m = re.search(r"(\d+(?:[.,]\d+)?) km", texte)
            return _nombre(m.group(1)) if m else 999.0
        choix = min(range(len(options)), key=lambda i: distance(options[i]))
        f.clic(f"[data-jarvis-opt='{choix}']")
        f.attendre("!document.querySelector('button.product-thumbnail__see-prices-button') "
                   "&& document.querySelector('article.product-thumbnail meta[itemprop=price]')", 20)
        return self._contexte(f) or options[choix][:90]

    _PROMOS = "https://www.auchan.fr/boutique/promos"

    def chercher(self, f, requete):
        f.aller(self._RECHERCHE.format(q=quote_plus(requete)))
        passer_verification(f, self.nom)
        f.attendre("document.querySelector('article.product-thumbnail') || "
                   "/aucun r[ée]sultat|0 r[ée]sultat/i.test(document.body.innerText)", 12)
        time.sleep(0.8)
        return self._offres_de_la_page(f)

    def catalogue(self, f, journal=print):
        offres, vus = [], set()
        for page in range(1, 41):
            f.aller(self._PROMOS + (f"?page={page}" if page > 1 else ""))
            passer_verification(f, self.nom)
            if not f.attendre("document.querySelector('article.product-thumbnail')", 12):
                break
            time.sleep(0.8)
            nouvelles = [o for o in self._offres_de_la_page(f, maxi=200) if o.lien not in vus]
            if not nouvelles:
                break
            vus.update(o.lien for o in nouvelles)
            offres.extend(nouvelles)
            journal(f"    page {page} : {len(offres)} offres")
            if not f.js(f"return !!document.querySelector('a[href*=\"page={page + 1}\"]')"):
                break
            time.sleep(self.pause)
        return offres

    def _offres_de_la_page(self, f, maxi=24):
        offres = []
        for c in f.js(self._CARTES.replace("slice(0, 24)", f"slice(0, {maxi})")) or []:
            if c["vendeur"] != "GROCERY" or not c["prix"] or not c["ajoutable"]:
                continue                              # marketplace ou indisponible
            lignes = [l for l in c["lignes"] if not re.fullmatch(r"\(\d+\)", l)]
            # le nom est la ligne que reprend le texte de la photo (« AUCHAN Riz basmati 1kg ») ;
            # les autres lignes sont des badges (« Nos clients adorent »).
            alt = (c["alt"] or "").lower()
            textes = [l for l in lignes if re.search(r"[A-Za-zÀ-ÿ]{3}", l) and "€" not in l]
            nom = next((l for l in textes if alt.startswith(l.lower()[:18])),
                       textes[0] if textes else c["alt"])
            ref = next((re.search(r"(\d+(?:[.,]\d+)?)\s?€\s?/\s?(kg|l|pièce|pce|unité|u)\b", l, re.I)
                        for l in lignes if "/" in l and "€" in l), None)
            formats = [l for l in lignes
                       if re.fullmatch(r"(?:\d+\s?x\s?)?\d+(?:[.,]\d+)?\s?(?:kg|g|l|cl|ml)", l, re.I)
                       or re.fullmatch(r"(?:x\s?)?\d+\s?(?:pièces?|sachets?|œufs|oeufs|unités?|tranches?)?", l, re.I)]
            promo = " ".join(l for l in lignes if l != nom and "€ /" not in l
                             and re.search(r"cagnott|2ème|offert|promo|remise|^-?\d+ ?%", l, re.I))
            unite = (ref.group(2).lower() if ref else "")
            offres.append(Offre(
                enseigne=self.nom, nom=nom, prix=_nombre(c["prix"]),
                format=" ".join(formats[:2]),
                prix_ref=_nombre(ref.group(1)) if ref else 0.0,
                unite_ref={"pce": "pièce", "unité": "pièce", "u": "pièce"}.get(unite, unite),
                promo=promo[:80], lien=c["lien"]))
        return offres

    def composition(self, f, offre):
        f.aller(offre.lien)
        passer_verification(f, self.nom)
        f.attendre("/ingr[ée]dients/i.test(document.body.textContent)", 8)
        texte = f.js(r"""
const direct = [...document.querySelectorAll('.product-description__feature-values')]
  .find(e => /^\s*ingr[ée]dients\s*:/i.test(e.textContent || ''));
if (direct) return direct.textContent.replace(/\s+/g, ' ').trim().slice(0, 1500);
const blocs = [...document.querySelectorAll('h2,h3,h4,h5,h6,dt,span,div,button')]
  .filter(e => /^\s*ingr[ée]dients\s*:?\s*$/i.test(e.textContent || ''));
for (const b of blocs) {
  let c = b;
  for (let i = 0; i < 4 && c; i++, c = c.parentElement) {
    const t = (c.textContent || '').replace(/\s+/g, ' ').trim();
    if (t.length > 40) return t.slice(0, 1500);
  }
}
return '';""") or ""
        return re.sub(r"^\s*ingr[ée]dients\s*:?\s*", "", texte, flags=re.I)

    def ajouter_au_panier(self, f, offre, quantite):
        f.aller(offre.lien)
        passer_verification(f, self.nom)
        bouton = ".product-price__container .quantity-selector__button--add, .quantity-selector__button--add"
        if not f.attendre("document.querySelector('.quantity-selector__button--add')", 12):
            return 0
        faits = 0
        for _ in range(quantite):
            try:
                f.clic(bouton)
            except ErreurNavigateur:
                break
            faits += 1
            time.sleep(1.6)
        return faits


class Leclerc(Enseigne):
    """E.Leclerc Drive / livraison (leclercdrive.fr). Le site du magasin est propre
    a chaque point de retrait : on le trouve a partir du code postal, puis on
    garde son adresse dans donnees_repas/leclerc.json."""

    nom = "Leclerc"
    _ACCUEIL = "https://www.leclercdrive.fr/"
    _CARTES = r"""
return [...document.querySelectorAll('li.liWCRS310_Product')].slice(0, 24).map(li => {
  const t = s => { const e = li.querySelector(s); return e ? (e.innerText || '').trim() : ''; };
  return {
    lignes: t('a.aWCRS310_Product').split('\n').map(l => l.trim()).filter(Boolean),
    entier: t('.pWCRS310_PrixUnitairePartieEntiere'),
    decimale: t('.pWCRS310_PrixUnitairePartieDecimale'),
    ref: t('.pWCRS310_PrixUniteMesure'),
    disponible: li.dataset.vignette === 'disponible' && !!li.querySelector('a.aWCRS310_Add'),
    promo: [...li.querySelectorAll('.divWCRS310_HG img[alt], .divWCRS310_HD img[alt], [class*=Promo]')]
      .map(e => e.alt || e.innerText || '').join(' ').trim(),
  };
});"""
    # Repere la carte d'un produit par son nom exact (l'ordre des resultats peut bouger).
    _TROUVER = r"""
const voulu = %s;
const li = [...document.querySelectorAll('li.liWCRS310_Product')].find(l => {
  const a = l.querySelector('a.aWCRS310_Product');
  return a && (a.innerText || '').replace(/\s+/g, ' ').trim() === voulu;
});
document.querySelectorAll('[data-jarvis-carte]').forEach(e => e.removeAttribute('data-jarvis-carte'));
if (li) li.setAttribute('data-jarvis-carte', '1');
return !!li;"""

    def __init__(self):
        self._base = ""

    def _memoire(self):
        from repas import stock
        return stock.dossier() / "leclerc.json"

    def preparer(self, f, code_postal):
        import json
        memoire = self._memoire()
        if memoire.exists():
            try:
                connu = json.loads(memoire.read_text(encoding="utf-8"))
                if connu.get("code_postal") == code_postal and connu.get("base"):
                    self._base = connu["base"]
                    return connu.get("contexte", "magasin enregistre")
            except ValueError:
                pass
        f.aller(self._ACCUEIL)
        passer_verification(f, self.nom)
        f.attendre("document.querySelector('#wpad-recherche-magasin-input')", 15)
        fermer_bandeau(f)
        f.saisir("#wpad-recherche-magasin-input", code_postal)
        f.attendre("[...document.querySelectorAll('div,li')].some(e => e.children.length < 3 && "
                   f"/{code_postal}/.test(e.innerText || '') && (e.innerText || '').length < 80 "
                   "&& e.getBoundingClientRect().width > 0)", 10)
        time.sleep(1.0)
        f.js(r"""
const cp = %s;
const s = [...document.querySelectorAll('div,li')].filter(e => e.getBoundingClientRect().width > 0
  && (e.innerText || '').includes(cp) && (e.innerText || '').length < 80).pop();
if (s) for (const t of ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'])
  s.dispatchEvent(new MouseEvent(t, {bubbles: true, cancelable: true, view: window}));"""
             % repr(code_postal))
        lien = "a[href*='courses.leclercdrive.fr/magasin-']"
        if not f.attendre(f"[...document.querySelectorAll(\"{lien}\")].some(a => a.getBoundingClientRect().width > 0)", 15):
            raise ErreurNavigateur("Leclerc : aucun point de retrait propose pour ce code postal.")
        choix = f.js(r"""
const a = [...document.querySelectorAll("a[href*='courses.leclercdrive.fr/magasin-']")]
  .find(a => a.getBoundingClientRect().width > 0);
let c = a;
for (let i = 0; i < 4 && c.parentElement && (c.innerText || '').length < 25; i++) c = c.parentElement;
return {href: a.href, texte: (c.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 80)};""")
        self._base = re.sub(r"\.aspx.*$", "", choix["href"])
        contexte = choix["texte"].replace("Horaires et tarifs", "").strip() or "magasin choisi"
        memoire.write_text(json.dumps({"code_postal": code_postal, "base": self._base,
                                       "contexte": contexte}, ensure_ascii=False),
                           encoding="utf-8")
        return contexte

    def _recherche(self, requete):
        return f"{self._base}/recherche.aspx?TexteRecherche={quote_plus(requete)}"

    def chercher(self, f, requete):
        url = self._recherche(requete)
        f.aller(url)
        passer_verification(f, self.nom)
        f.attendre("document.querySelector('li.liWCRS310_Product') || "
                   "/aucun r[ée]sultat|0 r[ée]sultat|aucun produit/i.test(document.body.innerText)", 12)
        time.sleep(0.8)
        return self._offres_de_la_page(f, url)

    def catalogue(self, f, journal=print):
        url = f"{self._base}/promotions.aspx"          # toutes les promotions sur une page
        f.aller(url)
        passer_verification(f, self.nom)
        f.attendre("document.querySelectorAll('li.liWCRS310_Product').length > 20", 20)
        time.sleep(1.5)
        # Les cartes ne se remplissent (prix, bouton) qu'en arrivant a l'ecran :
        # on fait defiler toute la page, comme un lecteur du catalogue.
        vides = "document.querySelectorAll('li.liWCRS310_Product[data-vignette=vide]').length"
        for _ in range(200):
            fin = f.js("window.scrollBy(0, 1400); return window.innerHeight + window.scrollY"
                       " >= document.documentElement.scrollHeight - 5")
            time.sleep(0.35)
            if fin:
                break
        f.attendre(f"{vides} === 0", 6)
        offres = self._offres_de_la_page(f, url, maxi=3000)
        f.js("window.scrollTo(0, 0)")
        journal(f"    {len(offres)} offres")
        return offres

    def _offres_de_la_page(self, f, url, maxi=24):
        offres = []
        for c in f.js(self._CARTES.replace("slice(0, 24)", f"slice(0, {maxi})")) or []:
            if not c["disponible"] or not c["entier"] or not c["lignes"]:
                continue
            try:
                prix = _nombre(c["entier"] + c["decimale"].replace(" ", ""))
            except ValueError:
                continue
            ref = re.search(r"(\d+(?:[.,]\d+)?)\s?€\s?/\s?(kg|l|pièce|pce|unité|u)\b", c["ref"], re.I)
            unite = ref.group(2).lower() if ref else ""
            detail = " ".join(c["lignes"][1:])
            fmt = re.search(r"(?:\d+\s?x\s?)?\d+(?:[.,]\d+)?\s?(?:kg|g|l|cl|ml)\b|x\s?\d+\b|\d+\s?(?:pièces?|œufs|oeufs)",
                            detail, re.I)
            offres.append(Offre(
                enseigne=self.nom, nom=" ".join(c["lignes"]), prix=prix,
                format=fmt.group(0) if fmt else "",
                prix_ref=_nombre(ref.group(1)) if ref else 0.0,
                unite_ref={"pce": "pièce", "unité": "pièce", "u": "pièce"}.get(unite, unite),
                promo=c["promo"][:80], lien=url))
        return offres

    def _viser(self, f, offre) -> bool:
        """Ouvre la page de recherche de l'offre et marque sa carte."""
        import json
        if "leclercdrive.fr/" not in offre.lien:
            return False
        f.aller(offre.lien)                           # page de recherche ou des promotions
        passer_verification(f, self.nom)
        f.attendre("document.querySelector('li.liWCRS310_Product')", 15)
        time.sleep(0.8)
        if f.js(self._TROUVER % json.dumps(offre.nom)):
            return True
        # Page des promotions : une carte hors ecran n'est qu'une etiquette (debut du
        # nom). On amene a l'ecran celles qui peuvent etre le produit, une par une.
        candidates = f.js(r"""
const voulu = %s;
const vides = [...document.querySelectorAll('li.liWCRS310_Product[data-vignette=vide]')]
  .filter(l => { const t = (l.innerText || '').replace(/\s+/g, ' ').trim();
                 return t.length > 2 && voulu.startsWith(t); });
vides.forEach((l, i) => l.setAttribute('data-jarvis-vide', i));
return vides.length;""" % json.dumps(offre.nom)) or 0
        for i in range(min(candidates, 12)):
            f.js(f"const l = document.querySelector('[data-jarvis-vide=\"{i}\"]');"
                 "if (l) l.scrollIntoView({block: 'center'});")
            f.attendre(f"!document.querySelector('[data-jarvis-vide=\"{i}\"][data-vignette=vide]')", 5)
            time.sleep(0.4)
            if f.js(self._TROUVER % json.dumps(offre.nom)):
                return True
        return False

    def composition(self, f, offre):
        if not self._viser(f, offre):
            return ""
        f.clic("[data-jarvis-carte] a.aWCRS310_Product")
        # La fiche charge ses accordeons apres coup : on attend le texte des ingredients,
        # pas seulement le titre « Ingredients ».
        lire = (r"(() => { if (!/fiche-produits-/.test(location.href)) return ''; "
                r"const t = document.body.textContent.replace(/\s+/g, ' '); "
                r"const m = t.match(/Composition\s+Ingr[ée]dients\s+(.+?)(?:Type d'allerg|Valeurs nutritionnelles|"
                r"Informations pratiques|Conservation|PAYS DE FABRICA|$)/); "
                r"return m ? m[1].replace(/^Ingr[ée]dients\s*:\s*/i, '').trim() : ''; })()")
        f.attendre(lire + ".length > 15", 10)
        return (f.js("return " + lire) or "")[:1500]

    def ajouter_au_panier(self, f, offre, quantite):
        if not self._viser(f, offre):
            return 0
        compte = ("parseInt((document.querySelector('[data-jarvis-carte] .spanWCRS310_count')"
                  " || {innerText: '0'}).innerText) || 0")
        depart = f.js("return " + compte)
        for i in range(quantite):
            visible = f.js("const a = document.querySelector('[data-jarvis-carte] a.aWCRS310_Add');"
                           "return !!a && a.getBoundingClientRect().width > 0")
            try:
                f.clic("[data-jarvis-carte] a.aWCRS310_Add" if visible
                       else "[data-jarvis-carte] a.aWCRS310_More")
            except ErreurNavigateur:
                break
            if not f.attendre(f"({compte}) >= {depart + i + 1}", 8):
                break
        return max(0, f.js("return " + compte) - depart)


ENSEIGNES = {"auchan": Auchan, "leclerc": Leclerc}


def creer(nom: str) -> Enseigne | None:
    cle = re.sub(r"[^a-z]", "", nom.lower().replace("é", "e").replace("è", "e"))
    classe = ENSEIGNES.get(cle)
    return classe() if classe else None

repas/etiquettes.py:
"""Les valeurs nutritionnelles RÉELLES d'un produit du commerce, lues en ligne au lieu d'être devinées
(Taha, 19/11/2026 : le cookie de la boulangerie Auchan avait de fausses macros alors que le site
d'Auchan les donnait).

Deux sources, interrogées en même temps, sans navigateur ni compte :
  - auchan.fr : la page de recherche et les pages produit sont servies en HTML, avec le tableau
    « pour 100 g » et la liste des ingrédients ;
  - Open Food Facts : la base ouverte des étiquettes (produits emballés de toutes les marques).
Chaque résultat garde l'adresse de la page où les chiffres ont été lus. Rien n'est enregistré ici :
l'utilisateur choisit le bon produit et vérifie avant de créer l'ingrédient."""
from __future__ import annotations

import concurrent.futures
import html
import json
import re
import urllib.parse
import urllib.request

from .pdf import normaliser

_NAVIGATEUR = "Mozilla/5.0 (X11; Linux x86_64; rv:130.0) Gecko/20100101 Firefox/130.0"
_OFF = "MonMealPrep/1.0"            # Open Food Facts demande un nom d'application, rien de personnel
_AUCHAN = "https://www.auchan.fr"
_VIDES = {"de", "du", "des", "d", "la", "le", "les", "l", "a", "au", "aux", "en", "et", "avec", "sans", "pour",
          "un", "une", "mon", "ma", "par", "sur"}
ENSEIGNES = {"auchan": "Auchan", "leclerc": "Leclerc", "carrefour": "Carrefour", "lidl": "Lidl", "aldi": "Aldi",
             "intermarche": "Intermarché", "monoprix": "Monoprix", "franprix": "Franprix", "casino": "Casino",
             "super u": "U", "systeme u": "U"}


def _lire(url: str, delai: float = 10, entetes: dict | None = None) -> str:
    requete = urllib.request.Request(url, headers={"User-Agent": _NAVIGATEUR, "Accept-Language": "fr-FR,fr;q=0.9",
                                                    **(entetes or {})})
    with urllib.request.urlopen(requete, timeout=delai) as r:
        return r.read(3_000_000).decode("utf-8", "replace")


def _nombre(texte: str) -> float | None:
    m = re.search(r"(\d+(?:[.,]\d+)?)", texte or "")
    return float(m.group(1).replace(",", ".")) if m else None


def _mots(texte: str) -> list:
    """Les mots qui comptent, au singulier grossier (« cookies » = « cookie »)."""
    return [re.sub(r"(?<=[a-z]{3})[sx]$", "", m) for m in normaliser(texte).split() if len(m) >= 3 and m not in _VIDES]


def ressemblance(tape: str, nom: str) -> float:
    """Part des mots tapés que l'on retrouve dans le nom du produit (0 à 1)."""
    voulus, dans = _mots(tape), set(_mots(nom))
    return sum(1 for m in voulus if m in dans) / len(voulus) if voulus else 0.0


def enseigne_dite(tape: str) -> str:
    n = f" {normaliser(tape)} "
    return next((nom for cle, nom in ENSEIGNES.items() if f" {cle} " in n), "")


# ------------------------------------------------------------------ auchan.fr
def lire_page_auchan(page: str) -> dict | None:
    """{nom, kcal, prot, gluc, lip, fib, portion_g, composition} d'une page produit auchan.fr, ou None
    si la page n'a pas de tableau « pour 100 g »."""
    tables = re.findall(r'<table[^>]*class="nutritionals__table"[^>]*>(.*?)</table>', page, re.S)
    valeurs, portion = None, None
    for t in tables:
        legende = html.unescape(re.sub(r"<[^>]+>", " ", (re.search(r"<caption[^>]*>(.*?)</caption>", t, re.S) or [None, ""])[1]))
        pour = _nombre(re.sub(r".*pour", "", legende, flags=re.I))
        lignes = {}
        for cellules in re.findall(r"<tr[^>]*>(.*?)</tr>", t, re.S):
            c = [html.unescape(re.sub(r"<[^>]+>", " ", x)).strip() for x in re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", cellules, re.S)]
            if len(c) >= 2 and c[1]:
                lignes[re.sub(r"\s+", " ", c[0]).lower()] = c[1]
        if pour == 100:
            valeurs = lignes
        elif pour and not portion:
            portion = pour
    if not valeurs:
        return None

    def cherche(*debuts):
        for libelle, v in valeurs.items():
            if libelle.startswith("dont"):
                continue
            if any(libelle.startswith(d) for d in debuts):
                return _nombre(v)
        return None
    kcal = next((_nombre(v) for l, v in valeurs.items() if "kcal" in l or v.strip().lower().endswith("kcal")), None)
    if kcal is None:
        kj = next((_nombre(v) for l, v in valeurs.items() if "kj" in l), None)
        kcal = round(kj / 4.184) if kj else None
    fiche = {"kcal": kcal, "prot": cherche("protéines", "proteines"), "gluc": cherche("glucides"),
             "lip": cherche("matières grasses", "matieres grasses", "lipides"), "fib": cherche("fibres", "fibre") or 0.0}
    if fiche["kcal"] is None or fiche["prot"] is None:
        return None
    titre = re.search(r'<h1[^>]*>(.*?)</h1>', page, re.S)
    complet = re.search(r'<meta property="og:title" content="([^"]*)"', page)
    marque = html.unescape(complet.group(1)).split()[0].capitalize() if complet else ""
    nom = html.unescape(re.sub(r"<[^>]+>", "", titre.group(1))).strip() if titre else (html.unescape(complet.group(1)) if complet else "")
    compo = re.search(r"Ingr[ée]dients\s*:\s*(.*?)</", html.unescape(page), re.S)
    return {**fiche, "nom": f"{nom} ({marque})" if marque and marque.lower() not in nom.lower() else nom,
            "nom_complet": html.unescape(complet.group(1)) if complet else nom,
            "portion_g": portion, "composition": re.sub(r"\s+", " ", compo.group(1)).strip()[:1500] if compo else ""}


def chercher_auchan(tape: str, maxi: int = 6) -> list:
    # Deux recherches : le texte tel quel, et sans le nom de l'enseigne ni les mots vagues (« boulangerie »
    # fait sortir des ustensiles de cuisine quand aucun magasin n'est choisi).
    vagues = {"auchan", "boulangerie", "rayon", "magasin", "maison"}
    court = " ".join(m for m in normaliser(tape).split() if m not in vagues)
    liens = []
    for q in dict.fromkeys(x for x in (tape, court) if x):
        page = _sans_erreur(lambda: _lire(f"{_AUCHAN}/recherche?text={urllib.parse.quote_plus(q)}")) or ""
        for lien in re.findall(r'href="(/[^"#?]+/pr-[A-Za-z0-9-]+)"', page):
            if lien not in liens:
                liens.append(lien)
    # Le nom du produit est dans l'adresse (« /auchan-cookie-pur-beurre-au-chocolat-noir/pr-C1793416 »).
    notes = sorted(liens, key=lambda l: -ressemblance(tape, l.split("/")[1].replace("-", " ")))
    retenus = [l for l in notes if ressemblance(tape, l.split("/")[1].replace("-", " ")) > 0][:maxi]
    resultats = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool:
        for lien, fiche in zip(retenus, pool.map(lambda l: _sans_erreur(lambda: lire_page_auchan(_lire(_AUCHAN + l))), retenus)):
            if fiche:
                resultats.append({**fiche, "url": _AUCHAN + lien, "source": "auchan.fr"})
    return resultats


# ------------------------------------------------------------------ Open Food Facts
def chercher_off(tape: str, maxi: int = 5) -> list:
    adresse = ("https://world.openfoodfacts.org/cgi/search.pl?" + urllib.parse.urlencode({
        "search_terms": tape, "search_simple": 1, "json": 1, "page_size": 12, "countries_tags_en": "france",
        "fields": "code,product_name_fr,product_name,brands,nutriments,serving_quantity,ingredients_text_fr"}))
    donnees = json.loads(_lire(adresse, entetes={"User-Agent": _OFF}))
    resultats = []
    for p in donnees.get("products") or []:
        n = p.get("nutriments") or {}
        kcal, prot = n.get("energy-kcal_100g"), n.get("proteins_100g")
        nom = (p.get("product_name_fr") or p.get("product_name") or "").strip()
        if kcal is None or prot is None or not nom or not p.get("code"):
            continue
        marque = (p.get("brands") or "").split(",")[0].strip()
        try:
            portion = float(p.get("serving_quantity")) if p.get("serving_quantity") else None
        except (TypeError, ValueError):
            portion = None
        resultats.append({"nom": f"{nom} ({marque})" if marque and marque.lower() not in nom.lower() else nom,
                          "nom_complet": f"{nom} {marque}", "kcal": round(float(kcal)), "prot": float(prot),
                          "gluc": float(n.get("carbohydrates_100g") or 0), "lip": float(n.get("fat_100g") or 0),
                          "fib": float(n.get("fiber_100g") or 0), "portion_g": portion,
                          "composition": (p.get("ingredients_text_fr") or "")[:1500],
                          "url": f"https://fr.openfoodfacts.org/produit/{p['code']}", "source": "Open Food Facts"})
    return sorted(resultats, key=lambda x: -ressemblance(tape, x["nom_complet"]))[:maxi]


def _sans_erreur(f):
    try:
        return f()
    except Exception:                    # page absente, site lent ou change : cette source ne donne rien
        return None


def chercher(tape: str, maxi: int = 5) -> list:
    """Les produits qui ressemblent le plus à ce qui est tapé, avec leurs vraies valeurs pour 100 g :
    [{nom, kcal, prot, gluc, lip, fib, portion_g, composition, url, source, ressemblance}], les plus
    ressemblants d'abord ; à ressemblance égale, ceux de l'enseigne nommée. [] si rien n'est trouvé."""
    tape = re.sub(r"\s+", " ", str(tape or "")).strip()[:80]
    if len(tape) < 3:
        return []
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        auchan, off = pool.submit(_sans_erreur, lambda: chercher_auchan(tape)), pool.submit(_sans_erreur, lambda: chercher_off(tape))
        trouves = (auchan.result() or []) + (off.result() or [])
    dite = enseigne_dite(tape)
    for x in trouves:
        x["ressemblance"] = round(ressemblance(tape, x["nom_complet"]), 2)
    trouves = [x for x in trouves if x["ressemblance"] >= 0.5]
    trouves.sort(key=lambda x: (-x["ressemblance"], not (dite and dite.lower() in (x["source"] + x["nom_complet"]).lower())))
    vus, uniques = set(), []
    for x in trouves:
        cle = (normaliser(x["nom"]), x["kcal"])
        if cle not in vus:
            vus.add(cle)
            uniques.append(x)
    return uniques[:maxi]

repas/export.py:
"""Comptes rendus en PDF : le menu des semaines, la liste de courses, les fiches de cuisine.

Chaque document est une page HTML autonome (styles et photos dedans), convertie en PDF par
Chrome sans fenetre. Rien n'est calcule ici : tout vient de l'etat du site (les memes
chiffres que les pages Semaine, Courses et Cuisine)."""
import base64
import datetime
import html
import shutil
import subprocess
import tempfile
from pathlib import Path

from . import planification as P
from . import stock as mod_stock

