.fiche li { margin-bottom: 2.5pt; }
.pied { margin-top: 14pt; font-size: 8pt; color: #7a7f75; }
"""


def esc(texte) -> str:
    return html.escape(str(texte))


def nombre(v, decimales=0) -> str:
    return f"{v:,.{decimales}f}".replace(",", " ").replace(".", ",")


def quantite(q: float, u: str) -> str:
    """Comme sur le site : grammes entiers, cuilleres et pieces au demi."""
    if u == "qs":
        return "au goût"
    if u in ("g", "ml"):
        q = round(q) if q >= 10 else round(q, 1)
    elif u.startswith("c.à"):
        q = max(0.5, round(q * 2) / 2)
    else:
        q = round(q * 4) / 4
    return f"{mod_stock.fmt(q)} {u}{'s' if u in ('pièce', 'gousse') and q > 1 else ''}"


def _date(jour: datetime.date) -> str:
    mois = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre",
            "novembre", "décembre"][jour.month - 1]
    return f"{jour.day}{'er' if jour.day == 1 else ''} {mois}"


def _periode(plan: dict) -> str:
    if not plan.get("debut"):
        return ""
    debut = datetime.date.fromisoformat(plan["debut"])
    return f"du {_date(debut)} au {_date(debut + datetime.timedelta(days=6))}"


def _jour_date(plan: dict, n: int) -> str:
    nom = plan["jours"][n]["jour"]
    if not plan.get("debut"):
        return nom
    return f"{nom} {_date(datetime.date.fromisoformat(plan['debut']) + datetime.timedelta(days=n))}"


class Contexte:
    """Ce dont les trois documents ont besoin, rassemble une fois par le serveur."""

    def __init__(self, nom, plans, rang, par_id, nutriments, photo, magasin, etat):
        self.nom, self.plans, self.rang = nom, plans, rang          # plans = semaines composees, de la courante a la derniere
        self.par_id, self.nutriments, self.photo = par_id, nutriments, photo
        self.magasin, self.etat = magasin, etat

    def image(self, ident: str, largeur=160) -> str:
        try:
            brut = self.photo(ident, largeur)
        except Exception:
            brut = None
        return f'<img src="data:image/jpeg;base64,{base64.b64encode(brut).decode()}" alt="">' if brut else ""

    def du_jour(self, plan, n, ident, moment=""):
        jour = plan["jours"][n]
        source = plan["jours"][n - 1] if moment == "dej" and jour.get("dej_reste") and n > 0 else jour
        return P.recette_du_jour(self.par_id[ident], source, self.nutriments)


def _page(titre: str, corps: str, ctx: Contexte) -> str:
    return (f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>{esc(titre)}</title><style>{STYLE}</style></head>'
            f'<body>{corps}<p class="pied">Mon Meal Prep, profil {esc(ctx.nom)}. Édité le '
            f'{_date(datetime.date.today())} {datetime.date.today().year} à {datetime.datetime.now():%H h %M}. '
            'Calories et protéines calculées depuis les ingrédients crus.</p></body></html>')


def _repas_du_jour(plan: dict, n: int) -> list:
    j = plan["jours"][n]
    return ([("Matin", j["pdj"], "pdj"), ("Midi", j["dej"], "dej")] + [("Collation", c, "col") for c in j["collations"]]
            + [("Soir", j["din"], "din")])


# ------------------------------------------------------------------ le menu
def menu(ctx: Contexte) -> str:
    corps = []
    for k, plan in enumerate(ctx.plans):
        o, jours = plan["objectif"], [j for j in plan["jours"] if not j.get("retire")]
        moy = lambda cle: round(sum(j.get(cle, 0) for j in jours) / max(1, len(jours)))
        modes = ", ".join(P.NOMS_MODES.get(m, m) for m in plan.get("modes") or [])
        corps.append(f'<div class="{"page" if k else ""}"><h1>Menu de la semaine {ctx.rang + k + 1}</h1>'
                     f'<p class="sous">{esc(ctx.nom)}{", " + _periode(plan) if _periode(plan) else ""}'
                     f'{". Régime " + esc(modes) if modes else ""}.</p>'
                     '<div class="faits">'
                     f'<div class="fait"><b>{nombre(moy("kcal"))} kcal</b><span>par jour en moyenne, pour {nombre(o["kcal"])} visées</span></div>'
                     f'<div class="fait"><b>{moy("prot")} g</b><span>de protéines par jour, pour {o["prot"]} g visés</span></div>'
                     f'<div class="fait"><b>{nombre(plan["cout"], 2)} €</b><span>de repas, pour {nombre(plan["budget_semaine"], 2)} € de budget</span></div>'
                     '</div>')
        bas = [j["jour"].lower() for j in jours if j["prot"] < 0.95 * o["prot"]]
        if bas:
            corps.append(f'<p class="alerte"><b>Protéines sous l\'objectif</b> : {", ".join(bas)}. '
                         'Une collation protéinée ou des quantités ajustées les rattrapent.</p>')
        # vue d'ensemble : une ligne par jour
        lignes = []
        for n, j in enumerate(plan["jours"]):
            nom = lambda ident: "–" if ident == P.RIEN else esc(ctx.par_id[ident]["nom"])
            lignes.append(f'<tr><td><b>{esc(_jour_date(plan, n))}</b></td><td>{nom(j["pdj"])}</td>'
                          f'<td>{nom(j["dej"])}{" <i>(reste)</i>" if j.get("dej_reste") else ""}</td><td>{nom(j["din"])}</td>'
                          f'<td>{"<br>".join(nom(c) for c in j["collations"]) or "–"}</td>'
                          f'<td class="n">{nombre(j["kcal"])}</td><td class="n">{j["prot"]} g</td></tr>')
        corps.append('<h2>En un coup d\'œil</h2><table><tr><th>Jour</th><th>Matin</th><th>Midi</th><th>Soir</th>'
                     '<th>Collations</th><th class="n">kcal</th><th class="n">Prot.</th></tr>' + "".join(lignes) + "</table>")
        corps.append("<h2>Jour par jour, avec les quantités de chaque assiette</h2>"
                     '<p class="sous">Les quantités sont déjà ajustées à l\'objectif du jour : c\'est ce qu\'il y a dans UNE assiette.</p>')
        for n, j in enumerate(plan["jours"]):
            bloc = [f'<div class="jour"><h3>{esc(_jour_date(plan, n))} <span class="chiffres">· {nombre(j["kcal"])} kcal, {j["prot"]} g de protéines'
                    f'{", " + nombre(j["cout"], 2) + " €" if j.get("cout") else ""}</span></h3>']
            if j.get("retire"):
                bloc.append('<p class="sous">Jour mis de côté : rien de prévu.</p>')
            for quand, ident, moment in ([] if j.get("retire") else _repas_du_jour(plan, n)):
                if ident == P.RIEN:
                    bloc.append(f'<div class="repas"><div><div class="quand">{quand}</div><span class="sous">Rien de prévu.</span></div></div>')
                    continue
                r, f = ctx.du_jour(plan, n, ident, moment), P.taille(j, ident, ctx.par_id)   # 1 pour un repas fixe
                notes = []
                if moment == "dej" and j.get("dej_reste"):
                    notes.append("la part gardée d'hier soir")
                if moment == "din" and any(c["id"] == ident and c.get("pour_demain") for c in j["cuisine"]):
                    notes.append("cuisiné en double pour demain midi")
                if (j.get("ajustes") or {}).get(ident):
                    notes.append("quantités ajustées ce jour")
                bloc.append(f'<div class="repas">{ctx.image(ident)}<div><div class="quand">{quand}{" · " + " · ".join(notes) if notes else ""}</div>'
                            f'<b>{esc(r["nom"])}</b> <span class="chiffres">{nombre(r["kcal"] * f)} kcal, {nombre(r["prot"] * f)} g</span>'
                            f'<div class="ing">{", ".join(esc(i["n"]) + " " + quantite(i["q"] * f, i["u"]) for i in r["ing"])}</div></div></div>')
            fruits = [ctx.par_id[i]["nom"] for i in j.get("fruits", []) if i in ctx.par_id]
            if j.get("fruits_secs") and j["fruits_secs"]["id"] in ctx.par_id:
                fruits.append(f'{ctx.par_id[j["fruits_secs"]["id"]]["nom"]} ({j["fruits_secs"]["g"]} g)')
            if fruits:
                bloc.append(f'<p class="ing"><b>Fruits du jour</b> : {esc(", ".join(fruits))}.</p>')
            corps.append("".join(bloc) + "</div>")
        corps.append("</div>")
    return _page("Menu", "".join(corps), ctx)


# ------------------------------------------------------------------ les courses
def _pour_quels_plats(ctx: Contexte) -> dict:
    """{ingredient: [plats qui l'utilisent]} sur les semaines exportees."""
    usages = {}
    for plan in ctx.plans:
        for ident in plan["choix"]:
            for i in ctx.par_id[ident]["ing"]:
                noms = usages.setdefault(i["n"], [])
                if ctx.par_id[ident]["nom"] not in noms:
                    noms.append(ctx.par_id[ident]["nom"])
    return usages


def courses(ctx: Contexte, rayons: list, rayon_de: dict) -> str:
    e, usages = ctx.etat, _pour_quels_plats(ctx)
    c, cm = e.get("courses") or {}, e.get("courses_mois")

    def cases(lignes, q=lambda l: quantite(l.get("acheter", l.get("quantite", 0)), l["unite"]), detail=True):
        def pour(nom):
            plats = usages.get(nom, [])
            return f'<small>pour : {esc(", ".join(p.split(",")[0] for p in plats[:2]))}{" …" if len(plats) > 2 else ""}</small>' if detail and plats else ""
        return '<ul class="cases">' + "".join(
            f'<li><span class="nom">{esc(l["nom"])}{pour(l["nom"])}</span><span class="q">{q(l)}</span></li>' for l in lignes) + "</ul>"

    def par_rayon(lignes):
        blocs = []
        for n, nom in enumerate(rayons):
            du_rayon = [l for l in lignes if rayon_de.get(l["nom"], 2) == n]
            if du_rayon:
                blocs.append(f"<h3>{esc(nom)} <span class=\"chiffres\">· {len(du_rayon)}</span></h3>" + cases(du_rayon))
        return "".join(blocs)

    principal = cm if cm else c
    periode = " et ".join(filter(None, [_periode(ctx.plans[0]), _periode(ctx.plans[-1]) if len(ctx.plans) > 1 else ""]))
    corps = [f'<h1>Liste de courses</h1><p class="sous">{esc(ctx.nom)}, {len(ctx.plans)} semaine{"s" if len(ctx.plans) > 1 else ""}'
             f'{" : " + periode if periode else ""}. Coche au fur et à mesure.</p>']
    estime = (cm or {}).get("estimation") if cm else ((e.get("couts") or {}).get("a_payer") or {}).get("supermarche")
    panier = (cm or {}).get("panier")
    corps.append('<div class="faits">'
                 f'<div class="fait"><b>{len(principal.get("a_acheter", []))}</b><span>produits à acheter chez {esc(ctx.magasin)}</span></div>'
                 f'<div class="fait"><b>{nombre(panier["total"], 2) + " €" if panier else (nombre(estime, 2) + " €" if estime is not None else "–")}</b>'
                 f'<span>{"dans le panier rempli par Jarvis, hors livraison" if panier else "environ, d\'après les prix relevés ou estimés"}</span></div>'
                 f'<div class="fait"><b>{len(principal.get("en_stock", [])) + len(principal.get("coches", []))}</b><span>produits déjà chez toi, non achetés</span></div></div>')
    if principal.get("a_acheter"):
        corps.append(f'<h2>{"Panier " + esc(ctx.magasin) if cm else "À acheter chez " + esc(ctx.magasin)}</h2>'
                     + ('<p class="sous">Rempli par Jarvis pour toutes les semaines : épicerie, frais, surgelés, légumes qui se gardent.</p>' if cm else "")
                     + par_rayon(principal["a_acheter"]))
    if cm and cm.get("hors_panier"):
        corps.append('<h2>À acheter toi-même</h2><p class="sous">Jarvis ne les a pas trouvés ou les a refusés.</p>'
                     + cases(cm["hors_panier"], lambda l: quantite(l["acheter"], l["unite"]) + (f' <small>({esc(l["raison"])})</small>' if l.get("raison") else ""), False))
    if cm:
        marches = [(ctx.rang, c)] + [(x["rang"], x) for x in cm.get("marches_suivants") or []]
        for rang, m in marches:
            plan = ctx.plans[rang - ctx.rang] if 0 <= rang - ctx.rang < len(ctx.plans) else None
            if not (m.get("a_acheter") or m.get("boucher")):
                continue
            corps.append(f'<h2>Marché, semaine {rang + 1}{" (" + _periode(plan) + ")" if plan and _periode(plan) else ""}</h2>'
                         '<p class="sous">Produits frais et viande : à acheter au début de cette semaine-là.</p>')
            if m.get("a_acheter"):
                corps.append("<h3>Fruits et légumes</h3>" + cases(m["a_acheter"]))
            if m.get("boucher"):
                corps.append("<h3>Viande, chez le boucher halal</h3>" + cases(m["boucher"], lambda l: quantite(l["quantite"], l["unite"])))
        fs = cm.get("fruits_secs")
        if fs and (fs.get("acheter") or fs.get("autres")):
            lignes = ([{"nom": fs["nom"], "acheter": fs["acheter"], "unite": "g"}] if fs.get("acheter") else []) + list(fs.get("autres") or [])
            corps.append('<h2>Fruits secs du mois</h2><p class="sous">Dans un magasin près de chez toi, jamais dans le panier en ligne.</p>'
                         + cases(lignes, detail=False))
    elif c.get("boucher"):
        corps.append("<h2>Chez le boucher halal</h2>" + cases(c["boucher"], lambda l: quantite(l["quantite"], l["unite"])))
    deja = list(principal.get("coches", [])) + list(principal.get("en_stock", []))
    if deja:
        corps.append('<h2>Déjà chez toi</h2><p class="sous">Cochés « j\'en ai déjà » ou comptés dans ton stock : rien à acheter.</p><p class="ing">'
                     + esc(", ".join(l["nom"] for l in deja)) + ".</p>")
    return _page("Courses", "".join(corps), ctx)


# ------------------------------------------------------------------ la cuisine
QUAND = {"matin": "Matin", "midi": "Midi", "soir": "Soir", "collation": "Collation"}


def cuisine(ctx: Contexte) -> str:
    corps = []
    for k, plan in enumerate(ctx.plans):
        faits = plan.get("prepares", {})
        corps.append(f'<div class="{"page" if k else ""}"><h1>Fiches de cuisine, semaine {ctx.rang + k + 1}</h1>'
                     f'<p class="sous">{esc(ctx.nom)}{", " + _periode(plan) if _periode(plan) else ""}. '
                     'Les quantités sont celles à cuisiner ce jour-là, déjà ajustées. Le plat du soir se fait en double quand c\'est indiqué : la seconde part est le déjeuner du lendemain.</p>')
        # planning : qui se cuisine quand, et combien de temps
        lignes = []
        for n, j in enumerate(plan["jours"]):
            seances = [s for s in j["cuisine"] if s["quand"] != "fruit"]
            minutes = sum(ctx.par_id[s["id"]].get("temps") or 0 for s in seances)
            lignes.append(f'<tr><td><b>{esc(_jour_date(plan, n))}</b></td><td>'
                          + ("<br>".join(f'{QUAND.get(s["quand"], s["quand"])} : {esc(ctx.par_id[s["id"]]["nom"])}'
                                         f'{" (en double)" if s.get("pour_demain") else ""}'
                                         f'{" ✓" if f"{n}|{s['id']}" in faits else ""}' for s in seances) or "Rien à cuisiner")
                          + f'</td><td class="n">{minutes} min</td></tr>')
        corps.append('<h2>Le planning</h2><table><tr><th>Jour</th><th>À cuisiner</th><th class="n">Temps</th></tr>' + "".join(lignes) + "</table>")
        for n, j in enumerate(plan["jours"]):
            seances = [s for s in j["cuisine"] if s["quand"] != "fruit"]
            if not seances:
                continue
            corps.append(f"<h2>{esc(_jour_date(plan, n))}</h2>")
            if j.get("dej_reste") and j["dej"] != P.RIEN:
                corps.append(f'<p class="sous">Ce midi : {esc(ctx.par_id[j["dej"]]["nom"])}, la part gardée d\'hier soir. À réchauffer.</p>')
            for s in seances:
                r = P.recette_du_jour(ctx.par_id[s["id"]], j, ctx.nutriments)
                f = P.taille(j, s["id"], ctx.par_id)                     # taille d'UNE assiette de ce plat ce jour
                repas = s.get("repas") or max(1, round(s["portions"] / (f or 1)))
                corps.append(
                    f'<div class="fiche"><div class="tete">{ctx.image(s["id"], 480)}<div><h3>{esc(r["nom"])}</h3>'
                    f'<p class="chiffres">{QUAND.get(s["quand"], s["quand"])} · pour {repas} repas'
                    f'{" (ce soir et demain midi)" if s.get("pour_demain") else ""}'
                    f'{" · " + str(r["temps"]) + " min" if r.get("temps") else ""}'
                    f' · {nombre(r["kcal"] * f)} kcal et {nombre(r["prot"] * f)} g de protéines par repas'
                    f'{" · four : " + esc(r["four"]) if r.get("four") else ""}</p></div></div>'
                    '<div class="deux"><div><b>Ingrédients</b><ul>'
                    + "".join(f'<li>{esc(i["n"])} : {quantite(i["q"] * s["portions"], i["u"])}</li>' for i in r["ing"])
                    + "</ul></div><div><b>Préparation</b><ol>" + "".join(f"<li>{esc(e)}</li>" for e in r.get("etapes", []))
                    + "</ol></div></div></div>")
            fruits = [ctx.par_id[i]["nom"] for i in j.get("fruits", []) if i in ctx.par_id]
            if fruits:
                corps.append(f'<p class="ing"><b>À manger aussi</b> : {esc(", ".join(fruits))}.</p>')
        corps.append("</div>")
    return _page("Cuisine", "".join(corps), ctx)


# ------------------------------------------------------------------ HTML -> PDF
def _chrome() -> str:
    for nom in ("google-chrome", "chrome", "chromium", "chromium-browser"):
        trouve = shutil.which(nom)
        if trouve:
            return trouve
    return next((c for c in ("/opt/google/chrome/chrome",) if Path(c).exists()), "")


def en_pdf(page: str, delai: int = 60) -> bytes | None:
    """Le PDF de cette page, imprime par Chrome sans fenetre (profil jetable, rien du Chrome
    de l'utilisateur n'est touche). None si Chrome manque ou echoue : on sert alors le HTML."""
    chrome = _chrome()
    if not chrome:
        return None
    with tempfile.TemporaryDirectory() as dossier:
        source, cible = Path(dossier) / "page.html", Path(dossier) / "page.pdf"
        source.write_text(page, encoding="utf-8")
        try:
            subprocess.run([chrome, "--headless=new", "--disable-gpu", "--no-first-run", "--disable-extensions",
                            f"--user-data-dir={Path(dossier) / 'profil'}", "--no-pdf-header-footer",
                            f"--print-to-pdf={cible}", source.as_uri()],
                           capture_output=True, timeout=delai, check=False)
        except (OSError, subprocess.SubprocessError):
            return None
        return cible.read_bytes() if cible.exists() and cible.stat().st_size > 800 else None

repas/journal_repas.py:
"""Mode flemmard (mode suivi) : ce que l'on a vraiment mangé, noté au jour le jour, sans menu préparé
à l'avance ni courses (Taha, 19/11/2026). On décrit un repas (texte libre, ingrédients, macros
données directement) ou on envoie une photo (l'assiette, une étiquette, un ticket de caisse) ; Claude
en fait une liste d'aliments avec leurs quantités, puis les valeurs sont reprises quand on les connaît
mieux que lui : les aliments du profil et du site (valeurs pour 100 g), et les vraies étiquettes
en ligne pour un produit de marque (repas/etiquettes.py). Rien n'est écrit ici : le serveur enregistre
ce que l'utilisateur a vérifié."""
from __future__ import annotations

import concurrent.futures
import json
import re
import time

from . import etiquettes
from .pdf import normaliser

MACROS = ("kcal", "prot", "gluc", "lip", "fib")
MOMENTS = {"pdj": "Matin", "dej": "Midi", "col": "Collation", "din": "Soir"}
BORNES_100 = {"kcal": 900, "prot": 100, "gluc": 100, "lip": 100, "fib": 100}
SOURCES = {"connu": "tes aliments", "etiquette_photo": "étiquette sur la photo", "facture": "ticket de caisse",
           "donne": "donné par toi", "estimation": "estimation de Claude"}


def _nombre(v, bas=0.0, haut=1e6):
    try:
        v = float(str(v).replace(",", "."))
    except (TypeError, ValueError):
        return None
    return v if bas <= v <= haut else None


def moment_du_moment(heure: int | None = None) -> str:
    """Le repas le plus probable à cette heure : matin, midi, collation ou soir."""
    h = time.localtime().tm_hour if heure is None else heure
    return "pdj" if h < 11 else "dej" if h < 15 else "col" if h < 18 else "din"


def consigne(texte: str, avec_photo: bool, moment: str, connus: dict, plats: list) -> str:
    """La demande faite à Claude. `connus` = {nom: valeurs pour 100 g} (site + aliments créés par
    l'utilisateur) ; `plats` = les plats de l'utilisateur, avec leurs chiffres d'une portion."""
    table = "\n".join(f"- {n} : {v['kcal']:g} kcal, {v['prot']:g} g prot" for n, v in sorted(connus.items()))
    mes_plats = "\n".join(f"- {p['nom']} : une portion = {p['kcal']:g} kcal, {p['prot']:g} g prot "
                          f"({', '.join(i['n'] + ' ' + format(i['q'], 'g') + ' ' + i['u'] for i in p['ing'] if i['u'] != 'qs')})"
                          for p in plats)
    return (
        "Tu aides un utilisateur français à noter ce qu'il mange, pour compter ses calories et ses protéines. "
        "Sois précis et réaliste : c'est son suivi de musculation.\n"
        + (f"Ce qu'il écrit : « {texte} »\n" if texte else "")
        + ("Il a joint une photo : lis le fichier ./photo.jpg (outil Read). Ce peut être son assiette (estime "
           "chaque aliment et son poids), une étiquette (lis le tableau pour 100 g et le poids), ou un ticket de "
           "caisse (les produits achetés : compte ce qu'il a mangé, en général tout le produit, son poids est "
           "souvent dans le nom).\n" if avec_photo else "")
        + f"Repas : {MOMENTS.get(moment, 'non précisé')}.\n\n"
        "Aliments qu'il a déjà dans son application (valeurs pour 100 g crus, ou 100 ml) : quand un aliment "
        "correspond, écris son nom EXACT dans \"connu\".\n" + table + "\n\n"
        + ("Ses propres plats (une portion) : si c'est l'un d'eux, écris son nom exact dans \"plat\" et le nombre "
           "de portions dans \"portions\".\n" + mes_plats + "\n\n" if mes_plats else "")
        + "Règles :\n"
        "- Une ligne par aliment. Poids en grammes mangés (« g »), ou en ml pour un liquide. Un œuf = 55 g, "
        "une tranche de pain = 35 g, une banane = 120 g, un verre = 200 ml.\n"
        "- S'il donne lui-même des chiffres (« 30 g de protéines, 150 kcal »), garde-les tels quels dans "
        "\"total\" et mets \"source\": \"donne\".\n"
        "- Valeurs d'étiquette lues sur la photo : \"source\": \"etiquette_photo\" ; ticket : \"facture\" ; "
        "aliment de la liste : \"connu\" ; sinon \"estimation\" (table CIQUAL).\n"
        "- Produit d'une marque ou d'une enseigne (Auchan, Lidl, Danone, Franprix…) : mets dans \"recherche\" "
        "le nom à chercher en ligne (« skyr nature auchan »), sinon null.\n"
        "- N'invente pas d'aliment qui n'est ni écrit ni visible. S'il manque une information importante "
        "(quantité inconnue…), fais l'estimation la plus probable et dis-le dans \"remarque\".\n\n"
        "Réponds par un objet JSON et rien d'autre :\n"
        "{\"nom\": titre court du repas, \"moment\": \"pdj\"|\"dej\"|\"col\"|\"din\", \"remarque\": phrase courte ou \"\", "
        "\"items\": [{\"nom\": nom court, \"g\": grammes mangés, \"connu\": nom exact ou null, \"plat\": nom exact ou null, "
        "\"portions\": nombre ou null, \"pour100\": {\"kcal\",\"prot\",\"gluc\",\"lip\",\"fib\"} ou null, "
        "\"total\": {\"kcal\",\"prot\",\"gluc\",\"lip\",\"fib\"} ou null, \"source\": \"connu\"|\"etiquette_photo\"|"
        "\"facture\"|\"donne\"|\"estimation\", \"recherche\": texte ou null}]}")


def _valeurs(d, bornes) -> dict | None:
    if not isinstance(d, dict):
        return None
    v = {m: _nombre(d.get(m), 0, bornes.get(m, 10_000) if isinstance(bornes, dict) else bornes) for m in MACROS}
    if v["kcal"] is None or v["prot"] is None:
        return None
    return {m: round(x or 0.0, 1) for m, x in v.items()}


def _total(g: float, pour100: dict) -> dict:
    return {m: round(pour100[m] * g / 100, 1) for m in MACROS}


def ligne(nom: str, g, pour100: dict | None, total: dict | None, source: str, url: str = "") -> dict | None:
    """Un aliment noté : nom, grammes (ou None), valeurs pour 100 g (ou None si seuls les totaux sont
    connus), totaux mangés, d'où viennent les chiffres."""
    g = _nombre(g, 0.1, 5000)
    if pour100 and g:
        total = _total(g, pour100)
    if not total:
        return None
    return {"nom": str(nom or "Aliment")[:80], "g": round(g, 1) if g else None, "pour100": pour100,
            **{m: round(total[m], 1) for m in MACROS}, "source": source, **({"url": url} if url else {})}


def lire_reponse(idee: dict, connus: dict, plats: dict, chercher=None) -> dict:
    """La réponse de Claude, nettoyée et corrigée par ce que l'on connaît mieux que lui."""
    if not isinstance(idee, dict) or not isinstance(idee.get("items"), list):
        raise ValueError("Claude n'a pas compris ce repas : décris-le autrement")
    par_norme = {normaliser(n): n for n in connus}
    plats_norme = {normaliser(p["nom"]): p for p in plats.values()}
    items, a_chercher = [], []
    for x in idee["items"][:25]:
        if not isinstance(x, dict):
            continue
        nom, source = str(x.get("nom") or "").strip(), str(x.get("source") or "estimation")
        plat = plats_norme.get(normaliser(str(x.get("plat") or "")))
        if plat:                                     # un de ses plats : ses chiffres a lui, par portion
            n = _nombre(x.get("portions"), 0.1, 20) or 1
            items.append({"nom": plat["nom"], "g": None, "pour100": None, "portions": n, "plat": plat["id"],
                          **{m: round(plat.get(m, 0) * n, 1) for m in MACROS}, "source": "tes plats"})
            continue
        connu = par_norme.get(normaliser(str(x.get("connu") or "")))
        if connu and source != "donne":
            l = ligne(connu if len(nom) < 3 else nom, x.get("g"), {m: float(connus[connu].get(m, 0)) for m in MACROS},
                      None, SOURCES["connu"])
        else:
            l = ligne(nom, x.get("g"), _valeurs(x.get("pour100"), BORNES_100), _valeurs(x.get("total"), 20_000),
                      SOURCES.get(source, SOURCES["estimation"]))
        if not l:
            continue
        if connu and source != "donne":
            l["aliment"] = connu                     # le nom exact dans tes aliments : le plat du menu le reprend
        items.append(l)
        if x.get("recherche") and source not in ("donne", "etiquette_photo", "connu") and l["g"]:
            a_chercher.append((len(items) - 1, str(x["recherche"])[:80]))
    # Produits de marque : la vraie étiquette en ligne quand elle correspond bien.
    if chercher and a_chercher:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
            trouves = list(pool.map(lambda c: _sans_erreur(lambda: chercher(c[1])), a_chercher[:4]))
        for (k, requete), resultats in zip(a_chercher, trouves):
            meilleur = (resultats or [None])[0]
            dite = etiquettes.enseigne_dite(requete)
            if (meilleur and meilleur.get("ressemblance", 0) >= 0.75
                    and (not dite or dite.lower() in (meilleur["source"] + " " + meilleur["nom_complet"]).lower())):
                pour100 = {m: float(meilleur[m]) for m in MACROS}
                items[k] = ligne(meilleur["nom"], items[k]["g"], pour100, None, "étiquette en ligne", meilleur["url"])
    if not items:
        raise ValueError("aucun aliment reconnu : décris ce que tu as mangé, avec les quantités si tu les connais")
    moment = idee.get("moment") if idee.get("moment") in MOMENTS else None
    return {"nom": str(idee.get("nom") or items[0]["nom"])[:80], "moment": moment, "items": items,
            "remarque": str(idee.get("remarque") or "")[:300], **totaux(items)}


def totaux(items: list) -> dict:
    return {m: round(sum(float(i.get(m) or 0) for i in items), 1) for m in MACROS}


def _sans_erreur(f):
    try:
        return f()
    except Exception:
        return None


def nettoyer_entree(champs: dict) -> dict:
    """Un repas envoyé par la page pour être enregistré : contrôle de chaque aliment (le client a pu
    changer les grammes) ; les totaux sont recalculés ici."""
    date = str(champs.get("date") or time.strftime("%Y-%m-%d"))
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
        raise ValueError("date impossible")
    moment = champs.get("moment") if champs.get("moment") in MOMENTS else moment_du_moment()
    items = []
    for x in (champs.get("items") or [])[:30]:
        if not isinstance(x, dict):
            continue
        pour100 = _valeurs(x.get("pour100"), BORNES_100)
        total = _valeurs(x, 20_000)
        l = ligne(x.get("nom"), x.get("g"), pour100, total, str(x.get("source") or "donné par toi")[:40],
                  str(x.get("url") or "")[:300] if str(x.get("url") or "").startswith("https://") else "")
        if l and x.get("portions"):
            l["portions"] = _nombre(x.get("portions"), 0.1, 20)
        for cle in ("aliment", "plat"):              # d'où vient l'aliment, pour le mettre au menu
            if l and isinstance(x.get(cle), str) and x[cle].strip():
                l[cle] = x[cle].strip()[:80]
        if l:
            items.append(l)
    if not items:
        raise ValueError("ajoute au moins un aliment")
    nom = re.sub(r"\s+", " ", str(champs.get("nom") or "")).strip()[:80] or items[0]["nom"]
    return {"date": date, "moment": moment, "nom": nom, "items": items, **totaux(items)}


def resume_jour(entrees: list, objectif: dict) -> dict:
    """Ce qui est mangé ce jour-là et ce qu'il reste pour tenir l'objectif."""
    t = totaux(entrees)
    return {**t, "reste": {m: round(objectif[m] - t[m]) for m in ("kcal", "prot") if objectif.get(m)}}


def idees_pour_le_reste(reste: dict, recettes: list, deja: set, n: int = 3) -> list:
    """Quelques plats du catalogue qui comblent le mieux ce qu'il reste (calories et protéines)."""
    if reste.get("kcal", 0) < 150:
        return []
    notes = []
    for r in recettes:
        if r.get("cat") not in ("plat", "collation", "petitdej") or not r.get("kcal") or r["id"] in deja or r["id"] == "rien":
            continue
        e = ((r["kcal"] - reste["kcal"]) / max(reste["kcal"], 300)) ** 2 + ((r["prot"] - reste.get("prot", 0)) / 60) ** 2
        notes.append((e, r))
    notes.sort(key=lambda x: x[0])
    return [{"id": r["id"], "nom": r["nom"], "kcal": r["kcal"], "prot": r["prot"]} for _, r in notes[:n]]

repas/navigateur.py:
"""Pilotage de Firefox pour les courses (commande --repas).

Deux modes (reglage `repas.firefox`) :

- `personnel` : TON Firefox, avec ton profil habituel et tes sites deja connectes.
  Firefox n'accepte d'etre pilote que s'il a ete lance avec --marionette : Jarvis
  le lance ainsi s'il est ferme. S'il est deja ouvert sans cette option, il faut
  le fermer d'abord (Jarvis ne le ferme jamais tout seul). Jarvis travaille dans
  un NOUVEL onglet et laisse le navigateur ouvert en partant.
- `dedie` (defaut) : le meme Firefox, mais avec un profil a part
  (~/snap/firefox/common/jarvis-firefox ou ~/.jarvis-firefox), ouvert et referme
  par Jarvis. Ton Firefox habituel n'est pas touche.

Le pilotage passe par geckodriver (fourni avec Firefox) et le protocole WebDriver
standard, parle directement en HTTP : aucune dependance Python en plus.
"""
from __future__ import annotations

import json
import re
import shutil
import socket
import subprocess
import time
from pathlib import Path

import requests

from core.config import reglage

_ELEMENT = "element-6066-11e4-a52e-4f735466cecf"
_PORT_MARIONETTE = 2828          # port par defaut de « firefox --marionette »


class ErreurNavigateur(RuntimeError):
    pass


def dossier_profil() -> Path:
    choisi = str(reglage("repas.profil_firefox", "") or "").strip()
    if choisi:
        d = Path(choisi).expanduser()
    else:
        # Firefox en snap (Ubuntu) ne lit pas les dossiers caches du home.
        snap = Path.home() / "snap" / "firefox" / "common"
        d = (snap if snap.is_dir() else Path.home()) / (
            "jarvis-firefox" if snap.is_dir() else ".jarvis-firefox")
    d.mkdir(parents=True, exist_ok=True)
    return d


def _port_libre() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _port_ouvert(port: int) -> bool:
    with socket.socket() as s:
        s.settimeout(0.5)
        return s.connect_ex(("127.0.0.1", port)) == 0


def firefox_personnel_ouvert() -> bool:
    """Vrai si le Firefox habituel (hors profil dedie de Jarvis) tourne."""
    try:
        p = subprocess.run(["ps", "-eo", "args"], capture_output=True, text=True, timeout=5)
    except (OSError, subprocess.TimeoutExpired):
        return False
    return any(re.search(r"/firefox(\s|$)", l) and "jarvis-firefox" not in l
               and "-contentproc" not in l and "crashhelper" not in l
               for l in p.stdout.splitlines())


def lancer_firefox_personnel(attente: float = 40.0) -> None:
    """S'assure que le Firefox habituel tourne en mode pilotable (--marionette)."""
    if _port_ouvert(_PORT_MARIONETTE):
        return
    if firefox_personnel_ouvert():
        raise ErreurNavigateur(
            "ton Firefox est ouvert mais pas en mode pilotable : ferme-le, puis relance "
            "la commande (Jarvis le rouvrira lui-meme avec --marionette).")
    exe = shutil.which("firefox")
    if not exe:
        raise ErreurNavigateur("Firefox est introuvable sur ce poste.")
    subprocess.Popen([exe, "--marionette"], stdout=subprocess.DEVNULL,
                     stderr=subprocess.DEVNULL, start_new_session=True)
    fin = time.monotonic() + attente
    while time.monotonic() < fin:
        if _port_ouvert(_PORT_MARIONETTE):
            time.sleep(2)
            return
        time.sleep(0.5)
    raise ErreurNavigateur("Firefox n'a pas ouvert son port de pilotage (--marionette).")


class Firefox:
    """Une fenetre Firefox pilotee. A utiliser avec `with Firefox() as f:`."""

    def __init__(self, invisible: bool = False, attente_page: float = 45.0,
                 personnel: bool | None = None):
        if personnel is None:
            personnel = str(reglage("repas.firefox", "dedie") or "").strip().lower() == "personnel"
        self.personnel = personnel
        self.invisible = invisible and not personnel      # ton Firefox est toujours visible
        self.attente_page = attente_page
        self._pilote = None
        self._base = ""
        self._session = ""

    # ------------------------------------------------------------ cycle de vie
    def __enter__(self):
        self.ouvrir()
        return self

    def __exit__(self, *exc):
        self.fermer()

    def ouvrir(self):
        exe = shutil.which("geckodriver") or shutil.which("firefox.geckodriver")
        if not exe:
            raise ErreurNavigateur(
                "geckodriver est introuvable (il est fourni avec Firefox : "
                "« sudo snap install firefox » ou « sudo apt install firefox-geckodriver »).")
        port = _port_libre()
        commande = [exe, "--port", str(port)]
        if self.personnel:
            lancer_firefox_personnel()
            commande += ["--connect-existing", "--marionette-port", str(_PORT_MARIONETTE)]
        self._pilote = subprocess.Popen(
            commande, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self._base = f"http://127.0.0.1:{port}"
        for _ in range(50):
            try:
                if requests.get(self._base + "/status", timeout=1).ok:
                    break
            except requests.RequestException:
                time.sleep(0.1)
        args = ["-profile", str(dossier_profil())]
        if self.invisible:
            args.append("-headless")
        if self.personnel:
            capacites = {"capabilities": {"alwaysMatch": {"pageLoadStrategy": "eager"}}}
        else:
          capacites = {"capabilities": {"alwaysMatch": {
            "browserName": "firefox",
            "pageLoadStrategy": "eager",
            "moz:firefoxOptions": {"args": args, "prefs": {
                "intl.accept_languages": "fr-FR,fr",
                "browser.shell.checkDefaultBrowser": False,
                "browser.aboutwelcome.enabled": False,
                "datareporting.policy.dataSubmissionPolicyBypassNotification": True,
            }}}}}
        try:
            r = requests.post(self._base + "/session", json=capacites, timeout=90)
            valeur = r.json().get("value") or {}
        except (requests.RequestException, ValueError) as e:
            self.fermer()
            raise ErreurNavigateur(f"Firefox n'a pas demarre : {e}") from e
        if "sessionId" not in valeur:
            self.fermer()
            message = str(valeur.get("message", ""))[:300]
            if "lock" in message.lower() or "already running" in message.lower():
                message = ("le Firefox de Jarvis est deja ouvert : ferme sa fenetre puis "
                           "relance la commande.")
            raise ErreurNavigateur(f"Firefox n'a pas demarre : {message}")
        self._session = valeur["sessionId"]
        self._cmd("POST", "/timeouts", {"pageLoad": int(self.attente_page * 1000),
                                        "script": 30000})
        if self.personnel:
            self.nouvel_onglet()                 # on ne touche pas a tes onglets ouverts

    def fermer(self):
        if self._session:
            try:
                requests.delete(f"{self._base}/session/{self._session}", timeout=15)
            except requests.RequestException:
                pass
            self._session = ""
        if self._pilote is not None:
            self._pilote.terminate()
            try:
                self._pilote.wait(timeout=5)
            except subprocess.TimeoutExpired:
                self._pilote.kill()
            self._pilote = None

    # --------------------------------------------------------------- commandes
    def _cmd(self, methode, chemin, corps=None, delai=None):
        try:
            r = requests.request(methode, f"{self._base}/session/{self._session}{chemin}",
                                 json=corps if corps is not None else ({} if methode == "POST" else None),
                                 timeout=delai or self.attente_page + 15)
            donnees = r.json()
        except (requests.RequestException, ValueError) as e:
            raise ErreurNavigateur(f"Firefox ne repond plus : {e}") from e
        valeur = donnees.get("value")
        if isinstance(valeur, dict) and "error" in valeur:
            raise ErreurNavigateur(f"{valeur['error']} : {str(valeur.get('message', ''))[:200]}")
        return valeur

    def aller(self, url: str) -> None:
        """Ouvre l'adresse. Une page lente a finir de charger n'est pas une erreur :
        on travaille avec ce qui est affiche."""
        try:
            self._cmd("POST", "/url", {"url": url})
        except ErreurNavigateur as e:
            if "timeout" not in str(e).lower():
                raise

    def js(self, script: str, *args):
        """Execute du JavaScript dans la page et renvoie sa valeur."""
        return self._cmd("POST", "/execute/sync", {"script": script, "args": list(args)})

    def adresse(self) -> str:
        return self._cmd("GET", "/url") or ""

    def titre(self) -> str:
        return self._cmd("GET", "/title") or ""

    def texte(self, maxi: int = 20000) -> str:
        return (self.js("return document.body ? document.body.innerText : ''") or "")[:maxi]

    def nouvel_onglet(self, url: str = "") -> None:
        poignee = self._cmd("POST", "/window/new", {"type": "tab"})["handle"]
        self._cmd("POST", "/window", {"handle": poignee})
        if url:
            self.aller(url)

    def onglets(self) -> list:
        return self._cmd("GET", "/window/handles") or []

    def _element(self, css: str) -> str:
        return self._cmd("POST", "/element", {"using": "css selector", "value": css})[_ELEMENT]

    def clic(self, css: str) -> None:
        """Vrai clic (souris) sur le premier element qui correspond."""
        self._cmd("POST", f"/element/{self._element(css)}/click")

    def saisir(self, css: str, texte: str, effacer: bool = True) -> None:
        """Tape `texte` au clavier dans le champ."""
        ident = self._element(css)
        if effacer:
            self._cmd("POST", f"/element/{ident}/clear")
        self._cmd("POST", f"/element/{ident}/value", {"text": texte})

    def attendre(self, condition_js: str, delai: float = 10.0, pas: float = 0.4) -> bool:
        """Attend qu'une expression JavaScript devienne vraie."""
        fin = time.monotonic() + delai
        while time.monotonic() < fin:
            try:
                if self.js(f"return !!({condition_js})"):
                    return True
            except ErreurNavigateur:
                pass
            time.sleep(pas)
        return False


class ChromeJarvis:
    """Le navigateur de Jarvis, ouvert COMME JARVIS LE FAIT (tools/navigateur.py) :
    un Chrome normal avec le profil dedie « jarvis-chrome » et son port de debug,
    auquel on se branche. Deja ouvert -> on s'y connecte ; ferme -> Jarvis le lance.
    On travaille dans un nouvel onglet et on laisse Chrome ouvert en partant.

    Meme interface que Firefox (aller, js, clic, saisir, attendre…)."""

    invisible = False
    personnel = False

    def __init__(self, attente_page: float = 45.0, **_):
        self.attente_page = attente_page
        self._page = None

    def __enter__(self):
        self.ouvrir()
        return self

    def __exit__(self, *exc):
        self.fermer()

    def ouvrir(self):
        from tools import navigateur as outil
        from repas import profil as mod_profil
        profil = mod_profil.actif(reglage)
        if chrome_propre(profil):
            # Ce profil a SON Chrome (ses propres comptes d'enseignes).
            navigateur = chrome_du_profil(profil)
            if navigateur is None:
                raise ErreurNavigateur(f"le Chrome du profil « {profil.nom} » n'a pas pu etre ouvert.")
        else:
            navigateur = outil._connexion(auto=True)
        if navigateur is None:
            raise ErreurNavigateur("le Chrome de Jarvis n'a pas pu etre ouvert "
                                   "(voir docs/navigateur.md).")
        try:
            self._page = outil._contexte(navigateur).new_page()
            self._page.set_default_timeout(15000)
        except Exception as e:
            raise ErreurNavigateur(f"Chrome ne repond pas : {e}") from e

    def fermer(self):
        if self._page is not None:
            try:
                self._page.close()
            except Exception:
                pass
            self._page = None

    def _essayer(self, action):
        try:
            return action()
        except Exception as e:
            raise ErreurNavigateur(str(e).split("\n")[0][:200]) from e

    def aller(self, url: str) -> None:
        try:
            self._page.goto(url, wait_until="domcontentloaded",
                            timeout=int(self.attente_page * 1000))
        except Exception as e:
            if "timeout" not in str(e).lower():
                raise ErreurNavigateur(str(e).split("\n")[0][:200]) from e

    def js(self, script: str, *args):
        return self._essayer(lambda: self._page.evaluate("(() => {" + script + "\n})()"))

    def adresse(self) -> str:
        return self._page.url or ""

    def titre(self) -> str:
        return self._essayer(self._page.title) or ""

    def texte(self, maxi: int = 20000) -> str:
        return (self.js("return document.body ? document.body.innerText : ''") or "")[:maxi]

    def nouvel_onglet(self, url: str = "") -> None:
        self._page = self._essayer(self._page.context.new_page)
        if url:
            self.aller(url)

    def _visible(self, css: str):
        """Premier element VISIBLE : certaines pages gardent des doublons caches."""
        visibles = self._page.locator(css).locator("visible=true")
        try:
            if visibles.count():
                return visibles.first
        except Exception:
            pass
        return self._page.locator(css).first

    def clic(self, css: str) -> None:
        """Clic souris ; si un calque gene (bandeau, animation), clic force."""
        cible = self._visible(css)
        try:
            cible.click(timeout=3000)
        except Exception:
            self._essayer(lambda: cible.click(timeout=5000, force=True))

    def saisir(self, css: str, texte: str, effacer: bool = True) -> None:
        # Saisie d'un bloc : tapee lettre a lettre, certaines pages redessinent le
        # champ en cours de frappe et perdent la fin du texte.
        champ = self._visible(css)
        ancien = "" if effacer else self._essayer(champ.input_value)
        self._essayer(lambda: champ.fill(ancien + texte))

    attendre = Firefox.attendre


# ------------------------------------------------------------------ un Chrome par profil
# Chaque profil cree depuis le site a son Chrome : meme programme, mais un dossier
# de donnees et un port de debug a lui. Ses connexions aux enseignes y restent, et
# Jarvis remplit SON panier. Le mot de passe d'une enseigne n'est jamais vu par
# Jarvis : la personne le tape elle-meme dans la fenetre.
CONNEXIONS = {"Auchan": "https://www.auchan.fr/client/accueil",
              "Leclerc": "https://www.leclercdrive.fr/",
              "Intermarché": "https://www.intermarche.com/",
              "Système U": "https://www.coursesu.com/",
              "Casino": "https://www.casino.fr/",
              "Franprix": "https://www.franprix.fr/",
              "Monoprix": "https://www.monoprix.fr/"}
_EXECUTABLES = ("chrome", "google-chrome", "chrome-wrapper", "chromium", "chrome.exe",
                "GoogleChromePortable.exe", "GoogleChromePortable")


def _executable_dans(dossier: Path) -> str:
    for nom in _EXECUTABLES:
        for f in [dossier / nom, *sorted(dossier.glob(f"*/{nom}")), *sorted(dossier.glob(f"*/*/{nom}"))]:
            if f.is_file():
                return str(f)
    return ""


def deployer_chrome(profil) -> str:
    """Programme Chrome a utiliser pour ce profil. Si `repas.chrome_portable` est un
    DOSSIER (Chrome portable), il est copie une fois dans le dossier du profil ; si
    c'est un fichier, il est utilise tel quel ; sinon le Chrome de Jarvis."""
    from tools import navigateur as outil
    source = str(reglage("repas.chrome_portable", "") or "").strip()
    if source:
        chemin = Path(source).expanduser()
        if chemin.is_dir():
            cible = profil.dossier / "chrome-portable"
            if not cible.is_dir():
                import shutil
                shutil.copytree(chemin, cible, symlinks=True)
            trouve = _executable_dans(cible)
            if trouve:
                return trouve
        elif chemin.is_file():
            return str(chemin)
    return outil._chrome_exe() or ""


def chrome_propre(profil) -> bool:
    """Ce profil travaille-t-il dans SON Chrome ? Oui s'il en a un (navigateur.port) et si
    le reglage repas.chrome_par_profil ne l'interdit pas. A false, tous les profils passent
    par le Chrome de Jarvis : un seul navigateur, donc un seul compte et un seul panier par enseigne."""
    return bool(profil.valeur("navigateur.port")) and bool(reglage("repas.chrome_par_profil", True))


def lancer_chrome_profil(profil, adresses=()) -> bool:
    """Ouvre le Chrome du profil (ou y ajoute des onglets s'il tourne deja)."""
    from tools import navigateur as outil
    port = int(profil.valeur("navigateur.port"))
    if outil._port_ouvert(port):
        import urllib.parse
        import urllib.request
        for adresse in adresses:
            try:
                urllib.request.urlopen(urllib.request.Request(
                    f"http://localhost:{port}/json/new?" + urllib.parse.quote(adresse, safe=":/?&="),
                    method="PUT"), timeout=5).close()
            except OSError:
                pass
        return True
    exe = deployer_chrome(profil)
    if not exe:
        return False
    donnees = profil.dossier / str(profil.valeur("navigateur.dossier", "chrome"))
    donnees.mkdir(parents=True, exist_ok=True)
    import subprocess
    try:
        subprocess.Popen([exe, f"--remote-debugging-port={port}", f"--user-data-dir={donnees}",
                          "--no-first-run", "--no-default-browser-check", *adresses],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True)
    except OSError:
        return False
    return True


def chrome_du_profil(profil):
    """Navigateur Playwright branche sur le Chrome du profil (lance au besoin)."""
    from tools import navigateur as outil
    port = int(profil.valeur("navigateur.port"))
    if not lancer_chrome_profil(profil):
        return None
    for _ in range(50):
        if outil._port_ouvert(port):
            navigateur = outil._tenter_cdp(port)
            if navigateur is not None:
                return navigateur
        time.sleep(0.5)
    return None


def ouvrir_connexions(profil) -> list:
    """Ouvre, dans le Chrome du profil, la page de chaque enseigne qu'il utilise :
    la personne s'y connecte elle-meme. Renvoie les enseignes ouvertes."""
    enseignes = [profil.valeur("courses.enseigne_principale", "Auchan"),
                 *(profil.valeur("courses.enseignes_catalogue", []) or [])]
    enseignes = [e for e in dict.fromkeys(enseignes) if e in CONNEXIONS]
    if not chrome_propre(profil):
        return []
    return enseignes if lancer_chrome_profil(profil, [CONNEXIONS[e] for e in enseignes]) else []


def ouvrir_navigateur(invisible: bool = False):
    """Navigateur des courses selon `repas.navigateur` :
    chrome (defaut, comme Jarvis) | firefox (voir repas.firefox)."""
    choix = str(reglage("repas.navigateur", "chrome") or "chrome").strip().lower()
    if choix == "firefox":
        return Firefox(invisible=invisible)
    return ChromeJarvis()

repas/offres.py:
"""Offres de la semaine pour le site « Mon Meal Prep » (commande --repas-offres).

Le site choisit lui-meme les repas selon les meilleures promotions : pour cela
Jarvis ecrit, a cote de la page HTML, un fichier `offres.js` que la page charge
toute seule a l'ouverture (comme photos.js).

Contenu : pour chaque ingredient des recettes du site, la meilleure promotion
trouvee dans les catalogues telecharges (--repas-catalogues), et le vrai prix
releve chez l'enseigne principale quand il est connu (--repas-prix).
"""
from __future__ import annotations

import json
import re
import time
from pathlib import Path

from core.config import reglage
from repas import prix, stock as mod_stock
from repas.enseignes import Offre
from repas.pdf import normaliser

_INGREDIENT = re.compile(r'\{n:"([^"]+)",q:[\d.]+,u:"([^"]+)"')


def chemin_site(argument: str = "") -> Path:
    choisi = argument or str(reglage("repas.site", "") or "")
    return Path(choisi).expanduser()


def ingredients_du_site(html: Path) -> list:
    """Noms des ingredients utilises par les recettes de la page (sans doublon)."""
    vus, noms = set(), []
    for nom, unite in _INGREDIENT.findall(html.read_text(encoding="utf-8")):
        if unite != "qs" and nom not in vus:
            vus.add(nom)
            noms.append(nom)
    return noms


def prix_de_reference(offre: Offre) -> tuple:
    """(prix, 'kg' | 'l' | 'pièce') d'une offre, ou (0, '') si son contenu est inconnu."""
    quantite, unite = prix.contenu(offre)
    if quantite <= 0:
        return 0.0, ""
    if unite == "pièce":
        return round(offre.prix / quantite, 3), "pièce"
    return round(offre.prix / quantite * 1000, 2), "kg" if unite == "g" else "l"


def _fiche(offre: Offre) -> dict | None:
    valeur, par = prix_de_reference(offre)
    if not par:
        return None
    return {"enseigne": offre.enseigne, "produit": offre.nom, "paquet": offre.prix,
            "format": offre.format, "prix": valeur, "par": par, "promo": offre.promo}


def construire(noms: list, exclus, journal=print) -> dict:
    """Meilleure promotion et prix releve pour chaque ingredient du site."""
    d = mod_stock.dossier()
    catalogues = {}
    for fichier in sorted(d.glob("catalogue_*.json")):
        with open(fichier, encoding="utf-8") as h:
            c = json.load(h)
        catalogues[c["enseigne"]] = c
    if not catalogues:
        raise RuntimeError("aucun catalogue telecharge : lance d'abord "
                           "--repas-catalogues Auchan Leclerc.")
    utiles = [n for n in noms if not exclus(n)]

    promos = {}
    for enseigne, c in catalogues.items():
        offres = [Offre(**o) for o in c["offres"]]
        candidats = [(n, prix.dans_le_catalogue(n, offres)) for n in utiles]
        candidats = [(n, o) for n, o in candidats if o]
        journal(f"  {enseigne} : {len(offres)} promotions, {len(candidats)} ingredients "
                "avec des candidats ; tri par Claude…")
        tri = prix.trier_par_claude([(n, "prix au kilo le plus bas", o) for n, o in candidats])
        for k, (nom, liste) in enumerate(candidats):
            fiches = [f for f in (_fiche(liste[j]) for j in tri.get(k, [])) if f]
            if not fiches:
                continue
            meilleure = min(fiches, key=lambda f: f["prix"])
            ancienne = promos.get(nom)
            if ancienne is None or (ancienne["par"] == meilleure["par"]
                                    and meilleure["prix"] < ancienne["prix"]):
                promos[nom] = meilleure

    releves = {}
    for fichier in sorted(d.glob("prix_*.json")):
        with open(fichier, encoding="utf-8") as h:
            r = json.load(h)
        for nom, a in r.get("articles", {}).items():
            if a.get("trouve"):
                fiche = _fiche(Offre(**a["offre"]))
                if fiche:
                    releves[nom] = fiche
    return {
        "genere_le": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "catalogues": {e: {"promotions": len(c["offres"]), "telecharge_le": c["telecharge_le"]}
                       for e, c in catalogues.items()},
        "ingredients": len(utiles),
        "promos": promos,          # meilleure promotion par ingredient
        "prix": releves,           # prix releve chez l'enseigne principale
    }


def ecrire(html: Path, donnees: dict) -> Path:
    # copie pour le site servi par Jarvis (--repas-site)
    with open(mod_stock.dossier() / "offres.json", "w", encoding="utf-8") as h:
        json.dump(donnees, h, ensure_ascii=False, indent=1)
    sortie = html.parent / "offres.js"
    sortie.write_text(
        "/* Ecrit par Jarvis (--repas-offres) : offres de la semaine pour Mon Meal Prep. */\n"
        "window.OFFRES = " + json.dumps(donnees, ensure_ascii=False, indent=1) + ";\n",
        encoding="utf-8")
    return sortie

repas/planification.py:
"""Choix automatique des repas de la semaine (site « Mon Meal Prep » servi par Jarvis).

Chaque repas recoit une note sur des criteres lisibles, puis la semaine est
composee en gardant de la diversite, le budget et l'objectif calorique :

    notes donnees aux plats   -> les plats bien notes reviennent, les mal notes sortent
    stock                     -> les plats dont on a deja les ingredients passent devant
    promotions                -> economie par portion cette semaine
    prix                      -> les plats chers reculent
    objectif                  -> densite en proteines selon la phase du programme
    diversite                 -> pas le meme plat que la semaine d'avant, familles variees

Tout est en fonctions pures (aucun fichier lu ici) : voir repas/serveur.py pour
les donnees et tests/test_repas_site.py.
"""
from __future__ import annotations

import datetime as _dt
import itertools
import math
import re

from repas import base
from repas.pdf import normaliser

PHASES = [
    {"n": 1, "nom": "Recomposition", "jusqu_a": "2027-03", "kcal": 2500, "prot": 190},
    {"n": 2, "nom": "Prise de masse propre", "jusqu_a": "2027-12", "kcal": 3000, "prot": 160},
    {"n": 3, "nom": "Mini-sèche", "jusqu_a": "2028-02", "kcal": 2500, "prot": 200},
    {"n": 4, "nom": "Prise de masse propre 2", "jusqu_a": "2028-08", "kcal": 3100, "prot": 165},
    {"n": 5, "nom": "Sèche finale", "jusqu_a": "2028-11", "kcal": 2600, "prot": 200},
]
POIDS_PIECE = {nom: g / 1000 for nom, g in base.POIDS_ACHAT.items()}      # kg par piece achetee
CUILLERES = base.CUILLERES
FACTEUR_MIN, FACTEUR_MAX = 0.85, 1.4      # taille des portions d'une journee
FAMILLES = [("poisson", ("saumon", "thon", "sardine", "crevette", "colin", "cabillaud", "maquereau", "truite")),
            ("poulet", ("poulet",)), ("boeuf", ("boeuf",)), ("dinde", ("dinde",)),
            ("agneau", ("agneau", "mouton", "merguez")), ("veau", ("veau",)), ("tofu", ("tofu", "tempeh")),
            ("legumineuses", ("lentille", "pois chiche", "haricots rouges", "haricots noirs", "haricots blancs")),
            ("oeufs", ("oeuf",)),
            ("laitage", ("skyr", "fromage blanc", "whey"))]
JOURS = ["Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi", "Dimanche"]


def phase_du_jour(jour: _dt.date | None = None, phases: list | None = None) -> dict:
    """Phase du programme en cours (les phases viennent du profil)."""
    phases = phases or PHASES
    mois = (jour or _dt.date.today()).strftime("%Y-%m")
    return next((p for p in phases if mois <= p["jusqu_a"]), phases[-1])


def famille(recette: dict) -> str:
    """Proteine principale d'un plat, pour varier la semaine."""
    noms = " ".join(normaliser(i["n"]) for i in recette["ing"])
    return next((f for f, mots in FAMILLES if any(m in noms for m in mots)), "autre")


# ------------------------------------------------------------------ quantites
def en_base(nom: str, quantite: float, unite: str) -> tuple:
    """Quantite convertie en (valeur, 'g' | 'ml' | 'pièce' | 'qs')."""
    if unite == "qs":
        return 0.0, "qs"
    if unite in CUILLERES:
        return quantite * CUILLERES[unite], "ml"
    if unite == "gousse":
        return quantite, "pièce"
    return quantite, unite


def convertir(nom: str, quantite: float, de: str, vers: str) -> float | None:
    """Convertit entre g, ml et pièce (poids moyen d'une piece) ; None si impossible."""
    if de == vers or {de, vers} == {"g", "ml"}:
        return quantite
    poids = POIDS_PIECE.get(normaliser(nom))
    if poids is None:
        return None
    if de == "pièce" and vers in ("g", "ml"):
        return quantite * poids * 1000
    if de in ("g", "ml") and vers == "pièce":
        return quantite / (poids * 1000)
    return None


def en_stock(stock: dict, nom: str, quantite: float, unite: str) -> float:
    """Part du besoin (0 a 1) deja couverte par le stock. `stock` = {nom normalise:
    [(quantite, unite), …]}."""
    besoin, base = en_base(nom, quantite, unite)
    lignes = stock.get(normaliser(nom), [])
    if base == "qs":
        return 1.0 if lignes else 0.0
    if besoin <= 0:
        return 0.0
    dispo = 0.0
    for q, u in lignes:
        qb, ub = en_base(nom, q, u)
        c = convertir(nom, qb, ub, base)
        if c is not None:
            dispo += c
    return max(0.0, min(1.0, dispo / besoin))


# ------------------------------------------------------------------ prix
class Tarifs:
    """Prix d'un ingredient : promotion de la semaine, sinon prix releve en magasin,
    sinon estimation. `offres` = contenu de offres.json ({promos, prix})."""

    def __init__(self, estimations: dict, offres: dict | None = None):
        self.estimations = estimations or {}
        offres = offres or {}
        self.promos = offres.get("promos") or {}
        self.releves = offres.get("prix") or {}

    @staticmethod
    def _fiche(ing: dict, fiche: dict | None) -> float | None:
        if not fiche or ing["u"] == "qs":
            return None
        q, u = en_base(ing["n"], ing["q"], ing["u"])
        if u in ("g", "ml") and fiche["par"] in ("kg", "l"):
            return q * fiche["prix"] / 1000
        if u == "pièce" and ing["u"] != "gousse":
            if fiche["par"] == "pièce":
                return q * fiche["prix"]
            poids = POIDS_PIECE.get(normaliser(ing["n"]))
            if fiche["par"] == "kg" and poids:
                return q * poids * fiche["prix"]
        return None

    def estime(self, ing: dict) -> float:
        if ing["u"] == "qs":
            return 0.0
        p = self.estimations.get(ing["n"])
        if isinstance(p, dict):
            p = p.get(ing["u"])
        if not p:
            return 0.0
        return ing["q"] * p / 1000 if ing["u"] in ("g", "ml") else ing["q"] * p

    def normal(self, ing: dict) -> float:
        releve = self._fiche(ing, self.releves.get(ing["n"]))
        return releve if releve is not None else self.estime(ing)

    def cout(self, ing: dict) -> tuple:
        """(cout, economie de promotion) pour la quantite de l'ingredient."""
        normal = self.normal(ing)
        promo = self._fiche(ing, self.promos.get(ing["n"]))
        if promo is not None and promo < normal:
            return promo, normal - promo
        return normal, 0.0

    def recette(self, recette: dict) -> tuple:
        """(cout d'une portion, economie de promotion, ingredients en promotion)."""
        total = eco = 0.0
        en_promo = []
        for ing in recette["ing"]:
            c, e = self.cout(ing)
            total += c
            if e >= 0.03:
                eco += e
                en_promo.append(ing["n"])
        return round(total, 2), round(eco, 2), en_promo


# ------------------------------------------------------------------ notes
def moyenne_des_notes(notes: list) -> dict:
    """{plat: (moyenne, nombre)} a partir de [{plat, note, date}, …]."""
    sommes = {}
    for n in notes or []:
        try:
            valeur = float(n["note"])
        except (KeyError, TypeError, ValueError):
            continue
        if 1 <= valeur <= 5:
            s = sommes.setdefault(n["plat"], [0.0, 0])
            s[0] += valeur
            s[1] += 1
    return {p: (round(s[0] / s[1], 2), s[1]) for p, s in sommes.items()}


# ------------------------------------------------------------------ score
# Valeurs par defaut ; les vraies viennent de ponderation.yaml (voir repas/profil.py).
POIDS_DEFAUT = {"note": 20.0, "jamais_note": 5.0, "stock": 25.0, "stock_seuil": 0.05,
                "promo": 20.0, "promo_max": 15.0, "prix": 6.0, "proteines": 6.0,
                "proteines_max": 15.0, "deja_mange": 30.0, "famille": 8.0,
                "temps": 0.3, "temps_max": 8.0, "vitamines": 20.0,
                "envie": 40.0, "pas_aime": 80.0, "gras": 1.2, "gras_max": 20.0}
GOUTS = ("tester", "non")                 # avis donne dans le catalogue, avant d'avoir goute
COMPOSITION_DEFAUT = {"nb_plats": 7, "nb_petits_dej": 4, "nb_collations": 4,
                      "portion_min": FACTEUR_MIN, "portion_max": FACTEUR_MAX,
                      "collations_max": 3, "seuil_2e_collation": 1.25,
                      "restes_au_dejeuner": 1, "proteines_min": 0.95, "fruits_par_jour": 2, "sortes_de_fruits": 2,
                      "fruits_secs_g": 30}
# Les boutons proposes avant de composer : chaque mode multiplie des criteres
# et/ou impose des valeurs de composition. « fodmap » est un filtre de recettes.
MODES_DEFAUT = {
    "moins_cher": {"criteres": {"prix": 3.0, "promo": 1.5, "stock": 1.5}, "composition": {}},
    "plus_varie": {"criteres": {"deja_mange": 2.0, "famille": 2.5, "jamais_note": 4.0, "note": 0.5},
                   "composition": {"nb_petits_dej": 7, "nb_collations": 6}},
    "fodmap": {"criteres": {}, "composition": {}},
    # flemmard : les repas fixes du profil, sans autre collation, et chaque jour UN plat
    # cuisine une fois et mange midi et soir, choisi pour tomber sur les calories et les proteines.
    "flemmard": {"criteres": {}, "composition": {}},
}
NOMS_MODES = {"moins_cher": "moins cher", "plus_varie": "plus varié", "fodmap": "pauvre en FODMAP", "flemmard": "flemmard"}
REPAS = ("plat", "petitdej", "collation")       # ce qui se choisit comme repas ; « fruit » s'ajoute
VITAMINES = ["A", "B1", "B2", "B6", "B9", "B12", "C", "D", "E", "K"]
FRUITS_DEFAUT = ["Banane", "Kiwi", "Orange", "Clémentine", "Myrtilles", "Framboises",
                 "Pomme", "Poire", "Raisin"]


# ------------------------------------------------------------------ vitamines
def besoins_vitamines(sexe: str = "homme", kcal: float = 2500) -> dict:
    """Besoins quotidiens d'un adulte : references nutritionnelles de l'ANSES (2021).
    B1 et B2 dependent de l'energie depensee (0,14 et 0,17 mg par megajoule) ;
    A, B6 et E dependent du sexe."""
    femme = str(sexe or "").strip().lower().startswith("f")
    megajoules = float(kcal) * 4.184 / 1000
    return {"A": 650 if femme else 750, "B1": round(0.14 * megajoules, 2),
            "B2": round(0.17 * megajoules, 2), "B6": 1.6 if femme else 1.7, "B9": 330,
            "B12": 4, "C": 110, "D": 15, "E": 9 if femme else 10, "K": 79}


def grammes(ing: dict, nutriments: dict) -> float:
    """Poids approximatif d'un ingredient de recette, en grammes (ou millilitres)."""
    q, u = ing["q"], ing["u"]
    if u == "qs":
        return 0.0
    if u in ("g", "ml"):
        return float(q)
    if u in ("pièce", "gousse"):
        nom = "Ail" if u == "gousse" else ing["n"]
        poids = (nutriments.get("poids_piece_g") or {}).get(nom)
        if poids is None:                             # ce qu'on mange d'une piece, pas ce qu'on achete
            poids = base.POIDS_MANGE.get(normaliser(nom), 0)
        return q * poids
    return q * (nutriments.get("poids_cuillere_g") or CUILLERES).get(u, 0)


def vitamines(recette: dict, nutriments: dict | None) -> dict:
    """Vitamines d'UNE portion : {code: quantite} (unites de nutriments.json)."""
    table = (nutriments or {}).get("ingredients") or {}
    total = dict.fromkeys(VITAMINES, 0.0)
    for ing in recette["ing"]:
        fiche = table.get(ing["n"])
        if fiche:
            g = grammes(ing, nutriments)
            for v in VITAMINES:
                total[v] += fiche.get(v, 0) * g / 100
    return {v: round(q, 2) for v, q in total.items()}


MACROS = ("kcal", "prot", "gluc", "lip", "fib")


def macros(recette: dict, nutriments: dict | None) -> dict | None:
    """Calories, proteines, glucides et lipides d'UNE portion, calcules depuis les
    ingredients (table « macros » de nutriments.json, pour 100 g ou 100 ml crus).
    None si un ingredient compte n'est pas dans la table."""
    table = (nutriments or {}).get("macros") or {}
    total = dict.fromkeys(MACROS, 0.0)
    for ing in recette["ing"]:
        if ing["u"] == "qs":
            continue
        fiche = table.get(ing["n"])
        if fiche is None:
            return None
        g = grammes(ing, nutriments)
        for m in MACROS:
            total[m] += fiche[m] * g / 100
    return {m: round(q) for m, q in total.items()}


def crus(recette: dict) -> list:
    """Les legumes manges crus dans cette recette (ecartee du mode pauvre en FODMAP)."""
    return base.legumes_crus(normaliser(recette.get("nom", "")), [normaliser(i["n"]) for i in recette.get("ing", [])])


def filtres(recette: dict, cout: float | None = None) -> dict:
    """Ce qui sert a filtrer le catalogue, DEDUIT de la recette (jamais saisi) :
    regimes (d'apres les ingredients), atouts (d'apres les chiffres), origine, genre,
    proteine principale (la famille qui sert deja a varier la semaine)."""
    interdits = base.interdits([normaliser(i["n"]) for i in recette["ing"]])
    regimes = (["Pauvre en FODMAP"] if recette.get("fodmap") else []) + [
        nom for nom in ("Sans gluten", "Sans lactose", "Végétarien") if not interdits[nom]]
    kcal, prot = recette.get("kcal") or 0, recette.get("prot") or 0
    plat = recette.get("cat") == "plat"
    atouts = []
    if kcal and prot / kcal * 100 >= 7:
        atouts.append("Riche en protéines")
    if (recette.get("fib") or 0) >= (8 if plat else 5):
        atouts.append("Riche en fibres")
    if plat and kcal and kcal <= 550:
        atouts.append("Léger")
    if plat and (recette.get("temps") or 99) <= 20:
        atouts.append("Express")
    if cout is not None and cout <= {"plat": 2.5, "petitdej": 1.8, "collation": 1.0}.get(recette.get("cat"), 0):
        atouts.append("Petit budget")
    if recette.get("four"):
        atouts.append("Au four")
    return {"regimes": regimes, "atouts": atouts, "origine": recette.get("origine") or "",
            "genre": recette.get("genre") or "", "proteine": famille(recette), "cru": bool(crus(recette))}


def couverture(recette: dict, ctx: dict) -> tuple:
    """(indice 0..1, vitamines bien couvertes). Un plat « fait sa part » quand il
    apporte, pour chaque vitamine, la meme part du besoin que sa part des calories."""
    besoins = ctx.get("besoins_vitamines")
    if not besoins or not ctx.get("nutriments"):
        return None, []
    phase = ctx.get("phase") or PHASES[0]
    part = max(1, recette["kcal"]) / phase["kcal"]
    apports = vitamines(recette, ctx["nutriments"])
    ratios = {v: apports[v] / (besoins[v] * part) for v in VITAMINES if besoins.get(v)}
    indice = sum(min(1.0, x) for x in ratios.values()) / max(1, len(ratios))
    fortes = [v for v, x in sorted(ratios.items(), key=lambda kv: -kv[1]) if x >= 1.5][:3]
    return indice, fortes


def evaluer(recette: dict, ctx: dict) -> dict:
    """Score d'une recette et ses raisons, hors diversite dans la semaine.

    ctx : tarifs, stock, notes ({plat: (moyenne, n)}), gouts ({plat: "tester" | "non"}),
    semaines_passees ([[ids]…],
    la plus recente d'abord), phase, mediane ({categorie: cout median}), poids,
    nutriments (table des vitamines) et besoins_vitamines."""
    poids = {**POIDS_DEFAUT, **(ctx.get("poids") or {})}
    cout, eco, en_promo = ctx["tarifs"].recette(recette)
    raisons, score = [], 0.0

    note = ctx.get("notes", {}).get(recette["id"])
    if note:
        points = (note[0] - 3) * poids["note"]
        score += points
        etoiles = str(note[0]).rstrip("0").rstrip(".").replace(".", ",")
        raisons.append({"critere": "note", "points": round(points, 1),
                        "texte": f"noté {etoiles}/5 ({note[1]} fois)"})
    else:
        score += poids["jamais_note"]
        raisons.append({"critere": "note", "points": round(poids["jamais_note"], 1),
                        "texte": "jamais noté : à découvrir"})

    gout = ctx.get("gouts", {}).get(recette["id"])
    if gout == "tester" and poids["envie"]:
        score += poids["envie"]
        raisons.append({"critere": "goût", "points": round(poids["envie"], 1),
                        "texte": "tu veux bien le tester"})
    elif gout == "non" and poids["pas_aime"]:
        score -= poids["pas_aime"]
        raisons.append({"critere": "goût", "points": -round(poids["pas_aime"], 1),
                        "texte": "tu as dit que tu n'aimes pas"})

    avec_prix = [(i, ctx["tarifs"].cout(i)[0]) for i in recette["ing"]]
    total = sum(c for _, c in avec_prix) or 1.0
    couvert = sum(c * en_stock(ctx.get("stock", {}), i["n"], i["q"], i["u"]) for i, c in avec_prix)
    part = couvert / total
    if part >= poids["stock_seuil"]:
        points = part * poids["stock"]
        score += points
        raisons.append({"critere": "stock", "points": round(points, 1),
                        "texte": f"{round(part * 100)} % des ingrédients déjà en stock"})

    if eco > 0:
        points = min(poids["promo_max"], eco * poids["promo"])
        score += points
        raisons.append({"critere": "promo", "points": round(points, 1),
                        "texte": f"en promotion : {', '.join(en_promo)} "
                                 f"(−{eco:.2f} €)".replace(".", ",")})

    mediane = ctx.get("mediane", {}).get(recette["cat"], cout)
    points = -(cout - mediane) * poids["prix"]
    score += points
    if abs(points) >= 2:
        raisons.append({"critere": "prix", "points": round(points, 1),
                        "texte": f"{cout:.2f} € la portion".replace(".", ",")
                                 + (" (bon marché)" if points > 0 else " (plutôt cher)")})

    phase = ctx.get("phase") or PHASES[0]
    densite = recette["prot"] / max(1, recette["kcal"]) * 100          # g pour 100 kcal
    cible = phase["prot"] / phase["kcal"] * 100
    points = max(-poids["proteines_max"],
                 min(poids["proteines_max"], (densite - cible) * poids["proteines"]))
    score += points
    if abs(points) >= 2:
        raisons.append({"critere": "objectif", "points": round(points, 1),
                        "texte": ("riche en protéines pour la phase" if points > 0
                                  else "peu protéiné pour la phase")})

    # Lipides : la phase fixe leur part des calories (70 g a 2500 kcal = 25 %). Un plat plus
    # maigre que cette part gagne des points, un plat plus gras en perd.
    if phase.get("lipides") and recette.get("lip") is not None and recette["kcal"] and poids["gras"]:
        ecart = (phase["lipides"] / phase["kcal"] - recette["lip"] / recette["kcal"]) * 9 * 100      # en points de %
        points = max(-poids["gras_max"], min(poids["gras_max"], ecart * poids["gras"]))
        score += points
        if abs(points) >= 2:
            raisons.append({"critere": "lipides", "points": round(points, 1),
                            "texte": "peu gras pour ta phase" if points > 0 else "gras pour ta phase"})

    indice, fortes = couverture(recette, {**ctx, "phase": phase})
    if indice is not None and poids["vitamines"]:
        points = (indice - 0.5) * 2 * poids["vitamines"]
        score += points
        if abs(points) >= 2:
            texte = (("bonne source de vitamines " + ", ".join(fortes)) if points > 0 and fortes
                     else "couvre bien les vitamines" if points > 0 else "pauvre en vitamines")
            raisons.append({"critere": "vitamines", "points": round(points, 1), "texte": texte})

    # On cuisine chaque jour : un plat long a preparer un soir de semaine coute des points.
    minutes = recette.get("temps")
    if recette["cat"] == "plat" and minutes is not None and poids["temps"]:
        points = max(-poids["temps_max"], min(poids["temps_max"], (30 - minutes) * poids["temps"]))
        score += points
        if abs(points) >= 2:
            raisons.append({"critere": "temps", "points": round(points, 1),
                            "texte": f"{minutes} min de cuisine le jour même"
                                     + (" (rapide)" if points > 0 else " (long)")})

    for rang, semaine in enumerate(ctx.get("semaines_passees", [])[:2]):
        if recette["id"] in semaine:
            points = -poids["deja_mange"] / (rang + 1)
            score += points
            raisons.append({"critere": "diversité", "points": round(points, 1),
                            "texte": "déjà au menu " + ("la semaine dernière" if rang == 0
                                                         else "il y a deux semaines")})
            break
    return {"id": recette["id"], "score": round(score, 1), "cout": cout,
            "economie": eco, "famille": famille(recette), "raisons": raisons}


def _choisir(candidats: list, combien: int, poids_famille: float, deja=()) -> list:
    """Les `combien` meilleurs, en penalisant une famille deja presente."""
    choisis, reste = list(deja), list(candidats)
    pris = []
    while reste and len(pris) < combien:
        compte = {}
        for c in choisis:
            compte[c["famille"]] = compte.get(c["famille"], 0) + 1

        def valeur(c):
            n = compte.get(c["famille"], 0)
            # la penalite grandit vite : 1er doublon x1, 2e x4, 3e x9. Trois plats de la meme
            # famille restent possibles, cinq non.
            return c["score"] - (poids_famille * n * n if c["famille"] != "autre" else 0)
        meilleur = max(reste, key=lambda c: (valeur(c), -c["cout"], c["id"]))
        penalite = meilleur["score"] - valeur(meilleur)
        if penalite:
            meilleur = {**meilleur, "raisons": meilleur["raisons"] + [{
                "critere": "diversité", "points": -round(penalite, 1),
                "texte": f"déjà {compte[meilleur['famille']]} plat(s) « {meilleur['famille']} » cette semaine"}]}
        reste = [c for c in reste if c["id"] != meilleur["id"]]
        pris.append(meilleur)
        choisis.append(meilleur)
    return pris


# ------------------------------------------------------------------ la semaine, jour par jour
# On cuisine CHAQUE JOUR (plus de grande preparation le dimanche). Le plat du soir
# est cuisine en double : la seconde part est le dejeuner du lendemain. Le lundi
# midi, rien ne reste de la veille : le plat du dimanche soir est cuisine a midi.
_MIDIS_FRAIS = [0, 6, 5, 3, 1, 4, 2]       # ou placer un plat de plus quand il y en a plus de 7


def _ordre_des_soirs(plats: list, temps: dict) -> list:
    """Les 7 diners, ordonnes pour (1) ne pas manger deux fois la meme famille le
    meme jour (le midi = le plat de la veille au soir) et (2) garder les plats longs
    a cuisiner pour le samedi, quand il y a du temps."""
    n = len(plats)
    if n < 2:
        return [plats[0]] * 7 if plats else []
    poids_soir = [1, 1, 1, 1, 1, 0, 1]

    def cout(ordre):
        soirs = [ordre[j % n] for j in range(7)]
        doublons = sum(1 for j in range(7)
                       if soirs[j]["famille"] == soirs[j - 1]["famille"] != "autre"
                       and soirs[j]["id"] != soirs[j - 1]["id"])
        return doublons, sum(temps.get(s["id"], 0) * poids_soir[j] for j, s in enumerate(soirs))
    meilleur = min(itertools.permutations(plats), key=cout)
    return [meilleur[j % n] for j in range(7)]


def _repas_de_la_semaine(plats: list, temps: dict, restes: bool) -> list:
    """[(dejeuner, diner, le dejeuner est un reste de la veille)] pour les 7 jours."""
    soirs = _ordre_des_soirs(plats[:7], temps)
    midis = [soirs[j - 1] for j in range(7)]
    reste = [bool(restes) and j > 0 for j in range(7)]
    for rang, extra in zip(_MIDIS_FRAIS, plats[7:]):
        midis[rang], reste[rang] = extra, False
    return [(midis[j]["id"], soirs[j]["id"], reste[j]) for j in range(7)]


def _journee(recettes: dict, ids: dict, cible_kcal: float, tarifs: Tarifs,
             collations_dispo: list, rang: int, regles: dict | None = None,
             fixes=(), imposees: list | None = None, perso=()) -> dict:
    """Un jour : petit-dej, dejeuner, collation(s), diner, les fruits ajoutes
    (`fixes` = [(id, portions)], jamais agrandis) et le facteur de portion qui
    amene la journee sur l'objectif calorique. `imposees` = collations deja
    decidees (pour tenir l'objectif de proteines) : on ne les rechoisit pas.
    `perso` = repas fixes du profil (petit-dejeuner et collations de tous les jours) :
    toujours une portion, jamais agrandis ; ses collations passent avant les autres."""
    regles = {**COMPOSITION_DEFAUT, **(regles or {})}
    perso = list(perso)
    en_plus = [i for i in perso if i != ids["pdj"]]
    # un plat « tel quel » (une banane, un café) ne s'agrandit pas non plus : il compte comme un fixe
    une = set(perso) | {i for i in [ids["pdj"], ids["dej"], ids["din"]] + list(collations_dispo) + list(imposees or [])
                        if i in recettes and recettes[i].get("tel_quel")}
    collations = [collations_dispo[rang % len(collations_dispo)]] if collations_dispo else []
    if imposees is not None:
        collations = list(imposees)
    kcal_fixes = sum(recettes[i]["kcal"] * n for i, n in fixes) + sum(recettes[i]["kcal"] for i in une)
    reste_kcal = max(1.0, cible_kcal - kcal_fixes)

    def total():
        return max(1.0, sum(recettes[i]["kcal"] for i in [ids["pdj"], ids["dej"], ids["din"]] + collations
                            if i not in une))
    # une 2e puis une 3e collation plutot que des assiettes enormes
    while imposees is None and reste_kcal / total() > regles["seuil_2e_collation"] \
            and len(collations) < min(int(regles["collations_max"]), len(collations_dispo)):
        collations.append(collations_dispo[(rang + len(collations) * 2 + 1) % len(collations_dispo)])
        if len(set(collations)) < len(collations):
            collations.pop()
            break
    # Petit objectif calorique : on retire la collation plutot que de depasser, et
    # en dernier recours on descend sous la portion minimale (jamais sous 60 %).
    mini = regles["portion_min"]
    if reste_kcal / total() < mini and imposees is None:
        collations = []
        mini = max(0.6, min(mini, reste_kcal / total()))
    facteur = max(mini, min(regles["portion_max"], reste_kcal / total()))
    facteur = round(facteur * 20) / 20                              # pas de 5 %
    collations = en_plus + [c for c in collations if c not in en_plus]
    tous = [(i, 1 if i in une else facteur) for i in [ids["pdj"], ids["dej"]] + collations + [ids["din"]]] + list(fixes)
    return {"pdj": ids["pdj"], "dej": ids["dej"], "collations": collations, "din": ids["din"],
            "facteur": facteur, "perso": perso,
            "kcal": round(sum(recettes[i]["kcal"] * n for i, n in tous)),
            "prot": round(sum(recettes[i]["prot"] * n for i, n in tous)),
            "gluc": round(sum(recettes[i].get("gluc", 0) * n for i, n in tous)),
            "lip": round(sum(recettes[i].get("lip", 0) * n for i, n in tous)),
            "fib": round(sum(recettes[i].get("fib", 0) * n for i, n in tous)),
            "cout": round(sum(tarifs.recette(recettes[i])[0] * n for i, n in tous), 2)}


def taille_fixe(jour: dict, ident: str, par_id: dict) -> bool:
    """Ce repas ne suit pas le facteur du jour : repas fixe du profil, plat « tel quel », ou plat dont
    l'utilisateur a tapé les quantités pour ce jour (jour["figees"] : elles ne bougent plus)."""
    return (ident in (jour.get("perso") or []) or ident in (jour.get("figees") or {})
            or bool((par_id.get(ident) or {}).get("tel_quel")))


def taille(jour: dict, ident: str, par_id: dict) -> float:
    """La taille d'une assiette de ce plat ce jour-là : celle figée quand ses quantités ont été tapées,
    1 pour un repas fixe ou un plat « tel quel », sinon le facteur du jour."""
    figee = (jour.get("figees") or {}).get(ident)
    if figee:
        return figee
    return 1 if taille_fixe(jour, ident, par_id) else jour["facteur"]


def moments(jour: dict) -> list:
    """[(moment, id)] des repas du jour, dans l'ordre de la journée (les repas retirés sont omis)."""
    out = [("pdj", jour["pdj"]), ("dej", jour["dej"])] + [(f"col{k}", c) for k, c in enumerate(jour["collations"])] \
        + [("din", jour["din"])]
    return [(m, i) for m, i in out if i != RIEN]


def seances_de_cuisine(jours: list, j: int, par_id: dict, fixes=()) -> list:
    """Ce qui se cuisine le jour j : portions (tailles d'assiettes additionnées) et nombre de repas.
    Le dîner fait en double nourrit aussi le midi du lendemain quand celui-ci est un « reste ».
    Une même recette deux fois le même jour (flemmard : midi et soir) devient une seule séance."""
    jour = jours[j]
    t = lambda i, x=jour: taille(x, i, par_id)
    seances = [{"id": jour["pdj"], "portions": t(jour["pdj"]), "quand": "matin", "repas": 1}]
    if not jour.get("dej_reste"):
        seances.append({"id": jour["dej"], "portions": t(jour["dej"]), "quand": "midi", "repas": 1})
    demain = jours[j + 1] if j < 6 and jours[j + 1].get("dej_reste") else None
    seances.append({"id": jour["din"], "quand": "soir", "pour_demain": bool(demain), "repas": 1 + bool(demain),
                    "portions": round(t(jour["din"]) + (t(jour["din"], demain) if demain else 0), 2)})
    seances += [{"id": c, "portions": t(c), "quand": "collation", "repas": 1} for c in jour["collations"]]
    seances += [{"id": i, "portions": n, "quand": "fruit", "repas": 1} for i, n in fixes]
    fusion = {}
    for s in seances:
        if s["id"] == RIEN:
            continue
        if s["id"] in fusion:
            f = fusion[s["id"]]
            f["portions"] = round(f["portions"] + s["portions"], 2)
            f["repas"] += s["repas"]
            if s.get("pour_demain"):
                f["pour_demain"] = True                       # midi, soir et demain midi : on le dit (R-05)
        else:
            fusion[s["id"]] = dict(s)
    return list(fusion.values())


def repas_du_jour(jours: list, j: int, par_id: dict, nutriments: dict | None = None) -> list:
    """Chaque repas du jour tel qu'il se mange : taille de l'assiette, calories et protéines de CETTE assiette
    (quantités ajustées comprises). C'est ce que le site et les PDF affichent ; le total du jour en est la somme."""
    jour = jours[j]
    out = []
    for m, i in moments(jour):
        source = jours[j - 1] if m == "dej" and jour.get("dej_reste") and j > 0 else jour   # le reste suit la veille
        r = recette_du_jour(par_id[i], source, nutriments)
        t = taille(jour, i, par_id)
        out.append({"moment": m, "id": i, "taille": t,
                    **{c: round((r.get(c) or 0) * t, 1) for c in MACROS}})
    return out


def composer(recettes: list, ctx: dict, reglages: dict | None = None) -> dict:
    """La semaine proposee. reglages : kcal, prot, budget_mois, nb_plats (7),
    nb_petits_dej (4), nb_collations (4), exclus ([ids]), modes (moins_cher,
    plus_varie, fodmap)."""
    demande = {k: v for k, v in (reglages or {}).items() if v is not None}
    table = {**MODES_DEFAUT, **(ctx.get("modes") or {})}
    modes = [m for m in demande.get("modes") or [] if m in table]
    poids = {**POIDS_DEFAUT, **(ctx.get("poids") or {})}
    regles = {**COMPOSITION_DEFAUT, **(ctx.get("composition") or {})}
    for cle in ("nb_plats", "nb_petits_dej", "nb_collations", "fruits_secs_g"):   # reglages du site et du profil
        if cle in demande:
            regles[cle] = demande[cle]
    for m in modes:
        for cle, facteur in (table[m].get("criteres") or {}).items():
            poids[cle] = poids.get(cle, 0) * facteur
        regles.update(table[m].get("composition") or {})
    r = {"budget_mois": 300, "exclus": [], **demande,
         "nb_plats": max(2, min(14, int(regles["nb_plats"]))),
         "nb_petits_dej": int(regles["nb_petits_dej"]), "nb_collations": int(regles["nb_collations"])}
    fodmap = "fodmap" in modes
    phase = ctx.get("phase") or phase_du_jour()
    kcal = r.get("kcal") or phase["kcal"]
    par_id = {x["id"]: x for x in recettes}
    tarifs = ctx["tarifs"]
    nutriments = ctx.get("nutriments") or {}
    utiles = [x for x in recettes if x["id"] not in r["exclus"] and x["id"] != "extrariz"
              and (not fodmap or (x.get("fodmap") and not crus(x)))]

    couts = {}
    for x in utiles:
        couts.setdefault(x["cat"], []).append(tarifs.recette(x)[0])
    ctx = {**ctx, "phase": phase, "poids": poids,
           "mediane": {c: sorted(v)[len(v) // 2] for c, v in couts.items()}}
    notes = {x["id"]: evaluer(x, ctx) for x in utiles}

    def meilleurs(cat, combien, poids_famille):
        return _choisir([notes[x["id"]] for x in utiles if x["cat"] == cat],
                        combien, poids_famille)
    plats = meilleurs("plat", r["nb_plats"], poids["famille"])
    fixe = r.get("petit_dej_fixe")      # le meme petit-dejeuner tous les jours (profil)
    if fixe and fixe in notes and par_id[fixe]["cat"] == "petitdej":
        petits_dej = [notes[fixe]]
    else:                               # absent, exclu ou hors du mode FODMAP : choix habituel
        petits_dej = meilleurs("petitdej", r["nb_petits_dej"], poids["famille"])
    perso_col = [i for i in r.get("collations_fixes") or [] if i in par_id and i not in r["exclus"]
                 and par_id[i]["cat"] == "collation"]     # collations de tous les jours (profil)
    for i in perso_col:                 # gardees meme hors du mode choisi (FODMAP) : c'est le profil qui decide
        notes.setdefault(i, evaluer(par_id[i], ctx))
    perso = ([petits_dej[0]["id"]] if fixe and petits_dej[0]["id"] == fixe else []) + perso_col
    collations = [c for c in meilleurs("collation", r["nb_collations"] + len(perso_col), poids["famille"])
                  if c["id"] not in perso_col][:r["nb_collations"]]
    # Fruits : on complete chaque jour jusqu'a `fruits_par_jour`, en comptant ceux
    # deja presents dans les recettes ; les fruits secs sont une option.
    # Les fruits frais s'abiment vite : peu de sortes par semaine (on achete un
    # filet de chaque, pas sept fruits differents), celles qui se gardent d'abord,
    # et les plus fragiles sont mangees en debut de semaine.
    garde = {x["id"]: x.get("conservation", 7) for x in recettes}
    fruits = sorted((notes[x["id"]] for x in utiles if x["cat"] == "fruit" and not x.get("sec")),
                    key=lambda c: (garde[c["id"]] < 7, -c["score"], c["id"]))
    fruits = fruits[:max(1, int(regles["sortes_de_fruits"]))]
    secs = [x for x in utiles if x["cat"] == "fruit" and x.get("sec")]
    sec = (min(secs, key=lambda x: (not x.get("fodmap"), x["id"])) if fodmap
           else min(secs, key=lambda x: (bool(x.get("fodmap")), x["id"]))) if secs else None
    if regles["fruits_secs_g"] <= 0:
        sec = None
    flemmard, possibles_flemmard = "flemmard" in modes, []
    if flemmard:
        collations = []
        # Ce qu'il reste a manger en deux fois (midi et soir) une fois les repas fixes et les fruits ajoutes comptes :
        # les fruits frais qui completent la journee, et les fruits secs seulement s'ils sont demandes (R-04).
        frais = (sum(par_id[c["id"]]["kcal"] for c in fruits) / len(fruits)) * int(regles["fruits_par_jour"]) if fruits else 0
        secs_kcal = par_id[sec["id"]]["kcal"] * regles["fruits_secs_g"] / sec["ing"][0]["q"] if sec else 0
        besoin = max(200.0, (kcal - sum(par_id[i]["kcal"] for i in perso) - frais - secs_kcal) / 2)
        prot_fixes, cible_p = sum(par_id[i]["prot"] for i in perso), r.get("prot") or phase["prot"]

        def pour_flemmard(c):
            x = par_id[c["id"]]
            f = besoin / max(1, x["kcal"])
            if not regles["portion_min"] <= f <= regles["portion_max"]:
                return None
            manque = max(0.0, cible_p * regles["proteines_min"] - prot_fixes - 2 * f * x["prot"])
            if not manque:
                return c
            return {**c, "score": c["score"] - manque * 2, "raisons": c["raisons"] + [{
                "critere": "protéines", "points": -round(manque * 2, 1),
                "texte": f"manque {round(manque)} g de protéines sur la journée en mode flemmard"}]}
        possibles = [y for y in (pour_flemmard(notes[x["id"]]) for x in utiles if x["cat"] == "plat") if y]
        possibles_flemmard = possibles if len(possibles) >= 2 else []
        if len(possibles) >= 2:
            plats = _choisir(possibles, 7, poids["famille"])
    if len(plats) < 2 or not petits_dej:
        raise ValueError("pas assez de recettes pour composer une semaine"
                         + (" pauvre en FODMAP." if fodmap else "."))

    noms_fruits = set(nutriments.get("fruits") or FRUITS_DEFAUT)
    temps = {x["id"]: x.get("temps") or 0 for x in recettes}

    def fixes_du_jour(j, ids):
        deja = sum(1 for i in ids for ing in par_id[i]["ing"] if ing["n"] in noms_fruits)
        manque = max(0, min(len(fruits), int(regles["fruits_par_jour"]) - deja))
        ordre = sorted(fruits, key=lambda c: garde[c["id"]], reverse=j > 3)     # fragiles d'abord
        pris = [(ordre[(j + k) % len(ordre)]["id"], 1) for k in range(manque)]
        if sec:
            pris.append((sec["id"], round(regles["fruits_secs_g"] / sec["ing"][0]["q"], 2)))
        return pris

    # Proteines : chaque jour doit arriver a `proteines_min` x l'objectif. Les
    # calories etant fixees, on y arrive en remplacant ou en ajoutant des collations
    # tres proteinees (skyr, shake, thon, oeufs…), ce qui reduit un peu les assiettes.
    cible_prot = (r.get("prot") or phase["prot"]) * regles["proteines_min"]
    densite = lambda i: par_id[i]["prot"] / max(1, par_id[i]["kcal"])
    denses = [] if flemmard else sorted((x["id"] for x in utiles if x["cat"] == "collation" and densite(x["id"]) >= 0.08
                     and x["id"] not in perso_col),
                    key=lambda i: (-densite(i), i))
    proteines_ajoutees = {}

    def tenir_les_proteines(jour, ids, j, fixes):
        if not denses or jour["prot"] >= cible_prot:
            return jour
        maxi = int(regles["collations_max"])
        ordre = denses[:5][j % min(5, len(denses)):] + denses[:5][:j % min(5, len(denses))] + denses[5:]
        meilleur = jour
        for _ in range(8):
            cols = [c for c in meilleur["collations"] if c not in perso]
            libres = [c for c in ordre if c not in cols]
            if not libres or meilleur["prot"] >= cible_prot:
                break
            essais = []
            for nouvelle in libres[:5]:
                if len(cols) < maxi:
                    essais.append(cols + [nouvelle])
                if cols:
                    faible = min(cols, key=densite)
                    if densite(nouvelle) > densite(faible):
                        essais.append([nouvelle if c == faible else c for c in cols])
            candidats = [_journee(par_id, ids, kcal, tarifs, ids_collations, j, regles, fixes, imposees=e, perso=perso)
                         for e in essais]
            candidats = [c for c in candidats if c["facteur"] >= regles["portion_min"]
                         and abs(c["kcal"] - kcal) <= kcal * 0.06 and c["prot"] > meilleur["prot"]]
            if not candidats:
                break
            # le premier essai qui suffit (pour varier d'un jour a l'autre), sinon le plus proteine
            meilleur = next((c for c in candidats if c["prot"] >= cible_prot),
                            max(candidats, key=lambda c: c["prot"]))
        for c in meilleur["collations"]:
            if c not in jour["collations"]:
                proteines_ajoutees[c] = True
        return meilleur

    budget_semaine = r["budget_mois"] * 7 / 30
    remplacements = []
    ids_collations = [c["id"] for c in collations]

    def jours_de(plats_):
        jours = []
        semaine = ([(plats_[j % len(plats_)]["id"],) * 2 + (False,) for j in range(7)] if flemmard
                   else _repas_de_la_semaine(plats_, temps, regles["restes_au_dejeuner"]))
        for j, (dej, din, reste) in enumerate(semaine):
            ids = {"pdj": petits_dej[j % len(petits_dej)]["id"], "dej": dej, "din": din}
            premiere = ids_collations[j % len(ids_collations)] if ids_collations else None
            fixes = fixes_du_jour(j, [ids["pdj"], dej, din] + perso_col + ([premiere] if premiere else []))
            jour = _journee(par_id, ids, kcal, tarifs, ids_collations, j, regles, fixes, perso=perso)
            jour = tenir_les_proteines(jour, ids, j, fixes)
            jour["fruits"] = [i for i, _ in fixes if not par_id[i].get("sec")]
            jour["fruits_secs"] = ({"id": sec["id"], "g": round(regles["fruits_secs_g"])}
                                   if sec else None)
            jour["dej_reste"] = reste
            jour["_fixes"] = fixes
            jours.append(jour)
        # Ce qui se cuisine chaque jour, et pour combien de repas.
        for j, jour in enumerate(jours):
            jour["cuisine"] = seances_de_cuisine(jours, j, par_id, jour.pop("_fixes"))
        for j, jour in enumerate(jours):
            jour["repas"] = repas_du_jour(jours, j, par_id)
        return jours
    jours = jours_de(plats)
    # Budget : tant que la semaine depasse, le plat le plus cher cede sa place au
    # meilleur plat moins cher qui n'est pas deja au menu. Un plat marque « je veux
    # bien tester » ne sort qu'en dernier : sinon le budget effacerait l'avis.
    a_tester = {i for i, g in (ctx.get("gouts") or {}).items() if g == "tester"}
    # Les proteines passent avant le budget (R-09) : par rapport a la semaine de DEPART (pas a la precedente,
    # sinon de petites baisses s'additionnent), aucun jour de plus sous 95 % de l'objectif (le seuil de l'alerte
    # du site), et le jour le plus faible ne baisse pas de plus de 2 % de l'objectif.
    objectif_p = r.get("prot") or phase["prot"]
    seuil = 0.95 * objectif_p
    depart_min, depart_sous = min(j["prot"] for j in jours), sum(j["prot"] < seuil for j in jours)
    for _ in range(12):
        total = sum(j["cout"] for j in jours)
        if total <= budget_semaine:
            break
        cher = max(plats, key=lambda p: (p["id"] not in a_tester, p["cout"]))
        pris = {p["id"] for p in plats}
        # Le remplacant est le mieux note, moins la penalite de famille : sinon le budget
        # ramene toujours les memes familles bon marche et la semaine perd sa variete.
        familles = {}
        for p in plats:
            if p["id"] != cher["id"]:
                familles[p["famille"]] = familles.get(p["famille"], 0) + 1
        valeur = lambda c: c["score"] - (poids["famille"] * familles.get(c["famille"], 0) ** 2 if c["famille"] != "autre" else 0)
        # Jamais un 3e plat de la meme famille pour gagner quelques centimes : si le budget
        # ne peut pas etre tenu autrement, la semaine le depasse et le site le signale.
        # en mode flemmard, seulement les plats qui tiennent la journee (calories et proteines comptees)
        candidats = possibles_flemmard if flemmard and possibles_flemmard else [notes[x["id"]] for x in utiles if x["cat"] == "plat"]
        moins_chers = sorted((c for c in candidats
                              if c["id"] not in pris and c["cout"] < cher["cout"]
                              and (c["famille"] == "autre" or familles.get(c["famille"], 0) < 2)),
                             key=lambda c: -valeur(c))
        retenu = None
        # Un plat marque « J'aime pas » n'est essaye que s'il n'y a aucun autre remplacant.
        pas_aimes = {i for i, g in (ctx.get("gouts") or {}).items() if g == "non"}
        essais = [c for c in moins_chers if c["id"] not in pas_aimes] or moins_chers
        for c in essais[:6]:
            essai = [c if p["id"] == cher["id"] else p for p in plats]
            essai_jours = jours_de(essai)
            bas = min(j["prot"] for j in essai_jours)
            if sum(j["prot"] < seuil for j in essai_jours) <= depart_sous and bas >= depart_min - 0.02 * objectif_p:
                retenu = (c, essai, essai_jours)
                break
        if not retenu:
            break                                   # budget depasse : la puce « Budget depasse » le dit
        c, plats, jours = retenu
        nouveau = {**c, "raisons": c["raisons"] + [{
            "critere": "budget", "points": 0,
            "texte": f"remplace « {par_id[cher['id']]['nom']} » pour tenir le budget"}]}
        remplacements.append({"sorti": cher["id"], "entre": nouveau["id"]})
        plats = [nouveau if p["id"] == c["id"] else p for p in plats]

    portions = {}
    for j in jours:
        for s in j["cuisine"]:
            portions[s["id"]] = round(portions.get(s["id"], 0) + s["portions"], 2)
    ajoutes = []
    for ident in portions:
        if par_id[ident]["cat"] == "fruit":
            texte = (f"{round(regles['fruits_secs_g'])} g de fruits secs par jour" if par_id[ident].get("sec") else
                     f"ajouté pour arriver à {int(regles['fruits_par_jour'])} fruits par jour")
            ajoutes.append({**notes[ident], "raisons": [{"critere": "fruits", "points": 0, "texte": texte}]})

    # Vitamines de la semaine : apport moyen par jour, compare aux besoins du profil.
    bilan = {}
    besoins = ctx.get("besoins_vitamines")
    if besoins and nutriments:
        somme = dict.fromkeys(VITAMINES, 0.0)
        for ident, n in portions.items():
            for v, q in vitamines(par_id[ident], nutriments).items():
                somme[v] += q * n
        bilan = {v: {"apport": round(somme[v] / 7, 2), "besoin": besoins[v],
                     "pct": round(100 * somme[v] / 7 / besoins[v])} for v in VITAMINES if besoins.get(v)}

    total = round(sum(j["cout"] for j in jours), 2)
    return {
        "phase": phase["n"], "objectif": {"kcal": kcal, "prot": r.get("prot") or phase["prot"]},
        "budget_semaine": round(budget_semaine, 2), "cout": total,
        "dans_le_budget": total <= budget_semaine,
        "modes": modes, "fruits_secs": bool(sec), "vitamines": bilan,
        "jours": [{"jour": JOURS[k], **j} for k, j in enumerate(jours)],
        "choix": {c["id"]: {**c, "portions": portions.get(c["id"], 0)}
                  for c in plats + petits_dej + collations + ajoutes + [
                      {**notes[i], "raisons": notes[i]["raisons"] + [{
                          "critere": "objectif", "points": 0,
                          "texte": "ajouté pour tenir l'objectif de protéines du jour"}]}
                      for i in portions if i not in {x["id"] for x in plats + petits_dej + collations + ajoutes}]
                  if c["id"] in portions},
        "remplacements": remplacements,
    }


# ------------------------------------------------------------------ changer un plat a la main
RIEN = "rien"                             # identifiant de la recette vide : un repas retire
SUPPLEMENTS = ("shakewhey", "skyrnature", "fromageblanc", "oeufsdurs", "thongalettes", "yaourtkiwi")


def modifier(plan: dict, operation: dict) -> None:
    """Applique un changement demande par l'utilisateur, sur place.

    {"type": "changer", "jour": 2, "moment": "din" | "dej" | "pdj" | "col0"…, "plat": id}
    {"type": "cloner", "jour": 4, "depuis": 1}      les repas d'un jour copies sur un autre
    {"type": "ajouter", "jour": 2, "plat": id}      une collation de plus (complement)
    {"type": "ajouter", "jour": 2, "plat": id, "moment": "dej"}
                                                    un plat de plus a ce repas (jour["au_repas"][id] = "dej") :
                                                    autant de plats que l'on veut par repas (Taha, 19/11/2026)
    {"type": "retirer", "jour": 2, "moment": "din"} ce repas-la n'est pas pris (mange ailleurs)
    {"type": "retirer_jour", "jour": 2}             toute la journee, fruits compris
    {"type": "ajuster", "jour": 2, "plat": id, "quantites": {ingredient: q}}
                                                    ce plat, ce jour-la seulement ({} = comme la recette)

    Le dejeuner suit le diner de la veille tant qu'il en est le reste : changer un
    diner change aussi le dejeuner du lendemain ; choisir un autre dejeuner en fait
    un plat cuisine le midi. Une seance deja cuisinee ne se change pas.
    Un repas retire vaut RIEN (recette vide) ; retirer un diner ne retire pas le
    dejeuner du lendemain : il se cuisinera a midi."""
    jours, faits = plan["jours"], plan.get("prepares", {})
    j = int(operation["jour"])
    jour = jours[j]

    flemmard = "flemmard" in (plan.get("modes") or [])

    def libre(numero, ident):
        # En flemmard, « cuisiné » veut dire mangé : un plat mangé se corrige encore (Taha, 19/11/2026).
        if f"{numero}|{ident}" in faits and not flemmard:
            raise ValueError("Ce repas est déjà cuisiné : il ne peut plus changer.")

    def poser_diner(numero, ident):
        libre(numero, jours[numero]["din"])
        jours[numero]["din"] = ident
        if numero < 6 and jours[numero + 1].get("dej_reste"):
            jours[numero + 1]["dej"] = ident                 # le reste du lendemain suit

    def poser_dejeuner(numero, ident):
        if not jours[numero].get("dej_reste"):
            libre(numero, jours[numero]["dej"])
        jours[numero]["dej"] = ident
        # En flemmard, chaque jour cuisine une fois pour son midi et son soir : jamais de « reste de la veille ».
        jours[numero]["dej_reste"] = (numero > 0 and jours[numero - 1]["din"] == ident
                                      and "flemmard" not in (plan.get("modes") or []))

    def retirer(moment):
        if moment == "din":
            libre(j, jour["din"])
            if j < 6 and jours[j + 1].get("dej_reste"):
                jours[j + 1]["dej_reste"] = False            # plus de seconde part : cuisine a midi
            jour["din"] = RIEN
        elif moment == "dej":
            poser_dejeuner(j, RIEN)
            jour["dej_reste"] = False
        elif moment == "pdj":
            libre(j, jour["pdj"])
            jour["pdj"] = RIEN
        elif moment.startswith("col") and moment[3:].isdigit() and int(moment[3:]) < len(jour["collations"]):
            libre(j, jour["collations"][int(moment[3:])])
            del jour["collations"][int(moment[3:])]
            _ranger_au_repas(jour)
        else:
            raise ValueError("repas inconnu")

    if operation["type"] == "ajuster":
        ident = operation["plat"]
        cuisines = [jour["pdj"], jour["din"]] + jour["collations"] + ([] if jour.get("dej_reste") else [jour["dej"]])
        if ident not in cuisines or ident == RIEN:
            raise ValueError("ce plat ne se cuisine pas ce jour-là")
        if "flemmard" not in (plan.get("modes") or []):     # en flemmard, « cuisiné » = mangé : on corrige la quantité mangée
            libre(j, ident)
        quantites = {str(n): q if isinstance(q, dict) else round(float(q), 2) for n, q in (operation.get("quantites") or {}).items()}
        ajustes = jour.setdefault("ajustes", {})
        figees = jour.setdefault("figees", {})
        if quantites:
            ajustes[ident] = quantites
            # Les quantites tapees sont celles d'UNE assiette a cette taille : la taille est figee, sinon
            # un recalage du jour (repas retire…) les ferait changer toutes seules.
            if figees.get(ident) or operation.get("taille"):
                figees[ident] = figees.get(ident) or operation["taille"]
        else:
            ajustes.pop(ident, None)
            figees.pop(ident, None)
        if not figees:
            jour.pop("figees", None)
        if not ajustes:
            jour.pop("ajustes", None)
    elif operation["type"] == "retirer":
        retirer(str(operation.get("moment")))
    elif operation["type"] == "retirer_jour":
        for c in jour["collations"]:
            libre(j, c)
        for moment in ("pdj", "dej", "din"):
            retirer(moment)
        jour["collations"], jour["fruits"] = [], []
        jour.pop("fruits_secs", None)
        jour.pop("au_repas", None)
        jour["retire"] = True
    elif operation["type"] == "changer":
        jour.pop("retire", None)
        moment, ident = str(operation["moment"]), operation["plat"]
        # Mode flemmard : un seul plat cuisiné pour midi et soir ; changer l'un change les deux (R-06),
        # sauf si l'utilisateur a répondu « seulement celui-ci » (operation["ensemble"] = False).
        ensemble = ("flemmard" in (plan.get("modes") or []) and moment in ("dej", "din")
                    and jour["dej"] == jour["din"] != RIEN and not jour.get("dej_reste")
                    and operation.get("ensemble", True) is not False)
        if ensemble:
            poser_dejeuner(j, ident)
            poser_diner(j, ident)
        elif moment == "din":
            poser_diner(j, ident)
        elif moment == "dej":
            poser_dejeuner(j, ident)
        elif moment == "pdj":
            libre(j, jour["pdj"])
            jour["pdj"] = ident
        elif moment.startswith("col") and int(moment[3:]) < len(jour["collations"]):
            ancien = jour["collations"][int(moment[3:])]
            libre(j, ancien)
            jour["collations"][int(moment[3:])] = ident
            place = (jour.get("au_repas") or {}).get(ancien)
            if place:                                        # le plat qui le remplace garde sa place (midi…)
                jour["au_repas"][ident] = place
            _ranger_au_repas(jour)
        else:
            raise ValueError("repas inconnu")
    elif operation["type"] == "cloner":
        source = jours[int(operation["depuis"])]
        if source is jour:
            raise ValueError("choisis un autre jour")
        jour.pop("retire", None)
        for c in jour["collations"] + [jour["pdj"]]:
            libre(j, c)
        jour["pdj"], jour["collations"] = source["pdj"], list(source["collations"])
        jour.pop("au_repas", None)
        if source.get("au_repas"):
            jour["au_repas"] = dict(source["au_repas"])
        if source.get("perso") is not None:
            jour["perso"] = list(source["perso"])           # les repas fixes copiés restent fixes
        poser_dejeuner(j, source["dej"])
        poser_diner(j, source["din"])
    elif operation["type"] == "ajouter":
        jour.pop("retire", None)
        if operation["plat"] not in jour["collations"]:
            jour["collations"].append(operation["plat"])
        place = operation.get("moment")
        if place in ("pdj", "dej", "din"):
            jour.setdefault("au_repas", {})[operation["plat"]] = place
    else:
        raise ValueError("operation inconnue")


def _ranger_au_repas(jour: dict) -> None:
    """Oublie la place (midi, soir…) des plats ajoutes qui ne sont plus au menu."""
    if "au_repas" in jour:
        jour["au_repas"] = {i: m for i, m in (jour["au_repas"] or {}).items() if i in jour["collations"]}
        if not jour["au_repas"]:
            del jour["au_repas"]


def recaler(jour: dict, par_id: dict, cible_kcal: float, regles: dict | None = None) -> float:
    """Recalcule la taille des assiettes d'un jour pour revenir sur l'objectif de calories, une fois des repas
    fixes retirés ou remplacés (comme _journee : bornes portion_min / portion_max, pas de 5 %). Renvoie le facteur."""
    regles = {**COMPOSITION_DEFAUT, **(regles or {})}
    fixes = [(i, 1) for i in jour.get("fruits", [])]
    if jour.get("fruits_secs") and jour["fruits_secs"]["id"] in par_id:
        sec = par_id[jour["fruits_secs"]["id"]]
        fixes.append((sec["id"], jour["fruits_secs"]["g"] / sec["ing"][0]["q"]))
    ids = [i for _, i in moments(jour)]
    chiffres = jour.get("ajustes_chiffres") or {}
    kcal = lambda i: (chiffres.get(i) or par_id[i])["kcal"]         # quantites ajustees ce jour comprises
    figes = sum(kcal(i) * taille(jour, i, par_id) for i in ids if taille_fixe(jour, i, par_id)) \
        + sum(par_id[i]["kcal"] * n for i, n in fixes)
    variables = sum(par_id[i]["kcal"] for i in ids if not taille_fixe(jour, i, par_id))
    if variables <= 0:
        return jour["facteur"]
    f = max(regles["portion_min"], min(regles["portion_max"], (cible_kcal - figes) / variables))
    jour["facteur"] = round(f * 20) / 20
    return jour["facteur"]


def recette_du_jour(recette: dict, jour: dict, nutriments: dict | None = None) -> dict:
    """La recette telle qu'elle se cuisine CE jour-la : avec les quantites ajustees pour ce
    jour seulement (jour["ajustes"] = {recette: {ingredient: quantite d'une portion}}).
    Avec `nutriments`, ses calories et ses macros sont recalcules."""
    quantites = (jour.get("ajustes") or {}).get(recette["id"])
    if not quantites:
        return recette
    return avec_quantites(recette, quantites, nutriments)


def avec_quantites(recette: dict, quantites: dict, nutriments: dict | None = None) -> dict:
    """La recette avec les quantites choisies : {ingredient: quantite d'une portion}. Un ingredient
    a 0 est retire ; un ingredient qui n'etait pas dans la recette vient en plus, avec son unite :
    {nom: {"q", "u", "a"}}. Une premiere etape dit a qui cuisine ce qui a change.
    Avec `nutriments`, calories et macros sont recalculees."""
    ing, sans = [], []
    for i in recette["ing"]:
        q = quantites.get(i["n"]) if i["u"] != "qs" else None
        if isinstance(q, (int, float)):
            if q <= 0:
                sans.append(i["n"])
                continue
            i = {**i, "q": float(q)}
        ing.append(i)
    noms = {i["n"] for i in recette["ing"]}
    plus = [{"n": n, "q": float(v["q"]), "u": v["u"], "a": int(v.get("a", 2))} for n, v in quantites.items()
            if n not in noms and isinstance(v, dict) and float(v.get("q") or 0) > 0]
    ing += plus
    calcul = macros({"ing": ing}, nutriments) if nutriments else None
    etapes = list(recette.get("etapes") or [])
    if sans or plus:
        dit = ([f"sans {', '.join(n.lower() for n in sans)}"] if sans else []) \
              + ([f"avec {', '.join(i['n'].lower() for i in plus)}"] if plus else [])
        etapes = [f"Tes changements : {' ; '.join(dit)}. Cuis-les comme ce qu'ils remplacent."] + etapes
    return {**recette, "ing": ing, **(calcul or {}), "etapes": etapes}


# ------------------------------------------------------------------ viser l'objectif du jour
# « Compléter l'objectif » (Taha, 18/11/2026) : au lieu de régler les grammes à la main, plat par plat,
# Jarvis règle d'un coup les repas pas encore cuisinés pour que la journée tombe sur l'objectif.
# Deux leviers : les ingrédients riches en protéines (viande, poisson, œufs, skyr…) et les autres
# (féculents, légumes, pain…). Les repas fixes, les plats « tel quel », ce qui est déjà cuisiné et
# les cuillères (huile, épices) ne bougent pas.
FACTEURS_OBJECTIF = tuple(x / 20 for x in range(10, 41))        # chaque levier entre 50 % et 200 %


def _kcal_prot(ing: dict, table: dict, nutriments: dict) -> tuple:
    fiche = table.get(ing["n"])
    if not fiche or ing["u"] == "qs":
        return 0.0, 0.0
    g = grammes(ing, nutriments)
    return fiche["kcal"] * g / 100, fiche["prot"] * g / 100


def _arrondir_quantite(q: float, u: str) -> float:
    if u in ("g", "ml"):
        return float(max(5, round(q / 5) * 5)) if q >= 5 else round(q, 1)
    if u == "pièce":
        return max(0.5, round(q * 2) / 2)
    return round(q, 2)


def reglables(plan: dict, j: int, par_id: dict, exclure=(), nutriments: dict | None = None) -> list:
    """Les recettes du jour j dont Jarvis peut régler les quantités pour viser l'objectif. Avec `nutriments`,
    seulement celles dont chaque ingrédient a ses valeurs (sinon, réglées, leurs calories ne suivraient pas)."""
    jour, faits = plan["jours"][j], plan.get("prepares", {})
    ids = []
    for m, i in moments(jour):
        r = par_id.get(i)
        if (m == "dej" and jour.get("dej_reste")) or not r or i in ids or i in exclure:
            continue
        # Tes plats a toi (cafe, cookie, pita…) gardent tes quantites : seules les recettes du site bougent.
        if f"{j}|{i}" in faits or r.get("tel_quel") or r.get("perso") or i in (jour.get("perso") or []):
            continue
        if nutriments is not None and macros(recette_du_jour(r, jour), nutriments) is None:
            continue
        ids.append(i)
    return ids


def reglable_seul(plan: dict, j: int, ident: str, par_id: dict, nutriments: dict | None = None) -> bool:
    """Ce plat du jour j peut-il être rééquilibré à lui seul (bouton « Rééquilibrer » du plat) ? Oui s'il
    se cuisine ce jour-là et pas encore cuisiné, et si chaque ingrédient a ses valeurs. Tes plats à toi
    aussi : c'est toi qui le demandes, pour ce plat-là (Taha, 19/11/2026)."""
    jour, r = plan["jours"][j], par_id.get(ident)
    if not r or ident == RIEN or f"{j}|{ident}" in plan.get("prepares", {}):
        return False
    if not any(i == ident and not (m == "dej" and jour.get("dej_reste")) for m, i in moments(jour)):
        return False                       # le midi « reste » de la veille se règle avec le dîner d'hier
    return nutriments is None or macros(recette_du_jour(r, jour), nutriments) is not None


def viser_objectif(plan: dict, j: int, par_id: dict, nutriments: dict, objectif: dict, recompter,
                   exclure=(), seulement: str | None = None) -> list:
    """Règle sur place (opérations « ajuster ») les recettes réglables du jour j pour que la journée
    tombe au plus près de `objectif` ({"kcal", "prot"}). `recompter()` refait les totaux du plan et
    rend (kcal, prot) du jour. Avec `seulement`, ce plat-là et rien d'autre.
    Renvoie ce qui a changé : [{"plat", "lignes": [{"n", "avant", "apres", "u"}]}]."""
    jour, table = plan["jours"][j], (nutriments or {}).get("macros") or {}
    if seulement is not None:
        ids = [seulement] if reglable_seul(plan, j, seulement, par_id, nutriments or {}) else []
    else:
        ids = reglables(plan, j, par_id, exclure, nutriments or {})
    if not ids or not objectif.get("kcal") or not objectif.get("prot"):
        return []
    avant = {i: {x["n"]: (x["q"], x["u"]) for x in recette_du_jour(par_id[i], jour)["ing"]} for i in ids}
    cumul = {"P": 1.0, "E": 1.0}          # chaque levier reste entre 50 % et 200 % des quantites de depart
    permis = lambda cle: [f for f in FACTEURS_OBJECTIF if 0.499 <= cumul[cle] * f <= 2.001] or [1.0]
    for _ in range(3):                    # le calcul, puis des corrections (arrondis, chiffres des recettes)
        k0, p0 = recompter()
        dk, dp = objectif["kcal"] - k0, objectif["prot"] - p0
        if abs(dk) <= 0.015 * objectif["kcal"] and abs(dp) <= 0.03 * objectif["prot"]:
            break
        leviers, parts = {"P": [0.0, 0.0], "E": [0.0, 0.0]}, []
        for i in ids:
            r, t = recette_du_jour(par_id[i], jour), taille(jour, i, par_id)
            fois = sum(1 for m, x in moments(jour) if x == i and not (m == "dej" and jour.get("dej_reste")))
            # Une fois réglé, un plat compte les calories de ses ingrédients, plus celles de sa fiche :
            # l'écart entre les deux est à combler aussi.
            compte = recette_du_jour(par_id[i], jour, nutriments)
            calcule = [_kcal_prot(x, table, nutriments) for x in r["ing"]]
            dk -= (sum(c[0] for c in calcule) - compte["kcal"]) * t * fois
            dp -= (sum(c[1] for c in calcule) - compte["prot"]) * t * fois
            for ing in r["ing"]:
                if ing["u"] not in ("g", "ml", "pièce"):
                    continue
                k, p = _kcal_prot(ing, table, nutriments)
                if k <= 0:
                    continue
                cle = "P" if p * 4 >= 0.3 * k else "E"
                leviers[cle][0] += k * t * fois
                leviers[cle][1] += p * t * fois
                parts.append((i, ing, cle))
        meilleur = None
        for fp in permis("P") if leviers["P"][0] else (1.0,):
            for fe in permis("E") if leviers["E"][0] else (1.0,):
                k = (fp - 1) * leviers["P"][0] + (fe - 1) * leviers["E"][0]
                p = (fp - 1) * leviers["P"][1] + (fe - 1) * leviers["E"][1]
                ecart = (((k - dk) / objectif["kcal"]) ** 2 + ((p - dp) / objectif["prot"]) ** 2
                         + 0.0004 * ((fp - 1) ** 2 + (fe - 1) ** 2))          # a ecart egal, le moins de changement
                if meilleur is None or ecart < meilleur[0]:
                    meilleur = (ecart, fp, fe)
        _, fp, fe = meilleur
        if fp == 1 and fe == 1:
            break
        cumul["P"] *= fp
        cumul["E"] *= fe
        nouvelles = {}
        for i, ing, cle in parts:
            t = taille(jour, i, par_id)             # arrondi sur l'assiette reelle (5 g, une demi-piece), pas sur la recette de base
            q = round(_arrondir_quantite(ing["q"] * (fp if cle == "P" else fe) * t, ing["u"]) / t, 3)
            if abs(q - ing["q"]) > 1e-6:
                nouvelles.setdefault(i, {})[ing["n"]] = q
        if not nouvelles:
            break
        for i, qs in nouvelles.items():
            dans = {x["n"] for x in par_id[i]["ing"]}
            choisies = dict((jour.get("ajustes") or {}).get(i) or {})
            ajoutes = {x["n"]: x for x in recette_du_jour(par_id[i], jour)["ing"] if x["n"] not in dans}
            for n, q in qs.items():
                choisies[n] = q if n in dans else {"q": q, "u": ajoutes[n]["u"], "a": int(ajoutes[n].get("a", 2))}
            modifier(plan, {"type": "ajuster", "jour": j, "plat": i, "quantites": choisies, "taille": taille(jour, i, par_id)})
    recompter()
    changes = []
    for i in ids:
        apres = {x["n"]: (x["q"], x["u"]) for x in recette_du_jour(par_id[i], jour)["ing"]}
        lignes = [{"n": n, "avant": avant[i].get(n, (0, u))[0], "apres": q, "u": u}
                  for n, (q, u) in apres.items() if u != "qs" and abs(q - avant[i].get(n, (0, u))[0]) > 1e-6]
        if lignes:
            changes.append({"plat": i, "taille": taille(jour, i, par_id), "lignes": lignes})
    return changes


def recalculer(plan: dict, recettes: list, ctx: dict) -> dict:
    """Refait les totaux d'une semaine dont les repas ont ete changes a la main :
    calories, proteines et cout de chaque jour, seances de cuisine, portions des
    courses, vitamines. La taille des portions (facteur) de chaque jour ne bouge pas."""
    par_id = {x["id"]: x for x in recettes}
    tarifs, nutriments = ctx["tarifs"], ctx.get("nutriments") or {}
    jours = plan["jours"]
    for jour in jours:              # un repas fixe remplacé ou retiré n'est plus un repas fixe (R-03)
        _ranger_au_repas(jour)
        if jour.get("perso") is not None:
            menu = {i for _, i in moments(jour)}
            jour["perso"] = [i for i in jour["perso"] if i in menu]
    for rang, jour in enumerate(jours):
        f = jour["facteur"]
        fixes = [(i, 1) for i in jour.get("fruits", [])]
        if jour.get("fruits_secs"):
            sec = par_id[jour["fruits_secs"]["id"]]
            fixes.append((sec["id"], round(jour["fruits_secs"]["g"] / sec["ing"][0]["q"], 2)))
        # Chaque repas avec les quantites du jour ou il est cuisine : le dejeuner « reste »
        # suit le diner de la veille, ajustements compris.
        veille = jours[rang - 1] if rang and jour.get("dej_reste") else jour
        du_jour = {i for i in [jour["pdj"], jour["din"]] + jour["collations"]} | ({jour["dej"]} if veille is jour else set())
        if jour.get("ajustes"):
            jour["ajustes"] = {i: q for i, q in jour["ajustes"].items() if i in du_jour and i in par_id}
            if not jour["ajustes"]:
                del jour["ajustes"]
        if jour.get("figees"):
            jour["figees"] = {i: t for i, t in jour["figees"].items() if i in (jour.get("ajustes") or {})}
            if not jour["figees"]:
                del jour["figees"]
        # Les totaux sont la somme des assiettes telles qu'elles s'affichent (repas_du_jour), plus les fruits.
        vraies = [(recette_du_jour(par_id[i], veille if m == "dej" else jour, nutriments), taille(jour, i, par_id))
                  for m, i in moments(jour)] + [(par_id[i], n) for i, n in fixes]
        jour["kcal"] = round(sum(r["kcal"] * n for r, n in vraies))
        jour["prot"] = round(sum(r["prot"] * n for r, n in vraies))
        jour["gluc"] = round(sum(r.get("gluc", 0) * n for r, n in vraies))
        jour["lip"] = round(sum(r.get("lip", 0) * n for r, n in vraies))
        jour["fib"] = round(sum(r.get("fib", 0) * n for r, n in vraies))
        jour["cout"] = round(sum(tarifs.recette(r)[0] * n for r, n in vraies), 2)
        # pour la page : les chiffres d'une portion des recettes ajustees ce jour-la
        jour.pop("ajustes_chiffres", None)
        if jour.get("ajustes"):
            jour["ajustes_chiffres"] = {i: {m: recette_du_jour(par_id[i], jour, nutriments).get(m, 0) for m in MACROS}
                                        for i in jour["ajustes"]}
        jour["_fixes"] = fixes
    for j, jour in enumerate(jours):
        jour["cuisine"] = seances_de_cuisine(jours, j, par_id, jour.pop("_fixes"))
    for j, jour in enumerate(jours):
        jour["repas"] = repas_du_jour(jours, j, par_id, nutriments)
    portions = {}
    for jour in jours:
        for s in jour["cuisine"]:
            portions[s["id"]] = round(portions.get(s["id"], 0) + s["portions"], 2)
    choix = {}
    for ident, n in portions.items():
        if ident in plan["choix"]:
            choix[ident] = {**plan["choix"][ident], "portions": n}
        else:
            note = evaluer(par_id[ident], ctx)
            choix[ident] = {**note, "portions": n, "raisons": [
                {"critere": "choix", "points": 0, "texte": "choisi par toi"}] + note["raisons"]}
    plan["choix"] = choix
    besoins = ctx.get("besoins_vitamines")
    if besoins and nutriments:
        somme = dict.fromkeys(VITAMINES, 0.0)
        for ident, n in portions.items():
            for v, q in vitamines(par_id[ident], nutriments).items():
                somme[v] += q * n
        plan["vitamines"] = {v: {"apport": round(somme[v] / 7, 2), "besoin": besoins[v],
                                 "pct": round(100 * somme[v] / 7 / besoins[v])}
                             for v in VITAMINES if besoins.get(v)}
    plan["cout"] = round(sum(jour["cout"] for jour in jours), 2)
    plan["dans_le_budget"] = plan["cout"] <= plan.get("budget_semaine", plan["cout"])
    return plan


# ------------------------------------------------------------------ ou s'achete chaque produit
# Quand plusieurs semaines sont composees d'un coup (courses.semaines_par_commande) :
#   "commande"     le panier du supermarche, rempli par Jarvis pour toutes ces semaines
#   "marche"       chaque semaine au marche : viande, poisson, fruits et legumes frais
#   "fruits_secs"  une fois par mois dans un magasin proche
# Rayons : 0 viande et poisson, 1 fruits et legumes, 2 epicerie, 3 frais, 4 surgeles.
LEGUMES_QUI_SE_GARDENT = {"oignon", "oignon rouge", "ail", "pommes de terre", "patate douce",
                          "carotte", "panais", "gingembre frais"}
FRUITS_SECS = ("fruits secs", "oleagineux", "noix", "amandes", "cacahuetes", "noisettes", "pistaches",
               "dattes", "raisins secs")       # « noix » couvre aussi les noix de cajou


def lieu_d_achat(nom: str, rayon: int) -> str:
    n = normaliser(re.sub(r"\([^)]*\)", "", nom)).strip()
    if n.startswith(FRUITS_SECS):
        return "fruits_secs"
    if rayon == 0:
        return "marche"
    if rayon == 1:
        return "commande" if n in LEGUMES_QUI_SE_GARDENT else "marche"
    return "commande"


def besoins(plan: dict, recettes: list, restants: bool = False) -> list:
    """Ingredients de la semaine, additionnes seance par seance (portions x facteur de
    chaque jour, et quantites ajustees pour un jour quand il y en a).
    `restants` : seulement ce qui n'est pas encore cuisine."""
    par_id = {x["id"]: x for x in recettes}
    faits = plan.get("prepares", {}) if restants else {}
    if all("cuisine" in j for j in plan["jours"]):
        seances = [(recette_du_jour(par_id[s["id"]], j), s["portions"]) for n, j in enumerate(plan["jours"])
                   for s in j["cuisine"] if f"{n}|{s['id']}" not in faits]
        connus = [par_id[i] for i in plan["choix"]]            # garde l'ordre habituel des produits
    else:                                                       # semaine d'avant la cuisine jour par jour
        seances, connus = [(par_id[i], c["portions"]) for i, c in plan["choix"].items()], []
    totaux, ordre = {}, []
    for recette in connus:
        for ing in recette["ing"]:
            if (ing["n"], ing["u"]) not in totaux:
                totaux[(ing["n"], ing["u"])] = 0.0
                ordre.append((ing["n"], ing["u"]))
    for recette, nombre in seances:
        for ing in recette["ing"]:
            cle = (ing["n"], ing["u"])
            if cle not in totaux:
                totaux[cle] = 0.0
                ordre.append(cle)
            totaux[cle] += 0 if ing["u"] == "qs" else ing["q"] * nombre
    return [{"nom": n, "quantite": round(totaux[(n, u)], 2), "unite": u} for n, u in ordre]


def portion(recette: dict, facteur: float) -> list:
    """Ingredients d'une recette pour `facteur` portions (arrondis lisibles)."""
    def arrondi(q, u):
        if u in ("pièce", "gousse"):
            return math.ceil(q * 4 - 1e-9) / 4
        return round(q) if q >= 20 else round(q * 2) / 2
    return [{"n": i["n"], "u": i["u"],
             "q": 0 if i["u"] == "qs" else arrondi(i["q"] * facteur, i["u"])}
            for i in recette["ing"]]

repas/plat_perso.py:
"""Un plat propose par l'utilisateur : il donne un nom et des ingredients, on
complete la recette pour qu'elle tienne une cible de calories et de proteines.

Rien n'est invente : seuls les ingredients deja connus du site (ceux des recettes,
avec leur prix et leurs valeurs pour 100 g) sont acceptes. La quantite de depart
de chacun est sa quantite habituelle dans les recettes existantes ; on ajoute ce
qui manque a une assiette (une proteine, un feculent, un legume, un peu de matiere
grasse), puis on regle la proteine sur la cible de proteines et le feculent sur la
cible de calories."""
import re
import statistics

from . import base
from . import planification as P
from .pdf import normaliser

ROLES = ("proteine", "feculent", "legume", "gras", "autre", "assaisonnement")
NOMS_ROLES = {"proteine": "la protéine", "feculent": "le féculent", "legume": "le légume", "gras": "la matière grasse"}
# Ce qu'on ajoute quand un role manque, par type de repas (premier connu et permis).
AJOUTS = {"plat": {"proteine": ("Blanc de poulet", "Œuf"), "feculent": ("Riz basmati", "Pommes de terre"),
                   "legume": ("Carotte", "Courgette"), "gras": ("Huile d'olive",)},
          "petitdej": {}, "collation": {}}                 # hors des plats : seulement de quoi tenir la cible
# Quand les calories restent loin de la cible, un feculent de plus : sale ou sucre selon le plat.
RENFORTS = {"sale": ("Pain complet", "Riz basmati"), "sucre": ("Flocons d'avoine", "Pain complet")}
ALIAS = {"steak hache": "Bœuf haché", "steak": "Bœuf haché", "viande hachee": "Bœuf haché", "dinde": "Dinde hachée",
         "pates": "Pâtes", "riz": "Riz basmati", "patate": "Pommes de terre", "patates": "Pommes de terre",
         "pomme de terre": "Pommes de terre", "huile": "Huile d'olive",
         "poulet": "Blanc de poulet", "boeuf": "Bœuf haché"}
# Chaque cible doit exister dans les recettes (contrôlé par tests/test_repas_donnees.py). Un mot générique sans
# alias (« yaourt », « fromage ») n'est jamais deviné : la liste des noms proches est proposée (R-13).
# Mots qui ne disent rien de l'aliment : enseignes, marques courantes, emballage.
MARQUES = {"lidl", "aldi", "auchan", "carrefour", "leclerc", "intermarche", "monoprix", "franprix", "casino",
           "super", "hyper", "systeme", "marque", "repere", "eco", "plus", "simpl", "danone", "lactel", "president",
           "bonne", "maman", "milbona", "pot", "pots", "paquet", "sachet", "boite", "bouteille", "brique", "u",
           "de", "du", "la", "le", "les", "des", "au", "aux", "d", "l", "en", "a", "et"}
BORNES = {"proteine": (0.6, 2.5), "feculent": (0.3, 3.0)}       # autour de la quantite de depart
PART = {"plat": 0.27, "petitdej": 0.2, "collation": 0.1}        # part de la journee, sans plat a remplacer


def habitudes(recettes: list) -> dict:
    """{nom: {"u": unite, "q": quantite habituelle, "a": rayon, "cats": {...}}} d'apres les recettes."""
    vus = {}
    for r in recettes:
        for i in r.get("ing", []):
            vus.setdefault(i["n"], []).append((i["u"], i["q"], i.get("a", 2), r.get("cat")))
    connus = {}
    for nom, fois in vus.items():
        unites = [u for u, *_ in fois]
        u = max(set(unites), key=unites.count)
        connus[nom] = {"u": u, "q": statistics.median(q for x, q, *_ in fois if x == u) if u != "qs" else 0,
                       "a": fois[0][2], "cats": {c for *_, c in fois}}
    return connus


def _utiles(texte: str) -> str:
    """Le nom sans les mots qui ne disent rien de l'aliment : « Yaourt nature – Lidl » -> « yaourt nature »."""
    return " ".join(m for m in normaliser(texte).split() if m not in MARQUES)


def trouver(nom: str, connus: dict) -> tuple:
    """(nom connu ou None, noms proches) pour ce que l'utilisateur a tape. La marque,
    l'enseigne et les petits mots ne comptent pas ; un mot de plus qui change l'aliment
    (« sucré ») empeche la reconnaissance : il est alors propose parmi les proches."""
    voulu = normaliser(nom)
    if not voulu:
        return None, []
    par_norme = {normaliser(n): n for n in connus}
    if ALIAS.get(voulu) in connus:
        return ALIAS[voulu], []
    if voulu in par_norme:
        return par_norme[voulu], []
    sans_marque = _utiles(nom)
    par_utile = {}
    for n in connus:
        par_utile.setdefault(_utiles(n), n)
    if sans_marque and sans_marque in par_utile:
        return par_utile[sans_marque], []
    if ALIAS.get(sans_marque) in connus:
        return ALIAS[sans_marque], []
    voulu = sans_marque or voulu
    jetons = set(base._jetons(voulu))
    proches = sorted((n for k, n in par_norme.items() if jetons & set(base._jetons(k))),
                     key=lambda n: (-len(set(base._jetons(normaliser(n))) & jetons),       # le plus de mots en commun
                                    len(set(base._jetons(normaliser(n))) ^ jetons), len(n)))
    # Tous les mots tapes sont dans UN seul nom connu : c'est lui. Dans plusieurs (« yaourt » : grec ou
    # sans lactose ?) : on ne devine pas, on propose la liste (les alias couvrent les mots courants).
    contenus = [n for n in proches if jetons <= set(base._jetons(normaliser(n)))]
    return (contenus[0] if len(contenus) == 1 else None), proches[:5]


def role(nom: str, habitude: dict, table: dict) -> str:
    m = table.get(nom)
    if habitude["u"] == "qs" or m is None:
        return "assaisonnement"
    if m["lip"] >= 40:
        return "gras"
    if habitude["u"] in ("c.à.c", "c.à.s", "gousse"):
        return "assaisonnement"
    if m["prot"] >= 10 and m["prot"] * 4 >= 0.3 * m["kcal"]:
        return "proteine"
    if m["gluc"] >= 15:
        return "feculent"
    if m["kcal"] <= 90 and habitude["a"] in (1, 4):
        return "legume"
    return "autre"


def _arrondi(q: float, u: str) -> float:
    if u in ("pièce", "gousse"):
        return max(0.5, round(q * 2) / 2)
    if u in ("c.à.c", "c.à.s"):
        return max(0.5, round(q * 2) / 2)
    return float(max(5, round(q / 5) * 5))


def completer(nom: str, voulus: list, cat: str, cible: dict, recettes: list, nutriments: dict,
              fodmap: bool = False, idee: dict | None = None, tel_quel: bool = False,
              quantites: dict | None = None, extra: dict | None = None) -> dict:
    """La recette completee. `cible` = {"kcal", "prot"} d'une portion.

    `idee` = ce que propose Claude pour ce plat ({"ajouter": [noms], "quantites": {nom: q},
    "etapes": [...], "temps": n}) : ses ingredients ne sont pris que s'ils sont connus du site ;
    ses quantites servent de point de depart, la proteine et le feculent sont ensuite regles sur la cible.

    `tel_quel` : un aliment ou quelques-uns, sans rien ajouter ni regler (une banane, du chocolat) ;
    `quantites` = {ingredient: quantite} choisies par l'utilisateur, sinon la quantite habituelle.
    Le nom peut alors etre vide : il devient la liste des ingredients.

    Renvoie {"recette": …, "ajoutes": [noms mis par Jarvis], "inconnus": [{"nom", "proches"}],
    "compris": {ce qui a ete tape: l'ingredient retenu}, "cible": cible}. Avec des inconnus, la recette n'est pas construite (None)."""
    if cat not in AJOUTS:
        raise ValueError("type de repas inconnu")
    nom = re.sub(r"\s+", " ", str(nom)).strip()[:80]
    if len(nom) < 3 and not tel_quel:
        raise ValueError("donne un nom à ton plat")
    connus = {**habitudes(recettes), **(extra or {})}   # extra : ingredients crees par le profil
    table = (nutriments or {}).get("macros") or {}
    choisis, inconnus, compris = [], [], {}
    for brut in voulus:
        if len(str(brut).strip()) > 80:
            raise ValueError(f"« {str(brut).strip()[:40]}… » : 80 caractères au plus par ingrédient")
        trouve, proches = trouver(str(brut), connus)
        if trouve and normaliser(trouve) != normaliser(str(brut)):
            compris[str(brut).strip()[:40]] = trouve
        if trouve and trouve not in choisis:
            choisis.append(trouve)
        elif not trouve and str(brut).strip():
            inconnus.append({"nom": str(brut).strip(), "proches": proches})   # exact : le site remplace la pastille par ce nom
    if inconnus:
        return {"recette": None, "ajoutes": [], "inconnus": inconnus, "cible": cible}
    if not choisis:
        raise ValueError("donne au moins un ingrédient")
    if len(choisis) > 20:
        raise ValueError("20 ingrédients au plus")
    if len(nom) < 3:                                        # tel quel, sans nom : « Banane », « Chocolat noir & noix »
        nom = (", ".join(choisis[:-1]) + " & " + choisis[-1]) if len(choisis) > 1 else choisis[0]
        nom = nom[:1].upper() + nom[1:].lower() if len(choisis) > 1 else nom
    roles = {n: role(n, connus[n], table) for n in choisis}
    ajoutes = []
    if tel_quel:
        idee = None
    permis = lambda n: n in connus and not (fodmap and base.interdits([normaliser(n)])["Pauvre en FODMAP"])
    for brut in ((idee or {}).get("ajouter") or [])[:10]:
        trouve, _ = trouver(str(brut), connus)
        if trouve and trouve not in choisis and permis(trouve) and len(choisis) < 20:
            choisis.append(trouve)
            roles[trouve] = role(trouve, connus[trouve], table)
            ajoutes.append(trouve)
    for manque, possibles in ({} if tel_quel else AJOUTS[cat]).items():
        if manque in roles.values():
            continue
        for n in possibles:
            interdit = fodmap and base.interdits([normaliser(n)])["Pauvre en FODMAP"]
            if n in connus and n in table and not interdit:
                choisis.append(n)
                roles[n] = manque
                ajoutes.append(n)
                break
    # Quantite de depart : celle que Claude donne pour ce plat si elle est plausible, sinon l'habituelle.
    proposees_q = {}
    for brut, q in ((idee or {}).get("quantites") or {}).items():
        trouve, _ = trouver(str(brut), connus)
        try:
            q = float(q)
        except (TypeError, ValueError):
            continue
        if trouve in choisis and connus[trouve]["u"] != "qs" and connus[trouve]["q"] / 5 <= q <= connus[trouve]["q"] * 5:
            proposees_q[trouve] = _arrondi(q, connus[trouve]["u"])
    if tel_quel:                                            # les quantites demandees, telles quelles
        for brut, q in (quantites or {}).items():
            trouve, _ = trouver(str(brut), connus)
            tape = q.get("u") if isinstance(q, dict) else None   # l'unite tapee : "g", "ml", "pièce" ou "" (aucune)
            try:
                q = float(q.get("q") if isinstance(q, dict) else q)
            except (TypeError, ValueError):
                continue
            if trouve not in choisis or connus[trouve]["u"] == "qs":
                continue
            u = connus[trouve]["u"]
            if tape == "" and u in ("g", "ml") and q <= 10:
                q = q * connus[trouve]["q"]                  # « yaourt 2 » : deux portions habituelles
            elif tape and tape != u:
                continue                                     # « œuf 120 g » : rien a convertir, la quantite habituelle reste
            if 0 < q <= max(connus[trouve]["q"] * 10, 10):
                proposees_q[trouve] = round(q, 2)
    ing = [{"n": n, "q": proposees_q.get(n, connus[n]["q"]), "u": connus[n]["u"], "a": connus[n]["a"]} for n in choisis]
    depart = {i["n"]: i["q"] for i in ing}

    def apport(lot):
        return P.macros({"ing": lot}, nutriments) or dict.fromkeys(P.MACROS, 0)

    def regler(quel, mesure, voulu):
        """Met a l'echelle les ingredients de ce role pour que `mesure` atteigne `voulu`."""
        lot = [i for i in ing if roles[i["n"]] == quel]
        du_role = apport(lot)[mesure]
        if not lot or du_role <= 0:
            return
        reste = apport([i for i in ing if roles[i["n"]] != quel])[mesure]
        bas, haut = BORNES[quel]
        for i in lot:
            if i["n"] not in ajoutes:
                bas = max(bas, 1.0 if quel == "proteine" else bas)     # ce que tu as demande ne descend pas sous sa dose normale
            f = min(haut, max(bas, (voulu - reste) / du_role * i["q"] / depart[i["n"]]))
            i["q"] = _arrondi(depart[i["n"]] * f, i["u"])

    def ajuster():
        for _ in range(3):
            regler("proteine", "prot", cible["prot"])
            regler("feculent", "kcal", cible["kcal"])

    if not tel_quel:
        ajuster()
    if not tel_quel and apport(ing)["kcal"] < 0.85 * cible["kcal"] and "feculent" not in roles.values():
        # Trop leger et rien pour monter : un feculent de plus, puis on regle de nouveau.
        sale = any(roles[n] in ("legume", "gras") or (roles[n] == "proteine" and connus[n]["a"] != 3) or n == "Œuf" for n in choisis)
        renfort = next((n for n in RENFORTS["sale" if sale else "sucre"] if n not in choisis and n in table and permis(n)), None)
        if renfort:
            choisis.append(renfort)
            roles[renfort] = "feculent"
            ajoutes.append(renfort)
            ing.append({"n": renfort, "q": connus[renfort]["q"], "u": connus[renfort]["u"], "a": connus[renfort]["a"]})
            depart[renfort] = connus[renfort]["q"]
            ajuster()
    m = apport(ing)
    etiquettes = base.interdits([normaliser(i["n"]) for i in ing])
    par_role = {r: [i["n"] for i in ing if roles[i["n"]] == r] for r in ROLES}
    liste = lambda noms: ", ".join(n.lower() for n in noms)
    etapes = []
    if par_role["feculent"]:
        etapes.append(f"Lance la cuisson : {liste(par_role['feculent'])}.")
    if par_role["proteine"]:
        etapes.append(f"Cuis {liste(par_role['proteine'])}" + (f" dans {liste(par_role['gras'])}" if par_role["gras"] else "") + ".")
    if par_role["legume"] or par_role["autre"]:
        etapes.append(f"Ajoute {liste(par_role['legume'] + par_role['autre'])} et laisse cuire à ton goût.")
    if par_role["assaisonnement"]:
        etapes.append(f"Assaisonne : {liste(par_role['assaisonnement'])}.")
    etapes.append("Recette posée par toi, quantités calculées par Jarvis : ajuste la cuisson comme tu la fais d'habitude.")
    if tel_quel:
        etapes = ["Rien à préparer : à manger tel quel."] if len(ing) == 1 else ["Réunis les ingrédients et mange."]
    proposees = [str(e).strip()[:300] for e in ((idee or {}).get("etapes") or []) if str(e).strip()][:10]
    if len(proposees) >= 2:
        etapes = proposees + ["Sel et poivre à ton goût : ils ne sont pas comptés dans les courses."]
    try:
        temps = min(240, max(2, int((idee or {}).get("temps"))))
    except (TypeError, ValueError):
        temps = 2 if tel_quel else 25 if cat == "plat" else 10
    ident = "perso-" + re.sub(r"[^a-z0-9]+", "-", normaliser(nom)).strip("-")[:40]
    recette = {"id": ident, "cat": cat, "slot": "", "emoji": "", "nom": nom, "tags": [], "perso": True,
               "kcal": m["kcal"], "prot": m["prot"], "gluc": m["gluc"], "lip": m["lip"], "fib": m["fib"],
               "four": "", "ing": ing, "temps": temps, "etapes": etapes,
               **({"tel_quel": True} if tel_quel else {}),       # mange tel quel : toujours une portion (R-03)
               "fodmap": not etiquettes["Pauvre en FODMAP"], "origine": "", "genre": ""}
    return {"recette": recette, "ajoutes": ajoutes, "inconnus": [], "cible": cible, "compris": compris,
            "par_claude": bool(idee), "tel_quel": bool(tel_quel),
            "roles": {n: r for n, r in roles.items()}}

repas/prix.py:
"""Prix des articles « a acheter » chez chaque enseigne, puis panier le moins cher.

    python jarvis14.py --repas-prix Auchan            (apres --repas liste.pdf)

Pour chaque article : recherche sur le site, tri des resultats par Claude (quel
produit correspond VRAIMENT a l'ingredient), calcul du nombre de paquets pour
couvrir le besoin, et — pour les sauces et condiments — lecture de la composition
(refus de tout produit contenant un ingredient interdit, ex. vinaigre d'alcool).
