# ------------------------------------------------------------ regimes : regles dures
# Une mention de regime dans le nom de l'ingredient est une EXIGENCE : le produit choisi doit la
# porter dans son nom, sinon il n'entre pas au panier (un yaourt ordinaire n'est pas un
# « yaourt sans lactose », meme si c'est le seul yaourt trouve).
MENTIONS = {
    "sans lactose": (r"\bsans lactose\b", r"\b0 lactose\b", r"\bdelactose", r"\blactose free\b"),
    "sans gluten": (r"\bsans gluten\b", r"\bgluten free\b"),
    "halal": (r"\bhalal\b",),
}
# « 100 % sarrasin » : la composition doit etre lue, et ne contenir aucune autre cereale.
PURS = {"100 sarrasin": ["blé", "froment", "farine de blé", "seigle", "orge"]}
# Jamais au panier, quel que soit le profil : le nom du produit suffit a le refuser.
# La charcuterie passe si le produit se dit halal ; l'alcool, jamais.
PORC = ("porc", "jambon", "lardon", "lardons", "bacon", "saucisson", "chorizo", "pancetta", "coppa",
        "rosette", "rillettes", "boudin", "andouille", "andouillette")
ALCOOL = ("alcool", "vin", "biere", "rhum", "whisky", "vodka", "cognac", "kirsch", "liqueur", "marsala")


def mentions_exigees(nom: str) -> list:
    """Les mentions de regime que porte le nom d'un ingredient."""
    n = f" {normaliser(nom)} "
    return [m for m in MENTIONS if f" {m} " in n]


def porte_la_mention(texte: str, mention: str) -> bool:
    return any(re.search(p, normaliser(texte)) for p in MENTIONS[mention])


def refus_sur_le_nom(ingredient: str, produit: str, fodmap: bool) -> str:
    """Premier controle, sans rien lire d'autre que le NOM du produit : la raison du refus,
    ou '' s'il peut continuer (sa composition sera lue ensuite)."""
    for m in mentions_exigees(ingredient):
        if not porte_la_mention(produit, m):
            return f"ne porte pas la mention « {m} »"
    voulu, nom = f" {normaliser(ingredient)} ", f" {normaliser(produit)} "
    interdit = _contient_interdit(produit, [a for a in ALCOOL if f" {a} " not in voulu])
    if interdit:
        return f"alcool dans le nom ({interdit})"
    if not porte_la_mention(produit, "halal"):
        for p in PORC:
            if f" {p} " in nom:
                return f"porc dans le nom ({p})"
    if fodmap:
        mot = base.fodmap_dans_le_nom(normaliser(produit), normaliser(ingredient))
        if mot:
            return f"riche en FODMAP ({mot})"
    return ""


