def verifier_par_claude(choisis: list, interdits: list, fodmap: bool) -> dict | None:
    """Deuxieme controle, independant du premier et fait par un modele plus fort
    (reglage repas.modele_verification). choisis = [(ingredient, produit, composition)].
    Renvoie {index: raison} pour chaque produit refuse ; un article sans verdict est refuse.
    None si le controle n'a pas pu se faire : rien ne doit alors entrer au panier."""
    if not choisis:
        return {}
    exe = shutil.which("claude")
    if not exe:
        return None
    modele = str(reglage("repas.modele_verification", "sonnet") or "sonnet")
    lignes = ["Ingredients interdits dans la composition : " + ", ".join(interdits)
              + ". Un interdit qui EST l'ingredient demande (du miel quand la recette demande du miel) "
                "ne compte pas pour cet article."]
    if fodmap:
        lignes.append(_REGLE_FODMAP)
    for i, (ingredient, produit, compo) in enumerate(choisis):
        lignes.append(f"Article {i} : ingredient demande « {ingredient} » ; produit choisi « {produit} » ; "
                      + (f"composition : {compo[:600]}" if compo else "composition non lue"))
    try:
        p = subprocess.run(
            [exe, "-p", "\n".join(lignes), "--model", modele, "--tools", "",
             "--setting-sources", "", "--no-session-persistence",
             "--output-format", "json", "--system-prompt", _SYSTEME_VERIFICATION,
             "--json-schema", json.dumps(_SCHEMA_VERIFICATION)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300, env=_env_abonnement())
        verdicts = (json.loads(p.stdout).get("structured_output") or {}).get("verdicts")
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return None
    if not isinstance(verdicts, list):
        return None
    refus = {i: "pas de réponse du contrôle" for i in range(len(choisis))}
    for v in verdicts:
        try:
            i = int(v["article"])
        except (KeyError, TypeError, ValueError):
            continue
        if i in refus:
            if v.get("ok") is True:
                del refus[i]
            else:
                refus[i] = str(v.get("raison") or "refusé sans raison donnée").strip()[:160]
    return refus

_CUILLERES = base.CUILLERES
_CANDIDATS = 10

_SYSTEME = (
    "Tu aides a faire des courses. Pour chaque article (un ingredient de recette), "
    "choisis parmi ses candidats les produits qui SONT cet ingredient, sous sa forme "
    "simple et brute : pas de plat prepare, pas de version aromatisee, sucree, en chips "
    "ou en sauce, pas un autre produit qui en contient. « (boîte) » = en conserve. "
    "Classe du plus adapte au moins adapte, 4 au maximum. Aucun candidat adapte = liste vide.")
_SCHEMA = {"type": "object", "required": ["choix"], "properties": {"choix": {
    "type": "array", "items": {"type": "object", "required": ["article", "candidats"],
                               "properties": {"article": {"type": "integer"},
                                              "candidats": {"type": "array",
                                                            "items": {"type": "integer"}}}}}}}


def requete(nom: str) -> str:
    sans = re.sub(r"\([^)]*\)", " ", nom).strip()
    return REQUETES.get(normaliser(sans), sans)


def requete_simple(nom: str) -> str:
    """Recherche de repli, plus large : « Gingembre frais » -> « gingembre »."""
    sans = re.sub(r"\([^)]*\)", " ", nom)
    # Une mention de regime ne se retire jamais de la recherche : « Yaourt nature sans lactose »
    # s'elargit en « Yaourt sans lactose », pas en « Yaourt sans ».
    garde = mentions_exigees(sans)
    for m in garde:
        sans = re.sub(re.escape(m), " ", sans, flags=re.I)
    mots = [m for m in re.findall(r"[^\s'’]+", sans)
            if normaliser(m) not in ("frais", "fraiche", "moulues", "moulu", "decortique",
                                     "nature", "a", "l", "huile", "de", "d", "certifiee")]
    if garde:
        return " ".join(mots[:1] + garde) if mots else nom
    return " ".join(mots[:2]) if mots else nom


def fusionner(lignes: list) -> list:
    """Une seule ligne par article : l'huile demandee en c.à.s ET en c.à.c devient
    un seul besoin en ml (sinon elle serait achetee deux fois)."""
    par_nom, ordre = {}, []
    for l in lignes:
        if l["nom"] not in par_nom:
            par_nom[l["nom"]] = dict(l)
            ordre.append(l["nom"])
            continue
        garde = par_nom[l["nom"]]
        q1, u1 = besoin_de_base(garde)
        q2, u2 = besoin_de_base(l)
        if u1 == u2 and u1 != "paquet":
            garde.update(acheter=q1 + q2, unite=u1, besoin=q1 + q2)
        garde["composition_a_verifier"] = bool(
            garde.get("composition_a_verifier") or l.get("composition_a_verifier"))
        garde["composition_stricte"] = bool(
            garde.get("composition_stricte") or l.get("composition_stricte"))
    return [par_nom[n] for n in ordre]


def code_postal() -> str:
    from repas import profil
    adresse = profil.actif(reglage).valeur("courses.adresse") or reglage("repas.adresse", "")
    m = re.search(r"\b\d{5}\b", str(adresse or ""))
    return m.group(0) if m else ""


# ------------------------------------------------------------ quantites
def besoin_de_base(ligne: dict) -> tuple:
    """Besoin converti en (quantite, 'g' | 'ml' | 'pièce' | 'paquet')."""
    q, u = float(ligne.get("acheter") or 0), ligne["unite"]
    if u == "qs":
        return 1.0, "paquet"
    if u in _CUILLERES:
        return q * _CUILLERES[u], "ml"
    if u == "gousse":
        return q, "pièce"
    return q, u


def contenu(offre: Offre) -> tuple:
    """Contenu d'un paquet : (quantite, 'g' | 'ml' | 'pièce'), ou (0, '') si inconnu."""
    if offre.prix_ref > 0 and offre.unite_ref in ("kg", "l", "pièce"):
        q = offre.prix / offre.prix_ref
        return (round(q), "pièce") if offre.unite_ref == "pièce" else (
            q * 1000, "g" if offre.unite_ref == "kg" else "ml")
    # Le format d'abord ; a defaut le nom du produit, ou certaines enseignes
    # l'ecrivent (« Kiwi vert 1p », « Oranges Eco+ 1.5kg », « Oeufs x12 »).
    for texte in (offre.format, offre.nom):
        m = re.search(r"(?:(\d+)\s?x\s?)?(\d+(?:[.,]\d+)?)\s?(kg|g|l|cl|ml)\b", texte, re.I)
        if m:
            fois = int(m.group(1) or 1)
            q = float(m.group(2).replace(",", ".")) * fois
            u = m.group(3).lower()
            return {"kg": (q * 1000, "g"), "g": (q, "g"), "l": (q * 1000, "ml"),
                    "cl": (q * 10, "ml"), "ml": (q, "ml")}[u]
        m = (re.search(r"(\d+)\s?(?:pièces?|œufs|oeufs|unités?|p)\b", texte, re.I)
             or re.search(r"\bx\s?(\d+)\b", texte, re.I))             # « x20 »
        if m:
            return (float(m.group(1)), "pièce")
    return (0.0, "")


def est_bio(offre: Offre) -> bool:
    return bool(re.search(r"\bbio\b", offre.nom, re.I))


def paquets(nom: str, besoin: float, unite: str, offre: Offre) -> int:
    """Nombre de paquets a acheter pour couvrir le besoin."""
    q, u = contenu(offre)
    cle = normaliser(re.sub(r"\([^)]*\)", "", nom))
    if unite == "pièce" and q <= 0 and cle in A_L_UNITE:
        return max(1, math.ceil(besoin - 1e-9))     # fruit ou legume sans contenance : vendu a l'unite
    if unite == "paquet" or q <= 0:
        return 1
    poids = POIDS_PIECE.get(cle, 100)
    if unite == "pièce" and u in ("g", "ml"):
        besoin *= poids                       # pieces demandees, produit vendu au poids
    elif unite in ("g", "ml") and u == "pièce":
        besoin /= poids
    if normaliser(nom) == "ail" and u == "pièce":
        besoin = besoin / 10                  # 1 tete d'ail = une dizaine de gousses
    return max(1, math.ceil(besoin / q - 1e-9))


def _regle_bio() -> bool:
    """Eviter le bio quand un produit classique convient (courses.eviter_bio du
    profil, sinon repas.eviter_bio ; vrai par defaut)."""
    from repas import profil
    valeur = profil.actif(reglage).valeur("courses.eviter_bio")
    if valeur is None:
        valeur = reglage("repas.eviter_bio", True)
    return bool(True if valeur is None else valeur)


# ------------------------------------------------------------ choix par Claude
def _env_abonnement() -> dict:
    retire = ("ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL",
              "CLAUDECODE", "CLAUDE_CODE_ENTRYPOINT")
    return {k: v for k, v in os.environ.items() if k not in retire}


def trier_par_claude(articles: list) -> dict:
    """articles = [(nom, besoin lisible, [Offre…])]. Renvoie {index: [index candidats]}.

    Un appel par lot de 12 articles, modele leger (reglage repas.modele_tri), par
    l'abonnement Claude Code : pas de cle API."""
    exe = shutil.which("claude")
    if not exe:
        raise RuntimeError("le CLI claude est introuvable (tri des produits).")
    modele = str(reglage("repas.modele_tri", "haiku") or "haiku")
    resultat = {}
    for debut in range(0, len(articles), 12):
        lot = articles[debut:debut + 12]
        lignes = []
        for i, (nom, besoin, offres) in enumerate(lot):
            lignes.append(f"Article {i} : {nom} (besoin : {besoin})")
            for j, o in enumerate(offres):
                lignes.append(f"  [{j}] {o.nom} — {o.format} — {o.prix:.2f} €")
        try:
            p = subprocess.run(
                [exe, "-p", "\n".join(lignes), "--model", modele, "--tools", "",
                 "--setting-sources", "", "--no-session-persistence",
                 "--output-format", "json", "--system-prompt", _SYSTEME,
                 "--json-schema", json.dumps(_SCHEMA)],
                capture_output=True, text=True, encoding="utf-8", errors="replace",
                timeout=180, env=_env_abonnement())
            choix = (json.loads(p.stdout).get("structured_output") or {}).get("choix") or []
        except (OSError, ValueError, subprocess.TimeoutExpired):
            choix = []
        for c in choix:
            try:
                i = int(c["article"])
                if 0 <= i < len(lot):
                    resultat[debut + i] = [int(j) for j in c["candidats"]
                                           if 0 <= int(j) < len(lot[i][2])]
            except (KeyError, TypeError, ValueError):
                continue
    return resultat


# ------------------------------------------------------------ collecte
def _contient_interdit(composition: str, interdits: list) -> str:
    """Premier ingredient interdit trouve dans la composition ('' si aucun).
    « vin » ne vise pas le vinaigre de vin, qui est un autre produit."""
    texte = f" {normaliser(composition)} "
    sans_vinaigre_de_vin = re.sub(r" vinaigre(s)? (balsamique )?de vin( rouge| blanc)?", " ", texte)
    for i in interdits:
        cible = f" {normaliser(i)} "
        if cible == " e471 ":
            # l'additif s'ecrit de plusieurs facons sur les etiquettes
            if re.search(r" e ?471 | mono et diglycerides? d acides gras | monoglycerides? et diglycerides? ", texte):
                return "E471"
        elif cible == " gelatine ":
            # refusee si elle est de porc ou d'origine non precisee ; admise si l'etiquette
            # dit boeuf, bovine, poisson ou vegetale
            for m in re.finditer(r" gelatines?(( d[eu]| alimentaire)? (\w+))?", texte):
                if (m.group(3) or "") not in ("boeuf", "bovine", "poisson", "vegetale", "halal"):
                    return "gélatine de porc ou d'origine non précisée"
        elif cible in (sans_vinaigre_de_vin if cible == " vin " else texte):
            return i
    return ""


_VIDES = {"de", "du", "des", "d", "la", "le", "les", "l", "a", "au", "aux", "en", "et",
          "boite", "frais", "fraiche", "nature", "certifiee", "halal", "egouttees"}


def _mots(texte: str) -> list:
    return [m for m in normaliser(texte).split() if len(m) >= 3 and m not in _VIDES]


def dans_le_catalogue(nom: str, offres: list) -> list:
    """Offres du catalogue dont le nom contient tous les mots de l'article
    (« Tomate concassée » trouve « Tomates concassées »). Les moins cheres d'abord."""
    voulus = [m[:5] for m in _mots(requete(nom))] or [m[:5] for m in _mots(nom)]
    if not voulus:
        return []
    retenues = []
    for o in offres:
        debuts = {m[:5] for m in _mots(o.nom)} | {m[:4] for m in _mots(o.nom)}
        if all(v in debuts or v[:4] in debuts for v in voulus):
            retenues.append(o)
    return sorted(retenues, key=lambda o: o.prix)[:_CANDIDATS]


def _choisir(enseigne: Enseigne, lignes: list, trouves: list, interdits: list, f,
             journal=print, elargir: bool = False) -> dict:
    """Pour chaque ligne : tri des candidats par Claude, moins cher qui couvre le
    besoin, et lecture de la composition pour les sauces."""
    def a_trier(indices):
        return [(lignes[i]["nom"], "1 paquet" if lignes[i]["unite"] == "qs"
                 else f"{mod_stock.fmt(lignes[i]['acheter'])} {lignes[i]['unite']}", trouves[i])
                for i in indices]

    avec = [i for i in range(len(lignes)) if trouves[i]]
    journal(f"  Tri des produits par Claude ({len(avec)} articles)…")
    tri = {avec[k]: v for k, v in trier_par_claude(a_trier(avec)).items() if k < len(avec)}
    if elargir:
        # 2e passe : recherche plus large pour les articles restes sans produit adapte.
        reste = [i for i in range(len(lignes)) if not tri.get(i)
                 and normaliser(requete_simple(lignes[i]["nom"])) != normaliser(requete(lignes[i]["nom"]))]
        if reste:
            journal(f"  Recherche elargie pour {len(reste)} articles sans resultat…")
            for i in reste:
                try:
                    trouves[i] = enseigne.chercher(f, requete_simple(lignes[i]["nom"]))[:_CANDIDATS]
                except ErreurNavigateur:
                    trouves[i] = []
                time.sleep(enseigne.pause)
            for k, choix in trier_par_claude(a_trier(reste)).items():
                if k < len(reste):
                    tri[reste[k]] = choix

    eviter_bio = bool(_regle_bio())
    # Semaine pauvre en FODMAP : la liste des interdits porte alors les mots de ce regime.
    fodmap = {normaliser(x) for x in base.FODMAP_COMPOSITION} <= {normaliser(x) for x in interdits}

    def choisir(i: int, exclus: list, deja_refuses: list) -> dict:
        """Le produit de la ligne i : le moins cher qui passe le controle du nom, puis celui de
        la composition. `exclus` : les produits refuses a la deuxieme verification."""
        ligne, offres = lignes[i], trouves[i]
        besoin, unite = besoin_de_base(ligne)
        candidats = [offres[j] for j in tri.get(i, []) if j < len(offres) and offres[j].nom not in exclus]
        mots = A_EVITER.get(normaliser(re.sub(r"\([^)]*\)", "", ligne["nom"])).strip(), ())
        candidats = [o for o in candidats if not any(m in normaliser(o.nom) for m in mots)]
        trop = [o for o in candidats if paquets(ligne["nom"], besoin, unite, o) > PAQUETS_MAX]
        candidats = [o for o in candidats if o not in trop]
        chiffres = sorted(
            ((paquets(ligne["nom"], besoin, unite, o) * o.prix,
              paquets(ligne["nom"], besoin, unite, o), o) for o in candidats),
            key=lambda t: (eviter_bio and est_bio(t[2]), t[0], t[2].prix_ref or 0))
        entree = {"nom": ligne["nom"], "trouve": False, "note": ""}
        refuses = list(deja_refuses)
        voulu = f" {normaliser(ligne['nom'])} "
        pur = next((mots_ for cle, mots_ in PURS.items() if f" {cle} " in voulu), None)
        for cout, nb, offre in chiffres:
            # 1er controle : le nom du produit (mention exigee, porc, alcool, FODMAP).
            raison = refus_sur_le_nom(ligne["nom"], offre.nom, fodmap)
            if raison:
                refuses.append(f"{offre.nom} ({raison})")
                continue
            if ligne.get("composition_a_verifier") or pur:
                try:
                    compo = enseigne.composition(f, offre)
                except ErreurNavigateur:
                    compo = ""
                time.sleep(enseigne.pause)
                if not compo and (pur or ligne.get("composition_stricte", True)):
                    refuses.append(f"{offre.nom} (composition illisible)")
                    continue
                # Un interdit qui EST le produit demande ne compte pas : une semaine pauvre en
                # FODMAP refuse l'ail dans une moutarde, pas l'ail qu'une recette demande.
                interdit = _contient_interdit(compo, [x for x in interdits if f" {normaliser(x)} " not in voulu]
                                              + (pur or []))
                if interdit:
                    refuses.append(f"{offre.nom} (contient {interdit})")
                    continue
                if compo:
                    entree["composition"] = compo[:400]
                else:
                    entree["composition_non_lue"] = True
            entree.update(trouve=True, cout=round(cout, 2), paquets=nb, offre=offre.dict())
            # Pourquoi lui : les autres produits possibles, avec leur cout pour ce besoin.
            entree["ecartes"] = [{"nom": o.nom, "cout": round(c, 2), "paquets": n, "bio": est_bio(o)}
                                 for c, n, o in chiffres if o is not offre][:4]
            if est_bio(offre) and eviter_bio:
                entree["note"] = "bio faute d'autre choix dans les résultats"
            elif eviter_bio and any(est_bio(o) and c < cout for c, _, o in chiffres):
                entree["note"] = "version bio moins chère écartée"
            break
        if refuses:
            entree["refuses"] = refuses
        if not entree["trouve"]:
            entree["note"] = ("aucun produit qui respecte le régime" if refuses
                              else "format inadapté" if trop else "aucun produit correspondant")
            if trop and not refuses:
                o = min(trop, key=lambda o: paquets(ligne["nom"], besoin, unite, o))
                entree["format"] = f"{paquets(ligne['nom'], besoin, unite, o)} × {o.nom}"
        return entree

    def retirer(entree: dict, note: str) -> None:
        """Un produit choisi qui ne doit finalement pas entrer au panier."""
        for cle in ("offre", "cout", "paquets", "ecartes", "composition", "composition_non_lue"):
            entree.pop(cle, None)
        entree.update(trouve=False, note=note)

    # 2e controle : chaque produit retenu est revu par Claude, independamment du premier tri.
    # Un produit refuse laisse sa place au suivant, revu a son tour ; trois tours au plus.
    resultats = {}
    exclus = {i: [] for i in range(len(lignes))}
    refus_2 = {i: [] for i in range(len(lignes))}
    a_faire = list(range(len(lignes)))
    for _tour in range(3):
        for i in a_faire:
            resultats[lignes[i]["nom"]] = choisir(i, exclus[i], refus_2[i])
        controles = [i for i in a_faire if resultats[lignes[i]["nom"]]["trouve"]]
        if not controles:
            a_faire = []
            break
        entrees = [resultats[lignes[i]["nom"]] for i in controles]
        verdict = verifier_par_claude(
            [(e["nom"], e["offre"]["nom"], e.get("composition", "")) for e in entrees], interdits, fodmap)
        if verdict is None:
            journal("  Deuxième vérification impossible : aucun produit n'est gardé sans elle.")
            for e in entrees:
                retirer(e, "deuxième vérification impossible, rien n'est mis au panier sans elle")
            a_faire = []
            break
        for k, e in enumerate(entrees):
            if k in verdict:
                exclus[controles[k]].append(e["offre"]["nom"])
                refus_2[controles[k]].append(f"{e['offre']['nom']} (2e vérification : {verdict[k]})")
            else:
                e["verifie"] = True
        journal(f"  Deuxième vérification : {len(entrees)} produits contrôlés, {len(verdict)} refusés.")
        a_faire = [controles[k] for k in sorted(verdict)]
        if not a_faire:
            break
    for i in a_faire:                                  # refuses au dernier tour : pas de remplacant controle
        e = resultats[lignes[i]["nom"]]
        retirer(e, "aucun produit n'a passé la deuxième vérification")
        e["refuses"] = refus_2[i]
    return resultats


def relever(enseigne: Enseigne, lignes: list, interdits: list, f: Firefox,
            journal=print) -> dict:
    """Prix de chaque ligne « a acheter » chez `enseigne`, par une recherche par
    article (long : a reserver a l'enseigne principale)."""
    contexte = enseigne.preparer(f, code_postal())
    journal(f"  {enseigne.nom} — {contexte}")
    trouves = []
    for n, ligne in enumerate(lignes, 1):
        try:
            offres = enseigne.chercher(f, requete(ligne["nom"]))[:_CANDIDATS]
        except ErreurNavigateur as e:
            journal(f"    {ligne['nom']} : recherche impossible ({str(e)[:60]})")
            offres = []
        trouves.append(offres)
        journal(f"    [{n}/{len(lignes)}] {ligne['nom']} : {len(offres)} produits")
        time.sleep(enseigne.pause)
    resultats = _choisir(enseigne, lignes, trouves, interdits, f, journal, elargir=True)
    return {"enseigne": enseigne.nom, "contexte": contexte, "source": "recherche",
            "releve_le": time.strftime("%Y-%m-%dT%H:%M:%S"), "articles": resultats}


def relever_catalogue(enseigne: Enseigne, lignes: list, interdits: list, f: Firefox,
                      journal=print) -> tuple:
    """Offres du CATALOGUE des promotions de `enseigne` qui correspondent a la
    liste : le catalogue est telecharge une fois, les calculs sont faits ensuite
    hors ligne. Renvoie (releve, offres du catalogue)."""
    contexte = enseigne.preparer(f, code_postal())
    journal(f"  {enseigne.nom} — {contexte}")
    journal("  Telechargement du catalogue des promotions…")
    offres = enseigne.catalogue(f, journal)
    trouves = [dans_le_catalogue(l["nom"], offres) for l in lignes]
    resultats = _choisir(enseigne, lignes, trouves, interdits, f, journal)
    for entree in resultats.values():
        if not entree["trouve"] and not entree.get("refuses"):
            entree["note"] = "pas dans le catalogue"
    return ({"enseigne": enseigne.nom, "contexte": contexte, "source": "catalogue",
             "offres_catalogue": len(offres),
             "releve_le": time.strftime("%Y-%m-%dT%H:%M:%S"), "articles": resultats},
            offres)


# ------------------------------------------------------------ comparaison
def comparer(releves: list, noms: list, max_enseignes: int = 2) -> list:
    """Toutes les combinaisons d'au plus `max_enseignes` enseignes, de la meilleure
    a la moins bonne : d'abord celle qui couvre le plus d'articles, puis la moins
    chere. Dans une combinaison, chaque article va a l'enseigne la moins chere."""
    scenarios = []
    for taille in range(1, max(1, max_enseignes) + 1):
        for combo in itertools.combinations(releves, taille):
            total, panier, manquants = 0.0, {r["enseigne"]: [] for r in combo}, []
            for nom in noms:
                offres = [(r["articles"][nom]["cout"], r["enseigne"]) for r in combo
                          if r["articles"].get(nom, {}).get("trouve")]
                if not offres:
                    manquants.append(nom)
                    continue
                cout, enseigne = min(offres)
                total += cout
                panier[enseigne].append(nom)
            scenarios.append({"enseignes": [r["enseigne"] for r in combo],
                              "total": round(total, 2), "panier": panier,
                              "manquants": manquants})
    scenarios.sort(key=lambda s: (len(s["manquants"]), s["total"], len(s["enseignes"])))
    return scenarios


def retenir(scenarios: list, economie_min: float = 5.0) -> dict:
    """Le panier a commander : le meilleur, sauf si une enseigne de plus ne fait
    gagner que quelques centimes (moins que `economie_min` : une commande et une
    livraison de plus couteraient davantage)."""
    meilleur = scenarios[0]
    for s in scenarios[1:]:
        if len(s["enseignes"]) < len(meilleur["enseignes"]) \
                and len(s["manquants"]) <= len(meilleur["manquants"]) \
                and s["total"] - meilleur["total"] < economie_min:
            meilleur = s
    return meilleur


