def remplacants_par_claude(manquants: list, connus: list, eviter: list = ()) -> dict:
    """manquants = [{nom, acheter, unite, plats}]. Renvoie {nom: [{nom, rapport, pourquoi}]} :
    les ingredients qui peuvent remplacer chacun, d'apres Claude (modele repas.modele_tri)."""
    exe = shutil.which("claude")
    if not exe:
        raise RuntimeError("le CLI claude est introuvable (recherche d'alternatives).")
    lignes = [f"Article {i} : {m['nom']} ({mod_stock.fmt(m['acheter'])} {m['unite']}) — dans : "
              + (" ; ".join(m.get("plats") or []) or "plats non precises") for i, m in enumerate(manquants)]
    if eviter:
        lignes.append("Regime pauvre en FODMAP : aucun remplacant qui soit ou contienne "
                      + ", ".join(eviter) + ".")
    lignes.append("Ingredients connus : " + ", ".join(connus) + ".")
    try:
        p = subprocess.run(
            [exe, "-p", "\n".join(lignes), "--model", str(reglage("repas.modele_tri", "haiku") or "haiku"),
             "--tools", "", "--setting-sources", "", "--no-session-persistence",
             "--output-format", "json", "--system-prompt", _SYSTEME_ALTERNATIVES,
             "--json-schema", json.dumps(_SCHEMA_ALTERNATIVES)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, env=_env_abonnement())
        choix = (json.loads(p.stdout).get("structured_output") or {}).get("choix") or []
    except (OSError, ValueError, subprocess.TimeoutExpired):
        choix = []
    return propres_remplacants(manquants, choix, connus)


def propres_remplacants(manquants: list, choix: list, connus: list) -> dict:
    """Nettoie la reponse de Claude : noms courts, sans l'ingredient d'origine ni doublon,
    rapport borne, orthographe de la table des ingredients quand le nom y figure."""
    officiel = {normaliser(n): n for n in connus}
    resultat = {m["nom"]: [] for m in manquants}
    for c in choix:
        try:
            m = manquants[int(c["article"])]
        except (KeyError, TypeError, ValueError, IndexError):
            continue
        vus = {normaliser(m["nom"])}
        for r in c.get("remplacants") if isinstance(c.get("remplacants"), list) else []:
            if not isinstance(r, dict):
                continue
            nom = re.sub(r"\s+", " ", str(r.get("nom") or "")).strip()[:60]
            if not nom or normaliser(nom) in vus or len(resultat[m["nom"]]) >= 3:
                continue
            vus.add(normaliser(nom))
            try:
                rapport = float(r.get("rapport") or 1)
            except (TypeError, ValueError):
                rapport = 1.0
            resultat[m["nom"]].append({"nom": officiel.get(normaliser(nom), nom[0].upper() + nom[1:]),
                                       "rapport": round(min(4.0, max(0.25, rapport)), 2),
                                       "pourquoi": str(r.get("pourquoi") or "").strip()[:160]})
    return resultat


def alternatives(enseigne: Enseigne, manquants: list, interdits: list, connus: list, f: Firefox,
                 journal=print, eviter: list = (), deja: dict | None = None,
                 refuser=lambda nom: False) -> dict:
    """Pour chaque produit absent du panier : les ingredients de remplacement proposes par
    Claude, puis, pour chacun, le produit que vend `enseigne` (meme tri et meme lecture des
    etiquettes que pour le panier). Seuls les remplacants TROUVES sont gardes.
    `deja` = {ingredient: offre} deja au panier : on reprend ce produit, sans le rechercher.
    `refuser(nom)` : vrai pour un ingredient qui ne s'achete pas au supermarche (viande)."""
    deja = deja or {}
    # Un remplacant dont le nom porte un interdit (vin, ail en regime FODMAP…) n'est pas propose.
    absents = {normaliser(m["nom"]) for m in manquants}         # un produit manquant n'en remplace pas un autre
    idees = {n: [r for r in rs if not refuser(r["nom"]) and not _contient_interdit(r["nom"], interdits)
                 and normaliser(r["nom"]) not in absents]
             for n, rs in remplacants_par_claude(manquants, connus, eviter).items()}
    journal("  Idées de remplacement : " + " ; ".join(
        f"{n} -> {', '.join(r['nom'] for r in rs) or 'aucune'}" for n, rs in idees.items()))
    articles = {m["nom"]: {"nom": m["nom"], "acheter": m["acheter"], "unite": m["unite"],
                           "alternatives": []} for m in manquants}
    lignes, origine = [], []
    for m in manquants:
        for r in idees.get(m["nom"], []):
            besoin = mod_stock.a_acheter(float(m["acheter"]) * r["rapport"], m["unite"]) if m["unite"] != "qs" else 0
            ligne = {"nom": r["nom"], "acheter": besoin, "besoin": besoin, "unite": m["unite"],
                     "composition_a_verifier": True, "composition_stricte": False}
            if r["nom"] in deja:                   # deja au panier pour d'autres plats : le meme produit, en plus
                offre = Offre(**deja[r["nom"]])
                nb = paquets(r["nom"], *besoin_de_base(ligne), offre)
                articles[m["nom"]]["alternatives"].append({
                    "nom": r["nom"], "rapport": r["rapport"], "pourquoi": r["pourquoi"], "quantite": besoin,
                    "unite": m["unite"], "offre": offre.dict(), "paquets": nb, "cout": round(nb * offre.prix, 2),
                    "deja_au_panier": True})
                continue
            lignes.append(ligne)
            origine.append((m["nom"], r))
    if not lignes:
        return {"enseigne": enseigne.nom, "cherche_le": time.strftime("%Y-%m-%dT%H:%M:%S"), "articles": articles}
    contexte = enseigne.preparer(f, code_postal())
    journal(f"  {enseigne.nom} — {contexte}")
    trouves = []
    for n, ligne in enumerate(lignes, 1):
        try:
            offres = enseigne.chercher(f, requete(ligne["nom"]))[:_CANDIDATS]
        except ErreurNavigateur:
            offres = []
        trouves.append(offres)
        journal(f"    [{n}/{len(lignes)}] {ligne['nom']} (à la place de {origine[n - 1][0]}) : {len(offres)} produits")
        time.sleep(enseigne.pause)
    # _choisir range ses resultats par nom : un meme remplacant propose pour deux produits
    # (du quinoa pour le sarrasin ET pour le millet) passe en deux fois.
    reste = list(range(len(lignes)))
    while reste:
        lot, vus = [], set()
        for i in reste:
            if lignes[i]["nom"] not in vus:
                vus.add(lignes[i]["nom"])
                lot.append(i)
        reste = [i for i in reste if i not in lot]
        choisis = _choisir(enseigne, [lignes[i] for i in lot], [trouves[i] for i in lot], interdits, f, journal)
        for i in lot:
            a, (nom, r) = choisis.get(lignes[i]["nom"]) or {}, origine[i]
            if a.get("trouve"):
                articles[nom]["alternatives"].append({
                    "nom": lignes[i]["nom"], "rapport": r["rapport"], "pourquoi": r["pourquoi"],
                    "quantite": lignes[i]["acheter"], "unite": lignes[i]["unite"], "offre": a["offre"],
                    "paquets": a["paquets"], "cout": a["cout"],
                    **({"composition_non_lue": True} if a.get("composition_non_lue") else {})})
    return {"enseigne": enseigne.nom, "cherche_le": time.strftime("%Y-%m-%dT%H:%M:%S"), "articles": articles}

repas/profil.py:
"""Profil actif : qui mange, avec quels objectifs, et quels fichiers vont avec.

Un profil est un dossier `<repas.profils>/profils/<repas.profil>/` :

    profil.yaml       identite, programme (phases, calories), budget, regles
                      alimentaires, courses, et les LIENS vers les autres fichiers
    historique.json   semaines choisies, plats cuisines, notes donnees
    stock.csv         ce qu'il y a a la maison (commande, prepare, en stock)
    mouvements.csv    le detail de chaque entree et sortie du stock

La ponderation (comment les plats sont choisis) est un fichier a part, partage
par defaut entre les profils : `<repas.profils>/ponderation.yaml`.

Sans profil configure, tout reste dans donnees_repas/ avec les valeurs par defaut.
"""
from __future__ import annotations

import contextvars
import json
import copy
import os
import re
import time
from pathlib import Path

import yaml

from core.config import reglage as _reglage
from repas import planification as P

CRITERES_DEFAUT = dict(P.POIDS_DEFAUT)
COMPOSITION_DEFAUT = dict(P.COMPOSITION_DEFAUT)
# Profil impose pour la requete en cours (le site sert plusieurs personnes). Une
# commande lancee a part recoit le meme nom par la variable JARVIS_REPAS_PROFIL.
_COURANT = contextvars.ContextVar("profil_repas", default="")
ACTIVITES = {"sedentaire": (1.2, "sédentaire"), "leger": (1.375, "légèrement actif"),
             "modere": (1.55, "modérément actif"), "actif": (1.725, "très actif"),
             "intense": (1.9, "sport intense tous les jours")}
OBJECTIFS = {"perte": (-0.15, 2.0, "Perte de poids"), "maintien": (0.0, 1.6, "Maintien"),
             "prise": (0.10, 1.8, "Prise de muscle")}
VIANDES = ["poulet", "dinde", "boeuf", "veau", "agneau", "mouton", "viande", "canard", "lapin",
           "merguez", "steak"]


_YAML = {}                               # chemin -> (date et taille du fichier, contenu)


def _yaml(fichier: Path) -> dict:
    """Contenu d'un fichier YAML. Garde en memoire tant que le fichier ne change pas :
    une requete du site lit le profil des dizaines de fois."""
    try:
        infos = os.stat(fichier)
        marque = (infos.st_mtime_ns, infos.st_size)
        connu = _YAML.get(str(fichier))
        if connu is None or connu[0] != marque:
            with open(fichier, encoding="utf-8") as h:
                donnees = yaml.safe_load(h)
            connu = _YAML[str(fichier)] = (marque, donnees if isinstance(donnees, dict) else {})
        return copy.deepcopy(connu[1])
    except (OSError, yaml.YAMLError):
        return {}


class Profil:
    def __init__(self, nom: str, dossier: Path, donnees: dict | None = None):
        self.nom, self.dossier, self.donnees = nom, Path(dossier), donnees or {}

    def valeur(self, chemin: str, defaut=None):
        """profil.valeur("alimentation.boucher") ; `defaut` si absent."""
        v = self.donnees
        for cle in chemin.split("."):
            if not isinstance(v, dict) or cle not in v:
                return defaut
            v = v[cle]
        return defaut if v is None else v

    def lien(self, cle: str, defaut: str) -> Path:
        """Chemin d'un fichier lie au profil (section `liens` de profil.yaml)."""
        f = Path(str(self.valeur(f"liens.{cle}", defaut))).expanduser()
        return f if f.is_absolute() else (self.dossier / f).resolve()

    def fichier(self, nom: str) -> Path:
        """Fichier de travail du profil (semaine.json, journal.json…)."""
        self.dossier.mkdir(parents=True, exist_ok=True)
        return self.dossier / nom

    @property
    def phases(self) -> list:
        phases = self.valeur("programme.phases")
        if isinstance(phases, list) and all(
                isinstance(p, dict) and {"n", "jusqu_a", "kcal", "prot"} <= set(p) for p in phases):
            return [{"nom": f"Phase {p['n']}", **p} for p in phases]
        return P.PHASES

    @property
    def budget_mois(self) -> int:
        return int(self.valeur("budget_mois", 300) or 300)

    def ponderation(self) -> dict:
        """{'criteres': …, 'composition': …, 'modes': …} : le fichier lie, complete par
        les valeurs par defaut. Relu a chaque appel : un changement s'applique tout de suite."""
        fichier = _yaml(self.lien("ponderation", "ponderation.yaml"))

        def nombres(lu, defaut, libre=False):
            lu = lu if isinstance(lu, dict) else {}
            return {**defaut, **{k: v for k, v in lu.items()
                                 if (libre or k in defaut) and isinstance(v, (int, float))
                                 and not isinstance(v, bool)}}
        lus = fichier.get("modes") if isinstance(fichier.get("modes"), dict) else {}
        modes = {}
        for nom, defaut in P.MODES_DEFAUT.items():
            lu = lus.get(nom) if isinstance(lus.get(nom), dict) else {}
            modes[nom] = {"criteres": nombres(lu.get("criteres"), defaut["criteres"], True)
                          if "criteres" in lu else dict(defaut["criteres"]),
                          "composition": nombres(lu.get("composition"), defaut["composition"], True)
                          if "composition" in lu else dict(defaut["composition"])}
        return {"criteres": nombres(fichier.get("criteres"), CRITERES_DEFAUT),
                "composition": nombres(fichier.get("composition"), COMPOSITION_DEFAUT),
                "modes": modes}

    def besoins_vitamines(self, kcal: float) -> dict:
        """Besoins quotidiens : calcul d'apres le sexe et les calories de la phase,
        sauf les valeurs fixees a la main dans la section `vitamines` de profil.yaml."""
        besoins = P.besoins_vitamines(self.valeur("identite.sexe", "homme"), kcal)
        fixes = self.valeur("vitamines", {})
        if isinstance(fixes, dict):
            besoins.update({v: float(q) for v, q in fixes.items()
                            if v in besoins and isinstance(q, (int, float)) and q > 0})
        return besoins

    @property
    def preferences(self) -> dict:
        """Ce qui est coche par defaut avant de composer une semaine."""
        p = self.valeur("preferences", {})
        p = p if isinstance(p, dict) else {}
        return {"modes": [m for m in p.get("modes") or [] if m in P.MODES_DEFAUT],
                "fruits_secs": p.get("fruits_secs") is True}      # une poignee par jour seulement si demande (19/11/2026)

    @property
    def calcule(self) -> bool:
        """Profil cree depuis le site : ses besoins se recalculent quand il change ses reponses."""
        return isinstance(self.valeur("programme.calcul"), dict)


# ------------------------------------------------------------------ quel profil
def choisir(nom: str) -> None:
    """Impose le profil de la requete (ou du fil) en cours ; "" = celui de config.yaml."""
    _COURANT.set(str(nom or ""))


def racine(lire=None) -> Path | None:
    chemin = str((lire or _reglage)("repas.profils", "") or "")
    return Path(chemin).expanduser() if chemin else None


def principal(lire=None) -> str:
    return str((lire or _reglage)("repas.profil", "") or "")


def liste(lire=None) -> list:
    """Noms des profils existants (dossiers contenant un profil.yaml)."""
    base = racine(lire)
    if not base or not (base / "profils").is_dir():
        return []
    return sorted(d.name for d in (base / "profils").iterdir() if (d / "profil.yaml").is_file())


def charger(nom: str, lire=None) -> Profil | None:
    base = racine(lire)
    if not base or not re.fullmatch(r"[a-z0-9_-]{2,30}", str(nom or "")):
        return None
    dossier = base / "profils" / nom
    if not (dossier / "profil.yaml").is_file():
        return None
    return Profil(nom, dossier, _yaml(dossier / "profil.yaml"))


def actif(lire=None) -> Profil:
    """Le profil en cours : celui impose par `choisir` (site) ou par la variable
    JARVIS_REPAS_PROFIL (commande lancee par le site), sinon celui de config.yaml
    (repas.profils + repas.profil), sinon un profil par defaut range dans
    donnees_repas/. `lire` = fonction de lecture des reglages du module appelant
    (les tests la remplacent)."""
    lire = lire or _reglage
    for nom in (_COURANT.get(), os.environ.get("JARVIS_REPAS_PROFIL", ""), principal(lire)):
        profil = charger(nom, lire) if nom else None
        if profil:
            return profil
    from repas import stock
    return Profil("defaut", stock.dossier_commun(), {})


# ------------------------------------------------------------------ creer un profil
def calculer(champs: dict) -> dict:
    """Besoins d'une personne d'apres ses reponses : metabolisme de base
    (Mifflin-St Jeor), depense selon l'activite, calories selon l'objectif,
    proteines par kilo, vitamines (ANSES)."""
    femme = str(champs["sexe"]).lower().startswith("f")
    poids, taille, age = float(champs["poids_kg"]), float(champs["taille_cm"]), int(champs["age"])
    base = 10 * poids + 6.25 * taille - 5 * age + (-161 if femme else 5)
    depense = base * ACTIVITES[champs["activite"]][0]
    ecart, prot_kg, nom = OBJECTIFS[champs["objectif"]]
    kcal = int(round(depense * (1 + ecart) / 50) * 50)
    return {"metabolisme": round(base), "depense": round(depense), "kcal": kcal,
            "prot": int(round(poids * prot_kg / 5) * 5), "objectif": nom,
            "vitamines": P.besoins_vitamines("femme" if femme else "homme", kcal)}


def _telephone(v) -> str:
    t = re.sub(r"[\s.-]", "", str(v or ""))
    if not re.fullmatch(r"\+?\d{6,15}", t):
        raise ValueError("Téléphone : un numéro, par exemple 06 12 34 56 78.")
    return t


def _naissance(v) -> tuple:
    """(date ISO, âge en années) ; ValueError si la date est impossible."""
    import datetime
    try:
        d = datetime.date.fromisoformat(str(v or "").strip())
    except ValueError:
        raise ValueError("Date de naissance : jour, mois et année.")
    t = datetime.date.today()
    age = t.year - d.year - ((t.month, t.day) < (d.month, d.day))
    if not 15 <= age <= 95:
        raise ValueError("Date de naissance : entre 15 et 95 ans.")
    return d.isoformat(), age


def valider(champs: dict, lire=None, creation: bool = True) -> dict:
    """Champs du formulaire nettoyes ; ValueError (message lisible) si un champ est faux.
    À la création (Taha, 19/11/2026) : prénom, nom, identifiant, date de naissance, sexe, téléphone, taille et poids."""
    def nombre(cle, mini, maxi, nom):
        try:
            v = float(str(champs.get(cle, "")).replace(",", "."))
        except ValueError:
            v = None
        if v is None or not mini <= v <= maxi:
            raise ValueError(f"{nom} : un nombre entre {mini} et {maxi}.")
        return v
    ident = str(champs.get("identifiant", "")).strip().lower()
    if not re.fullmatch(r"[a-z0-9_-]{3,20}", ident) or ident in ("admin", "defaut"):
        raise ValueError("Identifiant : 3 à 20 lettres minuscules, chiffres ou tirets.")
    if ident in liste(lire):
        raise ValueError("Cet identifiant est déjà pris.")
    nom = str(champs.get("prenom") or champs.get("nom") or "").strip()[:40]
    if not nom:
        raise ValueError("Indique ton prénom.")
    nom_famille = str(champs.get("nom_famille") or "").strip()[:60]
    if creation and not nom_famille:
        raise ValueError("Indique ton nom.")
    telephone = _telephone(champs["telephone"]) if creation or champs.get("telephone") else ""
    if champs.get("date_naissance") or creation:
        naissance, age = _naissance(champs.get("date_naissance"))
    else:
        naissance, age = "", int(nombre("age", 15, 95, "Âge"))
    if len(str(champs.get("mot_de_passe", ""))) < 8:
        raise ValueError("Mot de passe : 8 caractères au moins.")
    if champs.get("activite") not in ACTIVITES or champs.get("objectif") not in OBJECTIFS:
        raise ValueError("Choisis ton niveau d'activité et ton objectif.")
    sexe = "femme" if str(champs.get("sexe", "")).lower().startswith("f") else "homme"
    enseigne = str(champs.get("enseigne") or "Auchan")
    return {"identifiant": ident, "nom": nom, "nom_famille": nom_famille, "telephone": telephone,
            "date_naissance": naissance, "sexe": sexe, "age": age,
            "taille_cm": int(nombre("taille_cm", 130, 220, "Taille")),
            "poids_kg": round(nombre("poids_kg", 35, 250, "Poids"), 1),
            "activite": champs["activite"], "objectif": champs["objectif"],
            "budget_mois": int(nombre("budget_mois", 100, 2000, "Budget")) if champs.get("budget_mois") not in (None, "") else 300,
            "adresse": str(champs.get("adresse", "")).strip()[:120],
            "boucher": bool(champs.get("boucher")), "fodmap": bool(champs.get("fodmap")),
            "enseigne": enseigne if enseigne in ("Auchan", "Leclerc") else "Auchan"}


def creer(champs: dict, port_chrome: int, lire=None) -> Profil:
    """Cree le dossier du profil : profil.yaml, historique vide et PROFIL.md (sa fiche)."""
    base = racine(lire)
    if not base:
        raise ValueError("repas.profils n'est pas regle dans config.yaml.")
    c = valider(champs, lire)
    b = calculer(c)
    dossier = base / "profils" / c["identifiant"]
    dossier.mkdir(parents=True)
    donnees = {
        "identite": {k: c[k] for k in ("nom", "nom_famille", "date_naissance", "telephone", "sexe", "age", "taille_cm", "poids_kg")}
                    | {"activite": c["activite"], "cree_le": time.strftime("%Y-%m-%d")},
        "programme": {"nom": b["objectif"], "objectif": b["objectif"],
                      "calcul": {"metabolisme_de_base": b["metabolisme"], "depense_par_jour": b["depense"]},
                      "phases": [{"n": 1, "nom": b["objectif"], "jusqu_a": "2099-12",
                                  "kcal": b["kcal"], "prot": b["prot"]}]},
        "vitamines": b["vitamines"],
        "budget_mois": c["budget_mois"],
        "preferences": {"modes": ["fodmap"] if c["fodmap"] else []},
        "alimentation": {"regime": "halal" if c["boucher"] else "",
                         "boucher": VIANDES if c["boucher"] else [],
                         "retirer": [], "composition_interdite": [], "plats_exclus": []},
        "courses": {"adresse": c["adresse"], "enseigne_principale": c["enseigne"],
                    "enseignes_catalogue": [e for e in ("Auchan", "Leclerc") if e != c["enseigne"]],
                    "max_enseignes": 2, "economie_min": 5},
        "navigateur": {"port": int(port_chrome), "dossier": "chrome"},
        "liens": {"ponderation": "../../ponderation.yaml", "fiches": "../../repas.json",
                  "historique": "historique.json", "stock": "stock.csv",
                  "mouvements": "mouvements.csv"},
    }
    entete = ("# Profil cree depuis le site Mon Meal Prep. Meme format que les autres profils :\n"
              "# tout peut etre corrige a la main (voir SCHEMA.md).\n\n")
    (dossier / "profil.yaml").write_text(
        entete + yaml.safe_dump(donnees, allow_unicode=True, sort_keys=False), encoding="utf-8")
    (dossier / "historique.json").write_text(
        json.dumps({"profil": c["identifiant"], "semaines": [], "notes": []}), encoding="utf-8")
    profil = Profil(c["identifiant"], dossier, donnees)
    ecrire_fiche(profil)
    return profil


def modifier(profil: Profil, champs: dict, lire=None) -> Profil:
    """La personne corrige ce qu'elle avait repondu a la creation (poids, activite,
    objectif, FODMAP, boucher…) : besoins recalcules, profil.yaml et PROFIL.md reecrits.
    Reserve aux profils crees depuis le site (les autres sont ecrits a la main)."""
    d = profil.donnees
    ident = d.setdefault("identite", {})
    if "prenom" in champs or "nom" in champs:
        v = str(champs.get("prenom") or champs.get("nom") or "").strip()[:40]
        if not v:
            raise ValueError("Indique ton prénom.")
        ident["nom"] = v
    if "nom_famille" in champs:
        ident["nom_famille"] = str(champs["nom_famille"] or "").strip()[:60]
    if champs.get("telephone") not in (None, ""):
        ident["telephone"] = _telephone(champs["telephone"])
    if champs.get("date_naissance"):
        ident["date_naissance"], ident["age"] = _naissance(champs["date_naissance"])
    if not profil.calcule:
        # Profil écrit à la main (son programme vient de son fichier) : on garde ses besoins, on met à jour la personne.
        for cle, mini, maxi in (("taille_cm", 130, 220), ("poids_kg", 35, 250)):
            if champs.get(cle) not in (None, ""):
                try:
                    v = float(str(champs[cle]).replace(",", "."))
                except ValueError:
                    v = None
                if v is None or not mini <= v <= maxi:
                    raise ValueError(f"{'Taille' if cle == 'taille_cm' else 'Poids'} : un nombre entre {mini} et {maxi}.")
                ident[cle] = int(v) if cle == "taille_cm" else round(v, 1)
        if champs.get("sexe"):
            ident["sexe"] = "femme" if str(champs["sexe"]).lower().startswith("f") else "homme"
        if "fodmap" in champs:
            pref = d.get("preferences") if isinstance(d.get("preferences"), dict) else {}
            autres = [m for m in pref.get("modes") or [] if m != "fodmap"]
            d["preferences"] = {**pref, "modes": autres + (["fodmap"] if champs["fodmap"] else [])}
        (profil.dossier / "profil.yaml").write_text(
            "# Profil (informations modifiées depuis Réglages).\n\n" + yaml.safe_dump(d, allow_unicode=True, sort_keys=False), encoding="utf-8")
        ecrire_fiche(profil)
        return profil
    actuel = {**profil.valeur("identite", {}), "budget_mois": profil.budget_mois,
              "adresse": profil.valeur("courses.adresse", ""),
              "enseigne": profil.valeur("courses.enseigne_principale", "Auchan"),
              "boucher": bool(profil.valeur("alimentation.boucher")),
              "fodmap": "fodmap" in profil.preferences["modes"],
              "objectif": next((k for k, o in OBJECTIFS.items() if o[2] == profil.valeur("programme.nom")), "maintien")}
    actuel["age"] = ident.get("age", actuel.get("age"))
    c = valider({**actuel, **{k: v for k, v in champs.items() if k in actuel},
                 "identifiant": "zz-modification", "mot_de_passe": "x" * 8}, lambda cle, defaut=None: defaut, creation=False)
    b = calculer(c)
    d["identite"].update({k: c[k] for k in ("sexe", "taille_cm", "poids_kg", "activite")})
    d["programme"].update({"nom": b["objectif"], "objectif": b["objectif"],
                           "calcul": {"metabolisme_de_base": b["metabolisme"], "depense_par_jour": b["depense"]},
                           "phases": [{"n": 1, "nom": b["objectif"], "jusqu_a": "2099-12",
                                       "kcal": b["kcal"], "prot": b["prot"]}]})
    d["vitamines"] = b["vitamines"]
    autres = [m for m in profil.preferences["modes"] if m != "fodmap"]
    d["preferences"] = {**(d.get("preferences") if isinstance(d.get("preferences"), dict) else {}),
                        "modes": autres + (["fodmap"] if c["fodmap"] else [])}      # garde fruits_secs
    d.setdefault("alimentation", {}).update({"regime": "halal" if c["boucher"] else "",
                                             "boucher": VIANDES if c["boucher"] else []})
    (profil.dossier / "profil.yaml").write_text(
        "# Profil cree depuis le site Mon Meal Prep (modifie depuis Reglages).\n\n"
        + yaml.safe_dump(d, allow_unicode=True, sort_keys=False), encoding="utf-8")
    ecrire_fiche(profil)
    return profil


def ecrire_fiche(profil: Profil) -> Path:
    """PROFIL.md : la fiche lisible du profil (objectifs, besoins, regles)."""
    v = profil.valeur
    phase = P.phase_du_jour(phases=profil.phases)
    besoins = profil.besoins_vitamines(phase["kcal"])
    try:
        with open(Path(P.__file__).parent / "site" / "nutriments.json", encoding="utf-8") as h:
            noms = json.load(h)["vitamines"]
    except (OSError, ValueError, KeyError):
        noms = {}
    fr = lambda x: f"{x:g}".replace(".", ",")
    lignes = [f"# Profil de {v('identite.nom', profil.nom)}", "",
              f"Identifiant sur le site : `{profil.nom}`.", "",
              "## Qui", "", "| | |", "|---|---|",
              f"| Sexe | {v('identite.sexe', '')} |", f"| Âge | {v('identite.age', '')} ans |",
              f"| Taille | {v('identite.taille_cm', '')} cm |",
              f"| Poids | {fr(v('identite.poids_kg', 0))} kg |"]
    if v("identite.activite") in ACTIVITES:
        lignes.append(f"| Activité | {ACTIVITES[v('identite.activite')][1]} |")
    lignes += ["", "## Objectif", "", f"**{v('programme.nom', '')}**", ""]
    if v("programme.calcul.depense_par_jour"):
        lignes += [f"Métabolisme de base {v('programme.calcul.metabolisme_de_base')} kcal "
                   f"(formule de Mifflin-St Jeor), dépense estimée "
                   f"{v('programme.calcul.depense_par_jour')} kcal par jour avec l'activité.", ""]
    lignes += ["| Phase | Jusqu'à | Calories | Protéines |", "|---|---|---|---|"]
    lignes += [f"| {p['n']}. {p['nom']} | {p['jusqu_a']} | {p['kcal']} kcal | {p['prot']} g |"
               for p in profil.phases]
    lignes += ["", f"## Vitamines : besoins par jour (phase {phase['n']}, {phase['kcal']} kcal)", "",
               "| Vitamine | Besoin |", "|---|---|"]
    lignes += [f"| {noms.get(c, {}).get('nom', 'Vitamine ' + c)} | {fr(q)} {noms.get(c, {}).get('unite', '')} |"
               for c, q in besoins.items()]
    lignes += ["", "Références nutritionnelles de l'ANSES pour un adulte. B1 et B2 suivent les "
               "calories (0,14 et 0,17 mg par mégajoule). Ce sont des repères, pas un avis médical.",
               "", "## Courses", "", f"- Budget : {profil.budget_mois} € par mois.",
               f"- Enseigne : {v('courses.enseigne_principale', 'Auchan')}.",
               f"- Adresse : {v('courses.adresse', '') or 'non renseignée'}.",
               "- Viande : " + ("achetée chez le boucher, jamais mise au panier."
                                if v("alimentation.boucher") else "mise au panier comme le reste."),
               "", "## Préférences", ""]
    pref = profil.preferences
    lignes += ["- Modes cochés par défaut : "
               + (", ".join(P.NOMS_MODES[m] for m in pref["modes"]) or "aucun") + ".",
               "- Fruits secs : " + ("une poignée par jour." if pref["fruits_secs"] else "non.") + "", ""]
    f = profil.dossier / "PROFIL.md"
    f.write_text("\n".join(lignes), encoding="utf-8")
    return f

repas/serveur.py:
"""Site « Mon Meal Prep » servi en local par Jarvis.

    python jarvis14.py --repas-site        ->  http://127.0.0.1:8770

Le site ne fait que demander ; c'est ce module qui decide et qui agit :
choix automatique de la semaine, notes des plats, stock, panier rempli par Jarvis
(commandes --repas-prix puis --repas-panier lancees a part), commande passee,
repas prepares. Chaque decision est ecrite dans le journal avec ses raisons.

Ecoute sur 127.0.0.1, ou sur le Wi-Fi de la maison (repas.acces_wifi) avec un
identifiant et un mot de passe par personne.

Fichiers du PROFIL actif (repas/profil.py) : profil.yaml (objectifs), la
ponderation liee, historique.json (semaines, plats cuisines, notes), stock.csv et
mouvements.csv, plus semaine.json et journal.json. Donnees de marche communes
(offres, prix releves, paniers) : donnees_repas/.
"""
from __future__ import annotations

import contextlib
import gzip
import hashlib
import hmac
import io
import ipaddress
import json
import math
