from repas import base, cli, etiquettes as mod_etiquettes, export as mod_export, journal_repas as mod_journal, navigateur, pdf, planification as P, plat_perso as mod_perso, photo_perso as mod_photo, profil as mod_profil, stock as mod_stock

_SITE = Path(__file__).resolve().parent / "site"
_RACINE = Path(__file__).resolve().parent.parent
_VERROU = threading.RLock()
_TACHE = {"etat": "repos", "titre": "", "lignes": [], "debut": None, "fin": None, "profil": ""}


# ------------------------------------------------------------------ fichiers
_ALERTES = []                           # fichiers illisibles mis de cote, montres sur le site


def consigner(type_: str, detail: str = "") -> None:
    """Une ligne dans donnees_repas/site.log : erreurs, connexions refusees, fichiers illisibles."""
    with contextlib.suppress(OSError):
        with open(mod_stock.dossier_commun() / "site.log", "a", encoding="utf-8") as h:
            h.write(f"{time.strftime('%Y-%m-%dT%H:%M:%S')} {type_} {detail}".rstrip() + "\n")


def _json(f: Path, defaut):
    """Lit un fichier JSON. Absent : `defaut`. Illisible : le fichier est mis de cote
    (« .corrompu-date ») et signale sur le site, au lieu d'etre pris pour un fichier vide."""
    try:
        with open(f, encoding="utf-8") as h:
            return json.load(h)
    except OSError:
        return defaut
    except ValueError:
        cote = f.with_name(f"{f.name}.corrompu-{time.strftime('%Y%m%d-%H%M%S')}")
        with contextlib.suppress(OSError):
            f.replace(cote)
        _ALERTES.append({"date": time.time(), "fichier": f.name, "dossier": str(f.parent),
                         "texte": f"Le fichier « {f.name} » était illisible. Il est mis de côté sous le nom "
                                  f"« {cote.name} » : restaure une sauvegarde, ou recompose."})
        del _ALERTES[:-20]
        consigner("fichier-illisible", str(f))
        return defaut


def _ecrire_json(f: Path, donnees) -> None:
    f.parent.mkdir(parents=True, exist_ok=True)
    tmp = f.with_suffix(".tmp")
    with open(tmp, "w", encoding="utf-8") as h:
        json.dump(donnees, h, ensure_ascii=False, indent=1)
    tmp.replace(f)


def alertes() -> list:
