def sauvegarder(force: bool = False) -> Path | None:
    """Copie datee des profils (historique, stock, semaines, reglages), une par jour,
    les 14 dernieres gardees. Dossier : repas.sauvegardes, sinon
    ~/.local/share/mon-meal-prep/sauvegardes. Les Chrome de profil ne sont pas copies."""
    base = mod_profil.racine(reglage)
    if not base or not (base / "profils").is_dir():
        return None
    racine = Path(str(reglage("repas.sauvegardes", "") or "~/.local/share/mon-meal-prep/sauvegardes")).expanduser()
    cible = racine / time.strftime("%Y-%m-%d")
    if cible.exists() and not force:
        return None
    tmp = racine / (cible.name + ".tmp")
    shutil.rmtree(tmp, ignore_errors=True)
    ignorer = lambda _, noms: [n for n in noms if n == "chrome" or n.endswith(".tmp") or ".corrompu-" in n]
    shutil.copytree(base / "profils", tmp / "profils", ignore=ignorer)
    for nom in ("ponderation.yaml",):
        if (base / nom).is_file():
            shutil.copy2(base / nom, tmp / nom)
    shutil.rmtree(cible, ignore_errors=True)
    tmp.replace(cible)
    anciennes = sorted(d for d in racine.iterdir() if d.is_dir() and re.fullmatch(r"\d{4}-\d{2}-\d{2}", d.name))
    for d in anciennes[:-14]:
        shutil.rmtree(d, ignore_errors=True)
    return cible


def _sauvegardes_en_fond() -> None:
    """Une sauvegarde au lancement du site, puis une par jour tant qu'il tourne."""
    def boucle():
        while True:
            try:
                sauvegarder()
            except Exception:                      # disque plein, droits : on le note, le site continue
                consigner("sauvegarde-ratee", traceback.format_exc().strip().splitlines()[-1])
            time.sleep(3600)
    threading.Thread(target=boucle, daemon=True).start()


