def _historique() -> dict:
    """historique.json du profil : {profil, semaines: […], notes: […], gouts: {plat: avis}}."""
    donnees = _json(_profil().lien("historique", "historique.json"), {})
    if not isinstance(donnees, dict):
        donnees = {}
    donnees.setdefault("profil", _profil().nom)
    donnees.setdefault("semaines", [])
    donnees.setdefault("notes", [])
    if not isinstance(donnees.get("gouts"), dict):
        donnees["gouts"] = {}
    return donnees


def _ecrire_historique(h: dict) -> None:
    _ecrire_json(_profil().lien("historique", "historique.json"), h)


def _semaines_passees(sauf: str = "") -> list:
    """Plats des semaines reellement engagees (panier, commande, cuisine), la plus
    recente d'abord : sert a ne pas reproposer le meme menu."""
    return [sorted(p["id"] for p in s.get("plats", []))
            for s in reversed(_historique()["semaines"])
            if s.get("id") != sauf and s.get("etat") in ("panier", "commandee", "terminee")]


def _inscrire(plan: dict, retirer: str = "") -> None:
    """Ecrit (ou met a jour) la semaine dans l'historique du profil. `retirer` =
    identifiant d'une semaine seulement proposee, qu'elle remplace."""
    h = _historique()
    noms = {r["id"]: r for r in donnees_site()["recettes"]}
    notes = {n["plat"]: n["note"] for n in h["notes"] if n.get("semaine") == plan["cree_le"]}
    resume = {
        "id": plan["cree_le"], "cree_le": plan["cree_le"], "debut": plan.get("debut"), "etat": plan["etat"],
        "phase": plan["phase"], "objectif": plan["objectif"],
        "budget_semaine": plan["budget_semaine"], "cout": plan["cout"],
        "panier": plan.get("panier"), "paye": plan.get("paye"),
        "paye_total": paye_reel(plan.get("paye")),
        "modes": plan.get("modes", []),
        "vitamines": {v: x["pct"] for v, x in (plan.get("vitamines") or {}).items()},
        "jours": [{k: j.get(k) for k in ("jour", "pdj", "dej", "collations", "din", "fruits",
                                         "facteur", "kcal", "prot", "cout")}
                  | {"dej_reste": bool(j.get("dej_reste")),
                     "cuisine": [{"id": c["id"], "portions": c["portions"], "quand": c["quand"],
                                  "fait_le": plan.get("prepares", {}).get(f"{n}|{c['id']}")}
                                 for c in j.get("cuisine", [])]}
                  for n, j in enumerate(plan["jours"])],
        "plats": [{"id": i, "nom": noms[i]["nom"] if i in noms else i,
                   "categorie": noms[i]["cat"] if i in noms else "",
                   "portions": c["portions"], "score": c["score"],
                   "raisons": [r["texte"] for r in c["raisons"]],
                   "prepare_le": max((d for k, d in plan.get("prepares", {}).items()
                                      if k.split("|")[-1] == i), default=None),
                   "note": notes.get(i)}
                  for i, c in plan["choix"].items()],
    }
    h["semaines"] = [s for s in h["semaines"] if s.get("id") not in (plan["cree_le"], retirer)]
    h["semaines"].append(resume)
    _ecrire_historique(h)


def _enregistrer_semaine(plan: dict, retirer: str = "") -> None:
    _ecrire_p("semaine.json", plan)
    _inscrire(plan, retirer)


_FICHIERS = {}                          # chemin -> (date du fichier, contenu)
_FICHES = {}                            # profil -> (cle, version, fiches)


def _date(f: Path) -> int:
    try:
        return f.stat().st_mtime_ns
    except OSError:
        return 0


def _garde(f: Path):
    """Contenu d'un fichier JSON du site, relu seulement quand le fichier change.
    Le meme objet est rendu a chaque appel : il ne faut pas le modifier."""
    date = _date(f)
    connu = _FICHIERS.get(str(f))
    if connu is None or connu[0] != date:
        with open(f, encoding="utf-8") as h:
            connu = _FICHIERS[str(f)] = (date, json.load(h))
    return connu[1]


RIEN = {"id": P.RIEN, "cat": "rien", "slot": "", "emoji": "", "nom": "Repas retiré", "tags": [], "kcal": 0, "prot": 0,
        "gluc": 0, "lip": 0, "fib": 0, "four": "", "ing": [], "temps": 0, "etapes": [], "fodmap": True,
        "origine": "", "genre": ""}
_FUSIONS = {}                           # profil -> (cle, recettes du site + plats du profil)


def plats_perso() -> list:
    """Les plats crees par le profil actif (plats_perso.json), au format des recettes."""
    plats = _lire_p("plats_perso.json", [])
    plats = [x for x in plats if isinstance(x, dict) and str(x.get("id", "")).startswith("perso-")
             and isinstance(x.get("ing"), list)] if isinstance(plats, list) else []
    # Plats « tel quel » enregistres avant le 14/11/2026 (sans le drapeau) : reconnus a leurs etapes.
    tel_quel = ("Rien à préparer : à manger tel quel.", "Réunis les ingrédients et mange.")
    return [{**x, "tel_quel": True} if not x.get("tel_quel") and x.get("etapes") and x["etapes"][0] in tel_quel else x
            for x in plats]


def donnees_site() -> dict:
    """Recettes, prix et rayons du site, plus la recette vide (un repas retire) et les
    plats du profil actif. Le meme objet tant que rien ne change : _fiches s'y fie."""
    socle = _garde(_SITE / "recettes.json")
    try:
        profil = _profil()
        fichier = profil.fichier("plats_perso.json")
    except Exception:
        return socle
    ajustees, remplaces = profil.fichier("recettes_ajustees.json"), profil.fichier("remplacements.json")
    cle = (id(socle), _date(fichier), _date(ajustees), _date(remplaces), _date(profil.fichier("ingredients_perso.json")))
    connu = _FUSIONS.get(profil.nom)
    if connu is None or connu[0] != cle:
        pris = {r["id"] for r in socle["recettes"]}
        toutes = socle["recettes"] + [RIEN] + [x for x in plats_perso() if x["id"] not in pris]
        quantites = _json(ajustees, {})
        if isinstance(quantites, dict) and quantites:
            toutes = [_ajustee(r, quantites[r["id"]]) if r["id"] in quantites else r for r in toutes]
        prix = socle["prix"]
        echanges = _json(remplaces, {})
        if isinstance(echanges, dict) and echanges:
            toutes = [_remplacee(r, echanges) for r in toutes]
            prix = {**{e["nom"]: e["prix"] for e in echanges.values() if e.get("prix")}, **prix}
        perso = ingredients_perso()
        if perso:                       # valeurs corrigees ou ingredients crees : les recettes touchees sont recalculees
            table = nutriments()
            toutes = [{**r, **(P.macros(r, table) or {})} if any(i["n"] in perso for i in r.get("ing", [])) else r
                      for r in toutes]
            prix = {**prix, **{n: float(v["prix"]) for n, v in perso.items()
                               if isinstance(v.get("prix"), (int, float)) and v["prix"] > 0}}
        connu = _FUSIONS[profil.nom] = (cle, {**socle, "recettes": toutes, "prix": prix, "_socle": socle})
    return connu[1]


def _ajustee(recette: dict, quantites: dict) -> dict:
    """La recette avec les quantites choisies par le profil ({ingredient: quantite}) et ses
    calories, proteines, glucides, lipides et fibres recalcules."""
    return {**P.avec_quantites(recette, quantites, nutriments()), "ajustee": True}


def _quantites_choisies(base: dict, demande: dict) -> dict:
    """Ce que l'utilisateur a choisi pour une portion de `base`, verifie : {ingredient: quantite}
    pour ceux de la recette (0 = retire), {ingredient: {"q", "u", "a"}} pour ceux qu'il ajoute.
    Un ingredient ajoute vaut une quantite, None (sa quantite habituelle) ou {"comme": ingredient
    remplace} (la quantite de celui-ci si l'unite est la meme). Seuls les changements sont gardes."""
    dans = {i["n"]: i for i in base["ing"]}
    connus = {**mod_perso.habitudes([x for x in donnees_site()["recettes"] if not x.get("perso")]), **_ingredients_crees()}
    table = nutriments().get("macros") or {}
    propres, ajoutes = {}, {}
    for brut, q in (demande or {}).items():
        nom = str(brut)
        if nom not in dans:
            trouve, proches = mod_perso.trouver(nom, connus)
            if not trouve or trouve not in table or connus[trouve]["u"] == "qs":
                raise ValueError(f"Je ne connais pas « {nom[:40]} »." + (f" Tu voulais dire {', '.join(proches[:3])} ?" if proches else "")
                                 + " Sinon crée-le dans « Mon propre plat ».")
            nom = trouve
        if nom in dans:
            i = dans[nom]
            if i["u"] == "qs":
                continue
            if q is None:                                    # deja dans la recette : sa quantite de la recette
                q = i["q"]
            elif isinstance(q, dict) and "comme" in q:       # remplace un autre ingredient : les deux quantites
                pareil = dans.get(str(q["comme"]))
                q = i["q"] + (pareil["q"] if pareil and pareil["u"] == i["u"] and pareil is not i else 0)
            q = float(q["q"] if isinstance(q, dict) else q)
            if not 0 <= q <= max(i["q"] * 10, 10):
                raise ValueError(f"{nom} : entre 0 et {mod_stock.fmt(max(i['q'] * 10, 10))} {i['u']}")
            if abs(q - i["q"]) > 1e-6:
                propres[nom] = round(q, 2)
            continue
        h = connus[nom]
        if isinstance(q, dict) and "comme" in q:
            pareil = dans.get(str(q["comme"]))
            q = pareil["q"] if pareil and pareil["u"] == h["u"] else h["q"]
        elif isinstance(q, dict):
            q = q.get("q")
        q = h["q"] if q is None else float(q)
        if not 0 <= q <= max(h["q"] * 10, 10):
            raise ValueError(f"{nom} : entre 0 et {mod_stock.fmt(max(h['q'] * 10, 10))} {h['u']}")
        if q > 0:
            ajoutes[nom] = {"q": round(q, 2), "u": h["u"], "a": int(h["a"])}
    if len(dans) + len(ajoutes) > 25:
        raise ValueError("25 ingrédients au plus")
    return {**propres, **ajoutes}


def _remplacee(recette: dict, echanges: dict) -> dict:
    """La recette ou les ingredients introuvables au magasin sont remplaces par ceux que le
    profil a choisis (remplacements.json : {ingredient: {nom, rapport}}). La quantite suit le
    rapport ; une premiere etape le rappelle a qui cuisine."""
    if not any(i["n"] in echanges for i in recette["ing"]):
        return recette
    ing, faits = [], []
    for i in recette["ing"]:
        e = echanges.get(i["n"])
        if e:
            faits.append({"n": e["nom"], "de": i["n"]})
            i = {**i, "n": e["nom"], "q": i["q"] if i["u"] == "qs" else round(i["q"] * float(e.get("rapport") or 1), 2)}
        meme = next((x for x in ing if x["n"] == i["n"] and x["u"] == i["u"]), None)
        if meme:                                             # le remplacant etait deja dans la recette
            meme["q"] = round(meme["q"] + i["q"], 2)
        else:
            ing.append(dict(i))
    calcul = P.macros({"ing": ing}, nutriments()) if all(
        i["u"] == "qs" or i["n"] in (nutriments().get("macros") or {}) for i in ing) else None
    note = "Remplacement : " + ", ".join(f"{f['n']} à la place de {f['de'].lower()}" for f in faits) \
           + " (introuvable au magasin). Même préparation."
    return {**recette, "ing": ing, **(calcul or {}), "remplaces": faits, "etapes": [note] + list(recette["etapes"])}


def _origine(ident: str) -> dict | None:
    """La recette telle qu'elle est sans ajustement du profil."""
    return next((r for r in _garde(_SITE / "recettes.json")["recettes"] + plats_perso() if r["id"] == ident), None)


def _plan_de(semaine) -> dict | None:
    mois = _mois() if rythme() == "mois" else None
    rang = mois["rang"] if mois else 0
    k = rang if semaine is None else int(semaine)
    if k == rang:
        return _lire_p("semaine.json", None)
    return mois["semaines"][k] if mois and 0 <= k < len(mois["semaines"]) else None


def ajuster_recette(ident: str, quantites: dict | None, apercu: bool = True, jour=None, semaine=None) -> dict:
    """Tu changes les quantites d'une recette pour TON profil (plus de proteines, moins de
    gras…). Renvoie les chiffres avant et apres ; sans `apercu`, enregistre et refait les
    totaux des semaines composees, donc aussi les courses. `quantites` = {} : la recette
    d'origine ; None : les quantites deja enregistrees pour ce profil."""
    pour_un_jour = jour is not None
    if pour_un_jour:                                        # un jour seulement : on part de la recette du profil
        base = next((r for r in donnees_site()["recettes"] if r["id"] == ident), None)
        plan = _plan_de(semaine)
        if not base or not plan or not 0 <= int(jour) < len(plan["jours"]):
            raise ValueError("recette ou jour inconnu")
        apercu = True                                       # l'enregistrement passe par /api/semaine/modifier
        if quantites is None:
            quantites = (plan["jours"][int(jour)].get("ajustes") or {}).get(ident, {})
    else:
        base = _origine(ident)
    if not base:
        raise ValueError("recette inconnue")
    if quantites is None:                                   # a l'ouverture : les quantites deja choisies par le profil
        deja = _lire_p("recettes_ajustees.json", {})
        quantites = deja.get(ident, {}) if isinstance(deja, dict) else {}
    propres = _quantites_choisies(base, quantites)
    nouvelle = _ajustee(base, propres) if propres else base
    if not any(i["q"] > 0 for i in nouvelle["ing"] if i["u"] != "qs"):
        raise ValueError("il faut garder au moins un ingrédient")
    recettes = donnees_site()
    tarifs = _contexte(recettes)["tarifs"]
    table, habitudes = nutriments().get("macros") or {}, mod_perso.habitudes(_garde(_SITE / "recettes.json")["recettes"])
    resultat = {"id": ident, "nom": base["nom"],
                "avant": {m: base.get(m) or 0 for m in P.MACROS}, "apres": {m: nouvelle.get(m) or 0 for m in P.MACROS},
                "cout_avant": tarifs.recette(base)[0], "cout": tarifs.recette(nouvelle)[0],
                "ingredients": [{"n": i["n"], "u": i["u"], "q": i["q"] if i["u"] == "qs" else propres.get(i["n"], i["q"]), "base": i["q"],
                                 "role": mod_perso.role(i["n"], habitudes.get(i["n"], {"u": i["u"], "a": i.get("a", 2)}), table)}
                                for i in base["ing"]]
                               + [{"n": n, "u": v["u"], "q": v["q"], "base": 0, "ajoute": True,
                                   "role": mod_perso.role(n, habitudes.get(n, {"u": v["u"], "a": v["a"]}), table)}
                                  for n, v in propres.items() if isinstance(v, dict)]}
    if apercu:
        return resultat
    with _VERROU:
        tout = _lire_p("recettes_ajustees.json", {})
        tout = tout if isinstance(tout, dict) else {}
        if propres:
            tout[ident] = propres
        else:
            tout.pop(ident, None)
        _ecrire_p("recettes_ajustees.json", tout)
        _recalculer_semaines()
        if not _achete():
            _devalider()
        a, b = resultat["avant"], resultat["apres"]
        journal("remplacement", f"Recette {'ajustée' if propres else 'remise à l’origine'} : « {base['nom']} »",
                [f"Une portion : {a['kcal']} kcal et {a['prot']} g de protéines avant, {b['kcal']} kcal et {b['prot']} g maintenant."]
                + (["Tes changements : " + ", ".join(f"{n} {mod_stock.fmt(q['q'] if isinstance(q, dict) else q)}"
                                                    + (" (ajouté)" if isinstance(q, dict) else " (retiré)" if not q else "")
                                                    for n, q in propres.items()) + "."] if propres else [])
                + ["Les semaines composées et les listes de courses sont recalculées."])
    return resultat


def _fixes() -> dict:
    """Les repas fixes de la personne, tous les jours : ceux qu'elle a fixés dans l'appli (bouton « Fixer »
    sur un plat, Taha, 19/11/2026), sinon ceux de son profil.yaml. {"petit_dej": id ou "", "collations": [ids]}."""
    choisi = _lire_p("reglages_site.json", {}).get("fixes")
    if isinstance(choisi, dict):
        return {"petit_dej": str(choisi.get("petit_dej") or ""), "collations": [str(i) for i in choisi.get("collations") or []]}
    p = _profil()
    return {"petit_dej": str(p.valeur("alimentation.petit_dej_fixe", "") or ""),
            "collations": [str(i) for i in p.valeur("alimentation.collations_fixes", []) or []]}


def _jours_a_venir(plan, faire) -> None:
    """faire(numero, jour) pour chaque jour de cette semaine, d'aujourd'hui à la fin (les jours passés ne bougent plus)."""
    import datetime
    debut = _debut(plan)
    if not debut:
        return
    for n, jour in enumerate(plan.get("jours", [])):
        if debut + datetime.timedelta(days=n) >= datetime.date.today() and not jour.get("retire"):
            faire(n, jour)


def eau_du_jour() -> dict:
    """Litres d'eau à boire par jour (Taha, 19/11/2026) : 35 ml par kilo de poids (la dernière pesée du suivi,
    sinon le poids du profil) ; sans poids, le repère de l'EFSA (2 L pour une femme, 2,5 L pour un homme)."""
    profil = _profil()
    poids = next((m["poids"] for m in suivi() if m.get("poids")), None) or profil.valeur("identite.poids_kg")
    try:
        poids = float(poids)
    except (TypeError, ValueError):
        poids = None
    if poids:
        return {"litres": round(poids * 0.035, 1), "selon": f"35 ml par kilo, pour {poids:g} kg".replace(".", ",")}
    femme = str(profil.valeur("identite.sexe", "")).lower().startswith("f")
    return {"litres": 2.0 if femme else 2.5, "selon": "repère pour un adulte"}


def fixer_plat(ident: str, moment: str, fixe: bool) -> None:
    """Fixe un plat (il revient chaque jour, toujours une portion) ou le défixe. Le petit-déjeuner et les collations
    se fixent ; le changement vaut tout de suite pour les jours qui viennent et pour les semaines composées ensuite."""
    recettes = {x["id"]: x for x in donnees_site()["recettes"]}
    if ident not in recettes or ident == P.RIEN:
        raise ValueError("recette inconnue")
    place = "pdj" if moment == "pdj" else "col" if str(moment).startswith("col") else None
    if place is None:
        raise ValueError("seuls le petit-déjeuner et les collations peuvent être fixes")
    with _VERROU:
        f = _fixes()
        if place == "pdj":
            f["petit_dej"] = ident if fixe else ("" if f["petit_dej"] == ident else f["petit_dej"])
        else:
            f["collations"] = [i for i in f["collations"] if i != ident] + ([ident] if fixe else [])
        _ecrire_p("reglages_site.json", {**_lire_p("reglages_site.json", {}), "fixes": f})

        def appliquer(plan):
            faits = plan.get("prepares", {})

            def jour_(n, jour):
                perso = [i for i in jour.get("perso") or [] if i != ident]
                if fixe:
                    if place == "pdj" and f"{n}|{jour['pdj']}" not in faits:
                        jour["pdj"] = ident
                    elif place == "col" and ident not in jour["collations"]:
                        jour["collations"].append(ident)
                    perso.append(ident)
                jour["perso"] = perso
            _jours_a_venir(plan, jour_)
        _recalculer_semaines(appliquer)
    journal("remplacement", f"{'Fixé' if fixe else 'Plus fixé'} : « {recettes[ident]['nom']} »",
            ["Il revient chaque jour, toujours une portion." if fixe else "Il reste au menu des jours prévus, à la taille du jour."])


def _fruits_secs_des_jours(oui: bool) -> None:
    """Une poignée de fruits secs par jour, ou plus du tout, pour les jours qui viennent. (Sous _VERROU.)"""
    recettes = donnees_site()["recettes"]
    secs = [x for x in recettes if x["cat"] == "fruit" and x.get("sec")]

    def appliquer(plan):
        fodmap = "fodmap" in (plan.get("modes") or [])
        sec = min(secs, key=lambda x: (bool(x.get("fodmap")) != fodmap, x["id"])) if secs else None

        def jour_(n, jour):
            jour["fruits_secs"] = {"id": sec["id"], "g": 30} if oui and sec else None
        _jours_a_venir(plan, jour_)
    _recalculer_semaines(appliquer)


def _recalculer_semaines(avant=None) -> None:
    """Les recettes du profil ont change : refait les totaux de toutes les semaines composees
    (donc les courses). `avant(plan)` retouche chaque semaine avant le calcul. (Sous _VERROU.)"""
    recettes = donnees_site()
    reglages = _reglages()
    phase = _phase(reglages)
    ctx = {**_contexte(recettes), "phase": phase, "besoins_vitamines": _profil().besoins_vitamines(
        phase["kcal"] + int(reglages.get("ajustement") or 0))}
    plan = _lire_p("semaine.json", None)
    if plan and all("cuisine" in j for j in plan.get("jours", [])):
        if avant:
            avant(plan)
        _enregistrer_semaine(P.recalculer(plan, recettes["recettes"], ctx))
    mois = _mois() if rythme() == "mois" else None
    if mois:
        for k, p in enumerate(mois["semaines"]):
            if plan and p.get("cree_le") == plan.get("cree_le"):
                mois["semaines"][k] = plan
            elif all("cuisine" in j for j in p.get("jours", [])):
                if avant:
                    avant(p)
                mois["semaines"][k] = P.recalculer(p, recettes["recettes"], ctx)
        _ecrire_p("mois.json", mois)


MACROS_ING = ("kcal", "prot", "gluc", "lip", "fib")     # pour 100 g ou 100 ml
_NUT_PERSO = {}                         # profil -> (cle, table du site + ingredients du profil)


def ingredients_perso() -> dict:
    """Ingredients crees ou corriges par le profil actif (ingredients_perso.json) :
    {nom: {kcal, prot, gluc, lip, fib pour 100 g ou 100 ml, source, le}} ; un ingredient
    cree a en plus {cree: True, u: "g"|"ml", q: portion habituelle, a: rayon, prix: euros au kilo ou au litre}."""
    try:
        d = _lire_p("ingredients_perso.json", {})
    except Exception:
        return {}
    if not isinstance(d, dict):
        return {}
    return {str(n): v for n, v in d.items() if isinstance(v, dict)
            and all(isinstance(v.get(m), (int, float)) for m in MACROS_ING)
            and (not v.get("cree") or (v.get("u") in ("g", "ml") and isinstance(v.get("q"), (int, float))))}


def nutriments() -> dict:
    """Table des vitamines et des macros par ingredient (repas/site/nutriments.json), avec
    les valeurs des ingredients crees ou corriges par le profil actif. Le meme objet tant
    que rien ne change : _fiches s'y fie."""
    try:
        socle = _garde(_SITE / "nutriments.json")
    except (OSError, ValueError):
        return {}
    try:
        profil = _profil()
        fichier = profil.fichier("ingredients_perso.json")
    except Exception:
        return socle
    cle = (id(socle), _date(fichier))
    connu = _NUT_PERSO.get(profil.nom)
    if connu is None or connu[0] != cle:
        perso = ingredients_perso()
        table = socle if not perso else {**socle, "macros": {
            **(socle.get("macros") or {}), **{n: {m: float(v[m]) for m in MACROS_ING} for n, v in perso.items()}}}
        connu = _NUT_PERSO[profil.nom] = (cle, table)
    return connu[1]


def _stock_couvre(recettes: list, stock: dict) -> dict:
    """{recette: part de ses ingredients (hors « au gout ») entierement en stock}, pour
    le filtre « faisable avec mon stock » du catalogue. Seules les parts non nulles."""
    if not stock:
        return {}
    couvre = {}
    for r in recettes:
        comptes = [i for i in r["ing"] if i["u"] != "qs"]
        prets = sum(1 for i in comptes if P.en_stock(stock, i["n"], i["q"], i["u"]) >= 0.999)
        if prets and comptes:
            couvre[r["id"]] = round(prets / len(comptes), 2)
    return couvre


def _fiches(recettes: dict, ctx: dict) -> tuple:
    """(version, fiches) : chaque recette avec son prix, ses promotions, ses vitamines,
    sa famille et sa photo. Calcule une fois, puis garde tant que rien ne change
    (recettes, vitamines, prix releves, photos)."""
    profil = _profil()
    table = ctx["nutriments"]
    cle = (id(recettes["recettes"]), id(table), str(mod_stock.dossier()),
           _date(mod_stock.dossier() / "offres.json"), _date(profil.lien("fiches", "repas.json")),
           _date(profil.fichier("photos")))                       # une photo de plat perso arrivee en fond
    connu = _FICHES.get(profil.nom)
    if connu is None or connu[0] != cle:
        avec_photo = photos_des_fiches()
        fiches = []
        for r in recettes["recettes"]:
            cout, eco, promos = ctx["tarifs"].recette(r)
            fiches.append({**r, "cout": cout, "economie": eco, "promos": promos,
                           "vitamines": P.vitamines(r, table),
                           # la date de la photo sert de version : une photo remplacee change d'adresse
                           "photo": (int(avec_photo[r["id"]].stat().st_mtime) if r["id"] in avec_photo else
                                     int(avec_photo[r["photo_de"]].stat().st_mtime) if r.get("photo_de") in avec_photo else False),
                           "famille": P.famille(r), "filtres": P.filtres(r, cout)})
        version = hashlib.sha256(json.dumps([fiches, recettes["rayons"]], ensure_ascii=False,
                                            sort_keys=True).encode("utf-8")).hexdigest()[:16]
        # recettes et table sont gardees ici pour que leur identite reste la leur
        connu = _FICHES[profil.nom] = (cle, version, fiches, recettes["recettes"], table)
    return connu[1], connu[2]


