def _phases() -> list:
    """Les périodes d'objectifs : celles que la personne a réglées elle-même dans l'appli (Taha, 19/11/2026 :
    « chacun règle pour lui-même »), sinon celles de son profil (calculées à la création, ou écrites à la main)."""
    perso = _lire_p("reglages_site.json", {}).get("phases")
    if isinstance(perso, list) and perso:
        return perso
    return _profil().phases


def _phase(reglages: dict) -> dict:
    import datetime
    phases = _phases()
    choisie = next((p for p in phases if p["n"] == reglages.get("phase")), None)
    if choisie:
        return choisie
    if phases and all(p.get("du") for p in phases):          # périodes réglées dans l'appli : au jour près
        aujourdhui = datetime.date.today().isoformat()
        return next((p for p in phases if p["du"] <= aujourdhui <= p["au"]),
                    next((p for p in phases if p["du"] > aujourdhui), phases[-1]))
    return P.phase_du_jour(phases=phases)


def regler_objectifs(phases: list) -> list:
    """Les périodes d'objectifs de la personne : [{nom, du, au, kcal, prot, glucides, lipides}], vérifiées ;
    une liste vide revient au programme du profil."""
    propres = []
    for k, x in enumerate(phases or []):
        if not isinstance(x, dict):
            raise ValueError("période illisible")
        nom = re.sub(r"\s+", " ", str(x.get("nom") or "")).strip()[:40] or f"Période {k + 1}"
        du, au = str(x.get("du") or ""), str(x.get("au") or "")
        if not (re.fullmatch(r"\d{4}-\d{2}-\d{2}", du) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", au)) or du > au:
            raise ValueError(f"« {nom} » : une date de début et une date de fin, dans l'ordre")

        def nombre(cle, mini, maxi, requis=True):
            v = x.get(cle)
            if v in (None, "") and not requis:
                return None
            try:
                v = float(str(v).replace(",", "."))
            except ValueError:
                v = None
            if v is None or not mini <= v <= maxi:
                raise ValueError(f"« {nom} » : {({'kcal': 'calories', 'prot': 'protéines'}).get(cle, cle)} entre {mini} et {maxi}")
            return int(round(v))
        propres.append({"nom": nom, "du": du, "au": au, "jusqu_a": au[:7], "kcal": nombre("kcal", 1000, 6000),
                        "prot": nombre("prot", 30, 400), "glucides": nombre("glucides", 0, 1000, False),
                        "lipides": nombre("lipides", 0, 400, False)})
    propres.sort(key=lambda p: p["du"])
    for a, b in zip(propres, propres[1:]):
        if b["du"] <= a["au"]:
            raise ValueError(f"« {a['nom']} » et « {b['nom']} » se chevauchent")
    propres = [{"n": k + 1, **{c: v for c, v in p.items() if v is not None}} for k, p in enumerate(propres)]
    with _VERROU:
        r = _lire_p("reglages_site.json", {})
        r["phases"] = propres
        r.pop("phase", None)                                   # la phase « choisie à la main » ne vaut plus
        _ecrire_p("reglages_site.json", r)
    journal("profil", "Objectifs par période réglés", [f"{p['nom']} : du {p['du']} au {p['au']}, {p['kcal']} kcal, {p['prot']} g de protéines."
                                                        for p in propres] or ["Retour au programme du profil."])
    return propres


def proposer_objectifs(demande: str) -> dict:
    """Claude propose des périodes d'objectifs d'après ce que la personne veut et qui elle est (avec SA clé)."""
    import datetime
    demande = re.sub(r"\s+", " ", str(demande or "")).strip()[:600]
    if len(demande) < 3:
        raise ValueError("dis à Claude ce que tu veux, par exemple : perdre 4 kg d'ici mars, puis garder mon poids")
    i = _profil().valeur("identite", {}) or {}
    qui = ", ".join(f"{k} : {v}" for k, v in (("sexe", i.get("sexe")), ("âge", i.get("age")),
                                              ("taille", f"{i.get('taille_cm')} cm" if i.get("taille_cm") else None),
                                              ("poids", f"{i.get('poids_kg')} kg" if i.get("poids_kg") else None),
                                              ("activité", i.get("activite"))) if v)
    idee = _claude_json(
        "Une personne règle ses objectifs nutritionnels par période dans son appli de repas (musculation, nutrition).\n"
        f"Elle : {qui or 'inconnue'}. Aujourd'hui : {datetime.date.today().isoformat()}.\n"
        f"Ce qu'elle veut : « {demande} »\n"
        "Propose des périodes qui se suivent, réalistes et prudentes (pas plus de 20 % sous la dépense en sèche, protéines "
        "1,6 à 2,2 g par kilo). Réponds UNIQUEMENT par du JSON : {\"phases\": [{\"nom\": court, \"du\": \"AAAA-MM-JJ\", "
        "\"au\": \"AAAA-MM-JJ\", \"kcal\": nombre, \"prot\": grammes, \"glucides\": grammes, \"lipides\": grammes}], "
        "\"explication\": une ou deux phrases}.", timeout=90)
    if not idee or not isinstance(idee.get("phases"), list):
        raise ValueError("Claude ne répond pas : branche ton compte Claude dans Réglages, ou règle les périodes toi-même")
    return {"phases": idee["phases"][:8], "explication": str(idee.get("explication") or "")[:400]}


def oublier_preparation(jour: int, ident: str) -> None:
    """« Pas encore mangé » : le plat n'est plus marqué (mode flemmard : rien à remettre en stock)."""
    with _VERROU:
        plan = _lire_p("semaine.json", None)
        if not plan or not 0 <= int(jour) < len(plan["jours"]):
            raise ValueError("jour inconnu")
        if not (plan.get("prepares") or {}).pop(f"{int(jour)}|{ident}", None):
            return
        if plan.get("etat") == "terminee":
            plan["etat"] = "validee"
        _enregistrer_semaine(plan)


# ------------------------------------------------------------------ semaine
def nb_semaines() -> int:
    """Semaines composees et commandees d'un coup (courses.semaines_par_commande du
    profil, sinon repas.semaines_par_commande). 1 = une semaine a la fois, tout au
    supermarche, comme a l'origine."""
    choisi = (_lire_p("reglages_site.json", {}).get("nb_semaines")        # choisi sur le site : passe avant le profil
              or _profil().valeur("courses.semaines_par_commande") or reglage("repas.semaines_par_commande", 1))
    try:
        return max(1, min(6, int(choisi)))
    except (TypeError, ValueError):
        return 1


def rythme() -> str:
    """"mois" (nom historique) des que plusieurs semaines sont commandees d'un coup :
    un panier de supermarche pour ces semaines, le marche chaque semaine, les
    fruits secs une fois par mois. Sinon "semaine"."""
    return "mois" if nb_semaines() > 1 else "semaine"


def _mois() -> dict | None:
    mois = _lire_p("mois.json", None)
    return mois if isinstance(mois, dict) and mois.get("semaines") else None


def _coches() -> tuple:
    """({"panier": noms, "marche": noms}, cles) : les produits que l'utilisateur a coches
    « j'en ai deja » dans Courses. Ceux du panier valent pour toute la commande (les semaines
    composees ensemble), ceux du marche pour la semaine en cours ; ils repartent a zero avec elles."""
    brut = _lire_p("courses_cochees.json", {})
    brut = brut if isinstance(brut, dict) else {}
    plan = _lire_p("semaine.json", None) or {}
    mois = _mois() if rythme() == "mois" else None
    cles = {"panier": (mois or plan).get("cree_le"), "marche": plan.get("cree_le")}
    return ({k: set((brut.get(k) or {}).get("noms") or []) if (brut.get(k) or {}).get("cle") == cles[k] else set()
             for k in cles}, cles)


def cocher_course(liste: str, nom: str, coche: bool) -> None:
    """Coche ou decoche un produit de Courses : coche = « j'en ai deja », Jarvis ne l'achete pas
    et il ne compte plus dans ce qui reste a acheter."""
    if liste not in ("panier", "marche"):
        raise ValueError("liste inconnue")
    with _VERROU:
        noms, cles = _coches()
        (noms[liste].add if coche else noms[liste].discard)(str(nom)[:80])
        _ecrire_p("courses_cochees.json", {k: {"cle": cles[k], "noms": sorted(noms[k])} for k in noms})


def _besoins_tries(plans: list, recettes: dict, quoi: str | None = None, restants: bool = False) -> tuple:
    """Besoins additionnes de plusieurs semaines, tries : boucher / retires / deja en
    stock / a acheter. `quoi` = "mois" ou "semaine" pour ne garder qu'un rythme d'achat."""
    rayon = {i["n"]: i["a"] for x in recettes["recettes"] for i in x["ing"]}
    totaux, ordre = {}, []
    for plan in plans:
        for b in P.besoins(plan, recettes["recettes"], restants):
            lieu = P.lieu_d_achat(b["nom"], rayon.get(b["nom"], 2))
            if quoi and lieu != quoi:
                continue
            cle = (b["nom"], b["unite"])
            if cle not in totaux:
                totaux[cle] = 0.0
                ordre.append(cle)
            totaux[cle] += b["quantite"]
    # Un meme produit demande en cuilleres a cafe ET a soupe (huile d'olive, sirop d'erable) :
    # une seule ligne, en cuilleres a soupe (1 c.à.s = 3 c.à.c).
    for nom, unite in [c for c in ordre if c[1] == "c.à.c" and (c[0], "c.à.s") in totaux]:
        totaux[(nom, "c.à.s")] += totaux.pop((nom, unite)) / 3
        ordre.remove((nom, unite))
    lecture = pdf.Lecture(
        ingredients=[pdf.Ingredient(n, round(totaux[(n, u)], 2), u) for n, u in ordre],
        recettes=sum(len(p["choix"]) for p in plans), portions_annoncees=round(sum(
            c["portions"] for p in plans for c in p["choix"].values())))
    tri = cli.preparer(lecture, mod_stock.charger())
    for l in tri["a_acheter"]:                     # fruits et legumes frais : pas d'etiquette a lire
        if rayon.get(l["nom"]) == 1:
            l["composition_a_verifier"] = False
    # Ce que l'utilisateur a coche « j'en ai deja » sort de la liste a acheter : ni commande
    # par Jarvis, ni compte dans les estimations, ni entre au stock au paiement.
    deja = _coches()[0]["marche" if quoi == "marche" else "panier"]
    tri["coches"] = [l for l in tri["a_acheter"] if l["nom"] in deja]
    tri["a_acheter"] = [l for l in tri["a_acheter"] if l["nom"] not in deja]
    for l in tri["boucher"]:
        l["coche"] = l["nom"] in deja
    return lecture, tri


def _a_acheter(plan: dict, recettes: dict) -> dict:
    """La liste de la SEMAINE. Quand plusieurs semaines sont commandees d'un coup,
    c'est la liste du marche : viande, poisson, fruits et legumes frais."""
    if rythme() == "mois" and _mois():
        return _besoins_tries([plan], recettes, "marche", restants=True)
    return _besoins_tries([plan], recettes)


def _liste_du_mois(recettes: dict) -> tuple | None:
    """Le panier du SUPERMARCHE pour la semaine en cours et les suivantes deja
    composees, moins le stock. None quand on commande une semaine a la fois."""
    mois = _mois()
    if rythme() != "mois" or not mois:
        return None
    courante = _lire_p("semaine.json", None)
    plans = ([courante] if courante else []) + mois["semaines"][mois["rang"] + 1:]
    return _besoins_tries(plans, recettes, "commande", restants=True)


def hors_panier(tri: dict) -> list:
    """Produits de la liste que Jarvis n'a PAS mis au panier, et pourquoi : a acheter
    toi-meme ailleurs. D'apres le dernier releve de l'enseigne principale."""
    mis = _lire("dans_les_paniers.json", {})
    cle = pdf.normaliser(_enseignes()[0]).replace(" ", "_")
    releve = {a["nom"]: a for a in _lire(f"prix_{cle}.json", {}).get("articles", {}).values()}
    raisons = {"aucun produit sans ingredient interdit": "aucun produit sans alcool, gélatine ni E471",
               "aucun produit correspondant": "introuvable chez l'enseigne",
               "format inadapté": "format vendu inadapté à la quantité"}
    resultat = []
    for l in tri["a_acheter"]:
        if l["nom"] in mis and not mis[l["nom"]].get("demandes"):
            continue
        a = releve.get(l["nom"], {})
        if l["nom"] in mis:
            raison = f"seulement {mis[l['nom']]['paquets']} sur {mis[l['nom']]['demandes']} ajoutés au panier"
        elif a.get("trouve"):
            raison = "l'ajout au panier a échoué"
        else:
            raison = raisons.get(a.get("note", ""), "introuvable chez l'enseigne")
            if a.get("format"):
                raison += f" (il faudrait {a['format']})"
        if not any(x["nom"] == l["nom"] for x in resultat):
            resultat.append({"nom": l["nom"], "acheter": l["acheter"], "unite": l["unite"], "raison": raison})
    return resultat


# ------------------------------------------------------------------ alternatives
def _plans_composes() -> list:
    """La semaine en cours et celles composees a sa suite."""
    plan = _lire_p("semaine.json", None)
    mois = _mois() if rythme() == "mois" else None
    return ([plan] if plan else []) + (mois["semaines"][mois["rang"] + 1:] if mois else [])


def manquants(tri: dict, recettes: dict) -> list:
    """Les produits restes hors du panier, avec les plats qui s'en servent et les produits
    de remplacement trouves chez l'enseigne (alternatives.json, cherches par Jarvis)."""
    trouvees = _lire("alternatives.json", {})
    articles = trouvees.get("articles", {}) if trouvees.get("enseigne") == _enseignes()[0] else {}
    choisis = {i for p in _plans_composes() for i in p.get("choix", {})}
    resultat = []
    for l in hors_panier(tri):
        plats = [r["nom"] for r in recettes["recettes"] if r["id"] in choisis and any(i["n"] == l["nom"] for i in r["ing"])]
        a = articles.get(l["nom"])
        resultat.append({**l, "plats": plats, "cherche": a is not None,
                         "alternatives": [{"nom": x["nom"], "pourquoi": x.get("pourquoi", ""), "quantite": x["quantite"],
                                           "unite": x["unite"], "produit": x["offre"]["nom"], "format": x["offre"].get("format", ""),
                                           "paquets": x["paquets"], "cout": x["cout"],
                                           "deja_au_panier": bool(x.get("deja_au_panier")),
                                           "composition_non_lue": bool(x.get("composition_non_lue"))}
                                          for x in (a or {}).get("alternatives", [])]})
    return resultat


def remplacements() -> list:
    """Les ingredients que le profil a remplaces dans ses recettes, faute de les trouver."""
    echanges = _lire_p("remplacements.json", {})
    return [{"de": de, "nom": e["nom"], "le": e.get("le")} for de, e in echanges.items()] if isinstance(echanges, dict) else []


def _demander_alternatives() -> int:
    """Ecrit pour Jarvis la liste des produits manquants a remplacer. Renvoie leur nombre."""
    recettes = donnees_site()
    plan = _lire_p("semaine.json", None)
    if not plan or not _lire("dans_les_paniers.json", None):
        return 0
    _, tri = _liste_du_mois(recettes) or _a_acheter(plan, recettes)
    liste = [{"nom": m["nom"], "acheter": m["acheter"], "unite": m["unite"], "plats": m["plats"]}
             for m in manquants(tri, recettes)]
    principale = _enseignes()[0]
    fodmap = any("fodmap" in (p.get("modes") or []) for p in _plans_composes())
    _ecrire("alternatives_demande.json", {
        "enseigne": principale, "manquants": liste,
        "interdits": _lire("derniere_liste.json", {}).get("composition_interdite") or cli.interdits(),
        "eviter": list(base.FODMAP_COMPOSITION) if fodmap else [],
        "connus": sorted((nutriments().get("macros") or {})),
        "deja": {n: a["offre"] for n, a in _lire("dans_les_paniers.json", {}).items() if a.get("enseigne") == principale}})
    return len(liste)


def _jarvis(commande: list, profil: str, dire) -> int:
    """Lance une commande de Jarvis pour ce profil et raconte sa sortie ligne a ligne."""
    dire("")
    dire("$ jarvis " + " ".join(commande))
    p = subprocess.Popen([sys.executable, "-u", "jarvis14.py", *commande], cwd=str(_RACINE),
                         stdout=subprocess.PIPE, env={**os.environ, "JARVIS_REPAS_PROFIL": profil},
                         stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace")
    for ligne in p.stdout:
        dire(ligne.rstrip("\n"))
    return p.wait()


def _dire(ligne: str) -> None:
    with _VERROU:
        _TACHE["lignes"].append(ligne)
        del _TACHE["lignes"][:-400]


def _chercher_alternatives(profil: str) -> None:
    """Jarvis cherche chez l'enseigne de quoi remplacer les produits manquants, et le raconte."""
    with _VERROU:
        n = _demander_alternatives()
    if not n:
        return
    code = _jarvis(["--repas-alternatives"], profil, _dire)
    with _VERROU:
        recettes = donnees_site()
        _, tri = _liste_du_mois(recettes) or _a_acheter(_lire_p("semaine.json", None), recettes)
        liste = manquants(tri, recettes)
        avec = [m for m in liste if m["alternatives"]]
        journal("panier", f"Produits manquants : {len(avec)} sur {len(liste)} ont une alternative" if not code
                else "Produits manquants : la recherche d'alternatives a échoué",
                [f"{m['nom']} : " + (" ; ".join(f"{a['nom']} ({a['produit']}, {a['cout']:.2f} €)" for a in m["alternatives"])
                                     or "rien de proche trouvé") + "." for m in liste]
                + ["Choisis dans Courses : le produit va au panier et tes recettes changent toutes seules."])


def _tache_alternatives(profil: str = "") -> None:
    mod_profil.choisir(profil)
    try:
        _chercher_alternatives(profil)
    except Exception as e:
        _dire(f"ERREUR : {e}")
    finally:
        with _VERROU:
            _TACHE.update(etat="fini", fin=time.strftime("%Y-%m-%dT%H:%M:%S"))


def lancer_alternatives() -> bool:
    with _VERROU:
        if _TACHE["etat"] == "en cours" or not _lire("dans_les_paniers.json", None):
            return False
        nom = _profil().nom
        _TACHE.update(etat="en cours", titre="Jarvis cherche des alternatives", lignes=[], profil=nom,
                      debut=time.strftime("%Y-%m-%dT%H:%M:%S"), fin=None)
    threading.Thread(target=_tache_alternatives, args=(nom,), daemon=True).start()
    return True


def _renommer_ajustes(plan: dict, ancien: str, nouveau: str, rapport: float) -> None:
    """Les quantites ajustees pour un jour suivent l'ingredient remplace."""
    for jour in plan.get("jours", []):
        for quantites in (jour.get("ajustes") or {}).values():
            if ancien in quantites:
                q = quantites.pop(ancien)
                quantites[nouveau] = {**q, "q": round(q["q"] * rapport, 2)} if isinstance(q, dict) else round(q * rapport, 2)


def appliquer_alternatives(choix: dict) -> list:
    """Tu choisis, pour des produits manquants, le produit de remplacement trouve chez
    l'enseigne ({produit manquant: ingredient de remplacement}). Les recettes du profil
    changent tout de suite, donc les repas de toutes les semaines composees et les listes ;
    Jarvis ajoute ensuite ces produits au panier, sans payer. Le menu reste valide."""
    with _VERROU:
        if _TACHE["etat"] == "en cours":
            raise ValueError("Jarvis travaille déjà : attends qu'il ait fini.")
        trouvees = _lire("alternatives.json", {}).get("articles", {})
        echanges = _lire_p("remplacements.json", {})
        echanges = echanges if isinstance(echanges, dict) else {}
        remplacants = {e["nom"] for e in echanges.values()}
        produits, faits = [], []
        for nom, voulu in (choix or {}).items():
            a = next((x for x in trouvees.get(str(nom), {}).get("alternatives", []) if x["nom"] == voulu), None)
            if not a:
                raise ValueError(f"alternative inconnue pour {nom}")
            if a["nom"] in echanges or nom in remplacants:
                raise ValueError(f"{a['nom']} est déjà un produit remplacé : annule d'abord ce remplacement")
            cout_unitaire = a["cout"] / a["quantite"] if a["quantite"] else 0      # prix du remplacant, pour le cout des plats
            echanges[str(nom)] = {"nom": a["nom"], "rapport": a["rapport"], "le": time.strftime("%Y-%m-%dT%H:%M:%S"),
                                  "prix": round(cout_unitaire * (1000 if a["unite"] in ("g", "ml") else 1), 2)}
            produits.append({"nom": a["nom"], "remplace": str(nom), "offre": a["offre"], "paquets": a["paquets"]})
            faits.append((str(nom), a))
        if not produits:
            raise ValueError("aucun produit choisi")
        _ecrire_p("remplacements.json", echanges)

        def suivre(plan):
            for nom, a in faits:
                _renommer_ajustes(plan, nom, a["nom"], a["rapport"])
        _recalculer_semaines(suivre)
        _ecrire("alternatives_choisies.json", {"enseigne": _enseignes()[0], "produits": produits})
        nb = len(_plans_composes())
        journal("remplacement", f"{len(faits)} produit{'s' if len(faits) > 1 else ''} manquant{'s' if len(faits) > 1 else ''} "
                f"remplacé{'s' if len(faits) > 1 else ''}",
                [f"{nom} → {a['nom']} : {a['paquets']} × {a['offre']['nom']} ({a['cout']:.2f} €)." for nom, a in faits]
                + [f"Les recettes de {'tes ' + str(nb) + ' semaines' if nb > 1 else 'ta semaine'} utilisent maintenant ces produits. "
                   "Jarvis les ajoute au panier, sans payer."])
        nom_profil = _profil().nom
        _TACHE.update(etat="en cours", titre="Jarvis complète le panier", lignes=[], profil=nom_profil,
                      debut=time.strftime("%Y-%m-%dT%H:%M:%S"), fin=None)
    threading.Thread(target=_tache_ajout, args=(nom_profil,), daemon=True).start()
    return [a["nom"] for _, a in faits]


def _tache_ajout(profil: str = "") -> None:
    """Fil a part : Jarvis ajoute au panier les produits de remplacement choisis."""
    mod_profil.choisir(profil)
    try:
        code = _jarvis(["--repas-panier-ajout"], profil, _dire)
        with _VERROU:
            mois = _mois() if rythme() == "mois" else None
            if mois:
                mois["panier"] = _total_panier()
                _ecrire_p("mois.json", mois)
            journal("panier", "Panier complété avec tes produits de remplacement" if not code
                    else "Panier : des produits de remplacement n'ont pas pu être ajoutés",
                    [l for l in _TACHE["lignes"] if l.startswith("  ")][:20]
                    + ["Rien n'est payé : vérifie le panier sur le site de l'enseigne."])
    except Exception as e:
        _dire(f"ERREUR : {e}")
        journal("panier", "Panier : échec de l'ajout des produits de remplacement", [str(e)])
    finally:
        with _VERROU:
            _TACHE.update(etat="fini", fin=time.strftime("%Y-%m-%dT%H:%M:%S"))


def annuler_remplacement(nom: str) -> None:
    """Le produit d'origine revient dans les recettes (et dans la liste a acheter). Le
    produit de remplacement deja mis au panier y reste : a retirer sur le site de l'enseigne."""
    with _VERROU:
        echanges = _lire_p("remplacements.json", {})
        e = echanges.pop(nom, None) if isinstance(echanges, dict) else None
        if not e:
            raise ValueError("remplacement inconnu")
        _ecrire_p("remplacements.json", echanges)
        _recalculer_semaines(lambda plan: _renommer_ajustes(plan, e["nom"], nom, 1 / float(e.get("rapport") or 1)))
        journal("remplacement", f"Remplacement annulé : {nom} revient dans tes recettes",
                [f"{e['nom']} n'est plus utilisé à sa place. S'il est déjà dans ton panier, retire-le sur le site de l'enseigne."])


def fruits_secs(recettes: dict) -> dict | None:
    """Fruits secs et oleagineux, a acheter dans un magasin proche (jamais en ligne) :
    le melange du MOIS (grammes par jour x 30 jours, moins le stock), et les noix,
    amandes ou cacahuetes que demandent les recettes des semaines composees."""
    plan = _lire_p("semaine.json", None)
    if rythme() != "mois" or not plan:
        return None
    mois = _mois()
    plans = [plan] + (mois["semaines"][mois["rang"] + 1:] if mois else [])
    _, tri = _besoins_tries(plans, recettes, "fruits_secs", restants=True)
    prevu = next((j["fruits_secs"] for j in plan.get("jours", []) if j.get("fruits_secs")), None)
    melange = None
    if prevu:
        recette = next(x for x in recettes["recettes"] if x["id"] == prevu["id"])
        melange = recette["ing"][0]["n"]
    autres = [{"nom": l["nom"], "acheter": l["acheter"], "unite": l["unite"]}
              for l in tri["a_acheter"] if l["nom"] != melange]
    resultat = {"autres": autres, "nom": melange, "acheter": 0, "besoin": 0, "stock": 0, "par_jour": 0,
                "jours_en_stock": 0, "cout": 0.0, "conseil": ""}
    if prevu:
        besoin = pdf.Ingredient(melange, prevu["g"] * 30, "g")
        stock = mod_stock.disponible(mod_stock.charger(), besoin)
        resultat.update({
            "conseil": recette["etapes"][0], "par_jour": prevu["g"], "besoin": besoin.quantite,
            "stock": round(min(stock, besoin.quantite)),
            "acheter": max(0, int(math.ceil((besoin.quantite - stock) / 50.0) * 50)),
            "jours_en_stock": int(stock // prevu["g"]),
            "cout": round(recettes["prix"].get(melange, 0) * max(0.0, besoin.quantite - stock) / 1000, 2)})
    return resultat if (prevu or autres) else None


def fruits_secs_achetes(grammes=None) -> None:
    """Tu declares les fruits secs ACHETES : ils entrent au stock."""
    with _VERROU:
        f = fruits_secs(donnees_site())
        if not f:
            raise ValueError("pas de fruits secs prevus")
        stock = mod_stock.charger()
        entres = []
        q = float(grammes) if grammes not in (None, "") else f["acheter"]
        if f["nom"] and q > 0:
            if q > 5000:
                raise ValueError("quantité entre 1 et 5 000 g")
            mod_stock.ajouter(stock, f["nom"], q, "g")
            entres.append(f"{mod_stock.fmt(q)} g de fruits secs")
        for l in f["autres"]:
            if l["unite"] != "qs" and l["acheter"]:
                mod_stock.ajouter(stock, l["nom"], l["acheter"], l["unite"])
                entres.append(f"{l['nom']} {mod_stock.fmt(l['acheter'])} {l['unite']}")
        mod_stock.enregistrer(stock, motif="commande", detail="fruits secs du mois")
        journal("commande", "Fruits secs achetés : le stock est à jour",
                ["Entré en stock : " + (", ".join(entres) or "rien") + "."])


def _demain():
    import datetime
    return datetime.date.today() + datetime.timedelta(days=1)


def _dater(plan: dict, debut) -> dict:
    """Une semaine commence le jour `debut` (le lendemain du jour ou elle est composee),
    pas forcement un lundi : chaque jour prend le nom de sa date."""
    import datetime
    plan["debut"] = debut.isoformat()
    for k, jour in enumerate(plan["jours"]):
        jour["jour"] = P.JOURS[(debut + datetime.timedelta(days=k)).weekday()]
    return plan


def _debut(plan: dict | None):
    """Premier jour d'une semaine. Les semaines d'avant le 11 octobre 2026 n'ont pas de
    date : elles allaient du lundi au dimanche de la semaine ou elles ont ete composees."""
    import datetime
    if plan and plan.get("debut"):
        return datetime.date.fromisoformat(plan["debut"])
    if plan and plan.get("cree_le"):
        jour = datetime.date.fromisoformat(plan["cree_le"][:10])
        return jour - datetime.timedelta(days=jour.weekday())
    return None


def _composer(exclus=(), modes=None, ancienne=None, deja=(), debut=None) -> tuple:
    """(plan, phase) d'une semaine, sans rien ecrire. `deja` = menus des semaines
    deja composees pour ce mois, a ne pas repeter."""
    recettes, reglages = donnees_site(), _reglages()
    phase = _phase(reglages)
    preferences = _profil().preferences
    if modes is None:
        modes = ancienne.get("modes", preferences["modes"]) if ancienne else preferences["modes"]
    modes = [m for m in modes if m in P.MODES_DEFAUT]
    if SEUL_FLEMMARD:                                   # le flemmard pour tous, le FODMAP pour qui en a besoin
        modes = ["flemmard"] + [m for m in modes if m == "fodmap"]
    kcal = phase["kcal"] + int(reglages.get("ajustement") or 0)
    ctx = {**_contexte(recettes), "phase": phase,
           "besoins_vitamines": _profil().besoins_vitamines(kcal)}
    # Fruits secs : le choix fait sur le site (case du dialogue de composition), sinon la preference du profil (R-04).
    fruits_secs = reglages.get("fruits_secs")
    if fruits_secs is None:
        fruits_secs = preferences["fruits_secs"]
    if ancienne and ancienne.get("etat") != "proposee":
        ctx["semaines_passees"] = _semaines_passees()
    ctx["semaines_passees"] = [sorted(d) for d in reversed(list(deja))] + ctx["semaines_passees"]
    plan = P.composer(recettes["recettes"], ctx, {
        **reglages, "kcal": kcal, "prot": phase["prot"], "modes": modes,
        **({} if fruits_secs else {"fruits_secs_g": 0}),
        "petit_dej_fixe": _fixes()["petit_dej"],
        "collations_fixes": _fixes()["collations"],
        "exclus": sorted(set(exclus) | set(_profil().valeur("alimentation.plats_exclus", []) or []))})
    import datetime
    plan.update(etat="proposee",          # la date sert aussi d'identifiant de la semaine
                cree_le=datetime.datetime.now().isoformat(timespec="milliseconds"),
                prepares={}, exclus=list(exclus))
    _dater(plan, debut or _demain())
    return plan, phase


def _raisons(plan: dict, phase: dict) -> list:
    noms = {r["id"]: r["nom"] for r in donnees_site()["recettes"]}
    details = [f"Objectif {plan['objectif']['kcal']} kcal et {plan['objectif']['prot']} g de "
               f"protéines par jour (phase {phase['n']} · {phase['nom']}).",
               f"Coût estimé {plan['cout']:.2f} € pour un budget de "
               f"{plan['budget_semaine']:.2f} € par semaine.",
               "Cuisine jour par jour : le plat du soir est fait en double, la seconde "
               "part est le déjeuner du lendemain."]
    if plan["modes"]:
        details.append("Demandé : " + ", ".join(P.NOMS_MODES[m] for m in plan["modes"]) + ".")
    faibles = [v for v, x in plan["vitamines"].items() if x["pct"] < 80]
    if plan["vitamines"]:
        details.append("Vitamines : besoins couverts en moyenne"
                       + (", sauf " + ", ".join(f"{v} ({plan['vitamines'][v]['pct']} %)" for v in faibles)
                          if faibles else "") + ".")
    for ident, c in plan["choix"].items():
        details.append(f"{noms[ident]} : " + " ; ".join(r["texte"] for r in c["raisons"]) + ".")
    for r in plan["remplacements"]:
        details.append(f"Budget : « {noms[r['sorti']]} » remplacé par « {noms[r['entre']]} ».")
    return details


def generer(exclus=(), modes=None) -> dict:
    """Compose une nouvelle semaine et explique chaque choix dans le journal.
    modes : moins_cher, plus_varie, fodmap. Sans indication, on reprend ceux de la
    semaine precedente, sinon les preferences du profil. Au rythme du mois, elle
    remplace la semaine en cours du mois."""
    with _VERROU:
        ancienne = _lire_p("semaine.json", None)
        # une semaine seulement proposee est remplacee ; une semaine engagee
        # (panier, commande, cuisine) reste dans l'historique.
        remplacee = ancienne["cree_le"] if ancienne and ancienne.get("etat") == "proposee" else ""
        mois = _mois() if rythme() == "mois" else None
        deja = [p["choix"] for k, p in enumerate(mois["semaines"]) if k != mois["rang"]] if mois else ()
        import datetime
        # La semaine recomposee repart de demain ; au rythme du mois, une semaine qui n'est
        # pas la premiere garde sa place, et les suivantes s'enchainent derriere elle.
        debut = _debut(ancienne) if mois and mois["rang"] > 0 and ancienne and ancienne.get("debut") else _demain()
        plan, phase = _composer(exclus, modes, ancienne, deja, debut)
        _enregistrer_semaine(plan, retirer=remplacee)
        if mois:
            for k in range(mois["rang"] + 1, len(mois["semaines"])):
                if mois["semaines"][k].get("etat") == "proposee":
                    _dater(mois["semaines"][k], debut + datetime.timedelta(days=7 * (k - mois["rang"])))
            mois["semaines"][mois["rang"]] = plan
            mois["valide"] = None                   # menu change : a revalider avant tout panier
            _ecrire_p("mois.json", mois)
        journal("selection", "Semaine choisie : voici pourquoi", _raisons(plan, phase))
        return plan


def generer_mois(modes=None, garder: bool = True, ajouter: bool = False) -> dict:
    """Compose d'un coup les semaines d'une commande (courses.semaines_par_commande),
    pour remplir un seul panier de supermarche. Une semaine deja engagee
    (panier, commande, cuisine) est gardee telle quelle comme premiere semaine."""
    with _VERROU:
        ancienne = _lire_p("semaine.json", None)
        # `ajouter` : la semaine deja composee reste la premiere, meme seulement proposee ;
        # on compose seulement celles qui suivent.
        engagee = ancienne if garder and ancienne and (ajouter or ancienne.get("etat") != "proposee") \
            and all("cuisine" in j for j in ancienne.get("jours", [])) else None
        if modes is None and ancienne:
            modes = ancienne.get("modes")
        import datetime
        plans = [engagee] if engagee else []
        if ajouter and engagee:                                  # les semaines deja composees derriere elle restent aussi
            existant = _mois()
            if existant and existant["semaines"][existant["rang"]].get("cree_le") == engagee.get("cree_le"):
                plans += existant["semaines"][existant["rang"] + 1:]
            plans = plans[:nb_semaines()]
        phase = None
        premier = _debut(engagee) if engagee else _demain()      # les semaines s'enchainent, 7 jours chacune
        while len(plans) < nb_semaines():
            plan, phase = _composer((), modes, ancienne if not plans else plans[-1],
                                    [p["choix"] for p in plans],
                                    premier + datetime.timedelta(days=7 * len(plans)))
            plan["etat"] = "proposee"
            plans.append(plan)
        if not engagee:
            # De nouvelles semaines, donc un nouveau panier : les produits remplaces faute de
            # les trouver reviennent, le magasin les aura peut-etre cette fois.
            if _lire_p("remplacements.json", {}):
                _ecrire_p("remplacements.json", {})
            remplacee = ancienne["cree_le"] if ancienne and ancienne.get("etat") == "proposee" else ""
            _enregistrer_semaine(plans[0], retirer=remplacee)
        mois = {"cree_le": datetime.datetime.now().isoformat(timespec="seconds"), "rang": 0,
                "semaines": plans, "commande": None, "panier": None}
        _ecrire_p("mois.json", mois)
        noms = {r["id"]: r["nom"] for r in donnees_site()["recettes"]}
        recettes = donnees_site()
        _, tri = _liste_du_mois(recettes)
        f = fruits_secs(recettes)
        details = [f"{len(plans)} semaines composées d'un coup, sans répéter les mêmes plats d'une "
                   "semaine à l'autre.",
                   f"Panier du supermarché pour ces {len(plans)} semaines : {len(tri['a_acheter'])} produits "
                   "(épicerie, frais, surgelés, et les légumes qui se gardent : oignons, ail, pommes de "
                   "terre, carottes).",
                   "Chaque semaine au marché : viande, poisson, fruits et légumes frais."]
        if f:
            details.append(f"Fruits secs, une fois par mois près de chez toi : {f['besoin']:.0f} g pour "
                           f"30 jours à {f['par_jour']} g par jour.")
        for k, p in enumerate(plans, 1):
            plats = [noms[i] for i in p["choix"] if next(
                x for x in recettes["recettes"] if x["id"] == i)["cat"] == "plat"]
            details.append(f"Semaine {k}" + (" (déjà en cours)" if engagee and k == 1 else "")
                           + f", {p['cout']:.2f} € : " + ", ".join(plats) + ".")
        journal("selection", f"{len(plans)} semaines composées : voici le plan", details)
        return mois


def semaine_suivante() -> dict:
    """Au rythme du mois : passe a la semaine suivante du mois (ou compose un nouveau mois)."""
    with _VERROU:
        mois = _mois()
        if rythme() != "mois" or not mois or mois["rang"] + 1 >= len(mois["semaines"]):
            return generer_mois(garder=False)       # la periode est finie : de nouvelles semaines
        courante = _lire_p("semaine.json", None)
        if courante:
            mois["semaines"][mois["rang"]] = courante
        mois["rang"] += 1
        plan = mois["semaines"][mois["rang"]]
        _ecrire_p("mois.json", mois)
        _enregistrer_semaine(plan)
        journal("selection", f"Semaine {mois['rang'] + 1} sur {len(mois['semaines'])}",
                ["Elle était déjà composée ; la liste du marché de la semaine est à jour."])
        return mois


def _achete() -> bool:
    """Les courses sont-elles deja payees ? (le panier du supermarche, ou la semaine)"""
    plan = _lire_p("semaine.json", None) or {}
    mois = _mois() if rythme() == "mois" else None
    return bool((mois and mois.get("commande")) or plan.get("etat") in ("commandee", "terminee"))


def _manques(recettes: dict) -> dict:
    """{(produit, unite): quantite} de tout ce qu'il reste a acheter, toutes listes confondues."""
    plan = _lire_p("semaine.json", None)
    listes = [_a_acheter(plan, recettes)[1]] if plan else []
    du_mois = _liste_du_mois(recettes)
    if du_mois:
        listes.append(du_mois[1])
    manques = {(l["nom"], l["unite"]): l["acheter"] for tri in listes for l in tri["a_acheter"]}
    if plan:                                        # la viande n'est pas au stock : son besoin compte
        manques.update({(l["nom"], l["unite"]): l["quantite"] for l in listes[0]["boucher"]})
    return manques


def _double_du_jour(r: dict, jour: dict, par_id: dict) -> dict:
    """Le même plat une 2e fois le même jour (une 2e banane alors que la 1re est mangée) : une copie « Banane (2) »,
    qui a sa propre place et son propre « cuisiné », et la photo de l'original (photo_de)."""
    base = re.sub(r" \(\d+\)$", "", r["nom"])
    racine = "perso-" + re.sub(r"[^a-z0-9]+", "-", pdf.normaliser(base)).strip("-")[:36]
    deja = {i for _, i in P.moments(jour)}
    for k in range(2, 30):
        ident = f"{racine}-{k}"
        if ident in deja:
            continue
        if ident in par_id:
            return {**par_id[ident], "_existe": True}
        return {**{c: v for c, v in r.items() if c not in ("note", "nb_notes", "gout", "ajustee")},
                "id": ident, "nom": f"{base} ({k})", "perso": True, "photo_de": r.get("photo_de") or r["id"]}
    raise ValueError("ce plat est déjà prévu trop de fois ce jour-là")


def eau_bue(date: str | None = None) -> float:
    d = _lire_p("eau.json", {})
    return float(((d.get("jours") if isinstance(d, dict) else None) or {}).get(date or time.strftime("%Y-%m-%d"), 0))


def boire(date: str, ml=None, litres=None) -> float:
    """L'eau bue ce jour-là : `litres` = le total (la barre qu'on fait glisser, Taha, 19/11/2026), ou `ml` ajoutés
    (négatif : retirés). Renvoie le total du jour en litres."""
    if litres is not None:
        try:
            total = float(litres)
        except (TypeError, ValueError):
            raise ValueError("quantité d'eau impossible")
        if not 0 <= total <= 10:
            raise ValueError("quantité d'eau impossible")
        ml = (total - eau_bue(date)) * 1000
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(date or "")) or str(date) > time.strftime("%Y-%m-%d"):
        raise ValueError("ce jour n'est pas encore là")
    try:
        ml = float(ml)
    except (TypeError, ValueError):
        raise ValueError("quantité d'eau impossible")
    if litres is None and not -2000 <= ml <= 2000:          # la barre donne le total : pas de limite par geste
        raise ValueError("quantité d'eau impossible")
    with _VERROU:
        d = _lire_p("eau.json", {})
        jours = (d.get("jours") if isinstance(d, dict) else None) or {}
        jours[date] = round(max(0.0, min(10.0, float(jours.get(date, 0)) + ml / 1000)), 2)
        _ecrire_p("eau.json", {"jours": dict(sorted(jours.items())[-400:])})
    return jours[date]


def modifier_semaine(operation: dict, semaine: int | None = None, apercu: bool = False,
                     confirme: bool = False, supplements=()) -> dict:
    """Change un plat, copie un jour ou ajoute un complement, a la main.

    Renvoie ce que le changement entraine : ecart de calories et de proteines du
    jour, produits a racheter, complements proposes. `apercu` = ne rien ecrire.
    Une fois les courses payees, le changement n'est applique que si l'utilisateur
    confirme qu'il a vu les ecarts et qu'il achetera lui-meme ce qui manque."""
    with _VERROU:
        recettes = donnees_site()
        par_id = {x["id"]: x for x in recettes["recettes"]}
        mois = _mois() if rythme() == "mois" else None
        rang = mois["rang"] if mois else 0
        k = rang if semaine is None else int(semaine)
        courante = k == rang
        if courante:
            plan = _lire_p("semaine.json", None)
        elif mois and rang < k < len(mois["semaines"]):
            plan = mois["semaines"][k]
        else:
            plan = None
        if not plan:
            raise ValueError("semaine inconnue")
        j = int(operation.get("jour", -1))
        if not 0 <= j < 7:
            raise ValueError("jour inconnu")
        double = None
        jour_ = plan["jours"][j]
        vide = operation.get("type") == "changer" and (str(operation.get("moment", "")).startswith("col")
                                                       or jour_.get(str(operation.get("moment")), P.RIEN) == P.RIEN)
        if (operation.get("type") == "ajouter" or vide) and operation.get("plat") in {i for _, i in P.moments(jour_)} \
                and par_id.get(operation["plat"]):
            double = _double_du_jour(par_id[operation["plat"]], plan["jours"][j], par_id)
            operation = {**operation, "plat": double["id"]}
            recettes = {**recettes, "recettes": [x for x in recettes["recettes"] if x["id"] != double["id"]] + [double]}
            par_id = {**par_id, double["id"]: double}
        if operation.get("type") == "ajuster":
            cible = par_id.get(operation.get("plat"))
            if not cible:
                raise ValueError("recette inconnue")
            propres = _quantites_choisies(cible, operation.get("quantites") or {})
            if propres and not any(i["q"] > 0 for i in P.avec_quantites(cible, propres)["ing"] if i["u"] != "qs"):
                raise ValueError("il faut garder au moins un ingrédient")
            operation = {**operation, "quantites": propres}
        if operation.get("type") == "reequilibrer":
            if operation.get("plat") not in par_id:
                raise ValueError("recette inconnue")
        for cle in ("plat",):
            if cle in operation and operation.get("type") not in ("ajuster", "reequilibrer"):
                cible = par_id.get(operation[cle])
                # N'importe quel plat a n'importe quel repas, un pancake a midi : « je mange ce que je
                # veux tant que ça respecte les macros » (Taha, 19/11/2026).
                if not cible or cible["cat"] not in ("collation", "plat", "petitdej", "fruit"):
                    raise ValueError("ce plat ne convient pas à ce repas")
        if operation.get("type") == "ajouter" and operation.get("moment") not in (None, "", "col", "pdj", "dej", "din"):
            raise ValueError("repas inconnu")
        avant_fichiers = (json.dumps(plan), json.dumps(mois) if mois else None)
        avant_manques = _manques(recettes)
        avant = {n: (x["kcal"], x["prot"]) for n, x in enumerate(plan["jours"])}
        reglages = _reglages()
        phase = _phase(reglages)
        ctx = {**_contexte(recettes), "phase": phase, "besoins_vitamines": _profil().besoins_vitamines(
            phase["kcal"] + int(reglages.get("ajustement") or 0))}
        fixes_avant = list(plan["jours"][j].get("perso") or [])
        if operation.get("type") == "ajuster":       # la taille de l'assiette sur laquelle les quantites sont tapees
            operation = {**operation, "taille": P.taille(plan["jours"][j], operation.get("plat"), par_id)}
        if operation.get("type") not in ("objectif", "reequilibrer"):      # seulement les quantites, plus bas
            P.modifier(plan, operation)
        menu = {i for _, i in P.moments(plan["jours"][j])}
        if any(i not in menu for i in fixes_avant) and not _achete():
            plan["jours"][j]["perso"] = [i for i in fixes_avant if i in menu]
            P.recaler(plan["jours"][j], par_id, plan["objectif"]["kcal"], _profil().ponderation()["composition"])
        for ident in supplements or ():
            if ident in par_id and par_id[ident]["cat"] == "collation":
                P.modifier(plan, {"type": "ajouter", "jour": j, "plat": ident})
        P.recalculer(plan, recettes["recettes"], ctx)
        # Viser l'objectif du jour, toujours a la demande (Taha, 19/11/2026 : jamais tout seul) :
        # « Compléter l'objectif » règle les plats du jour ; « Rééquilibrer » sur un plat ne règle que
        # lui ; un plat proposé par Jarvis (regler_plat) se règle lui seul une fois mis.
        reglages_objectif, remplacer, atteint = [], None, True

        def recompter():
            P.recalculer(plan, recettes["recettes"], ctx)
            return plan["jours"][j]["kcal"], plan["jours"][j]["prot"]
        if operation.get("type") == "objectif":
            reglages_objectif = P.viser_objectif(plan, j, par_id, ctx["nutriments"], plan["objectif"], recompter)
        elif operation.get("type") == "reequilibrer" or (operation.get("regler_plat") and operation["type"] in ("changer", "ajouter")):
            if operation["type"] == "reequilibrer" and not P.reglable_seul(plan, j, operation["plat"], par_id, ctx["nutriments"]):
                raise ValueError("ce plat ne se règle pas ce jour-là (déjà cuisiné, ou c'est la part gardée d'hier soir)")
            reglages_objectif = P.viser_objectif(plan, j, par_id, ctx["nutriments"], plan["objectif"], recompter,
                                                 seulement=operation["plat"])
            if operation["type"] == "reequilibrer":
                atteint = _dans_l_objectif(plan["jours"][j], plan["objectif"])
                if not atteint or _preferes(operation):
                    remplacer = _pour_remplacer(plan, j, operation, par_id, recettes["recettes"], ctx)

        def ecrire(p, m):
            if courante:
                _ecrire_p("semaine.json", p)
            if m:
                m["semaines"][k] = p
                _ecrire_p("mois.json", m)
        ecrire(plan, mois)                           # ecrit pour mesurer, annule si apercu
        if double and not apercu and not double.get("_existe"):
            _ecrire_p("plats_perso.json", [x for x in plats_perso() if x["id"] != double["id"]]
                      + [{k: v for k, v in double.items() if not k.startswith("_")}])
        apres_manques = _manques(recettes)
        manque = [{"nom": n, "unite": u, "quantite": round(q - avant_manques.get((n, u), 0), 2)}
                  for (n, u), q in apres_manques.items() if q - avant_manques.get((n, u), 0) > 0.001
                  or (u == "qs" and (n, u) not in avant_manques)]
        touches = [n for n, x in enumerate(plan["jours"]) if (x["kcal"], x["prot"]) != avant[n]]
        ecarts = [{"jour": plan["jours"][n]["jour"], "kcal": plan["jours"][n]["kcal"] - avant[n][0],
                   "prot": plan["jours"][n]["prot"] - avant[n][1],
                   "kcal_total": plan["jours"][n]["kcal"], "prot_total": plan["jours"][n]["prot"]}
                  for n in touches]
        objectif = plan["objectif"]["prot"]
        deficit = objectif - plan["jours"][j]["prot"]
        perdu = -min([e["prot"] for e in ecarts if e["jour"] == plan["jours"][j]["jour"]] or [0])
        propositions = []
        if max(deficit, perdu) > 8 and operation["type"] not in ("retirer", "retirer_jour", "reequilibrer"):   # un repas retire est un choix
            stock = mod_stock.charger()
            for ident in P.SUPPLEMENTS:
                x = par_id.get(ident)
                if not x or ident in plan["jours"][j]["collations"] or ("fodmap" in plan.get("modes", [])
                                                                        and not x.get("fodmap")):
                    continue
                en_stock = all(mod_stock.disponible(stock, pdf.Ingredient(i["n"], i["q"], i["u"])) >= i["q"] - 0.01
                               for i in x["ing"] if i["u"] != "qs")
                propositions.append({"id": ident, "nom": x["nom"], "prot": x["prot"], "kcal": x["kcal"],
                                     "en_stock": en_stock})
            propositions.sort(key=lambda c: (not c["en_stock"], -c["prot"]))
        achete = _achete()
        combler = _pour_combler(plan, j, par_id, recettes["recettes"]) if operation["type"] == "objectif" else None
        resultat = {"semaine": k, "jour": plan["jours"][j]["jour"], "ecarts": ecarts, "manque": manque, "combler": combler,
                    "atteint": atteint, "remplacer": remplacer,
                    "jour_kcal": plan["jours"][j]["kcal"], "jour_prot": plan["jours"][j]["prot"],
                    "achete": achete, "objectif": plan["objectif"], "deficit_proteines": max(0, deficit, perdu),
                    "supplements": propositions[:4],
                    "panier_a_refaire": bool(not achete and _total_panier()),
                    "confirmation_requise": achete,
                    "reglages": [{**c, "nom": par_id[c["plat"]]["nom"]} for c in reglages_objectif],
                    "reglables": len(P.reglables(plan, j, par_id))}
        if apercu or (achete and not confirme):
            ancien_plan, ancien_mois = json.loads(avant_fichiers[0]), (
                json.loads(avant_fichiers[1]) if avant_fichiers[1] else None)
            ecrire(ancien_plan, ancien_mois)         # on remet tout comme avant
            if not apercu:
                raise PermissionError("confirmation")
            return resultat
        a_revalider = _devalider() if not achete else False     # le panier ne correspond plus au menu
        if courante:
            _inscrire(plan)
        noms = {x["id"]: x["nom"] for x in recettes["recettes"]}
        titre = {"changer": f"Plat changé à ta demande : « {noms.get(operation.get('plat'), '')} »",
                 "cloner": f"{plan['jours'][int(operation.get('depuis', 0))]['jour']} copié sur {plan['jours'][j]['jour'].lower()}",
                 "ajouter": f"Complément ajouté : « {noms.get(operation.get('plat'), '')} »",
                 "ajuster": f"Quantités ajustées pour {plan['jours'][j]['jour'].lower()} seulement : « {noms.get(operation.get('plat'), '')} »",
                 "retirer": f"Repas retiré à ta demande, {plan['jours'][j]['jour'].lower()}",
                 "retirer_jour": f"{plan['jours'][j]['jour']} retiré à ta demande",
                 "objectif": f"Objectif complété pour {plan['jours'][j]['jour'].lower()} : quantités réglées par Jarvis",
                 "reequilibrer": f"Plat rééquilibré pour {plan['jours'][j]['jour'].lower()} : « {noms.get(operation.get('plat'), '')} »"}[operation["type"]]
        details = [f"Semaine {k + 1}, {plan['jours'][j]['jour']}."]
        details += [f"{e['jour']} : {e['kcal']:+d} kcal et {e['prot']:+d} g de protéines "
                    f"(soit {e['kcal_total']} kcal et {e['prot_total']} g)." for e in ecarts]
        if manque:
            details.append(("À acheter toi-même, près de chez toi : " if achete else "Ajouté aux courses : ")
                           + ", ".join(f"{m['nom']} {mod_stock.fmt(m['quantite'])} {m['unite']}".replace(" 0 qs", "")
                                       for m in manque) + ".")
        for c in reglages_objectif:
            t = c["taille"]
            details.append(("Réglé par Jarvis, " if operation["type"] in ("changer", "ajouter") else "") + f"« {noms.get(c['plat'], '')} » : "
                           + ", ".join(f"{l['n']} {mod_stock.fmt(round(l['avant'] * t, 1))} → {mod_stock.fmt(round(l['apres'] * t, 1))} {l['u']}"
                                       for l in c["lignes"]) + ".")
        if supplements:
            details.append("Compléments ajoutés : " + ", ".join(noms.get(i, i) for i in supplements) + ".")
        if a_revalider:
            details.append("Le menu était validé : valide-le de nouveau quand tu as fini, pour que Jarvis refasse le panier.")
        if resultat["panier_a_refaire"]:
            details.append("Le panier déjà rempli ne correspond plus tout à fait : vide-le et refais-le avant de payer.")
        journal("remplacement", titre, details)
        return resultat


def _dans_l_objectif(jour: dict, objectif: dict) -> bool:
    """La journée tombe-t-elle sur l'objectif ? A 3 % près pour les calories, 5 % pour les protéines."""
    return (abs(jour["kcal"] - objectif["kcal"]) <= 0.03 * objectif["kcal"]
            and abs(jour["prot"] - objectif["prot"]) <= 0.05 * objectif["prot"])


def _ecart_objectif(kcal: float, prot: float, objectif: dict) -> float:
    return ((kcal - objectif["kcal"]) / objectif["kcal"]) ** 2 + ((prot - objectif["prot"]) / objectif["prot"]) ** 2


def _preferes(operation: dict) -> list:
    """Les ingrédients que l'utilisateur préfère avoir dans le plat de remplacement (« pâtes, oignon ») :
    [(texte tapé, mots à retrouver)], 5 au plus. « steak », « pates »… passent par les alias des plats perso."""
    brut = operation.get("preferes") or []
    if isinstance(brut, str):
        brut = re.split(r"[,;+]| et ", brut)
    termes = []
    for texte in [str(x).strip() for x in brut if str(x).strip()][:5]:
        n = pdf.normaliser(texte).strip()
        mots = set(mod_etiquettes._mots(mod_perso.ALIAS.get(n) or n))
        if mots:
            termes.append((texte[:40], mots))
    return termes


def _avec_preferes(r: dict, termes: list) -> list:
    """Les ingrédients préférés que contient ce plat (dans son nom ou ses ingrédients)."""
    dans = set(mod_etiquettes._mots(r.get("nom", "")))
    for i in r.get("ing", []):
        dans |= set(mod_etiquettes._mots(i["n"]))
    return [texte for texte, mots in termes if mots <= dans]


def _pour_remplacer(plan: dict, j: int, operation: dict, par_id: dict, recettes: list, ctx: dict) -> dict | None:
    """Quand régler les grammes d'un plat ne suffit pas à tenir l'objectif du jour (30 g de protéines de plus
    sur un plat de 150 kcal…) : les plats qui, mis à sa place puis réglés à leur tour, en approchent le plus.
    Une estimation rapide sur tout le catalogue, puis le vrai calcul sur les meilleurs. Avec des ingrédients
    préférés (operation["preferes"], Taha 19/11/2026), les plats qui les contiennent passent devant ; s'il n'y en
    a aucun, les meilleurs quand même. None si aucun ne fait mieux."""
    termes = _preferes(operation)
    jour, o, nutr = plan["jours"][j], plan["objectif"], ctx["nutriments"] or {}
    table, ident = nutr.get("macros") or {}, operation["plat"]
    moment = str(operation.get("moment") or "")
    places = [m for m, i in P.moments(jour) if i == ident and not (m == "dej" and jour.get("dej_reste"))]
    if moment not in places:
        moment = places[0] if places else ""
    if not moment:
        return None
    fois = len(places) if (len(places) > 1 and "flemmard" in (plan.get("modes") or [])
                           and operation.get("ensemble", True) is not False) else 1
    actuel = P.recette_du_jour(par_id[ident], jour, nutr)
    t_actuel = P.taille(jour, ident, par_id)
    sans_k = jour["kcal"] - actuel["kcal"] * t_actuel * fois
    sans_p = jour["prot"] - actuel["prot"] * t_actuel * fois
    deja = _ecart_objectif(jour["kcal"], jour["prot"], o)
    cats = {"din": ("plat",), "dej": ("plat",), "pdj": ("petitdej",)}.get(moment, ("collation", "plat", "petitdej"))
    fodmap = "fodmap" in (plan.get("modes") or [])
    pas_aimes = {i for i, g in _historique()["gouts"].items() if g == "non"}
    menu = {i for _, i in P.moments(jour)}
    grille = P.FACTEURS_OBJECTIF[::2]
    estimes = []
    for r in recettes:
        if (r["cat"] not in cats or r["id"] in (P.RIEN, "extrariz", ident) or r["id"] in pas_aimes or r["id"] in menu
                or (fodmap and not r.get("fodmap"))):
            continue
        base = P.macros(r, nutr)
        if not base or not base.get("kcal"):
            continue
        t = 1 if r.get("tel_quel") or r.get("perso") else jour["facteur"]
        lev = {"P": [0.0, 0.0], "E": [0.0, 0.0]}
        for ing in r["ing"]:
            if ing["u"] not in ("g", "ml", "pièce"):
                continue
            k, p = P._kcal_prot(ing, table, nutr)
            if k > 0:
                cle = "P" if p * 4 >= 0.3 * k else "E"
                lev[cle][0] += k
                lev[cle][1] += p
        meilleur = None
        for fp in grille if lev["P"][0] else (1.0,):
            for fe in grille if lev["E"][0] else (1.0,):
                k = sans_k + fois * t * (base["kcal"] + (fp - 1) * lev["P"][0] + (fe - 1) * lev["E"][0])
                p = sans_p + fois * t * (base["prot"] + (fp - 1) * lev["P"][1] + (fe - 1) * lev["E"][1])
                e = _ecart_objectif(k, p, o)
                if meilleur is None or e < meilleur:
                    meilleur = e
        estimes.append((-len(_avec_preferes(r, termes)), meilleur, r["id"]))
    estimes.sort()
    trouves = bool(termes) and bool(estimes) and estimes[0][0] < 0
    vrais = []
    for nb, _, autre in estimes[:6]:           # le vrai calcul : mis a la place, puis regle comme il le serait
        copie = json.loads(json.dumps(plan))
        try:
            P.modifier(copie, {"type": "changer", "jour": j, "moment": moment, "plat": autre,
                               **({"ensemble": operation["ensemble"]} if "ensemble" in operation else {})})
        except ValueError:
            continue

        def recompter(c=copie):
            P.recalculer(c, recettes, ctx)
            return c["jours"][j]["kcal"], c["jours"][j]["prot"]
        recompter()
        P.viser_objectif(copie, j, par_id, nutr, o, recompter, seulement=autre)
        x = copie["jours"][j]
        e = _ecart_objectif(x["kcal"], x["prot"], o)
        if e < deja - 1e-4 or nb < 0:          # un plat avec tes ingredients est montre meme s'il fait moins bien
            vrais.append((nb, e, {"id": autre, "nom": par_id[autre]["nom"], "kcal_jour": x["kcal"], "prot_jour": x["prot"],
                                  "atteint": _dans_l_objectif(x, o), "avec": _avec_preferes(par_id[autre], termes)}))
    vrais.sort(key=lambda v: (v[0], v[1]))
    if not vrais:
        return None
    return {"moment": moment, "plats": [v for *_, v in vrais[:4]], "preferes": [texte for texte, _ in termes],
            "preferes_trouves": trouves}


def _pour_combler(plan: dict, j: int, par_id: dict, recettes: list) -> dict | None:
    """Quand la journee reste loin de l'objectif (un repas retire, des repas fixes) : les plats qui
    combleraient le mieux ce qui manque, et le repas ou les mettre. None si la journee est bonne."""
    jour, o = plan["jours"][j], plan["objectif"]
    dk, dp = o["kcal"] - jour["kcal"], o["prot"] - jour["prot"]
    if dk < 0.08 * o["kcal"] and dp < 0.1 * o["prot"]:
        return None
    vide = next((m for m in ("din", "dej", "pdj") if jour[m] == P.RIEN and not (m == "dej" and jour.get("dej_reste"))), None)
    moment = vide or f"col{len(jour['collations'])}"
    cats = {"din": ("plat",), "dej": ("plat",), "pdj": ("petitdej",)}.get(vide, ("collation", "plat", "petitdej"))
    fodmap = "fodmap" in (plan.get("modes") or [])
    pas_aimes = {i for i, g in _historique()["gouts"].items() if g == "non"}
    menu = {i for _, i in P.moments(jour)}
    notes = []
    for r in recettes:
        if (r["cat"] not in cats or r["id"] in (P.RIEN, "extrariz") or r["id"] in pas_aimes or r["id"] in menu
                or (fodmap and not r.get("fodmap")) or not r.get("kcal")):
            continue
        t = 1 if r.get("tel_quel") or r.get("perso") else jour["facteur"]
        ecart = ((r["kcal"] * t - dk) / o["kcal"]) ** 2 + ((r["prot"] * t - dp) / o["prot"]) ** 2
        notes.append((ecart, r, t))
    notes.sort(key=lambda x: x[0])
    return {"moment": moment, "kcal": dk, "prot": dp,
            "plats": [{"id": r["id"], "nom": r["nom"], "kcal": round(r["kcal"] * t), "prot": round(r["prot"] * t)}
                      for _, r, t in notes[:4]]}


def _cible_du_repas(cat: str, remplace: str | None, par_id: dict) -> dict:
    """Calories et proteines qu'une portion du nouveau plat doit tenir : celles du
    plat qu'il remplace, sinon la part habituelle de ce repas dans l'objectif du jour."""
    ancien = par_id.get(remplace or "")
    if ancien and ancien.get("kcal"):
        return {"kcal": ancien["kcal"], "prot": ancien["prot"], "d_apres": ancien["nom"]}
    reglages = _reglages()
    phase = _phase(reglages)
    part = mod_perso.PART[cat]
    return {"kcal": round((phase["kcal"] + int(reglages.get("ajustement") or 0)) * part),
            "prot": round(phase["prot"] * part), "d_apres": ""}


_IDEES = {}                             # (nom, ingredients, type de repas, fodmap) -> ce que Claude a propose


def _idee_de_claude(nom: str, ingredients: list, cat: str, fodmap: bool, connus: list) -> dict | None:
    """Ce qu'il faut pour que ce plat soit une vraie recette : ingredients a ajouter (pris
    dans ceux du site), etapes, temps. Demande a Claude par l'abonnement Claude Code (le
    CLI `claude`, modele rapide), une fois par plat. None si le reglage repas.plat_perso_ia
    est a false, si le CLI manque ou si la reponse n'est pas lisible : on complete alors
    sans lui."""
    if not reglage("repas.plat_perso_ia", True):
        return None
    cle = (nom.strip().lower(), tuple(sorted(i.strip().lower() for i in ingredients)), cat, fodmap)
    if cle in _IDEES:
        return _IDEES[cle]
    try:
        from core.llm import ClaudeCodeProvider
        binaire = ClaudeCodeProvider._trouver_binaire()
        env = {k: v for k, v in os.environ.items() if k not in ClaudeCodeProvider._ENV_RETIRE}
    except Exception:
        return None
    if not binaire:
        return None
    repas_ = {"plat": "un plat (déjeuner ou dîner)", "petitdej": "un petit-déjeuner", "collation": "une collation"}[cat]
    demande = (
        f"Tu complètes une recette maison pour UNE personne. Nom du plat : « {nom} ». C'est {repas_}.\n"
        f"La personne veut y mettre : {', '.join(ingredients)}.\n"
        "Ajoute ce qu'il faut pour que ce soit la vraie recette de ce plat : matière grasse, aromates, "
        "épices, herbes, et l'accompagnement habituel s'il y en a un. Garde tous ses ingrédients. "
        "Cuisine halal : n'ajoute ni porc ni alcool, et n'ajoute pas de viande si elle n'en a pas mis."
        + (" Régime pauvre en FODMAP : ni oignon, ni ail, ni blé, ni légumineuses." if fodmap else "") + "\n"
        "Tu ne peux ajouter QUE des ingrédients de cette liste, avec leur nom exact (le sel et le poivre "
        "n'y sont pas : ne les ajoute pas, ils vont de soi). L'unité de chacun est entre crochets "
        "(qs = à volonté, sans quantité) :\n" + ", ".join(connus) + "\n"
        "Réponds par un objet JSON et rien d'autre : {\"ajouter\": [au plus 8 noms de la liste, sans les crochets], "
        "\"quantites\": {nom: nombre dans l'unité de la liste, pour une portion, pour CHAQUE ingrédient du plat sauf ceux en qs}, "
        "\"etapes\": [4 à 7 phrases courtes, à l'impératif, en tutoyant], \"temps\": minutes de préparation et de cuisson}")
    modele = str(reglage("repas.plat_perso_modele", "haiku") or "haiku")
    try:
        with tempfile.TemporaryDirectory() as vide:           # ni projet ni fichiers a lire
            sortie = subprocess.run([binaire, "-p", demande, "--model", modele, "--output-format", "text",
                                     "--tools", "", "--setting-sources", ""], capture_output=True, text=True,
                                    timeout=int(reglage("repas.plat_perso_timeout", 60) or 60), env=env, cwd=vide)
        trouve = re.search(r"\{.*\}", sortie.stdout, re.S)
        idee = json.loads(trouve.group(0)) if sortie.returncode == 0 and trouve else None
    except (OSError, subprocess.SubprocessError, ValueError):
        idee = None
    if not isinstance(idee, dict) or not isinstance(idee.get("ajouter"), list):
        consigner("plat_perso", f"Claude n'a pas repondu pour « {nom} » : recette completee sans lui")
        return None
    if len(_IDEES) > 200:
        _IDEES.clear()
    _IDEES[cle] = idee
    return idee


def plat_perso(champs: dict, apercu: bool = True, photo: bytes | None = None) -> dict:
    """Complete le plat que l'utilisateur decrit (nom + ingredients) et, sans
    `apercu`, l'enregistre dans les plats du profil. Renvoie la recette, ce que
    Jarvis a ajoute, son cout, et ce qu'il faudrait acheter pour une portion."""
    cat = str(champs.get("cat") or "plat")
    if cat not in mod_perso.PART:
        raise ValueError("type de repas inconnu")
    nom = str(champs.get("nom") or "")
    ingredients = [str(i) for i in (champs.get("ingredients") or [])][:30]
    modes = champs.get("modes")
    fodmap = "fodmap" in (modes if isinstance(modes, list) else _profil().preferences["modes"])
    socle = [x for x in donnees_site()["recettes"] if not x.get("perso")]
    # D'abord sans Claude : inutile de l'appeler si un ingredient est inconnu ou le nom vide.
    tel_quel = bool(champs.get("tel_quel"))
    choisies = champs.get("quantites") if isinstance(champs.get("quantites"), dict) else None
    extra = _ingredients_crees()
    essai = mod_perso.completer(nom, ingredients, cat, {"kcal": 600, "prot": 30}, socle, nutriments(), fodmap, None, tel_quel,
                                extra=extra)
    idee = None
    if essai["recette"] is not None and not tel_quel:                      # hors du verrou : Claude met quelques secondes
        idee = _idee_de_claude(essai["recette"]["nom"], [i["n"] for i in essai["recette"]["ing"] if i["n"] not in essai["ajoutes"]],
                               cat, fodmap, [f"{n} [{h['u']}]" for n, h in sorted({**mod_perso.habitudes(socle), **extra}.items())])
    with _VERROU:
        recettes = donnees_site()
        par_id = {x["id"]: x for x in recettes["recettes"]}
        cible = _cible_du_repas(cat, champs.get("remplace"), par_id)
        r = mod_perso.completer(nom, ingredients, cat, cible, socle, nutriments(), fodmap, idee, tel_quel, choisies, extra=extra)
        recette = r["recette"]
        if recette is None:
            return r
        if recette["id"] in par_id and not par_id[recette["id"]].get("perso"):
            raise ValueError("ce nom est déjà celui d'une recette du site")
        ctx = _contexte(recettes)
        cout = ctx["tarifs"].recette(recette)[0]
        tri = cli.preparer(pdf.Lecture(ingredients=[pdf.Ingredient(i["n"], i["q"], i["u"]) for i in recette["ing"]],
                                       recettes=1, portions_annoncees=1), mod_stock.charger())
        manque = [{"nom": l["nom"], "quantite": l["acheter"], "unite": l["unite"]} for l in tri["a_acheter"]]
        r.update(cout=cout, manque=manque, boucher=tri["boucher"], existe=recette["id"] in par_id,
                 ecart={"kcal": recette["kcal"] - cible["kcal"], "prot": recette["prot"] - cible["prot"]})
        if apercu:
            return r
        plats = [x for x in plats_perso() if x["id"] != recette["id"]] + [recette]
        if len(plats) > 300:          # les repas mis au menu depuis « Ajouter » deviennent aussi des plats
            raise ValueError("300 plats personnels au plus : supprime-en un")
        _ecrire_p("plats_perso.json", plats)
        if photo:                                   # ta photo de l'assiette, sinon on en cherche une
            poser_photo_perso(recette["id"], photo, {"titre": "ta photo", "page": "", "auteur": "toi", "licence": "", "source": "ta photo"})
        else:
            chercher_photo(recette)
        journal("remplacement", f"Plat ajouté par toi : « {recette['nom']} »",
                [f"{recette['kcal']} kcal et {recette['prot']} g de protéines la portion, pour une cible de "
                 f"{cible['kcal']} kcal et {cible['prot']} g" + (f" (celle de « {cible['d_apres']} »)." if cible["d_apres"] else "."),
                 "Ingrédients : " + ", ".join(f"{i['n']} {mod_stock.fmt(i['q'])} {i['u']}".replace(" 0 qs", "") for i in recette["ing"]) + "."]
                + (["Ajouté par Jarvis pour compléter l'assiette : " + ", ".join(r["ajoutes"]) + "."] if r["ajoutes"] else []))
        return r


def _ingredients_crees() -> dict:
    """Les ingredients crees par le profil, au format de plat_perso.habitudes."""
    return {n: {"u": v["u"], "q": float(v["q"]), "a": int(v.get("a", 2)), "cats": set()}
            for n, v in ingredients_perso().items() if v.get("cree")}


def _claude_json(demande: str, timeout: int = 60) -> dict | None:
    """Reponse JSON de Claude (CLI `claude`, abonnement Claude Code), ou None."""
    if not reglage("repas.plat_perso_ia", True):
        return None
    try:
        from core.llm import ClaudeCodeProvider
        binaire = ClaudeCodeProvider._trouver_binaire()
        env = {k: v for k, v in os.environ.items() if k not in ClaudeCodeProvider._ENV_RETIRE}
    except Exception:
        return None
    if not binaire:
        return None
    modele = str(reglage("repas.plat_perso_modele", "haiku") or "haiku")
    try:
        with tempfile.TemporaryDirectory() as vide:
            sortie = subprocess.run([binaire, "-p", demande, "--model", modele, "--output-format", "text",
                                     "--tools", "", "--setting-sources", ""], capture_output=True, text=True,
                                    timeout=timeout, env=env, cwd=vide)
        trouve = re.search(r"\{.*\}", sortie.stdout, re.S)
        reponse = json.loads(trouve.group(0)) if sortie.returncode == 0 and trouve else None
    except (OSError, subprocess.SubprocessError, ValueError):
        return None
    return reponse if isinstance(reponse, dict) else None


def proposer_ingredient(tape: str) -> dict:
    """Ce que l'on sait d'un produit tape par l'utilisateur (« Cookie Auchan boulangerie ») : nom propre,
    unite, portion, rayon, prix, valeurs pour 100 g. D'abord les VRAIES etiquettes, lues en ligne
    (auchan.fr, Open Food Facts : repas/etiquettes.py) ; Claude dit laquelle est le produit tape, ou
    aucune, et donne le rayon et le prix. Sans etiquette qui corresponde, l'estimation de Claude, signalee
    comme telle. Rien n'est enregistre : l'utilisateur verifie, ou prend une autre etiquette de la liste."""
    tape = re.sub(r"\s+", " ", str(tape or "")).strip()[:80]
    if len(tape) < 2:
        raise ValueError("écris le nom du produit")
    vide = {"nom": tape[:1].upper() + tape[1:], "u": "g", "q": 100, "a": 2, "prix": None,
            **dict.fromkeys(MACROS_ING, None), "attention": "", "par_claude": False, "etiquette": None, "etiquettes": []}
    trouves = mod_etiquettes.chercher(tape) if reglage("repas.etiquettes_en_ligne", True) else []
    etiquettes = [{"nom": x["nom"], "source": x["source"], "url": x["url"], "portion_g": x["portion_g"],
                   "attention": _attention_composition(x["composition"]),
                   **{m: round(float(x[m]), 1) for m in MACROS_ING}} for x in trouves]
    rayons = ", ".join(f"{k} = {n}" for k, n in enumerate(donnees_site()["rayons"]))
    liste = "".join(f"[{k}] {x['nom']} ({x['source']}) : {x['kcal']:g} kcal, {x['prot']:g} g de protéines pour 100 g\n"
                    for k, x in enumerate(etiquettes))
    idee = _claude_json(
        f"Un utilisateur français ajoute un aliment à son application de repas : « {tape} ».\n"
        + (f"Étiquettes trouvées en ligne pour cette recherche :\n{liste}"
           "Si l'une d'elles est bien CE produit (même produit, même enseigne ou marque si elle est donnée ; "
           "pas un produit voisin), mets son numéro dans \"etiquette\", sinon null.\n" if etiquettes else "")
        + "Donne aussi les valeurs nutritionnelles moyennes de ce produit tel qu'il est vendu en France (celles de "
        "l'étiquette si tu connais ce produit précis, sinon celles d'un produit équivalent, table CIQUAL).\n"
        "Réponds par un objet JSON et rien d'autre : {" + ("\"etiquette\": numéro ou null, " if etiquettes else "")
        + "\"nom\": nom court de l'aliment en français, avec la marque "
        "ou l'enseigne entre parenthèses si l'utilisateur l'a donnée, \"u\": \"g\" ou \"ml\", \"q\": quantité "
        "d'une portion habituelle dans cette unité, \"a\": numéro du rayon (" + rayons + "), \"prix\": prix moyen en "
        "euros au kilo (ou au litre) en France, \"kcal\", \"prot\", \"gluc\", \"lip\", \"fib\": pour 100 g (ou 100 ml), "
        "\"attention\": une phrase courte si ce type de produit contient parfois de la gélatine de porc, de l'alcool, "
        "de la viande non halal ou du E471 (sinon une chaîne vide)}")
    propre = {**vide, "etiquettes": etiquettes}
    if idee:
        propre["par_claude"] = True
        if isinstance(idee.get("nom"), str) and 2 <= len(idee["nom"].strip()) <= 80:
            propre["nom"] = idee["nom"].strip()
        if idee.get("u") in ("g", "ml"):
            propre["u"] = idee["u"]
        for cle_, bas, haut in (("q", 1, 2000), ("prix", 0.01, 500), ("kcal", 0, 900), ("prot", 0, 100), ("gluc", 0, 100),
                                ("lip", 0, 100), ("fib", 0, 100)):
            try:
                v = float(idee.get(cle_))
            except (TypeError, ValueError):
                continue
            if bas <= v <= haut:
                propre[cle_] = round(v, 2)
        try:
            if 0 <= int(idee.get("a")) < len(donnees_site()["rayons"]):
                propre["a"] = int(idee["a"])
        except (TypeError, ValueError):
            pass
        if isinstance(idee.get("attention"), str):
            propre["attention"] = idee["attention"].strip()[:200]
    # L'etiquette retenue : celle que Claude reconnait ; sans Claude, seulement un nom identique a ce qui est tape.
    choisie = None
    if idee and etiquettes:
        try:
            k = int(idee.get("etiquette"))
            choisie = k if 0 <= k < len(etiquettes) else None
        except (TypeError, ValueError):
            choisie = None
    elif not idee and trouves and trouves[0]["ressemblance"] >= 1:
        choisie = 0
    if choisie is not None:
        e = etiquettes[choisie]
        propre.update({m: e[m] for m in MACROS_ING})
        propre["etiquette"] = choisie
        if e["portion_g"] and 1 <= e["portion_g"] <= 2000:
            propre["q"] = e["portion_g"]
        if e["attention"]:
            propre["attention"] = e["attention"]
        if not idee:
            propre["nom"] = e["nom"]
    return {**propre, "deja": _ingredients_proches(tape, propre["nom"])}


def _attention_composition(composition: str) -> str:
    """Une phrase si la liste d'ingrédients de l'étiquette contient du porc, de l'alcool, de la gélatine
    d'origine non précisée ou du E471 (les mêmes contrôles que pour le panier)."""
    if not composition:
        return ""
    from repas import prix
    trouve = prix._contient_interdit(composition, list(prix.PORC) + list(prix.ALCOOL) + ["gelatine", "e471"])
    return f"La composition de l'étiquette contient « {trouve} » : à vérifier avant de le manger." if trouve else ""


