def noter_repas(champs: dict) -> dict:
    """Ajoute un repas noté, ou le remplace (champs["id"])."""
    entree = mod_journal.nettoyer_entree(champs)
    with _VERROU:
        entrees = repas_notes()
        ident = str(champs.get("id") or "")
        ancien = next((e for e in entrees if e["id"] == ident), None)
        if ident and not ancien:
            raise ValueError("ce repas n'existe plus")
        entree = {**entree, "id": ident or secrets.token_hex(6), "cree": (ancien or {}).get("cree") or time.strftime("%Y-%m-%dT%H:%M:%S")}
        _ecrire_repas([e for e in entrees if e["id"] != entree["id"]] + [entree])
    return entree


def oublier_repas(ident: str) -> None:
    with _VERROU:
        entrees = repas_notes()
        if not any(e["id"] == ident for e in entrees):
            raise ValueError("ce repas n'existe plus")
        _ecrire_repas([e for e in entrees if e["id"] != ident])


def _poids_plausible(t: dict) -> float:
    """Un poids (g) pour lequel ces totaux font des valeurs pour 100 g possibles : un repas dont on ne connaît
    que les chiffres (« un kebab, 900 kcal ») devient un aliment de ce poids-là."""
    besoin = max(100.0, t["kcal"] / 8.5, (t["prot"] + t["gluc"] + t["lip"]) * 1.05, t.get("fib", 0) * 1.05)
    return float(math.ceil(besoin / 10) * 10)


def _ingredient_du_repas(item: dict, date: str) -> tuple:
    """(nom de l'ingrédient, quantité, unité) pour un aliment noté : celui de tes aliments quand les chiffres en
    viennent, sinon un ingrédient créé avec ses valeurs (étiquette, estimation de Claude, tes chiffres)."""
    table = nutriments().get("macros") or {}
    connus = {**mod_perso.habitudes([x for x in donnees_site()["recettes"] if not x.get("perso")]), **_ingredients_crees()}

    def en_unite(nom, g):
        u = connus[nom]["u"]
        if u == "qs":
            return None
        # Une pièce compte pour ce qu'on en mange (une banane : 120 g sans la peau), comme le calcul des calories.
        unite = 1.0 if u in ("g", "ml") else P.grammes({"n": nom, "q": 1, "u": u}, nutriments())
        return (nom, round(g / unite, 2), u) if unite else None
    g = item.get("g")
    nom = item.get("aliment")
    if nom in connus and nom in table and item.get("pour100") and g:
        trouve = en_unite(nom, g)
        if trouve:
            return trouve
    t = {m: float(item.get(m) or 0) for m in mod_journal.MACROS}
    if not g or g < 1 or t["kcal"] * 100 / g > 900 or (t["prot"] + t["gluc"] + t["lip"]) * 100 / g > 100.5 or t["fib"] * 100 / g > 100:
        g = _poids_plausible(t)
    pour100 = {m: round(t[m] * 100 / g, 2) for m in mod_journal.MACROS}
    base = re.sub(r"\s+", " ", str(item.get("nom") or "")).strip()[:70] or "Aliment"
    base = base[:1].upper() + base[1:]
    for k in range(1, 30):
        nom = base if k == 1 else f"{base} ({k})"
        if nom in table:
            v = table[nom]
            if nom in connus and abs(v["kcal"] - pour100["kcal"]) <= max(5, 0.05 * v["kcal"]) and abs(v["prot"] - pour100["prot"]) <= 1.5:
                trouve = en_unite(nom, g)           # le même aliment, déjà connu : on le reprend
                if trouve:
                    return trouve
            continue                                 # un autre aliment porte ce nom : on n'y touche pas
        source = item.get("url") or ("noté le " + date + " : " + str(item.get("source") or "tes chiffres"))
        nom = enregistrer_ingredient({"nom": nom, **pour100, "u": "g", "q": g, "a": 2, "source": source})
        return nom, round(g, 1), "g"
    raise ValueError(f"trop d'aliments s'appellent déjà « {base} »")


def repas_au_menu(champs: dict) -> dict:
    """« Ajouter un repas » (Taha, 19/11/2026) : ce que Claude a compris (un kebab, un ticket…)
    devient un plat du menu du jour, au repas choisi, comme un plat normal, et non une note « en plus ».
    Le plat est « tel quel » (ce qui a été mangé, sans rien ajouter) et rejoint tes plats ; chaque aliment
    vient de tes aliments, ou devient un aliment créé avec ses valeurs. Sans menu ce jour-là, le repas est
    noté comme avant. `champs["id"]` : un repas déjà noté en plus, qui passe au menu (sa note est retirée)."""
    import datetime
    entree = mod_journal.nettoyer_entree(champs)
    date = datetime.date.fromisoformat(entree["date"])
    plan, k, j = _plan_de_la_date(date)
    mois = _mois() if rythme() == "mois" else None
    if plan is None or (k is not None and mois and k < mois["rang"]):      # pas de menu modifiable ce jour-là
        return {"note": noter_repas(champs)}
    ident_note = str(champs.get("id") or "")
    if ident_note and not any(e["id"] == ident_note for e in repas_notes()):
        raise ValueError("ce repas n'existe plus")
    photo = None                                     # la photo de l'assiette jointe : elle devient celle du plat
    if champs.get("photo"):
        try:
            photo = base64.b64decode(str(champs["photo"]).split(",", 1)[-1], validate=False)
        except ValueError:
            photo = None
        if photo and (len(photo) > 6_000_000 or not (photo[:3] == b"\xff\xd8\xff" or photo[:8] == b"\x89PNG\r\n\x1a\n")):
            photo = None
    par_id = {x["id"]: x for x in donnees_site()["recettes"]}
    moment = entree["moment"]
    items = entree["items"]
    seul = items[0] if len(items) == 1 else None
    if seul and seul.get("plat") in par_id and par_id[seul["plat"]].get("perso") and (seul.get("portions") or 1) == 1:
        plat = seul["plat"]                          # un de tes plats, tel quel : il va directement au menu
    else:
        quantites = {}
        for item in items:
            source = par_id.get(item.get("plat")) if item.get("plat") else None
            if source and source.get("perso"):       # un de tes plats parmi d'autres aliments : ses ingrédients
                n = item.get("portions") or 1
                lignes = [(i["n"], i["q"] * n, i["u"]) for i in source["ing"] if i["u"] != "qs"]
            else:
                lignes = [_ingredient_du_repas(item, entree["date"])]
            for nom, q, u in lignes:
                avant = quantites.get(nom)
                quantites[nom] = {"q": round((avant["q"] if avant else 0) + q, 2), "u": u}
        if len(quantites) > 20:
            raise ValueError("20 aliments au plus dans un repas")
        cat = {"pdj": "petitdej", "col": "collation"}.get(moment, "plat")
        nom = entree["nom"][:1].upper() + entree["nom"][1:]
        perso = {x["id"]: x for x in plats_perso()}
        voulu = sorted((n, round(v["q"], 1)) for n, v in quantites.items())
        plat = None
        for essai in range(1, 30):                   # un nom libre, ou le même plat déjà enregistré
            nom_essai = nom if essai == 1 else f"{nom} ({essai})"
            ident = "perso-" + re.sub(r"[^a-z0-9]+", "-", pdf.normaliser(nom_essai)).strip("-")[:40]
            if ident in perso and sorted((i["n"], round(i["q"], 1)) for i in perso[ident]["ing"] if i["u"] != "qs") == voulu:
                plat = ident
                break
            if ident not in par_id:
                r = plat_perso({"nom": nom_essai, "cat": cat, "ingredients": list(quantites), "quantites": quantites,
                                "tel_quel": True}, apercu=False, photo=photo)
                if r.get("recette") is None:
                    raise ValueError("aliment inconnu : " + ", ".join(x["nom"] for x in r.get("inconnus", [])))
                plat = r["recette"]["id"]
                break
        if not plat:
            raise ValueError("trop de plats portent déjà ce nom")
    # Un plat repris (déjà enregistré) sans photo : ta photo, sinon on en cherche une.
    if not (_photos_perso() / f"{plat}.jpg").exists():
        if photo:
            poser_photo_perso(plat, photo, {"titre": "ta photo", "page": "", "auteur": "toi", "licence": "", "source": "ta photo"})
        elif plat in {x["id"] for x in plats_perso()}:
            chercher_photo(next(x for x in plats_perso() if x["id"] == plat))
    with _VERROU:
        jour = plan["jours"][j]
        libre = moment != "col" and jour[moment] == P.RIEN and not (moment == "dej" and jour.get("dej_reste"))
        if moment == "col" or not libre:
            op = {"type": "ajouter", "jour": j, "plat": plat, **({"moment": moment} if moment != "col" else {})}
        else:
            op = {"type": "changer", "jour": j, "moment": moment, "plat": plat, "ensemble": False}
        resultat = modifier_semaine(op, k, confirme=True)
        if ident_note:
            oublier_repas(ident_note)
    return {"plat": plat, "operation": op, "semaine": resultat["semaine"]}


def _claude_avec_photo(demande: str, photo: bytes | None, timeout: int = 150) -> dict | None:
    """Réponse JSON de Claude (CLI `claude`), qui peut lire la photo jointe (./photo.jpg). None sans réponse."""
    if not reglage("repas.plat_perso_ia", True):
        return None
    try:
        from core.llm import ClaudeCodeProvider
        binaire = ClaudeCodeProvider._trouver_binaire()
        env = {k: v for k, v in os.environ.items() if k not in ClaudeCodeProvider._ENV_RETIRE}
    except Exception:
        return None
    if not binaire:
        return None
    modele = str(reglage("repas.journal_modele", "sonnet") or "sonnet")
    outils = ["--allowedTools", "Read", "--tools", "Read"] if photo else ["--tools", ""]
    try:
        with tempfile.TemporaryDirectory() as dossier:
            if photo:
                (Path(dossier) / "photo.jpg").write_bytes(photo)
            sortie = subprocess.run([binaire, "-p", demande, "--model", modele, "--output-format", "text", *outils,
                                     "--setting-sources", ""], capture_output=True, text=True,
                                    timeout=timeout, env=env, cwd=dossier)
        trouve = re.search(r"\{.*\}", sortie.stdout, re.S)
        reponse = json.loads(trouve.group(0)) if sortie.returncode == 0 and trouve else None
    except (OSError, subprocess.SubprocessError, ValueError):
        return None
    return reponse if isinstance(reponse, dict) else None


def analyser_repas(champs: dict) -> dict:
    """Ce que Claude comprend d'un repas décrit (texte, photo d'assiette, d'étiquette ou de ticket, macros
    données) : une proposition à vérifier, rien n'est enregistré."""
    texte = re.sub(r"\s+", " ", str(champs.get("texte") or "")).strip()[:1500]
    photo = None
    if champs.get("photo"):
        brut = str(champs["photo"])
        try:
            photo = base64.b64decode(brut.split(",", 1)[-1], validate=False)
        except ValueError:
            raise ValueError("photo illisible")
        if len(photo) > 6_000_000 or not (photo[:3] == b"\xff\xd8\xff" or photo[:8] == b"\x89PNG\r\n\x1a\n"):
            raise ValueError("photo illisible (JPEG ou PNG, 6 Mo au plus)")
    if not texte and not photo:
        raise ValueError("décris ce que tu as mangé, ou ajoute une photo")
    moment = champs.get("moment") if champs.get("moment") in mod_journal.MOMENTS else mod_journal.moment_du_moment()
    connus = nutriments().get("macros") or {}
    plats = {p["id"]: p for p in plats_perso()}
    idee = _claude_avec_photo(mod_journal.consigne(texte, bool(photo), moment, connus, list(plats.values())), photo)
    if idee is None:
        raise ValueError("Claude ne répond pas pour l'instant : entre les chiffres toi-même, ou réessaie dans un moment")
    resultat = mod_journal.lire_reponse(idee, connus, plats,
                                        mod_etiquettes.chercher if reglage("repas.etiquettes_en_ligne", True) else None)
    return {**resultat, "moment": resultat["moment"] or moment}


def _plan_de_la_date(date) -> tuple:
    """(plan, rang de la semaine (None = semaine en cours seule), jour) qui contient cette date, ou (None, None, None)."""
    import datetime
    mois = _mois() if rythme() == "mois" else None
    courante = _lire_p("semaine.json", None)
    liste = [(courante if mois and k == mois["rang"] else p, k) for k, p in enumerate(mois["semaines"])] if mois else [(courante, None)]
    for plan, k in liste:
        debut = _debut(plan) if plan else None
        if debut and 0 <= (date - debut).days < 7:
            return plan, k, (date - debut).days
    return None, None, None


def idees_pour_finir(date, notes: list, recettes: dict, ctx: dict, n: int = 3) -> dict | None:
    """« Pour finir la journée » (Taha, 19/11/2026 : « pas bien calculé ») : les plats qui, AJOUTÉS au menu de ce
    jour (au repas vide, sinon en collation) puis réglés en grammes comme le ferait « Rééquilibrer », amènent la
    journée au plus près de l'objectif, ce qui a été noté en plus compris. Estimation rapide sur le catalogue,
    puis le vrai calcul sur les meilleurs. None si la journée est déjà bonne ou sans menu ce jour-là."""
    plan, k, j = _plan_de_la_date(date)
    if plan is None or plan["jours"][j].get("retire"):
        return None
    jour, o = plan["jours"][j], plan["objectif"]
    en_plus = {m: sum(float(e.get(m) or 0) for e in notes) for m in ("kcal", "prot")}
    vise = {"kcal": o["kcal"] - en_plus["kcal"], "prot": max(0.0, o["prot"] - en_plus["prot"])}
    manque_kcal, manque_prot = vise["kcal"] - jour["kcal"], vise["prot"] - jour["prot"]
    if manque_kcal < 150 and manque_prot <= 5:          # les deux objectifs sont atteints : rien à proposer
        return None
    par_id = {x["id"]: x for x in recettes["recettes"]}
    nutr = ctx.get("nutriments") or {}
    table = nutr.get("macros") or {}
    # Peu de calories à prendre (il manque surtout des protéines) : une collation, pas un repas entier.
    vide = None if manque_kcal < 350 else next(
        (m for m in ("din", "dej", "pdj") if jour[m] == P.RIEN and not (m == "dej" and jour.get("dej_reste"))), None)
    moment = vide or f"col{len(jour['collations'])}"
    cats = {"din": ("plat",), "dej": ("plat",), "pdj": ("petitdej",)}.get(vide, ("collation", "plat", "petitdej"))
    fodmap = "fodmap" in (plan.get("modes") or [])
    pas_aimes = {i for i, g in _historique()["gouts"].items() if g == "non"}
    menu = {i for _, i in P.moments(jour)}
    cible = lambda kc, pr: (((kc - vise["kcal"]) / o["kcal"]) ** 2 + ((pr - vise["prot"]) / o["prot"]) ** 2
                            + 0.5 * (max(0.0, pr - vise["prot"] - 15) / o["prot"]) ** 2)    # trop de protéines : un peu moins bien
    grille = P.FACTEURS_OBJECTIF[::2]
    estimes = []
    for r in recettes["recettes"]:
        if (r["cat"] not in cats or r["id"] in (P.RIEN, "extrariz") or r["id"] in pas_aimes or r["id"] in menu
                or (fodmap and not r.get("fodmap"))):
            continue
        base = P.macros(r, nutr)
        if not base or not base.get("kcal"):
            continue
        t = 1 if r.get("tel_quel") or r.get("perso") else jour["facteur"]
        lev = {"P": [0.0, 0.0], "E": [0.0, 0.0]}
        for ing in r["ing"]:
            if ing["u"] in ("g", "ml", "pièce"):
                kc, pr = P._kcal_prot(ing, table, nutr)
                if kc > 0:
                    cle = "P" if pr * 4 >= 0.3 * kc else "E"
                    lev[cle][0] += kc
                    lev[cle][1] += pr
        meilleur = min(cible(jour["kcal"] + t * (base["kcal"] + (fp - 1) * lev["P"][0] + (fe - 1) * lev["E"][0]),
                             jour["prot"] + t * (base["prot"] + (fp - 1) * lev["P"][1] + (fe - 1) * lev["E"][1]))
                       for fp in (grille if lev["P"][0] else (1.0,)) for fe in (grille if lev["E"][0] else (1.0,)))
        estimes.append((meilleur, r["id"]))
    estimes.sort()
    vrais = []
    for _, ident in estimes[:6]:
        copie = json.loads(json.dumps(plan))
        op = {"type": "ajouter", "jour": j, "plat": ident} if moment.startswith("col") else {"type": "changer", "jour": j, "moment": moment, "plat": ident}
        try:
            P.modifier(copie, op)
        except ValueError:
            continue

        def recompter(c=copie):
            P.recalculer(c, recettes["recettes"], ctx)
            return c["jours"][j]["kcal"], c["jours"][j]["prot"]
        recompter()
        P.viser_objectif(copie, j, par_id, nutr, vise, recompter, seulement=ident)
        x = copie["jours"][j]
        r = P.recette_du_jour(par_id[ident], x, nutr)
        t = P.taille(x, ident, par_id)
        vrais.append((cible(x["kcal"], x["prot"]), {"id": ident, "nom": par_id[ident]["nom"], "operation": op,
                      "kcal": round(r["kcal"] * t), "prot": round(r["prot"] * t),
                      "kcal_jour": round(x["kcal"] + en_plus["kcal"]), "prot_jour": round(x["prot"] + en_plus["prot"])}))
    vrais.sort(key=lambda v: v[0])
    return {"semaine": k if k is not None else 0, "jour": j, "moment": moment, "plats": [v for _, v in vrais[:n]]} if vrais else None


def idees_du_jour(date: str) -> dict | None:
    """« Pour finir la journée » d'un jour plus lointain que demain, demandé par la page quand on l'ouvre
    (calculé à la demande : 0,2 s par jour, de trop pour chaque état)."""
    import datetime
    try:
        jour = datetime.date.fromisoformat(str(date))
    except ValueError:
        raise ValueError("date impossible")
    with _VERROU:
        recettes = donnees_site()
        ctx = {**_contexte(recettes), "phase": _phase(_reglages())}
        notes = [e for e in repas_notes() if e["date"] == jour.isoformat()]
        return idees_pour_finir(jour, notes, recettes, ctx)


def journal_des_jours(recettes: dict, jours_max: int = 60, ctx: dict | None = None) -> dict:
    """Pour la page : aujourd'hui, les jours suivants couverts par une semaine composée (demain au moins)
    et l'historique. Un jour noté montre ses repas notés ; un jour passé sans rien de noté montre le menu
    prévu de la semaine (« menu prévu »)."""
    import datetime
    objectif = _objectif_du_jour()
    aujourdhui = datetime.date.today()
    par_date = {}
    for e in repas_notes():
        par_date.setdefault(e["date"], []).append(e)
    prevus = {}
    par_id = {x["id"]: x for x in recettes["recettes"]}
    plans = [_lire_p("semaine.json", None)] + list((_mois() or {}).get("semaines") or []) + list(_historique()["semaines"])
    for plan in plans:
        debut = _debut(plan) if plan else None
        if not debut:
            continue
        for n, j in enumerate(plan.get("jours", [])):
            date = (debut + datetime.timedelta(days=n)).isoformat()
            if date in prevus or j.get("retire") or not j.get("repas"):
                continue
            prevus[date] = {"kcal": j.get("kcal", 0), "prot": j.get("prot", 0), "gluc": j.get("gluc", 0),
                            "lip": j.get("lip", 0), "fib": j.get("fib", 0),
                            "repas": [{"moment": r["moment"], "id": r["id"], "nom": (par_id.get(r["id"]) or {}).get("nom", r["id"]),
                                       "au_repas": (j.get("au_repas") or {}).get(r["id"], ""),
                                       **{m: round(r.get(m, 0)) for m in ("kcal", "prot", "gluc", "lip")}} for r in j["repas"]]}
    # Les jours à venir que l'on peut ouvrir (« › » à côté de « Demain », Taha, 19/11/2026) : ceux d'une semaine composée.
    futurs = [(datetime.date.fromisoformat(d) - aujourdhui).days for d in list(prevus) + list(par_date)]
    plus_loin = min(60, max([1] + [n for n in futurs if n > 0]))
    jours = []
    for k in range(-plus_loin, jours_max):
        d = (aujourdhui - datetime.timedelta(days=k)).isoformat()
        notes = sorted(par_date.get(d, []), key=lambda e: (list(mod_journal.MOMENTS).index(e["moment"]), e.get("cree", "")))
        prevu = prevus.get(d)
        if k not in (0, -1) and not notes and not prevu:
            continue
        # Le jour = les plats prévus (le menu de la semaine, changé ou non) + ce qui a été noté en plus.
        total = {m: round(float((prevu or {}).get(m, 0) or 0) + sum(float(e.get(m) or 0) for e in notes), 1) for m in mod_journal.MACROS}
        reste = {m: round(objectif[m] - total[m]) for m in ("kcal", "prot") if objectif.get(m)}
        jours.append({"date": d, "source": "menu et notes" if prevu and notes else "menu prévu" if prevu else "noté" if notes else "vide",
                      "entrees": notes, "repas": (prevu or {}).get("repas", []), **total, "reste": reste})
    idees = {}
    if ctx:
        for decalage in (0, 1):
            d = aujourdhui + datetime.timedelta(days=decalage)
            try:
                idees[d.isoformat()] = idees_pour_finir(d, par_date.get(d.isoformat(), []), recettes, ctx)
            except Exception as e:                      # une idée qui rate ne doit pas empêcher la page de s'ouvrir
                consigner("idees", f"idées pour finir la journée impossibles : {e}")
    return {"actif": mode_suivi(), "objectif": objectif, "aujourdhui": aujourdhui.isoformat(), "jours": jours, "idees": idees,
            "dernier": (aujourdhui + datetime.timedelta(days=plus_loin)).isoformat()}


# ------------------------------------------------------------------ mon suivi (poids, mensurations)
# kg, puis cm. Les mesures « _avant » se prennent quand on veut (la séance n'est pas une condition) ; « _apres »,
# juste après une séance de musculation, en option (Taha, 19/11/2026).
SUIVI_CHAMPS = {"poids": (30, 300), "biceps_avant": (15, 70), "biceps_apres": (15, 70),
                "tour_avant": (40, 200), "tour_apres": (40, 200), "torse_avant": (50, 200), "torse_apres": (50, 200)}


def suivi() -> list:
    """Les mesures du profil (suivi.json), les plus récentes d'abord : [{date, poids, biceps_avant,
    biceps_apres, tour_avant, tour_apres}] ; un champ absent n'a pas été mesuré ce jour-là."""
    d = _lire_p("suivi.json", {})
    mesures = d.get("mesures") if isinstance(d, dict) else None
    return sorted([m for m in mesures or [] if isinstance(m, dict) and re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(m.get("date", "")))],
                  key=lambda m: m["date"], reverse=True)


def noter_suivi(champs: dict) -> None:
    """Enregistre les mesures d'un jour (aujourd'hui par défaut). Chaque champ donné remplace celui du
    jour ; un champ vide l'efface ; un champ absent ne change pas. Poids chaque jour, biceps et tour
    de hanches avant et après la séance de musculation (Taha, 19/11/2026)."""
    date = str(champs.get("date") or time.strftime("%Y-%m-%d"))
    try:
        quand = time.strptime(date, "%Y-%m-%d")
    except ValueError:
        raise ValueError("date impossible")
    if time.mktime(quand) > time.time() + 86400:
        raise ValueError("cette date n'est pas encore passée")
    nouveaux = {}
    for cle, (bas, haut) in SUIVI_CHAMPS.items():
        if cle not in champs:
            continue
        v = champs[cle]
        if v is None or str(v).strip() == "":
            nouveaux[cle] = None
            continue
        try:
            v = float(str(v).replace(",", "."))
        except ValueError:
            raise ValueError(f"nombre attendu pour {cle.replace('_', ' ')}")
        if not bas <= v <= haut:
            raise ValueError(f"{cle.replace('_', ' ').replace('apres', 'après')} : {v:g} n'est pas possible ({bas} à {haut})")
        nouveaux[cle] = round(v, 1)
    if not nouveaux:
        raise ValueError("note au moins une mesure")
    with _VERROU:
        mesures = [m for m in suivi() if m["date"] != date]
        jour = next((m for m in suivi() if m["date"] == date), {"date": date})
        for cle, v in nouveaux.items():
            if v is None:
                jour.pop(cle, None)
            else:
                jour[cle] = v
        if any(k in jour for k in SUIVI_CHAMPS):
            mesures.append(jour)
        _ecrire_p("suivi.json", {"mesures": sorted(mesures, key=lambda m: m["date"])})


def oublier_suivi(date: str) -> None:
    with _VERROU:
        mesures = suivi()
        if not any(m["date"] == date for m in mesures):
            raise ValueError("aucune mesure ce jour-là")
        _ecrire_p("suivi.json", {"mesures": sorted([m for m in mesures if m["date"] != date], key=lambda m: m["date"])})


def _ingredients_proches(*noms: str) -> list:
    """Les ingredients deja connus (du site ou crees par toi) qui ressemblent a ce qui est tape : pour ne pas
    creer six fois le meme gateau (Taha, 14/11/2026)."""
    connus = {**mod_perso.habitudes([x for x in donnees_site()["recettes"] if not x.get("perso")]), **_ingredients_crees()}
    vus = []
    for nom in noms:
        trouve, proches = mod_perso.trouver(nom, connus)
