def valeurs_ingredient(nom: str) -> dict:
    """Les valeurs pour 100 g d'un ingredient : celles du site, et la correction du profil s'il y en a une."""
    nom = str(nom or "")
    site = ((_garde(_SITE / "nutriments.json").get("macros") or {}).get(nom))
    perso = ingredients_perso().get(nom)
    if site is None and perso is None:
        raise ValueError("ingrédient inconnu")
    actuel = {m: (perso or site)[m] for m in MACROS_ING}
    utilise = sorted(r["nom"] for r in donnees_site()["recettes"] if any(i["n"] == nom for i in r.get("ing", [])))
    return {"nom": nom, "valeurs": actuel, "site": {m: site[m] for m in MACROS_ING} if site else None,
            "corrige": bool(perso) and not perso.get("cree"), "cree": bool(perso and perso.get("cree")),
            "u": (perso or {}).get("u"), "q": (perso or {}).get("q"), "a": (perso or {}).get("a"),
            "prix": (perso or {}).get("prix") if perso else donnees_site()["prix"].get(nom),
            "source": (perso or {}).get("source", ""), "plats": utilise[:40], "nb_plats": len(utilise)}


def enregistrer_ingredient(champs: dict) -> str:
    """Cree un ingredient (cree=True) ou corrige les valeurs d'un ingredient du site, pour le
    profil actif. Les recettes qui l'utilisent sont recalculees. Renvoie le nom retenu."""
    nom = re.sub(r"\s+", " ", str(champs.get("nom") or "")).strip()[:80]
    if len(nom) < 2:
        raise ValueError("donne un nom à l'ingrédient")
    valeurs = {}
    for m, haut in (("kcal", 900), ("prot", 100), ("gluc", 100), ("lip", 100), ("fib", 100)):
        try:
            v = float(champs.get(m))
        except (TypeError, ValueError):
            raise ValueError("remplis les calories, protéines, glucides, lipides et fibres pour 100 g")
        if not 0 <= v <= haut:
            raise ValueError(f"valeur impossible pour {m} : {v}")
        valeurs[m] = round(v, 2)
    if valeurs["prot"] + valeurs["gluc"] + valeurs["lip"] > 100.5:
        raise ValueError("protéines + glucides + lipides dépassent 100 g pour 100 g")
    with _VERROU:
        site = (_garde(_SITE / "nutriments.json").get("macros") or {})
        tout = _lire_p("ingredients_perso.json", {})
        tout = tout if isinstance(tout, dict) else {}
        source = str(champs.get("source") or "")[:300]
        if nom in site and not (tout.get(nom) or {}).get("cree"):           # correction d'un ingredient du site
            tout[nom] = {**valeurs, "source": source or "corrigé par toi", "le": time.strftime("%Y-%m-%d")}
            if isinstance(champs.get("prix"), (int, float)) and 0 < float(champs["prix"]) <= 500:
                tout[nom]["prix"] = round(float(champs["prix"]), 2)
            journal("remplacement", f"Valeurs corrigées : {nom}",
                    [f"Pour 100 g : {valeurs['kcal']} kcal, {valeurs['prot']} g de protéines, {valeurs['gluc']} g de glucides, "
                     f"{valeurs['lip']} g de lipides. Les plats qui l'utilisent sont recalculés."])
        else:
            connus = mod_perso.habitudes([x for x in donnees_site()["recettes"] if not x.get("perso")])
            if nom in connus and nom not in tout:
                raise ValueError("cet ingrédient existe déjà : corrige-le plutôt")
            u = champs.get("u") if champs.get("u") in ("g", "ml") else "g"
            try:
                q = float(champs.get("q"))
                a = int(champs.get("a", 2))
            except (TypeError, ValueError):
                raise ValueError("donne la quantité d'une portion")
            if not 1 <= q <= 2000 or not 0 <= a < len(donnees_site()["rayons"]):
                raise ValueError("portion ou rayon impossible")
            prix = champs.get("prix")
            prix = round(float(prix), 2) if isinstance(prix, (int, float)) and 0 < float(prix) <= 500 else None
            tout[nom] = {**valeurs, "cree": True, "u": u, "q": round(q, 1), "a": a, "prix": prix,
                         "source": source or "créé par toi", "le": time.strftime("%Y-%m-%d")}
            journal("remplacement", f"Ingrédient ajouté : {nom}",
                    [f"Pour 100 {u} : {valeurs['kcal']} kcal, {valeurs['prot']} g de protéines. Portion : {q:g} {u}."])
        _ecrire_p("ingredients_perso.json", tout)
        _recalculer_semaines()          # les totaux des jours et les courses suivent les nouvelles valeurs (R-11)
    return nom


def retirer_ingredient(nom: str) -> None:
    """Retire la correction (l'ingredient reprend les valeurs du site) ou l'ingredient cree,
    sauf s'il sert encore dans un de tes plats."""
    with _VERROU:
        tout = _lire_p("ingredients_perso.json", {})
        if not isinstance(tout, dict) or nom not in tout:
            raise ValueError("rien à retirer pour cet ingrédient")
        if tout[nom].get("cree") and any(i["n"] == nom for r in plats_perso() for i in r["ing"]):
            raise ValueError("il sert dans un de tes plats : supprime ou change d'abord le plat")
        del tout[nom]
        _ecrire_p("ingredients_perso.json", tout)
        _recalculer_semaines()          # R-11
        journal("remplacement", f"Valeurs du site rétablies : {nom}" if nom in (_garde(_SITE / "nutriments.json").get("macros") or {})
                else f"Ingrédient supprimé : {nom}")


def supprimer_plat_perso(ident: str) -> None:
    """Retire un plat du profil, sauf s'il est au menu d'une semaine en cours ou a venir."""
    with _VERROU:
        mois = _mois() if rythme() == "mois" else None
        plans = [_lire_p("semaine.json", None)] + (mois["semaines"] if mois else [])
