def appoint() -> list:
    """Tu declares ACHETES les produits qui manquaient encore apres tes courses (un
    plat change ou ajoute apres coup) : ils entrent au stock. Renvoie ce qui est entre."""
    with _VERROU:
        if not _achete():
            raise ValueError("déclare d'abord tes courses faites")
        recettes = donnees_site()
        plan = _lire_p("semaine.json", None)
        # La liste de la semaine seulement : le panier du mois garde ses propres boutons.
        listes = [_a_acheter(plan, recettes)[1]] if plan else []
        stock = mod_stock.charger()
        entres = []
        for l in (l for tri in listes for l in tri["a_acheter"]):
            if l["unite"] == "qs" or not l["acheter"]:
                continue
            mod_stock.ajouter(stock, l["nom"], l["acheter"], l["unite"])
            entres.append(f"{l['nom']} +{mod_stock.fmt(l['acheter'])} {l['unite']}")
        if entres:
            mod_stock.enregistrer(stock, motif="commande", detail="achat d'appoint")
            journal("commande", "Achat d'appoint : le stock est à jour", ["Entré en stock : " + ", ".join(entres) + "."])
        return entres


def remplacer(ident: str) -> dict:
    """L'utilisateur ne veut pas de ce plat cette semaine : on recompose sans lui."""
    with _VERROU:
        plan = _lire_p("semaine.json", None) or {}
        noms = {r["id"]: r["nom"] for r in donnees_site()["recettes"]}
        exclus = sorted(set(plan.get("exclus", [])) | {ident})
        journal("remplacement", f"« {noms.get(ident, ident)} » écarté à ta demande",
                ["La semaine est recomposée sans ce plat."])
        return generer(exclus)


# ------------------------------------------------------------------ actions
def noter(ident: str, note: int) -> None:
    with _VERROU:
        nom = next((r["nom"] for r in donnees_site()["recettes"] if r["id"] == ident), ident)
        plan = _lire_p("semaine.json", None)
        h = _historique()
        h["notes"].append({"plat": ident, "nom": nom, "note": int(note),
                           "date": time.strftime("%Y-%m-%d"),
                           "semaine": plan["cree_le"] if plan and ident in plan.get("choix", {}) else None})
        if h["gouts"].get(ident) == "tester":
            del h["gouts"][ident]                # goute et note : la note prend le relais
        _ecrire_historique(h)
        if plan and ident in plan.get("choix", {}):
            _inscrire(plan)                      # la note apparait aussi dans la semaine
        notes = h["notes"]
        moyenne = P.moyenne_des_notes(notes)[ident]
        journal("note", f"« {nom} » noté {note}/5",
                [f"Moyenne {moyenne[0]:g}/5 sur {moyenne[1]} note(s). "
                 + ("Il reviendra plus souvent." if moyenne[0] >= 4 else
                    "Il sera proposé moins souvent." if moyenne[0] < 3 else "")])


def gouter(ident: str, gout: str) -> None:
    """Avis donne dans le catalogue : "tester" (je veux bien tester), "non" (j'aime
    pas) ou "" (aucun avis). Il pese dans le choix des prochaines semaines."""
    if gout not in ("", *P.GOUTS):
        raise ValueError("avis inconnu")
    with _VERROU:
        r = next((r for r in donnees_site()["recettes"] if r["id"] == ident and r["cat"] in P.REPAS), None)
        if r is None:
            raise ValueError("recette inconnue")
        h = _historique()
        if h["gouts"].get(ident, "") == gout:
            return
        if gout:
            h["gouts"][ident] = gout
        else:
            del h["gouts"][ident]
        _ecrire_historique(h)
        poids = _profil().ponderation()["criteres"]
        journal("gout", f"« {r['nom']} » : " + {"tester": "tu veux bien le tester", "non": "tu n'aimes pas",
                                                "": "avis retiré"}[gout],
                [f"+{poids['envie']:g} points au prochain choix de plats." if gout == "tester" else
                 f"−{poids['pas_aime']:g} points au prochain choix de plats." if gout == "non" else
                 "Il est de nouveau choisi comme les autres."])


def prochaine_seance(plan: dict | None, ident: str) -> tuple | None:
    """(numero du jour, seance) de la prochaine fois ou cette recette se cuisine."""
    faits = (plan or {}).get("prepares", {})
    return next(((n, s) for n, j in enumerate((plan or {}).get("jours", []))
                 for s in j.get("cuisine", []) if s["id"] == ident and f"{n}|{ident}" not in faits), None)


def preparer(jour: int, ident: str | None = None) -> None:
    """Tu declares CUISINE (ou mange) ce qui etait prevu tel jour : c'est le seul
    moment ou des produits sortent du stock. `ident` = une seule recette du jour ;
    sans lui, toute la journee."""
    with _VERROU:
        plan = _lire_p("semaine.json", None)
        if not plan or not 0 <= int(jour) < len(plan["jours"]):
            return
        jour = int(jour)
        faits = plan.setdefault("prepares", {})
        seances = [s for s in plan["jours"][jour].get("cuisine", [])
                   if (ident is None or s["id"] == ident) and f"{jour}|{s['id']}" not in faits]
        if not seances:
            return
        par_id = {r["id"]: r for r in donnees_site()["recettes"]}
        stock = mod_stock.charger()
        manquants, sortis, noms = [], [], []
        for seance in seances:
            recette = P.recette_du_jour(par_id[seance["id"]], plan["jours"][jour])
            noms.append(recette["nom"])
            for ing in recette["ing"]:
                if ing["u"] == "qs":
                    continue
                besoin = pdf.Ingredient(ing["n"], round(ing["q"] * seance["portions"], 2), ing["u"])
                dispo = mod_stock.disponible(stock, besoin)
                mod_stock.retirer(stock, besoin)
                texte = f"{ing['n']} {mod_stock.fmt(besoin.quantite)} {ing['u']}"
                (sortis if dispo >= besoin.quantite - 0.01 else manquants).append(texte)
            faits[f"{jour}|{seance['id']}"] = time.strftime("%Y-%m-%dT%H:%M:%S")
        nom_jour = plan["jours"][jour]["jour"]
        mod_stock.enregistrer(stock, motif="preparation",
                              detail=noms[0] if len(noms) == 1 else f"{nom_jour} ({len(noms)} recettes)")
        if all(f"{n}|{s['id']}" in faits for n, j in enumerate(plan["jours"]) for s in j.get("cuisine", [])):
            plan["etat"] = "terminee"
        _enregistrer_semaine(plan)
        details = ["Cuisiné : " + " ; ".join(
                       f"{par_id[s['id']]['nom']} ({mod_stock.fmt(s['portions'])} portion(s))"
                       for s in seances) + ".",
                   "Sorti du stock : " + (", ".join(sortis) or "rien") + "."]
        if manquants:
            details.append("Pas (ou pas assez) en stock, donc rien retiré de plus : "
                           + ", ".join(manquants) + ".")
        journal("preparation", f"{nom_jour} : " + (f"« {noms[0]} » cuisiné" if len(noms) == 1
                                                    else "journée cuisinée"), details)


# ------------------------------------------------------------------ couts reels
def _total_panier() -> dict | None:
    """Ce que Jarvis a mis au panier et pas encore paye : total et nombre d'articles."""
    mis = _lire("dans_les_paniers.json", None)
    if not mis:
        return None
    return {"total": round(sum(a["paquets"] * a["offre"]["prix"] for a in mis.values()), 2),
            "articles": len(mis),
            "enseignes": sorted({a["enseigne"] for a in mis.values()})}


def _a_payer(tri: dict, tarifs) -> dict:
    """Estimation de ce qui reste a payer : courses au prix releve (au gramme, pas
    au paquet entier, donc plutot un plancher) et viande du boucher (prix estimes)."""
    def cout(nom, q, u, normal=False):
        if u == "qs" or not q:
            return 0.0
        ing = {"n": nom, "q": q, "u": u}
        return tarifs.estime(ing) if normal else tarifs.cout(ing)[0]
    return {"supermarche": round(sum(cout(l["nom"], l["acheter"], l["unite"]) for l in tri["a_acheter"]), 2),
            "boucher": round(sum(cout(l["nom"], l["quantite"], l["unite"], True) for l in tri["boucher"]), 2)}


def _montant(valeur) -> float | None:
    if valeur in (None, ""):
        return None
    montant = round(float(valeur), 2)
    if not 0 <= montant <= 5000:
        raise ValueError("montant entre 0 et 5 000 euros")
    return montant


def paye_reel(paye: dict | None) -> float | None:
    """Total reellement paye pour une semaine : supermarche + boucher (le montant
    saisi, sinon l'estimation de la viande). None tant que rien n'est paye."""
    if not paye or paye.get("supermarche") is None:
        return None
    boucher = paye.get("boucher")
    return round(paye["supermarche"] + (boucher if boucher is not None else paye.get("boucher_estime") or 0), 2)


def _paye_du_mois() -> dict:
    mois = time.strftime("%Y-%m")
    semaines = [s for s in _historique()["semaines"] if (s.get("paye") or {}).get("date", "")[:7] == mois]
    totaux = [paye_reel(s["paye"]) for s in semaines]
    totaux += [c.get("montant") for c in _historique().get("commandes", [])
               if str(c.get("date", ""))[:7] == mois]
    return {"paye": round(sum(t for t in totaux if t is not None), 2),
            "commandes": sum(1 for t in totaux if t is not None)}


def valeur_du_stock(tarifs, avant: str = "") -> dict:
    """Valeur du stock au prix de chaque produit (prix releve, sinon estimation).
    `avant` = date ISO : le stock tel qu'il etait juste avant cette date, retrouve en
    rejouant mouvements.csv. Sans `avant` : le stock d'aujourd'hui."""
    if avant:
        quantites = {}
        for l in mod_stock._mouvements():
            if l[0] < avant:
                cle = (l[1], l[2])
                quantites[cle] = quantites.get(cle, 0.0) + mod_stock._nombre(l[3])
        lignes = [(nom, q, u) for (nom, u), q in quantites.items() if q > 0.001]
    else:
        lignes = [(i.nom, i.quantite, i.unite) for i in mod_stock.charger().values()]
    total, sans_prix = 0.0, 0
    for nom, q, u in lignes:
        valeur = tarifs.normal({"n": nom, "q": q, "u": u})
        total += valeur
        sans_prix += valeur <= 0
    return {"valeur": round(total, 2), "produits": len(lignes), "sans_prix": sans_prix}


def budget_du_mois(tarifs, budget: float, recettes: list) -> dict:
    """Ou en est le budget du mois, stock compris.

    Le budget couvre ce qu'on mange dans le mois : ce qui etait deja en stock au
    1er du mois compte dedans. Il reste donc a depenser :
        budget - valeur du stock au debut du mois - deja paye ce mois-ci
    Exemple : 300 € de budget, 50 € de courses restees en stock -> 250 € a acheter."""
    mois = time.strftime("%Y-%m")
    debut = valeur_du_stock(tarifs, avant=f"{mois}-01")
    paye = _paye_du_mois()
    par_id = {r["id"]: r for r in recettes}
    consomme = sum(p["portions"] * tarifs.recette(par_id[p["id"]])[0]
                   for s in _historique()["semaines"] for p in s.get("plats", [])
                   if (p.get("prepare_le") or "")[:7] == mois and p["id"] in par_id)
    return {"mois": mois, "budget": budget, "stock_debut": debut["valeur"],
            "paye": paye["paye"], "commandes": paye["commandes"],
            "reste": round(budget - debut["valeur"] - paye["paye"], 2),
            "consomme": round(consomme, 2), "stock": valeur_du_stock(tarifs)}


def corriger_paye(supermarche=None, boucher=None) -> None:
    """Corrige les montants reellement payes de la semaine en cours."""
    with _VERROU:
        plan = _lire_p("semaine.json", None)
        if not plan or not plan.get("paye"):
            raise ValueError("aucune commande payee a corriger")
        plan["paye"]["supermarche"] = _montant(supermarche)
        plan["paye"]["boucher"] = _montant(boucher)
        _enregistrer_semaine(plan)
        total = paye_reel(plan["paye"])
        journal("commande", "Montants payés corrigés",
                [f"Total de la semaine : {total:.2f} €." if total is not None
                 else "Montant du supermarché non renseigné."])


def commande_passee(supermarche=None, boucher=None) -> None:
    """Tu declares la commande PAYEE : c'est le seul moment ou des produits entrent
    au stock. Entre ce que Jarvis a mis au panier ; s'il n'a rien rempli (courses
    faites toi-meme), la liste a acheter de la semaine en cours.

    `supermarche` et `boucher` = montants reellement payes, si tu les donnes ; a
    defaut, le total du panier rempli par Jarvis sert de montant du supermarche."""
    with _VERROU:
        supermarche, boucher = _montant(supermarche), _montant(boucher)
        plan = _lire_p("semaine.json", None)
        panier = _total_panier()
        estime = None
        if plan:
            recettes = donnees_site()
            lecture, tri = _a_acheter(plan, recettes)
            estime = _a_payer(tri, _contexte(recettes)["tarifs"])     # avant que le stock ne bouge
            if panier is None:
                cli._ecrire("site Mon Meal Prep", lecture, tri)
        avant = {k: v.quantite for k, v in mod_stock.charger().items()}
        sortie = io.StringIO()
        with contextlib.redirect_stdout(sortie):
            cli.commande_achete()
        apres = mod_stock.charger()
        entres = [f"{i.nom} +{mod_stock.fmt(i.quantite - avant.get(k, 0))} {i.unite}"
                  for k, i in sorted(apres.items()) if i.quantite - avant.get(k, 0) > 0.001]
        plan = _lire_p("semaine.json", None)
        lignes = []
        if plan:
            plan["etat"] = "commandee"
            plan["paye"] = {
                "date": time.strftime("%Y-%m-%dT%H:%M:%S"),
                "supermarche": supermarche if supermarche is not None else (panier or {}).get("total"),
                "supermarche_estime": (estime or {}).get("supermarche"),
                "boucher": boucher, "boucher_estime": (estime or {}).get("boucher")}
            _enregistrer_semaine(plan)
            total = paye_reel(plan["paye"])
            if total is not None:
                lignes.append(f"Payé : {plan['paye']['supermarche']:.2f} € au supermarché, "
                              + (f"{boucher:.2f} € chez le boucher." if boucher is not None
                                 else f"environ {plan['paye']['boucher_estime'] or 0:.2f} € chez le boucher (estimation)."))
            else:
                lignes.append("Montant payé non renseigné : indique-le dans l'onglet Courses pour suivre ton budget.")
        journal("commande", "Commande passée : le stock est à jour",
                lignes + [sortie.getvalue().strip() or "Stock mis à jour."]
                + (["Entré en stock : " + ", ".join(entres) + "."] if entres else []))


def _epices_en_stock(tri: dict) -> None:
    """Herbes et epices « au gout » (sans quantite) : un pot entre au stock, pour
    qu'elles ne restent pas a acheter une fois les courses faites."""
    stock = mod_stock.charger()
    ajoutes = [l["nom"] for l in tri["a_acheter"] if l["unite"] == "qs"]
    for nom in ajoutes:
        mod_stock.ajouter(stock, nom, 1, "pièce")
    if ajoutes:
        mod_stock.enregistrer(stock, motif="commande", detail="herbes et epices")


def commande_du_mois_payee(montant=None) -> None:
    """Tu declares PAYEE la commande du supermarche (rythme du mois) : le panier
    rempli par Jarvis entre au stock ; s'il n'a rien rempli, la liste du mois."""
    with _VERROU:
        montant = _montant(montant)
        recettes = donnees_site()
        mois = _mois()
        liste = _liste_du_mois(recettes)
        if not mois or liste is None:
            raise ValueError("aucun mois compose")
        panier = _total_panier()
        if panier is None:
            cli._ecrire("panier du supermarche", *liste)
        avant = {k: v.quantite for k, v in mod_stock.charger().items()}
        with contextlib.redirect_stdout(io.StringIO()):
            cli.commande_achete()
        if panier is None:
            _epices_en_stock(liste[1])
        apres = mod_stock.charger()
        entres = [f"{i.nom} +{mod_stock.fmt(i.quantite - avant.get(k, 0))} {i.unite}"
                  for k, i in sorted(apres.items()) if i.quantite - avant.get(k, 0) > 0.001]
        if montant is None and panier:
            montant = panier["total"]
        mois["commande"] = {"date": time.strftime("%Y-%m-%dT%H:%M:%S"), "montant": montant,
                            "articles": len(entres)}
        mois["panier"] = None
        _ecrire_p("mois.json", mois)
        h = _historique()
        h.setdefault("commandes", []).append({**mois["commande"], "quoi": "panier du supermarché"})
        _ecrire_historique(h)
        journal("commande", "Panier du supermarché payé : le stock est à jour",
                [(f"Payé : {montant:.2f} €." if montant is not None
                  else "Montant non renseigné : il manquera au suivi du budget."),
                 "Entré en stock : " + (", ".join(entres) or "rien") + "."])


def courses_de_la_semaine_faites(supermarche=None, boucher=None) -> None:
    """Tu declares FAITES les courses de la semaine (rythme du mois) : la liste de
    la semaine entre au stock. La viande du boucher n'est pas suivie dans le stock."""
    with _VERROU:
        supermarche, boucher = _montant(supermarche), _montant(boucher)
        plan = _lire_p("semaine.json", None)
        if not plan:
            raise ValueError("aucune semaine")
        recettes = donnees_site()
        _, tri = _a_acheter(plan, recettes)
        estime = _a_payer(tri, _contexte(recettes)["tarifs"])
        stock = mod_stock.charger()
        entres = []
        for l in tri["a_acheter"]:
            if l["unite"] != "qs" and l["acheter"]:
                mod_stock.ajouter(stock, l["nom"], l["acheter"], l["unite"])
                entres.append(f"{l['nom']} +{mod_stock.fmt(l['acheter'])} {l['unite']}")
        mod_stock.enregistrer(stock, motif="commande", detail="marché de la semaine")
        _epices_en_stock(tri)
        plan["etat"] = "commandee"
        plan["paye"] = {"date": time.strftime("%Y-%m-%dT%H:%M:%S"), "supermarche": supermarche,
                        "supermarche_estime": estime["supermarche"],
                        "boucher": boucher, "boucher_estime": estime["boucher"]}
        _enregistrer_semaine(plan)
        total = paye_reel(plan["paye"])
        journal("commande", "Marché de la semaine fait : le stock est à jour",
                [(f"Payé : {total:.2f} €, viande comprise." if total is not None
                  else "Montant payé non renseigné : indique-le pour suivre ton budget."),
                 "Entré en stock : " + (", ".join(entres) or "rien") + "."])


def _tache_panier(enseignes: list, profil: str = "") -> None:
    """Fil a part : Jarvis releve les prix puis remplit le panier, et raconte."""
    dire = _dire
    code = 0
    mod_profil.choisir(profil)                      # ce fil travaille pour ce profil
    try:
        _ecrire("alternatives.json", {})            # celles du panier precedent ne valent plus
        recettes = donnees_site()
        plan = _lire_p("semaine.json", None)
        lecture, tri = _liste_du_mois(recettes) or _a_acheter(plan, recettes)
        # Semaine pauvre en FODMAP : l'etiquette de chaque produit est lue aussi pour l'ail,
        # l'oignon, le fructose, les polyols… en plus des interdits halal du profil.
        mois = _mois() if rythme() == "mois" else None
        plans = [plan] + (mois["semaines"][mois["rang"] + 1:] if mois else [])
        fodmap = any("fodmap" in (p.get("modes") or []) for p in plans if p)
        cli._ecrire("site Mon Meal Prep", lecture, tri, base.FODMAP_COMPOSITION if fodmap else ())
        dire(f"Liste envoyée à Jarvis : {len(tri['a_acheter'])} articles à acheter, "
             f"{len(tri['en_stock'])} déjà en stock, {len(tri['boucher'])} chez le boucher.")
        dire("Composition refusée : " + ", ".join(cli.interdits()) + "."
             + (" Régime pauvre en FODMAP : aussi " + ", ".join(base.FODMAP_COMPOSITION[::2][:6]) + ", polyols." if fodmap else ""))
        for commande in (["--repas-prix", *enseignes, "--refaire"], ["--repas-panier"]):   # toujours un releve frais
            code = _jarvis(commande, profil, dire)
            if code:
                dire(f"(arrêt, code {code})")
                break
        _raconter_panier(tri, code)
        if not code:                                # ce qui manque : de quoi le remplacer, chez la meme enseigne
            _chercher_alternatives(profil)
    except Exception as e:                          # la tache ne doit jamais rester « en cours »
        dire(f"ERREUR : {e}")
        journal("panier", "Panier : échec", [str(e)])
    finally:
        with _VERROU:
            _TACHE.update(etat="fini", fin=time.strftime("%Y-%m-%dT%H:%M:%S"))


def _raconter_panier(tri: dict, code: int) -> None:
    d = mod_stock.dossier()
    panier = _lire("panier.json", {}).get("choisi") or {}
    mis = _lire("dans_les_paniers.json", {})
    details = [f"À acheter : {len(tri['a_acheter'])} articles. Déjà en stock, donc non achetés : "
               + (", ".join(l["nom"] for l in tri["en_stock"]) or "aucun") + ".",
               "Chez le boucher halal, hors panier : "
               + (", ".join(l["nom"] for l in tri["boucher"]) or "rien") + "."]
    if panier:
        details.append(f"Panier retenu : {panier['total']:.2f} € chez "
                       + " + ".join(panier["enseignes"]) + " (hors frais de livraison).")
    par_enseigne = {}
    for nom, a in mis.items():
        par_enseigne.setdefault(a["enseigne"], []).append(
            f"{a['paquets']} × {a['offre']['nom']} ({a['offre']['prix']:.2f} €)")
    for enseigne, lignes in par_enseigne.items():
        details.append(f"Mis au panier {enseigne} ({len(lignes)} articles) : " + " ; ".join(lignes) + ".")
    for fichier in sorted(d.glob("prix_*.json")):
        releve = _lire(fichier.name, {})
        absents = [a["nom"] for a in releve.get("articles", {}).values() if not a.get("trouve")]
        refuses = [r for a in releve.get("articles", {}).values() for r in a.get("refuses", [])]
        if absents and releve.get("enseigne") == _enseignes()[0]:
            details.append(f"Pas dans le panier, à acheter toi-même ({releve.get('enseigne')}) : "
                           + ", ".join(absents) + ".")
        non_lus = [a["nom"] for a in releve.get("articles", {}).values() if a.get("composition_non_lue")]
        if non_lus:
            details.append("Composition non lue sur le site, à vérifier toi-même sur l'étiquette (alcool, "
                           "gélatine, E471) : " + ", ".join(non_lus) + ".")
        bio = [a["nom"] for a in releve.get("articles", {}).values() if "faute d'autre choix" in a.get("note", "")]
        if bio:
            details.append("Pris en bio faute de version classique dans les résultats : " + ", ".join(bio) + ".")
        if refuses:
            details.append("Refusés à cause de leur composition : " + " ; ".join(refuses) + ".")
    details.append("Rien n'est payé : choisis ton mode de livraison et valide sur le site de "
                   "l'enseigne, puis clique « Commande passée ».")
    journal("panier", "Panier rempli : voici ce que j'ai fait" if not code and mis
            else "Panier : je n'ai pas pu tout faire", details)
    plan = _lire_p("semaine.json", None)
    mois = _mois() if rythme() == "mois" else None
    if mois and mis:                               # le panier est celui de la commande du mois
        mois["panier"] = _total_panier()
        _ecrire_p("mois.json", mois)
    elif plan and mis:
        plan["etat"] = "panier"
        plan["panier"] = _total_panier()
        _enregistrer_semaine(plan)


def _devalider() -> bool:
    """Le menu a change apres sa validation : il redevient « a valider », pour que le panier
    soit refait sur le menu final. Renvoie vrai s'il etait valide. (Appele sous _VERROU.)"""
    mois = _mois() if rythme() == "mois" else None
    if mois:
        if not mois.get("valide"):
            return False
        mois["valide"] = None
        _ecrire_p("mois.json", mois)
        return True
    plan = _lire_p("semaine.json", None)
    if not plan or not plan.get("valide"):
        return False
    plan["valide"] = None
    _ecrire_p("semaine.json", plan)
    return True


def est_valide() -> bool:
    """Les semaines composees sont-elles validees par l'utilisateur ? Jarvis ne
    remplit aucun panier avant."""
    mois = _mois() if rythme() == "mois" else None
    plan = _lire_p("semaine.json", None) or {}
    return bool(mois.get("valide") if mois else plan.get("valide"))


def valider() -> bool:
    """Tu valides les semaines composees : le menu est arrete. Le panier ne se remplit
    pas pour autant : c'est « Passer la commande », dans Courses, qui le lance."""
    with _VERROU:
        plan = _lire_p("semaine.json", None)
        if not plan:
            raise ValueError("aucune semaine a valider")
        maintenant = time.strftime("%Y-%m-%dT%H:%M:%S")
        mois = _mois() if rythme() == "mois" else None
        if mois:
            mois["valide"] = maintenant
            _ecrire_p("mois.json", mois)
        else:
            plan["valide"] = maintenant
            _ecrire_p("semaine.json", plan)
        journal("selection", "Semaines validées" if mois else "Semaine validée",
                ["Tu as validé le menu. Quand la liste de Courses te convient, clique sur « Passer la commande » : "
                 "Jarvis remplira alors ton panier, sans payer."])
    return True


def lancer_panier() -> bool:
    with _VERROU:
        if _TACHE["etat"] == "en cours" or not _lire_p("semaine.json", None) or not est_valide():
            return False
        principale, autres = _enseignes()
        nom = _profil().nom
        _TACHE.update(etat="en cours", titre="Jarvis remplit le panier", lignes=[], profil=nom,
                      debut=time.strftime("%Y-%m-%dT%H:%M:%S"), fin=None)
    threading.Thread(target=_tache_panier, args=([principale, *autres], nom), daemon=True).start()
    return True


def _enseignes() -> tuple:
    profil = _profil()
    principale = str(profil.valeur("courses.enseigne_principale")
                     or reglage("repas.enseigne_principale", "Auchan") or "Auchan")
    autres = profil.valeur("courses.enseignes_catalogue")
    if not isinstance(autres, list):
        autres = reglage("repas.enseignes_catalogue", ["Leclerc"]) or []
    seule = int(profil.valeur("courses.max_enseignes") or reglage("repas.max_enseignes", 2) or 2) <= 1
    # Une seule enseigne : inutile d'ouvrir les autres pour lire leurs promotions.
    return principale, [] if seule else [e for e in autres if e != principale]


# ------------------------------------------------------------------ avancement
def avancement(recettes: dict, tarifs, table: dict, kcal: float, prot: float, phase: dict | None = None) -> dict:
    """Ce qui a reellement ete cuisine (donc mange), par jour, semaine et mois.
    Source : les « c'est cuisine » de l'historique. La seconde part d'un diner
    cuisine en double compte pour le lendemain, ou elle est mangee."""
    import datetime
    par_id = {x["id"]: x for x in recettes["recettes"]}
    jours = {}

    # Les assiettes de chaque jour telles que l'écran Jour les montre (quantités réglées ce jour-là comprises) :
    # un plat cuisiné compte pour CES assiettes, pas pour la recette de base ni la copie gardée au moment de le
    # cuisiner (Taha, 19/11/2026 : « un dépassement dans la courbe alors que j'ai pas dépassé »).
    assiettes = {}
    for plan in [_lire_p("semaine.json", None)] + list((_mois() or {}).get("semaines") or []) + list(_historique()["semaines"]):
        debut = _debut(plan) if plan else None
        for n, jj in enumerate((plan or {}).get("jours", []) if debut else []):
            d = (debut + datetime.timedelta(days=n)).isoformat()
            if d not in assiettes and jj.get("repas"):
                assiettes[d] = jj["repas"]

    def ajouter(date, ident, portions, jour=None):
        vues = [r for r in assiettes.get(date, []) if r["id"] == ident]
        if vues:
            j = jours.setdefault(date, {"kcal": 0.0, "prot": 0.0, "gluc": 0.0, "lip": 0.0, "fib": 0.0, "cout": 0.0,
                                        "vitamines": dict.fromkeys(P.VITAMINES, 0.0)})
            tailles = sum(r.get("taille", 1) for r in vues)
            for m in ("kcal", "prot", "gluc", "lip", "fib"):
                j[m] += sum(float(r.get(m) or 0) for r in vues)
            j["cout"] += tarifs.recette(par_id[ident])[0] * tailles
            for v, q in P.vitamines(P.recette_du_jour(par_id[ident], jour or {}, table), table).items():
                j["vitamines"][v] += q * tailles
            return
        x = P.recette_du_jour(par_id[ident], jour, table) if jour else par_id[ident]
        j = jours.setdefault(date, {"kcal": 0.0, "prot": 0.0, "gluc": 0.0, "lip": 0.0, "fib": 0.0, "cout": 0.0,
                                    "vitamines": dict.fromkeys(P.VITAMINES, 0.0)})
        j["kcal"] += x["kcal"] * portions
        j["prot"] += x["prot"] * portions
        j["gluc"] += x.get("gluc", 0) * portions
        j["lip"] += x.get("lip", 0) * portions
        j["fib"] += x.get("fib", 0) * portions
        j["cout"] += tarifs.recette(x)[0] * portions
        for v, q in P.vitamines(x, table).items():
            j["vitamines"][v] += q * portions

    for semaine in _historique()["semaines"]:
        js = semaine.get("jours", [])
        for n, j in enumerate(js):
            for c in j.get("cuisine") or []:
                if not c.get("fait_le") or c["id"] not in par_id:
                    continue
                date = c["fait_le"][:10]
                suivant = js[n + 1] if n + 1 < len(js) else None
                reste = c["portions"] - j.get("facteur", 1)
                if c["quand"] == "soir" and suivant and suivant.get("dej_reste") and reste > 0.01:
                    ajouter(date, c["id"], j.get("facteur", 1), j)
                    lendemain = datetime.date.fromisoformat(date) + datetime.timedelta(days=1)
                    ajouter(lendemain.isoformat(), c["id"], reste, j)
                else:
                    ajouter(date, c["id"], c["portions"], j)

    # Mode flemmard : ce qui a été noté en plus s'ajoute aux plats cuisinés (Taha, 19/11/2026).
    notes = {}
    for e in repas_notes():
        notes.setdefault(e["date"], []).append(e)
    for date, entrees in notes.items():
        j = jours.setdefault(date, {"kcal": 0.0, "prot": 0.0, "gluc": 0.0, "lip": 0.0, "fib": 0.0, "cout": 0.0,
                                    "vitamines": dict.fromkeys(P.VITAMINES, 0.0)})
        for m in ("kcal", "prot", "gluc", "lip", "fib"):
            j[m] += float(sum(float(e.get(m) or 0) for e in entrees))

    aujourdhui = datetime.date.today()
    debut_suivi = str(_lire_p("reglages_site.json", {}).get("date_debut") or "")
    lundi = _debut(_lire_p("semaine.json", None)) or aujourdhui - datetime.timedelta(days=aujourdhui.weekday())
    if not lundi <= aujourdhui < lundi + datetime.timedelta(days=7):       # semaine pas commencee ou finie
        lundi = aujourdhui - datetime.timedelta(days=aujourdhui.weekday())

    def periode(dates, jour_en_cours=True):
        # La semaine et le mois ne comptent que les journées finies : la journée en cours ferait baisser
        # les moyennes pour rien tant qu'elle n'est pas terminée (Taha, 19/11/2026).
        # Rien avant la date de début choisie dans Réglages (Taha, 19/11/2026 : « la semaine démarre le 13, j'ai mis le 16 »).
        fini = lambda d: (jour_en_cours or d < aujourdhui.isoformat()) and (not debut_suivi or d >= debut_suivi)
        suivis = [d for d in dates if d in jours and d <= aujourdhui.isoformat() and fini(d)]
        n = len(suivis) or 1
        somme = lambda cle: sum(jours[d][cle] for d in suivis)
        return {"jours_suivis": len(suivis), "jours": len([d for d in dates if fini(d)]) or len(dates),
                "kcal": round(somme("kcal") / n), "prot": round(somme("prot") / n),
                "gluc": round(somme("gluc") / n), "lip": round(somme("lip") / n), "fib": round(somme("fib") / n),
                "cout": round(somme("cout"), 2),
                "vitamines": {v: round(sum(jours[d]["vitamines"][v] for d in suivis) / n, 2)
                              for v in P.VITAMINES},
                "detail": [{"date": d, "kcal": round(jours[d]["kcal"]) if d in suivis else None}
                           for d in dates]}
    semaine = [(lundi + datetime.timedelta(days=k)).isoformat() for k in range(7)]
    premier = aujourdhui.replace(day=1)
    mois = [(premier + datetime.timedelta(days=k)).isoformat() for k in range(31)
            if (premier + datetime.timedelta(days=k)).month == aujourdhui.month]
    return {"objectif": {"kcal": kcal, "prot": prot, "gluc": (phase or {}).get("glucides"),
                         "lip": (phase or {}).get("lipides"), "fib": 30}, "aujourdhui": aujourdhui.isoformat(),
            "jour": periode([aujourdhui.isoformat()]), "semaine": periode(semaine, False),
            "mois": periode(mois, False)}


