def _mettre_a_niveau() -> None:
    """Une semaine composee avant le 14/11/2026 n'a pas les chiffres par repas (jour["repas"], seance["repas"]) :
    on la recalcule une fois, comme apres n'importe quel changement. Ni les plats ni la taille des assiettes
    ne changent. (Sous _VERROU.)"""
    plan = _lire_p("semaine.json", None)
    mois = _mois() if rythme() == "mois" else None
    semaines = [plan] + (mois["semaines"] if mois else [])
    if any(p and any("cuisine" in j and "repas" not in j for j in p.get("jours", [])) for p in semaines):
        _recalculer_semaines()


def _avancer_si_flemmard() -> None:
    """Mode flemmard : pas de bouton « semaine suivante » à toucher ; quand la semaine en cours est finie,
    on passe à la suivante déjà composée (jamais de nouvelle composition ici). (Sous _VERROU.)"""
    import datetime
    if not mode_suivi() or rythme() != "mois":
        return
    for _ in range(4):
        mois, plan = _mois(), _lire_p("semaine.json", None)
        debut = _debut(plan)
        if not mois or not debut or mois["rang"] + 1 >= len(mois["semaines"]) \
                or datetime.date.today() < debut + datetime.timedelta(days=7):
            return
        semaine_suivante()


def etat() -> dict:
    with _VERROU:
        _mettre_a_niveau()
        _avancer_si_flemmard()
        recettes, reglages = donnees_site(), _reglages()
        ctx = _contexte(recettes)
        phase = _phase(reglages)
        table = ctx["nutriments"]
        version, base = _fiches(recettes, ctx)
        fiches = []
        for r in base:
            note = ctx["notes"].get(r["id"])
            fiches.append({**r, "gout": ctx["gouts"].get(r["id"]),
                           "note": note[0] if note else None, "nb_notes": note[1] if note else 0})
        plan = _lire_p("semaine.json", None)
        courses = None
        couts = None
        profil = _profil()
        if plan and not all("cuisine" in j for j in plan.get("jours", [])):
            plan = None            # semaine d'avant la cuisine jour par jour : a recomposer
        if plan:
            _, tri = _a_acheter(plan, recettes)
            courses = tri
            paye = plan.get("paye")
            couts = {
                "repas": plan["cout"],                       # valeur de ce qui est mange cette semaine
                "par_jour": round(plan["cout"] / 7, 2),
                "a_payer": None if paye else _a_payer(tri, ctx["tarifs"]),
                "panier": None if paye else (_total_panier() or plan.get("panier")),
                "paye": paye, "paye_total": paye_reel(paye),
                "jours": [{"jour": j["jour"], "cout": j["cout"]} for j in plan["jours"]],
            }
        offres = _lire("offres.json", {})
        mois, courses_mois = None, None
        if rythme() == "mois":
            m = _mois()
            if m and plan:
                _, tri_mois = _liste_du_mois(recettes)
                panier = _total_panier()
                courses_mois = {**tri_mois, "estimation": _a_payer(tri_mois, ctx["tarifs"])["supermarche"],
                                "panier": panier, "commande": m.get("commande")}
                courses_mois["fruits_secs"] = fruits_secs(recettes)
                courses_mois["hors_panier"] = manquants(tri_mois, recettes) if panier else []
                courses_mois["remplacements"] = remplacements()
                # Le marche des semaines suivantes, pour le voir d'avance (il s'achete semaine par semaine).
                courses_mois["marches_suivants"] = [
                    {"rang": k, "debut": p.get("debut"), **{cle: _besoins_tries([p], recettes, "marche", restants=True)[1][cle]
                                                           for cle in ("a_acheter", "boucher", "coches")}}
                    for k, p in enumerate(m["semaines"]) if k > m["rang"] and all("cuisine" in j for j in p.get("jours", []))]
                mois = {"rang": m["rang"], "nb": len(m["semaines"]), "cree_le": m["cree_le"],
                        "semaines": [plan if k == m["rang"] else p for k, p in enumerate(m["semaines"])]}
                if couts and not plan.get("paye"):
                    couts["panier"] = None          # le panier est celui du mois, pas de la semaine
        # Les plats que le bouton « Rééquilibrer » peut régler, jour par jour (rien n'est écrit).
        par_id_reg = {x["id"]: x for x in recettes["recettes"]}
        for p in ([plan] if plan else []) + (list(mois["semaines"]) if mois else []):
            for n, jour in enumerate(p.get("jours", [])):
                jour["reglables_seul"] = sorted({i for _, i in P.moments(jour)
                                                 if P.reglable_seul(p, n, i, par_id_reg, table)})
        return {
            "valide": est_valide(), "rythme": rythme(), "nb_semaines": nb_semaines(), "mois": mois, "courses_mois": courses_mois,
            "recettes": fiches, "rayons": recettes["rayons"], "recettes_version": version,
            "ingredients_perso": {n: {"cree": bool(v.get("cree"))} for n, v in ingredients_perso().items()},
            "stock_couvre": _stock_couvre(recettes["recettes"], ctx["stock"]),
            "alertes": alertes(),
            "phases": _phases(), "phases_perso": bool(_lire_p("reglages_site.json", {}).get("phases")),
            "phase": phase, "reglages": reglages,
            "profil": {"nom": profil.valeur("identite.nom", profil.nom), "id": profil.nom,
                       "dossier": str(profil.dossier), "identite": profil.valeur("identite", {}),
                       "programme": profil.valeur("programme.nom", ""),
                       "preferences": profil.preferences, "calcule": profil.calcule,
                       "boucher": bool(profil.valeur("alimentation.boucher")),
                       "chrome": navigateur.chrome_propre(profil)},
            "vitamines": {"noms": table.get("vitamines", {}),
                          "besoins": profil.besoins_vitamines(
                              phase["kcal"] + int(reglages.get("ajustement") or 0))},
            "modes": [{"id": m, "nom": P.NOMS_MODES[m], "a_venir": SEUL_FLEMMARD and m in ("moins_cher", "plus_varie"),
                       "impose": SEUL_FLEMMARD and m == "flemmard"} for m in P.MODES_DEFAUT],
            "avancement": avancement(recettes, ctx["tarifs"], table,
                                     phase["kcal"] + int(reglages.get("ajustement") or 0), phase["prot"], phase),
            "semaine": plan, "courses": courses, "couts": couts,
            "budget": budget_du_mois(ctx["tarifs"], reglages["budget_mois"], recettes["recettes"]),
            "stock": [{"nom": i.nom, "quantite": i.quantite, "unite": i.unite}
                      for i in sorted(mod_stock.charger().values(),
                                      key=lambda i: pdf.normaliser(i.nom))],
            "journal": _lire_p("journal.json", [])[:80],
            "suivi": suivi(),
            "fixes": _fixes(),
            "eau": {**eau_du_jour(), "bu": {d: eau_bue(d) for d in (time.strftime("%Y-%m-%d"),)}},
            "journal_repas": journal_des_jours(recettes, ctx={**ctx, "phase": phase}) if mode_suivi() else journal_des_jours(recettes),
            "tache": ({**_TACHE, "lignes": _TACHE["lignes"][-60:]} if _TACHE["profil"] in ("", profil.nom)
                      else {"etat": "occupe" if _TACHE["etat"] == "en cours" else "repos",
                            "titre": "", "lignes": [], "debut": None, "fin": None, "profil": ""}),
            "offres": {"genere_le": offres.get("genere_le"),
                       "catalogues": offres.get("catalogues", {}),
                       "promos": sorted(offres.get("promos", {}))},
            "magasin": {"principale": _enseignes()[0],
                        "adresse": str(profil.valeur("courses.adresse")
                                       or reglage("repas.adresse", "") or "")},
        }


