def exporter(quoi: str) -> tuple:
    """(nom du fichier, page HTML) du compte rendu demande : « semaine » (le menu, plat par plat),
    « courses » (les listes a cocher) ou « cuisine » (les fiches, jour par jour). Toutes les
    semaines composees, de la semaine en cours a la derniere."""
    e = etat()
    plan = e.get("semaine")
    if not plan:
        raise ValueError("aucune semaine composée")
    mois = e.get("mois")
    rang = mois["rang"] if mois else 0
    plans = mois["semaines"][rang:] if mois else [plan]
    recettes = donnees_site()
    par_id = {r["id"]: r for r in recettes["recettes"]}
    profil = _profil()
    ctx = mod_export.Contexte(profil.valeur("identite.nom", profil.nom), plans, rang, par_id, nutriments(), photo,
                              e["magasin"]["principale"], e)
    if quoi == "semaine":
        page = mod_export.menu(ctx)
    elif quoi == "courses":
        page = mod_export.courses(ctx, recettes["rayons"], {i["n"]: i["a"] for r in recettes["recettes"] for i in r["ing"]})
    elif quoi == "cuisine":
        page = mod_export.cuisine(ctx)
    else:
        raise ValueError("compte rendu inconnu")
    debut = (plans[0].get("debut") or time.strftime("%Y-%m-%d"))
    return f"{ {'semaine': 'menu', 'courses': 'courses', 'cuisine': 'cuisine'}[quoi]}-{profil.nom}-{debut}", page


def icones_js() -> bytes:
    """Les icones (Phosphor, fichiers SVG du dossier icones/) en un seul script."""
    icones = {f.stem: f.read_text(encoding="utf-8").strip()
              for f in sorted((_SITE / "icones").glob("*.svg"))}
    return ("const ICONES = " + json.dumps(icones, ensure_ascii=False) + ";\n").encode("utf-8")


def photos_des_fiches() -> dict:
    """{identifiant du repas: chemin de sa photo} d'apres les fiches liees au profil."""
    fiches = _profil().lien("fiches", "repas.json")
    try:
        with open(fiches, encoding="utf-8") as h:
            repas = json.load(h)["repas"]
    except (OSError, ValueError, KeyError):
        repas = []                                          # sans fiches, les photos du profil restent
    photos = {}
    for f in repas:
        image = fiches.parent / f.get("dossier", "") / "photo.jpg"
        if f.get("photo") and image.is_file():
            photos[f["id"]] = image
    for image in _photos_perso().glob("*.jpg"):              # les photos des plats du profil (photo_perso.py)
        photos.setdefault(image.stem, image)
    return photos


def _photos_perso() -> Path:
    """Dossier des photos des plats crees par le profil actif."""
    return _profil().fichier("photos")


