def _photo_de_secours(recette: dict) -> tuple | None:
    """La photo du plat du site qui ressemble le plus à `recette` (ingrédients en commun, puis mots du nom),
    réduite : la photo en dernier recours, pour qu'aucun plat ne reste sans photo (Taha, 19/11/2026)."""
    from PIL import Image
    photos = photos_des_fiches()
    mots = lambda t: {m for m in re.findall(r"[a-z]{4,}", pdf.normaliser(t))}
    siens, nom = {i["n"] for i in recette.get("ing", []) if i.get("u") != "qs"}, mots(recette.get("nom", ""))
    meilleur = max(((2 * len(siens & {i["n"] for i in r.get("ing", [])}) + len(nom & mots(r["nom"])) + 0.5 * (r.get("cat") == recette.get("cat")), r)
                    for r in donnees_site()["recettes"] if not r.get("perso") and r["id"] in photos and r["id"] != recette["id"]),
                   key=lambda x: x[0], default=None)
    if not meilleur:
        return None
    r = meilleur[1]
    try:
        with Image.open(photos[r["id"]]) as image:
            image = image.convert("RGB")
            image.thumbnail((mod_photo.LARGEUR, mod_photo.LARGEUR))
            tampon = io.BytesIO()
            image.save(tampon, "JPEG", quality=85, optimize=True)
    except OSError:
        return None
    return tampon.getvalue(), {"titre": f"photo de « {r['nom']} », plat qui lui ressemble", "page": "", "auteur": "Mon Meal Prep",
                               "licence": "", "source": "plat voisin"}


def poser_photo_perso(ident: str, image: bytes, credit: dict) -> None:
    """Ta photo (celle de l'assiette jointe dans « Ajouter ») devient celle du plat."""
    from PIL import Image, ImageOps
    with Image.open(io.BytesIO(image)) as im:
        im = ImageOps.exif_transpose(im).convert("RGB")
        im.thumbnail((mod_photo.LARGEUR, mod_photo.LARGEUR))
        tampon = io.BytesIO()
        im.save(tampon, "JPEG", quality=85, optimize=True)
    mod_photo.poser(_photos_perso(), ident, tampon.getvalue(), credit)


def photos_manquantes() -> None:
    """Relance la recherche pour chaque plat du profil encore sans photo (au plus une fois par heure chacun)."""
    try:
        dossier = _photos_perso()
        for r in plats_perso():
            if r.get("photo_de"):                            # une copie « (2) » a la photo de l'original
                continue
            if len(_PHOTOS_EN_COURS) >= 2:           # deux recherches à la fois au plus : les autres au prochain état
                break
            if not (dossier / f"{r['id']}.jpg").exists() and time.time() - _PHOTOS_ESSAIS.get((_profil().nom, r["id"]), 0) > 3600:
                chercher_photo(r)
    except Exception as e:
        consigner("photos", f"photos manquantes : {e}")


def chercher_photo(recette: dict) -> None:
    """Cherche en fond une photo pour un plat du profil qui n'en a pas : Foodiesfeed, puis Openverse et Wikimedia
    Commons (Claude choisit), sinon la photo du plat du site le plus proche. Le plat s'affiche tout de suite ;
    sa photo apparait au prochain rafraichissement."""
    dossier = _photos_perso()
    cle = (_profil().nom, recette["id"])           # deux profils peuvent avoir un plat du même nom
    if (dossier / f"{recette['id']}.jpg").exists() or cle in _PHOTOS_EN_COURS:
        return
    _PHOTOS_EN_COURS.add(cle)
    _PHOTOS_ESSAIS[cle] = time.time()
    demander = _claude_json if reglage("repas.plat_perso_ia", True) else (lambda texte: None)

    def tache():
        try:
            credit = mod_photo.trouver(recette, dossier, demander, secours=lambda: _photo_de_secours(recette))
            if credit:
                print(f"[repas] photo de « {recette['nom']} » : {credit['titre']} ({credit['page']})", flush=True)
            else:
                print(f"[repas] pas de photo trouvée pour « {recette['nom']} »", flush=True)
        except Exception as e:
            print(f"[repas] photo de « {recette['nom']} » : erreur {e}", flush=True)
        finally:
            _PHOTOS_EN_COURS.discard(cle)

    import contextvars
    # Le fil garde le profil de la requête (repas.profil.actif est une ContextVar).
    threading.Thread(target=contextvars.copy_context().run, args=(tache,), daemon=True, name=f"photo-{recette['id']}").start()


def photo(ident: str, largeur: int) -> bytes | None:
    """Photo d'un repas reduite a `largeur` pixels (gardee en cache sur le disque)."""
    fiches = photos_des_fiches()
    source = fiches.get(ident)
    if source is None:                                   # une copie « (2) » : la photo de l'original
        copie = next((r for r in plats_perso() if r["id"] == ident and r.get("photo_de")), None)
        source = fiches.get(copie["photo_de"]) if copie else None
    if source is None:
        return None
    largeur = min(_LARGEURS, key=lambda l: abs(l - largeur))
    cache = mod_stock.dossier_commun() / "cache_photos"
    cache.mkdir(exist_ok=True)
    cible = cache / f"{ident}_{largeur}_{int(source.stat().st_mtime)}.jpg"
    if not cible.exists():
        from PIL import Image
        with Image.open(source) as image:
            image = image.convert("RGB")
            image.thumbnail((largeur, largeur * 2))
            image.save(cible, "JPEG", quality=82, optimize=True)
    return cible.read_bytes()


# ------------------------------------------------------------------ acces
# Chaque personne se connecte avec SON identifiant (le nom de son profil) et son
# mot de passe : elle ne voit que son profil. L'identifiant « admin » (mot de passe
# du site : repas.mot_de_passe_site, sinon donnees_repas/mot_de_passe_site.txt)
# voit tous les profils. Depuis le poste lui-meme (127.0.0.1), il faut se connecter
# comme partout ; repas.admin_local: true redonne l'admin sans mot de passe sur le poste.
_POSTE = ("127.0.0.1", "::1")
ADMIN = "admin"
_ESSAIS_MAX, _BLOCAGE = 5, 300          # 5 mots de passe faux -> 5 minutes d'attente
_DUREE_SESSION = 30 * 86400             # une session expire au bout de 30 jours
_TLS = False                            # vrai quand le site est servi en HTTPS
# Bornes des reglages changes sur le site (minimum, maximum).
_BORNES = {"budget_mois": (0, 5000), "ajustement": (-1500, 1500), "phase": (1, 20),
           "nb_semaines": (1, 4), "nb_plats": (1, 14), "nb_petits_dej": (1, 7), "nb_collations": (0, 14)}
_SECURITE = (("X-Content-Type-Options", "nosniff"), ("Referrer-Policy", "same-origin"),
             ("X-Frame-Options", "DENY"),
             ("Content-Security-Policy", "default-src 'self'; img-src 'self' data:; "
                                         "style-src 'self' 'unsafe-inline'; frame-ancestors 'none'; "
                                         "base-uri 'none'; form-action 'self'"))


def _admin_local(adresse: str) -> bool:
    return adresse in _POSTE and bool(reglage("repas.admin_local", False))


def hote_connu(hote: str) -> bool:
    """Vrai si l'en-tete Host designe bien ce site : localhost, une adresse IP, le nom
    du poste ou un nom ajoute dans repas.hotes. Un nom de domaine inconnu est refuse :
    c'est ainsi qu'un autre site peut viser un service local (reassociation DNS)."""
    hote = str(hote or "").strip().lower()
    nom = hote[1:].split("]")[0] if hote.startswith("[") else hote.rsplit(":", 1)[0] if ":" in hote else hote
    poste = socket.gethostname().lower()
    if nom in ("localhost", poste, poste + ".local") or nom in [str(h).lower() for h in (reglage("repas.hotes", []) or [])]:
        return True
    try:
        ipaddress.ip_address(nom)
        return True
    except ValueError:
        return False


def _age_session(s: dict) -> float:
    if s.get("cree"):
        return time.time() - float(s["cree"])
    try:                                            # sessions d'avant : seule la date etait notee
        return time.time() - time.mktime(time.strptime(s.get("cree_le", ""), "%Y-%m-%d"))
    except ValueError:
        return float("inf")
_ECHECS = {}                            # adresse -> [nombre, fin du blocage]
_PORT_CHROME = 9230                     # premier port de debug des Chrome de profil


def mot_de_passe() -> str:
    """Mot de passe de l'admin : repas.mot_de_passe_site, sinon un mot de passe tire
    au hasard une fois et garde dans donnees_repas/mot_de_passe_site.txt."""
    choisi = str(reglage("repas.mot_de_passe_site", "") or "").strip()
    if choisi:
        return choisi
    f = mod_stock.dossier_commun() / "mot_de_passe_site.txt"
    if not f.exists():
        f.write_text(secrets.token_urlsafe(9) + "\n", encoding="utf-8")
        f.chmod(0o600)
    return f.read_text(encoding="utf-8").strip()


def code_invitation() -> str:
    """Code a donner a quelqu'un pour qu'il cree son profil depuis la page de connexion."""
    f = mod_stock.dossier_commun() / "code_invitation.txt"
    if not f.exists():
        f.write_text(secrets.token_hex(4) + "\n", encoding="utf-8")
        f.chmod(0o600)
    return f.read_text(encoding="utf-8").strip()


def _hacher(mdp: str, sel: str) -> str:
    return hashlib.pbkdf2_hmac("sha256", mdp.encode("utf-8"), bytes.fromhex(sel), 200_000).hex()


def definir_mot_de_passe(profil, mdp: str) -> None:
    """Mot de passe d'un profil : seule son empreinte salee est ecrite (acces.json)."""
    if len(str(mdp)) < 8:
        raise ValueError("Mot de passe : 8 caractères au moins.")
    sel = secrets.token_hex(16)
    f = profil.dossier / "acces.json"
    f.write_text(json.dumps({"sel": sel, "empreinte": _hacher(str(mdp), sel)}), encoding="utf-8")
    f.chmod(0o600)


def _mot_de_passe_juste(utilisateur: str, propose: str) -> bool:
    if utilisateur == ADMIN:
        return hmac.compare_digest(str(propose).encode("utf-8"), mot_de_passe().encode("utf-8"))
    profil = mod_profil.charger(utilisateur, reglage)
    try:
        with open(profil.dossier / "acces.json", encoding="utf-8") as h:
            acces = json.load(h)
        return hmac.compare_digest(_hacher(str(propose), acces["sel"]), acces["empreinte"])
    except (AttributeError, OSError, ValueError, KeyError):
        _hacher(str(propose), "00" * 16)            # meme duree, que l'identifiant existe ou non
        return False


def _empreinte(jeton: str) -> str:
    return hashlib.sha256(jeton.encode("utf-8")).hexdigest()


def ouvrir_session(utilisateur: str = ADMIN) -> str:
    """Nouveau jeton de session ; seule son empreinte est gardee sur le disque."""
    jeton = secrets.token_urlsafe(32)
    with _VERROU:
        sessions = [s for s in _lire_c("sessions_site.json", []) if _age_session(s) < _DUREE_SESSION]
        sessions.append({"empreinte": _empreinte(jeton), "cree_le": time.strftime("%Y-%m-%d"),
                         "cree": int(time.time()), "utilisateur": utilisateur})
        _ecrire_c("sessions_site.json", sessions[-60:])
    return jeton


def session(jeton: str) -> dict | None:
    if not jeton:
        return None
    cherche = _empreinte(jeton)
    return next((s for s in _lire_c("sessions_site.json", [])
                 if hmac.compare_digest(cherche, s.get("empreinte", ""))
                 and _age_session(s) < _DUREE_SESSION), None)


def session_valide(jeton: str) -> bool:
    return session(jeton) is not None


def fermer_session(jeton: str) -> None:
    with _VERROU:
        cherche = _empreinte(jeton or "")
        _ecrire_c("sessions_site.json", [s for s in _lire_c("sessions_site.json", [])
                                         if s.get("empreinte") != cherche])


def _bloque(adresse: str) -> str:
    fin = _ECHECS.get(adresse, [0, 0.0])[1]
    return (f"Trop d'essais. Réessaie dans {int((fin - time.time()) // 60) + 1} minute(s)."
            if time.time() < fin else "")


def _echec(adresse: str) -> None:
    nombre = _ECHECS.get(adresse, [0, 0.0])[0] + 1
    if len(_ECHECS) > 500:                          # la table ne grossit pas sans fin
        for a in [a for a, (_, fin) in _ECHECS.items() if fin < time.time() and a != adresse][:400]:
            del _ECHECS[a]
    _ECHECS[adresse] = [0, time.time() + _BLOCAGE] if nombre >= _ESSAIS_MAX else [nombre, 0.0]
    consigner("acces-refuse", f"{adresse} essai {nombre}" + (" : adresse bloquee" if nombre >= _ESSAIS_MAX else ""))


def verifier_mot_de_passe(adresse: str, propose: str, utilisateur: str = ADMIN) -> tuple:
    """(accepte, message). Bloque une adresse apres trop d'essais faux."""
    with _VERROU:
        message = _bloque(adresse)
        if message:
            return False, message
        if _mot_de_passe_juste(str(utilisateur or ADMIN).strip().lower(), propose):
            _ECHECS.pop(adresse, None)
            return True, ""
        _echec(adresse)
        return False, "Identifiant ou mot de passe incorrect."


def creer_profil(champs: dict) -> str:
    """Cree un profil depuis le formulaire du site : son dossier, sa fiche, son mot
    de passe et son Chrome (ouvert sur les enseignes pour qu'il s'y connecte)."""
    with _VERROU:
        pris = {int(p.valeur("navigateur.port", 0) or 0)
                for p in (mod_profil.charger(n, reglage) for n in mod_profil.liste(reglage)) if p}
        port = next(n for n in range(_PORT_CHROME, _PORT_CHROME + 200) if n not in pris)
        if len(str(champs.get("mot_de_passe", ""))) < 8:
            raise ValueError("Mot de passe : 8 caractères au moins.")
        profil = mod_profil.creer(champs, port, reglage)
        definir_mot_de_passe(profil, champs["mot_de_passe"])
    mod_profil.choisir(profil.nom)
    phase = profil.phases[0]
    ouvertes = ouvrir_enseignes()
    journal("profil", "Profil créé", [
        f"Objectif {phase['nom'].lower()} : {phase['kcal']} kcal et {phase['prot']} g de protéines par jour.",
        "Ta fiche : PROFIL.md dans ton dossier de profil.",
        ("Un Chrome à toi est ouvert sur le PC : connecte-toi à " + ", ".join(ouvertes)
         + ". Jarvis y remplira ton panier.") if ouvertes else
        "Ton Chrome n'a pas pu être ouvert sur le PC : relance-le depuis Réglages."])
    return profil.nom


def ouvrir_enseignes() -> list:
    """Ouvre le Chrome du profil en cours sur les pages de ses enseignes."""
    from repas import navigateur
    try:
        return navigateur.ouvrir_connexions(_profil())
    except Exception:                               # pas d'ecran, Chrome absent…
        return []


# ------------------------------------------------------------------ HTTP
class _Requete(BaseHTTPRequestHandler):
    server_version = "JarvisRepas"

    def _temoin(self, cherche: str) -> str:
        for morceau in (self.headers.get("Cookie") or "").split(";"):
            nom, _, valeur = morceau.strip().partition("=")
            if nom == cherche:
                return valeur
        return ""

    def _jeton(self) -> str:
        return self._temoin("repas_session")

    def _relaye(self) -> bool:
        """La requête arrive par un relais de ce PC (tailscale serve / funnel) : elle vient d'ailleurs."""
        return self.client_address[0] in _POSTE and any(self.headers.get(h) for h in ("X-Forwarded-For", "X-Forwarded-Host", "Tailscale-Funnel-Request"))

    def _adresse(self) -> str:
        """L'adresse du visiteur. Derrière le relais, tout le monde arrive de 127.0.0.1 : on prend celle que le
        relais a ajoutée (la DERNIÈRE de X-Forwarded-For, les précédentes peuvent être inventées par le visiteur).
        Sinon un inconnu qui se trompe de mot de passe bloquerait tout le monde."""
        if self._relaye():
            vue = [a.strip() for a in str(self.headers.get("X-Forwarded-For") or "").split(",") if a.strip()]
            return ("relais:" + vue[-1])[:80] if vue else "relais"
        return self.client_address[0]

    def _qui(self) -> str:
        """Identifiant de la personne connectee ("" si personne) ; choisit aussi le
        profil sur lequel porte la requete."""
        s = session(self._jeton())
        # L'admin sans mot de passe, sur le PC lui-même seulement : jamais pour une requête relayée d'ailleurs.
        qui = s.get("utilisateur", ADMIN) if s else (ADMIN if _admin_local(self.client_address[0]) and not self._relaye() else "")
        if qui == ADMIN:
            vu = self._temoin("repas_profil")
            mod_profil.choisir(vu if vu in mod_profil.liste(reglage) else "")
        elif qui:
            if mod_profil.charger(qui, reglage) is None:
                return ""                           # profil supprime depuis
            mod_profil.choisir(qui)
        return qui

    def _autorise(self) -> bool:
        return bool(self._qui())

    def _etat(self, qui: str) -> dict:
        """L'etat envoye a la page. Les recettes n'y sont pas (elles se demandent a part,
        une fois, par /api/recettes) : seuls la note et l'avis de chacune voyagent."""
        e = etat()
        photos_manquantes()                          # chaque plat du profil a sa photo (Taha, 19/11/2026)
        e["avis"] = {r["id"]: {"note": r["note"], "nb_notes": r["nb_notes"], "gout": r["gout"]}
                     for r in e.pop("recettes") if r["nb_notes"] or r["gout"]}
        del e["rayons"]
        e["journal_suite"] = len(e["journal"]) > 20
        e["journal"] = e["journal"][:20]
        e["utilisateur"] = {"id": qui, "admin": qui == ADMIN}
        if qui == ADMIN:
            e["profils"] = [{"id": n, "nom": (mod_profil.charger(n, reglage).valeur("identite.nom", n))}
                            for n in mod_profil.liste(reglage)]
            e["invitation"] = code_invitation()
        return e

    def log_message(self, *args):                   # pas de bruit dans la console
        pass

    def _repondre(self, code, corps, type_="application/json; charset=utf-8", entetes=(), etiquette=None):
        """`etiquette` : True (empreinte du contenu) ou un texte. Le navigateur garde alors
        la reponse et redemande seulement si elle a change (304 sinon)."""
        donnees = corps if isinstance(corps, bytes) else json.dumps(
            corps, ensure_ascii=False).encode("utf-8")
        entetes = list(entetes)
        if etiquette and code == 200:
            marque = '"' + (etiquette if isinstance(etiquette, str) else hashlib.sha256(donnees).hexdigest()[:20]) + '"'
            entetes += [("ETag", marque), ("Cache-Control", "private, no-cache")]
            if self.headers.get("If-None-Match") == marque:
                code, donnees = 304, b""
        if (len(donnees) > 1024 and "gzip" in (self.headers.get("Accept-Encoding") or "")
                and type_.startswith(("text/", "application/json"))):
            donnees = gzip.compress(donnees, 5)
            entetes.append(("Content-Encoding", "gzip"))
        self.send_response(code)
        for nom, valeur in entetes:
            self.send_header(nom, valeur)
        for nom, valeur in _SECURITE:
            self.send_header(nom, valeur)
        self.send_header("Vary", "Accept-Encoding")
        self.send_header("Content-Type", type_)
        self.send_header("Content-Length", str(len(donnees)))
        if not any(nom == "Cache-Control" for nom, _ in entetes):
            self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(donnees)

    def _proteger(self, traiter) -> None:
        """Une erreur imprevue donne une reponse 500 et une trace dans site.log, au lieu
        d'une connexion coupee sans explication."""
        try:
            if not hote_connu(self.headers.get("Host")):
                consigner("hote-refuse", f"{self.client_address[0]} {self.headers.get('Host')}")
                return self._repondre(403, {"erreur": "adresse du site inconnue"})
            traiter()
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception:
            consigner("erreur", f"{self.command} {self.path}\n{traceback.format_exc()}")
            with contextlib.suppress(Exception):
                self._repondre(500, {"erreur": "Erreur interne. Elle est notée dans site.log."})

    def do_GET(self):
        self._proteger(self._lire_requete)

    do_HEAD = do_GET

    def do_POST(self):
        self._proteger(self._ecrire_requete)

    def _lire_requete(self):
        chemin, _, requete = self.path.partition("?")
        # La page, son style, son script, ses polices et ses icones s'affichent sans
        # mot de passe (il faut bien montrer le formulaire) ; les donnees et les photos non.
        if chemin in _STATIQUES:
            nom, type_ = _STATIQUES[chemin]
            return self._repondre(200, (_SITE / nom).read_bytes(), type_, etiquette=True)
        if chemin == "/icones.js":
            return self._repondre(200, icones_js(), "text/javascript; charset=utf-8", etiquette=True)
        if chemin == "/sw.js":
            return self._repondre(200, (_SITE / "sw.js").read_bytes(), "text/javascript; charset=utf-8", etiquette=True)
        if chemin == "/manifest.webmanifest":
            return self._repondre(200, (_SITE / "manifest.webmanifest").read_bytes(),
                                  "application/manifest+json", etiquette=True)
        if chemin in ("/icone.svg", "/icone-192.png", "/icone-512.png", "/apple-touch-icon.png"):
            f = _SITE / chemin[1:]
            if f.is_file():
                return self._repondre(200, f.read_bytes(), "image/svg+xml" if chemin.endswith(".svg") else "image/png",
                                      entetes=[("Cache-Control", "public, max-age=604800")])
        if chemin.startswith("/fonts/") and chemin.endswith(".woff2"):
            f = _SITE / "fonts" / Path(chemin).name
            if f.is_file():
                return self._repondre(200, f.read_bytes(), "font/woff2",
                                      entetes=[("Cache-Control", "public, max-age=31536000, immutable")])
        if chemin == "/favicon.ico":
            return self._repondre(204, b"", "image/x-icon")
        qui = self._qui()
        if not qui:
            return self._repondre(401, {"erreur": "connexion"})
        if chemin == "/api/etat":
            return self._repondre(200, self._etat(qui))
        parametres = dict(p.split("=", 1) for p in requete.split("&") if "=" in p)
        if chemin == "/api/recettes":
            e = etat()
            base = [{k: v for k, v in r.items() if k not in ("note", "nb_notes", "gout")} for r in e["recettes"]]
            return self._repondre(200, {"version": e["recettes_version"], "recettes": base, "rayons": e["rayons"]},
                                  etiquette=e["recettes_version"])
        if chemin == "/api/repas/idees":
            try:
                return self._repondre(200, {"idees": idees_du_jour(parametres.get("date", ""))})
            except ValueError as e:
                return self._repondre(400, {"erreur": str(e)})
        if chemin == "/api/journal":
            try:
                debut = max(0, int(parametres.get("debut", 0)))
            except ValueError:
                debut = 0
            entrees = _lire_p("journal.json", [])
            return self._repondre(200, {"entrees": entrees[debut:debut + 40], "suite": len(entrees) > debut + 40})
        if chemin.startswith("/export/"):
            try:
                nom, page = exporter(Path(chemin).stem)
            except ValueError as e:
                return self._repondre(404, {"erreur": str(e)})
            fichier = mod_export.en_pdf(page)
            if fichier:
                return self._repondre(200, fichier, "application/pdf", entetes=[
                    ("Content-Disposition", f'attachment; filename="{nom}.pdf"'), ("Cache-Control", "no-store")])
            # Chrome absent : la meme page en HTML, a imprimer depuis le navigateur.
            return self._repondre(200, page.encode("utf-8"), "text/html; charset=utf-8", entetes=[("Cache-Control", "no-store")])
        if chemin.startswith("/photo/"):
            try:
                largeur = int(dict(p.split("=", 1) for p in requete.split("&") if "=" in p).get("l", 480))
            except ValueError:
                largeur = 480
            image = photo(Path(chemin).name, largeur)
            if image is not None:
                return self._repondre(200, image, "image/jpeg",
                                      entetes=[("Cache-Control", "private, max-age=604800")])
        self._repondre(404, {"erreur": "introuvable"})

    def _ecrire_requete(self):
        # On refuse une page d'un AUTRE site qui appellerait l'API : l'origine de la
        # requete doit etre le site lui-meme. Un navigateur envoie toujours Origin
        # avec un POST : son absence est refusee aussi.
        origine = self.headers.get("Origin", "")
        permis = {self.headers.get("Host") or ""}
        if self.client_address[0] in _POSTE and self.headers.get("X-Forwarded-Host"):
            permis.add(self.headers["X-Forwarded-Host"])       # relaye par ce PC (tailscale serve, en HTTPS)
        if origine.split("://", 1)[-1] not in permis or not hote_connu(origine.split("://", 1)[-1]):
            return self._repondre(403, {"erreur": "origine refusee"})
        chemin = self.path.partition("?")[0]
        try:
            taille = int(self.headers.get("Content-Length") or 0)
            limite = 9_000_000 if chemin in ("/api/repas/analyser", "/api/repas/au_menu") else 100_000      # une photo, encodee en base64
            corps = json.loads(self.rfile.read(taille) or b"{}") if 0 < taille < limite else {}
        except ValueError:
